window.LAW_SEARCH_IDX = window.LAW_SEARCH_IDX || {};
window.LAW_SEARCH_IDX["judicial-interpretations|规定"] = {"renminjianchayuanbanlixingzhengzhifajiguanyisongsh34835a":[],"renminjianchayuanjianchajianyigongzuoguiding":[{"i":1,"n":"第一条","txt":"为了进一步加强和规范检察建议工作，确保检察建议的质量和效果，充分发挥检察建议的作用，根据《中华人民共和国人民检察院组织法》等法律规定，结合检察工作实际，制定本规定。"},{"i":2,"n":"第二条","txt":"检察建议是人民检察院依法履行法律监督职责，参与社会治理，维护司法公正，促进依法行政，预防和减少违法犯罪，保护国家利益和社会公共利益，维护个人和组织合法权益，保障法律统一正确实施的重要方式。"},{"i":3,"n":"第三条","txt":"人民检察院可以直接向本院所办理案件的涉案单位、本级有关主管机关以及其他有关单位提出检察建议。"},{"i":4,"n":"第四条","txt":"提出检察建议，应当立足检察职能，结合司法办案工作，坚持严格依法、准确及时、必要审慎、注重实效的原则。"},{"i":5,"n":"第五条","txt":"检察建议主要包括以下类型："},{"i":6,"n":"第六条","txt":"检察建议应当由检察官办案组或者检察官办理。"},{"i":7,"n":"第七条","txt":"制发检察建议应当在统一业务应用系统中进行，实行以院名义统一编号、统一签发、全程留痕、全程监督。"},{"i":8,"n":"第八条","txt":"人民检察院发现同级人民法院已经发生法律效力的判决、裁定具有法律规定的应当再审情形的，或者发现调解书损害国家利益、社会公共利益的，可以向同级人民法院提出再审检察建议。"},{"i":9,"n":"第九条","txt":"人民检察院在履行对诉讼活动的法律监督职责中发现有关执法、司法机关具有下列情形之一的，可以向有关执法、司法机关提出纠正违法检察建议："},{"i":10,"n":"第十条","txt":"人民检察院在履行职责中发现生态环境和资源保护、食品药品安全、国有财产保护、国有土地使用权出让等领域负有监督管理职责的行政机关违法行使职权或者不作为，致使国家利益或者社会公共利益受到侵害，符合法律规定的公益诉讼条件的，应当按照公益诉讼案件办理程序向行政机关提出督促依法履职的检察建议。"},{"i":11,"n":"第十一条","txt":"人民检察院在办理案件中发现社会治理工作存在下列情形之一的，可以向有关单位和部门提出改进工作、完善治理的检察建议："},{"i":12,"n":"第十二条","txt":"对执法、司法机关在诉讼活动中的违法情形，以及需要对被不起诉人给予行政处罚、处分或者需要没收其违法所得，法律、司法解释和其他有关规范性文件明确规定应当发出纠正违法通知书、检察意见书的，依照相关规定执行。"},{"i":13,"n":"第十三条","txt":"检察官在履行职责中发现有应当依照本规定提出检察建议情形的，应当报经检察长决定，对相关事项进行调查核实，做到事实清楚、准确。"},{"i":14,"n":"第十四条","txt":"检察官可以采取以下措施进行调查核实："},{"i":15,"n":"第十五条","txt":"检察官一般应当在检察长作出决定后两个月以内完成检察建议事项的调查核实。情况紧急的，应当及时办结。"},{"i":16,"n":"第十六条","txt":"检察建议书要阐明相关的事实和依据，提出的建议应当符合法律、法规及其他有关规定，明确具体、说理充分、论证严谨、语言简洁、有操作性。"},{"i":17,"n":"第十七条","txt":"检察官依据本规定第十一条的规定起草的检察建议书，报送检察长前，应当送本院负责法律政策研究的部门对检察建议的必要性、合法性、说理性等进行审核。"},{"i":18,"n":"第十八条","txt":"检察建议书应当以人民检察院的名义送达有关单位。送达检察建议书，可以书面送达，也可以现场宣告送达。"},{"i":19,"n":"第十九条","txt":"人民检察院提出检察建议，除另有规定外，应当要求被建议单位自收到检察建议书之日起两个月以内作出相应处理，并书面回复人民检察院。因情况紧急需要被建议单位尽快处理的，可以根据实际情况确定相应的回复期限。"},{"i":20,"n":"第二十条","txt":"涉及事项社会影响大、群众关注度高、违法情形具有典型性、所涉问题应当引起有关部门重视的检察建议书，可以抄送同级党委、人大、政府、纪检监察机关或者被建议单位的上级机关、行政主管部门以及行业自律组织等。"},{"i":21,"n":"第二十一条","txt":"发出的检察建议书，应当于五日内报上一级人民检察院对口业务部门和负责法律政策研究的部门备案。"},{"i":22,"n":"第二十二条","txt":"检察长认为本院发出的检察建议书确有不当的，应当决定变更或者撤回，并及时通知有关单位，说明理由。"},{"i":23,"n":"第二十三条","txt":"被建议单位对检察建议提出异议的，检察官应当立即进行复核。经复核，异议成立的，应当报经检察长或者检察委员会讨论决定后，及时对检察建议书作出修改或者撤回检察建议书；异议不成立的，应当报经检察长同意后，向被建议单位说明理由。"},{"i":24,"n":"第二十四条","txt":"人民检察院应当积极督促和支持配合被建议单位落实检察建议。督促落实工作由原承办检察官办理，可以采取询问、走访、不定期会商、召开联席会议等方式，并制作笔录或者工作记录。"},{"i":25,"n":"第二十五条","txt":"被建议单位在规定期限内经督促无正当理由不予整改或者整改不到位的，经检察长决定，可以将相关情况报告上级人民检察院，通报被建议单位的上级机关、行政主管部门或者行业自律组织等，必要时可以报告同级党委、人大，通报同级政府、纪检监察机关。符合提起公益诉讼条件的，依法提起公益诉讼。"},{"i":26,"n":"第二十六条","txt":"各级人民检察院检察委员会应当定期对本院制发的检察建议的落实效果进行评估。"},{"i":27,"n":"第二十七条","txt":"人民检察院案件管理部门负责检察建议的流程监控和分类统计，定期组织对检察建议进行质量评查，对检察建议工作情况进行综合分析。"},{"i":28,"n":"第二十八条","txt":"人民检察院应当将制发检察建议的质量和效果纳入检察官履职绩效考核。"},{"i":29,"n":"第二十九条","txt":"上级人民检察院应当加强对下级人民检察院开展检察建议工作的指导，及时通报情况，帮助解决检察建议工作中的问题。"},{"i":30,"n":"第三十条","txt":"法律、司法解释和其他有关规范性文件对再审检察建议、纠正违法检察建议和公益诉讼检察建议的办理有规定的，依照其规定办理；没有规定的，参照本规定办理。"},{"i":31,"n":"第三十一条","txt":"本规定由最高人民检察院负责解释。"},{"i":32,"n":"第三十二条","txt":"本规定自公布之日起施行，2009年印发的《人民检察院检察建议工作规定（试行）》同时废止。"}],"zuigaorenminjianchayuanguanyuyijianchazhuandifangs39739d":[{"i":1,"n":"第一条","txt":"法律规定可以邮寄送达的检察法律文书，人民检察院可以交由邮政企业以检察专递方式邮寄送达，但下列情形除外："},{"i":2,"n":"第二条","txt":"以检察专递方式邮寄送达有关检察法律文书的，该送达与人民检察院直接送达具有同等法律效力。"},{"i":3,"n":"第三条","txt":"当事人向人民检察院申请监督、提出申诉或者提交答辩意见时，应当向人民检察院提供或者确认自己准确的送达地址及联系方式，并填写当事人联系方式确认书。"},{"i":4,"n":"第四条","txt":"当事人联系方式确认书的内容应当包括送达地址的邮政编码、详细地址以及受送达人的联系电话等内容。"},{"i":5,"n":"第五条","txt":"经人民检察院告知，当事人仍拒绝提供自己送达地址的，自然人以其户籍登记中的住所地或者经常居住地为其送达地址；法人或者其他组织以其工商登记或者其他依法登记、备案中的住所地为其送达地址。"},{"i":6,"n":"第六条","txt":"邮政企业按照当事人提供或者确认的送达地址送达的，应当在规定的日期内将回执退回人民检察院。"},{"i":7,"n":"第七条","txt":"邮寄送达检察法律文书，应当直接送交受送达人。受送达人是公民的，由其本人签收，本人不在其提供或者确认的送达地址的，邮政企业可以将邮件交给与他同住的成年家属代收，但同住的成年家属是同一案件中另一方当事人的除外；受送达人是法人或者其他组织的，应当由法人的法定代表人、其他组织的主要负责人或者该法人、组织负责收件的工作人员签收；受送达人有诉讼代理人的，可以送交其代理人签收；受送达人已向人民检察院指定代收人的，送交代收人签收。"},{"i":8,"n":"第八条","txt":"受送达人或者其代收人应当在邮件回执上签名、盖章或者捺印。"},{"i":9,"n":"第九条","txt":"有下列情形之一的，即为送达："},{"i":10,"n":"第十条","txt":"签收人是受送达人本人或者是受送达人的法定代表人、主要负责人、法定代理人、诉讼代理人的，签收人应当当场核对邮件内容。签收人发现邮件内容与回执上的文书名称不一致的，应当当场向邮政企业的投递员提出，由投递员在回执上记明情况，并将邮件退回人民检察院。"},{"i":11,"n":"第十一条","txt":"邮寄送达检察法律文书的费用，从各级人民检察院办案经费中支出。"},{"i":12,"n":"第十二条","txt":"本规定所称检察专递是指邮政企业针对送达检察法律文书所采取的特快专递邮寄形式。"},{"i":13,"n":"第十三条","txt":"本规定由最高人民检察院负责解释，自发布之日起施行。"}],"zuigaorenminjianchayuanguanyuzhipaipinqingyouzhuan22d2cd":[{"i":1,"n":"第一条","txt":"为了规范和促进人民检察院指派、聘请有专门知识的人参与办案，根据《中华人民共和国刑事诉讼法》《中华人民共和国民事诉讼法》《中华人民共和国行政诉讼法》等法律规定，结合检察工作实际，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称“有专门知识的人”，是指运用专门知识参与人民检察院的办案活动，协助解决专门性问题或者提出意见的人，但不包括以鉴定人身份参与办案的人。"},{"i":3,"n":"第三条","txt":"人民检察院可以指派、聘请有鉴定资格的人员，或者经本院审查具备专业能力的其他人员，作为有专门知识的人参与办案。"},{"i":4,"n":"第四条","txt":"人民检察院聘请检察机关以外的人员作为有专门知识的人参与办案，应当核实其有效身份证件和能够证明符合本规定第三条第一款要求的材料。"},{"i":5,"n":"第五条","txt":"具备条件的人民检察院可以明确专门部门，负责建立有专门知识的人推荐名单库。"},{"i":6,"n":"第六条","txt":"有专门知识的人的回避，适用《中华人民共和国刑事诉讼法》《中华人民共和国民事诉讼法》《中华人民共和国行政诉讼法》等法律规定中有关鉴定人回避的规定。"},{"i":7,"n":"第七条","txt":"人民检察院办理刑事案件需要收集证据的，可以指派、聘请有专门知识的人开展下列工作："},{"i":8,"n":"第八条","txt":"人民检察院在审查起诉时，发现涉及专门性问题的证据材料有下列情形之一的，可以指派、聘请有专门知识的人进行审查，出具审查意见："},{"i":9,"n":"第九条","txt":"人民检察院在人民法院决定开庭后，可以指派、聘请有专门知识的人，协助公诉人做好下列准备工作："},{"i":10,"n":"第十条","txt":"刑事案件法庭审理中，人民检察院可以申请人民法院通知有专门知识的人出庭，就鉴定人作出的鉴定意见提出意见。"},{"i":11,"n":"第十一条","txt":"刑事案件法庭审理中，公诉人出示、播放、演示涉及专门性问题的证据材料需要协助的，人民检察院可以指派、聘请有专门知识的人进行操作。"},{"i":12,"n":"第十二条","txt":"人民检察院在对公益诉讼案件决定立案和调查收集证据时，就涉及专门性问题的证据材料或者专业问题，可以指派、聘请有专门知识的人协助开展下列工作："},{"i":13,"n":"第十三条","txt":"公益诉讼案件法庭审理中，人民检察院可以申请人民法院通知有专门知识的人出庭，就鉴定人作出的鉴定意见或者专业问题提出意见。"},{"i":14,"n":"第十四条","txt":"人民检察院在下列办案活动中，需要指派、聘请有专门知识的人的，可以适用本规定："},{"i":15,"n":"第十五条","txt":"人民检察院应当为有专门知识的人参与办案提供下列必要条件："},{"i":16,"n":"第十六条","txt":"人民检察院依法保障接受指派、聘请参与办案的有专门知识的人及其近亲属的安全。"},{"i":17,"n":"第十七条","txt":"有专门知识的人因参与办案而支出的交通、住宿、就餐等费用，由人民检察院承担。对于聘请的有专门知识的人，应当给予适当报酬。"},{"i":18,"n":"第十八条","txt":"有专门知识的人参与办案，应当遵守法律规定，遵循技术标准和规范，恪守职业道德，坚持客观公正原则。"},{"i":19,"n":"第十九条","txt":"有专门知识的人应当保守参与办案中所知悉的国家秘密、商业秘密、个人隐私以及其他不宜公开的内容。"},{"i":20,"n":"第二十条","txt":"有专门知识的人应当妥善保管、使用并及时退还参与办案中所接触的证据等案卷材料。"},{"i":21,"n":"第二十一条","txt":"有专门知识的人不得在同一案件中同时接受刑事诉讼当事人、辩护人、诉讼代理人，民事、行政诉讼对方当事人、诉讼代理人，或者人民法院的委托。"},{"i":22,"n":"第二十二条","txt":"有专门知识的人违反本规定第十八条至第二十一条的规定，出现重大过错，影响正常办案的，人民检察院应当停止其作为有专门知识的人参与办案，并从推荐名单库中除名。必要时，可以建议其所在单位或者有关部门给予行政处分或者其他处分。构成违法犯罪的，依法追究行政责任或者刑事责任。"},{"i":23,"n":"第二十三条","txt":"各省、自治区、直辖市人民检察院可以依照本规定，结合本地实际，制定具体实施办法，并报最高人民检察院备案。"},{"i":24,"n":"第二十四条","txt":"本规定由最高人民检察院负责解释。"},{"i":25,"n":"第二十五条","txt":"本规定自公布之日起试行。"}],"zuigaorenminfayuanzuigaorenminjianchayuanguanyubanaed8a6":[{"i":1,"n":"第一条","txt":"本规定适用于损害行为发生地、损害结果地或者采取预防措施地在海洋环境保护法第二条第一款规定的海域内，因破坏海洋生态、海洋水产资源、海洋保护区而提起的民事公益诉讼、刑事附带民事公益诉讼和行政公益诉讼。"},{"i":2,"n":"第二条","txt":"依据海洋环境保护法第八十九条第二款规定，对破坏海洋生态、海洋水产资源、海洋保护区，给国家造成重大损失的，应当由依照海洋环境保护法规定行使海洋环境监督管理权的部门，在有管辖权的海事法院对侵权人提起海洋自然资源与生态环境损害赔偿诉讼。"},{"i":3,"n":"第三条","txt":"人民检察院在履行职责中发现破坏海洋生态、海洋水产资源、海洋保护区的行为，可以告知行使海洋环境监督管理权的部门依据本规定第二条提起诉讼。在有关部门仍不提起诉讼的情况下，人民检察院就海洋自然资源与生态环境损害，向有管辖权的海事法院提起民事公益诉讼的，海事法院应予受理。"},{"i":4,"n":"第四条","txt":"破坏海洋生态、海洋水产资源、海洋保护区，涉嫌犯罪的，在行使海洋环境监督管理权的部门没有另行提起海洋自然资源与生态环境损害赔偿诉讼的情况下，人民检察院可以在提起刑事公诉时一并提起附带民事公益诉讼，也可以单独提起民事公益诉讼。"},{"i":5,"n":"第五条","txt":"人民检察院在履行职责中发现对破坏海洋生态、海洋水产资源、海洋保护区的行为负有监督管理职责的部门违法行使职权或者不作为，致使国家利益或者社会公共利益受到侵害的，应当向有关部门提出检察建议，督促其依法履行职责。"},{"i":6,"n":"第六条","txt":"本规定自2022年5月15日起施行。"}],"zuigaorenminfayuanzuigaorenminjianchayuanguanyuban9deaa4":[{"i":1,"n":"第一条","txt":"违反土地管理法律、法规规定，实施非法占用耕地行为的公民、法人或者其他组织，为依法应当承担非法占用耕地行政法律责任的主体。"},{"i":2,"n":"第二条","txt":"行政机关依法作出责令停止建设或者责令限期拆除在非法占用耕地上新建的建筑物和其他设施的决定后，建设单位或者个人继续施工，行政机关依据城乡规划法等有关法律、法规的规定采取查封施工现场等措施予以制止的，人民法院依法予以支持。"},{"i":3,"n":"第三条","txt":"非法占用耕地的行为，在耕地恢复至未被占用的状态之前，应当视为具有行政处罚法第三十六条第二款规定的“继续状态”，行政处罚的追责期限应当从违法行为终了之日起计算。"},{"i":4,"n":"第四条","txt":"公民、法人或者其他组织对行政机关依照土地管理法作出的责令限期拆除决定不服，根据行政复议法第二十条、第二十一条的规定，向行政机关申请行政复议，对行政复议决定不服，在法定期限内向人民法院提起行政诉讼，或者在接到责令限期拆除决定之日起十五日内，直接向人民法院提起行政诉讼的，人民法院应当依法立案。"},{"i":5,"n":"第五条","txt":"公民、法人或者其他组织不服行政机关作出的责令限期拆除决定，向人民法院提起行政诉讼，人民法院经审理认为被诉责令限期拆除决定证据确凿，适用法律、法规正确，符合法定程序的，判决驳回原告的诉讼请求。"},{"i":6,"n":"第六条","txt":"符合行政诉讼法第二十五条规定的公民、法人或者其他组织以行政机关未履行查处非法占用耕地行为的法定职责为由，请求人民法院判决行政机关履行法定职责或者确认不履行法定职责行为违法的，人民法院应当依据法律、法规，参照规章，并结合国务院及其组成部门、省级人民政府就非法占用耕地问题依法制定的规范性文件的规定，对被告是否履行土地管理法律、法规规定的查处职责，或者依法作出补办、完善手续、在一定期限内予以保留等处理决定进行审理，并依法作出裁判。"},{"i":7,"n":"第七条","txt":"公民、法人或者其他组织因行政机关非法批准占用耕地行为受到损害，请求人民法院判决行政机关承担行政赔偿责任的，人民法院应当根据行政诉讼法以及相关司法解释的规定，综合考虑批准行为在损害发生和结果中的作用大小等因素，依法确定行政机关的赔偿责任。"},{"i":8,"n":"第八条","txt":"当事人约定占用耕地建房、建窑、建坟、挖砂、采石、采矿、取土等，以及约定买卖、租赁建在耕地上的房屋等内容违反土地管理法第二条、第三十五条、第三十七条规定的，人民法院应当认定该约定无效。"},{"i":9,"n":"第九条","txt":"占用耕地建房、建窑、建坟、挖砂、采石、采矿、取土等，以及买卖、租赁建在耕地上的房屋的合同被认定无效的，在确定财产返还、折价补偿、赔偿损失时，人民法院应当按照诚信原则和公平原则，结合当事人的过错程度，合理确定各方应当承担的民事责任。"},{"i":10,"n":"第十条","txt":"违反法律规定，非法占用耕地导致破坏生态环境和资源保护，损害国家利益或者社会公共利益的，人民检察院可以依据民事诉讼法、行政诉讼法等法律提起公益诉讼。"},{"i":11,"n":"第十一条","txt":"违反土地管理法律、法规，具有下列情形之一的，应当认定为刑法第三百四十二条规定的非法占用耕地，改变被占用耕地用途，造成耕地毁坏："},{"i":12,"n":"第十二条","txt":"实施本规定第十一条规定的行为，具有下列情形之一的，应当认定为刑法第三百四十二条规定的“数量较大，造成耕地、林地等农用地大量毁坏”，对于黑土地另有规定的，从其规定："},{"i":13,"n":"第十三条","txt":"违反刑法第三百四十二条的规定，构成非法占用农用地罪，同时构成污染环境罪、非法采矿罪等犯罪的，依照处罚较重的规定定罪处罚。"},{"i":14,"n":"第十四条","txt":"单位实施非法占用耕地的犯罪，依照本规定的定罪量刑标准，对直接负责的主管人员和其他直接责任人员定罪处罚，并对单位判处罚金。"},{"i":15,"n":"第十五条","txt":"实施非法占用耕地的犯罪，具有下列情形之一的，从重处罚："},{"i":16,"n":"第十六条","txt":"实施非法占用耕地的犯罪，行为人积极进行修复治理，恢复种植条件的，可以依法从宽处罚。犯罪情节轻微不需要判处刑罚的，可以不起诉或者免予刑事处罚；情节显著轻微危害不大的，不作为犯罪处理。"},{"i":17,"n":"第十七条","txt":"对耕地负有监督管理职责的国家机关工作人员，滥用职权或者玩忽职守，致使公共财产、国家和人民利益遭受重大损失的，应当依照刑法第三百九十七条的规定，以滥用职权罪或者玩忽职守罪定罪处罚。"},{"i":18,"n":"第十八条","txt":"多次实施非法占用耕地的犯罪，依法应当追诉的，或者二年内多次实施非法占用耕地的行为未经处理的，数量、数额累计计算。"},{"i":19,"n":"第十九条","txt":"对于实施非法占用耕地的相关行为被不起诉、宣告无罪或者免予刑事处罚的行为人，依法应当给予行政处罚、政务处分或者其他处分的，依法移送有关主管机关处理。"},{"i":20,"n":"第二十条","txt":"人民法院执行涉及耕地的生效判决书、调解书时，应当将维持或者恢复耕地种植条件作为停止侵害、恢复原状、排除妨碍、消除危险的标准。必要时，人民法院可以委托相关机构对是否已经达到维持或者恢复耕地种植条件进行评估。"},{"i":21,"n":"第二十一条","txt":"本规定自2026年5月18日起施行。最高人民法院、最高人民检察院以前所作的司法解释与本规定不一致的，以本规定为准。"}],"zuigaorenminfayuanzuigaorenminjianchayuanguanyuzhi4105b7":[],"zuigaorenminfayuanzuigaorenminjianchayuanguanyuzhid35b53":[],"zuigaorenminfayuanzuigaorenminjianchayuanguanyuzhi2f69fa":[],"zuigaorenminfayuanzuigaorenminjianchayuanguanyuzhi799e21":[],"zuigaorenminfayuanzuigaorenminjianchayuanguanyuzhid90098":[],"zuigaorenminfayuanzuigaorenminjianchayuanguanyuzhia4ed74":[],"zuigaorenminfayuanzuigaorenminjianchayuanguanyuzhi4774dc":[],"zuigaorenminfayuanzuigaorenminjianchayuanguanyuzhie0b7be":[],"zuigaorenminfayuanzuigaorenminjianchayuanguanyushiefec2a":[],"zuigaorenminfayuanzuigaorenminjianchayuanguanyushi09d355":[{"i":1,"n":"第一条","txt":"刑事诉讼法第二百九十一条第一款规定的“贪污贿赂犯罪案件”，包括刑法分则第八章规定的贪污贿赂犯罪案件，以及其他章节中规定依照第八章的规定定罪处罚的犯罪案件。"},{"i":2,"n":"第二条","txt":"刑事诉讼法第二百九十一条第一款规定的需要及时进行审判，经最高人民检察院核准的严重“危害国家安全犯罪案件”，包括刑法分则第一章规定的危害国家安全犯罪案件和危害国家安全的其他犯罪案件。"},{"i":3,"n":"第三条","txt":"犯罪嫌疑人、被告人涉嫌犯数罪，其中部分犯罪符合刑事诉讼法第二百九十一条第一款规定的，可以对该部分犯罪案件适用缺席审判程序。"},{"i":4,"n":"第四条","txt":"人民检察院收到移送审查起诉的案件材料后，应当及时告知犯罪嫌疑人有权委托辩护人，并告知其近亲属有权代为委托辩护人。"},{"i":5,"n":"第五条","txt":"对依照刑事诉讼法第二百九十一条第一款的规定拟适用缺席审判程序的案件，人民检察院、人民法院应当重点审查以下内容："},{"i":6,"n":"第六条","txt":"对人民检察院依照刑事诉讼法第二百九十一条第一款的规定提起公诉的案件，人民法院审查后，应当按照下列情形分别处理："},{"i":7,"n":"第七条","txt":"对人民检察院依照刑事诉讼法第二百九十一条第一款的规定提起公诉的案件，人民法院立案后，应当将传票和起诉书副本送达被告人，传票应当载明被告人到案期限以及不按要求到案的法律后果等事项；应当将起诉书副本送达被告人近亲属，告知其有权代为委托辩护人、有权申请参加诉讼，并通知其敦促被告人归案。"},{"i":8,"n":"第八条","txt":"对人民检察院依照刑事诉讼法第二百九十一条第一款的规定提起公诉的案件，向被告人送达相关诉讼文书，应当通过有关国际条约规定的或者外交途径提出的司法协助方式，或者被告人所在地法律允许的其他方式进行。"},{"i":9,"n":"第九条","txt":"人民法院审理人民检察院依照刑事诉讼法第二百九十一条第一款的规定提起公诉的案件，被告人有权委托或者由其近亲属代为委托一至二名辩护人。委托律师担任辩护人的，应当委托具有中华人民共和国法律职业资格并依法取得执业证书的律师；从境外寄交、托交的授权委托书，应当符合相关规定。"},{"i":10,"n":"第十条","txt":"人民法院审理人民检察院依照刑事诉讼法第二百九十一条第一款的规定提起公诉的案件，被告人的近亲属申请参加诉讼的，应当在收到起诉书副本后、第一审开庭前提交与被告人关系的证明材料。对被告人的近亲属提出申请的，人民法院应当及时审查决定。"},{"i":11,"n":"第十一条","txt":"被告人及其近亲属在境外的，除依法不公开开庭审理的以外，人民法院确定开庭日期后，至迟在开庭三十日以前发布开庭公告。"},{"i":12,"n":"第十二条","txt":"人民法院审理人民检察院依照刑事诉讼法第二百九十一条第一款的规定提起公诉的案件，被告人的近亲属参加诉讼的，可以发表意见，出示证据，申请法庭通知证人、鉴定人等出庭，进行辩论，提出上诉。"},{"i":13,"n":"第十三条","txt":"人民法院开庭审理人民检察院依照刑事诉讼法第二百九十一条第一款的规定提起公诉的案件，按照下列程序进行："},{"i":14,"n":"第十四条","txt":"人民法院经缺席审理，作出有罪判决的，应当达到事实清楚，证据确实、充分的证明标准。"},{"i":15,"n":"第十五条","txt":"在缺席审判案件审理过程中，被告人到案的，人民法院应当裁定终止审理。人民检察院依照刑事诉讼法第一百七十六条的规定提起公诉的，人民法院依法受理后应当重新审理。"},{"i":16,"n":"第十六条","txt":"适用缺席审判程序作出的判决、裁定生效后，罪犯到案的，人民法院应当将罪犯交付执行刑罚。交付执行刑罚前，人民法院应当告知罪犯有权对判决、裁定提出异议。罪犯对判决、裁定有异议的，应当在被告知有权提出异议后十日以内提出。"},{"i":17,"n":"第十七条","txt":"人民检察院认为犯罪事实已经查清，证据确实、充分，依法应当追究刑事责任的，可以不经违法所得没收程序，直接依照刑事诉讼法第二百九十一条的规定提起公诉，人民法院经审查认为符合缺席审判程序适用条件的，依法审理作出裁判。"},{"i":18,"n":"第十八条","txt":"刑事诉讼法第二百九十六条规定的“被告人患有严重疾病无法出庭”，是指被告人患有严重疾病导致其不能正常感知、理解、认识、表达而缺乏受审能力，无法出庭受审。"},{"i":19,"n":"第十九条","txt":"患有严重疾病被告人在缺席审理期间死亡或者逃匿，符合违法所得没收程序适用条件的，人民检察院应当及时向人民法院提出没收违法所得申请。"},{"i":20,"n":"第二十条","txt":"依照刑事诉讼法第二百九十六条的规定进行缺席审理，被告人恢复受审能力的，人民法院应当按照下列情形分别作出处理："},{"i":21,"n":"第二十一条","txt":"人民法院受理案件后被告人死亡的，应当裁定终止审理；但有证据证明被告人无罪，经缺席审理确认无罪的，应当判决宣告被告人无罪。"},{"i":22,"n":"第二十二条","txt":"人民法院按照审判监督程序重新审判的案件，被告人死亡的，可以缺席审理。经缺席审理确认无罪的，应当判决宣告被告人无罪；虽然构成犯罪，但原判量刑畸重的，应当依法作出判决。"},{"i":23,"n":"第二十三条","txt":"本规定所称“无罪”，包括案件事实清楚，证据确实、充分，依据法律认定被告人无罪的情形，以及证据不足，不能认定被告人有罪等情形。"},{"i":24,"n":"第二十四条","txt":"本规定自2026年5月22日起施行。之前发布的司法解释和规范性文件与本规定不一致的，以本规定为准。"}],"zuigaorenminfayuanzuigaorenminjianchayuanguanyushi17a650":[{"i":1,"n":"第一条","txt":"下列犯罪案件，应当认定为刑事诉讼法第二百八十条第一款规定的“犯罪案件”："},{"i":2,"n":"第二条","txt":"在省、自治区、直辖市或者全国范围内具有较大影响，或者犯罪嫌疑人、被告人逃匿境外的，应当认定为刑事诉讼法第二百八十条第一款规定的“重大”。"},{"i":3,"n":"第三条","txt":"犯罪嫌疑人、被告人为逃避侦查和刑事追究潜逃、隐匿，或者在刑事诉讼过程中脱逃的，应当认定为刑事诉讼法第二百八十条第一款规定的“逃匿”。"},{"i":4,"n":"第四条","txt":"犯罪嫌疑人、被告人死亡，依照刑法规定应当追缴其违法所得及其他涉案财产的，人民检察院可以向人民法院提出没收违法所得的申请。"},{"i":5,"n":"第五条","txt":"公安机关发布通缉令或者公安部通过国际刑警组织发布红色国际通报，应当认定为刑事诉讼法第二百八十条第一款规定的“通缉”。"},{"i":6,"n":"第六条","txt":"通过实施犯罪直接或者间接产生、获得的任何财产，应当认定为刑事诉讼法第二百八十条第一款规定的“违法所得”。"},{"i":7,"n":"第七条","txt":"刑事诉讼法第二百八十一条第三款规定的“利害关系人”包括犯罪嫌疑人、被告人的近亲属和其他对申请没收的财产主张权利的自然人和单位。"},{"i":8,"n":"第八条","txt":"人民检察院向人民法院提出没收违法所得的申请，应当制作没收违法所得申请书。"},{"i":9,"n":"第九条","txt":"对于没收违法所得的申请，人民法院应当在三十日内审查完毕，并根据以下情形分别处理："},{"i":10,"n":"第十条","txt":"同时具备以下情形的，应当认定为本规定第九条规定的“有证据证明有犯罪事实”："},{"i":11,"n":"第十一条","txt":"人民法院受理没收违法所得的申请后，应当在十五日内发布公告，公告期为六个月。公告期间不适用中止、中断、延长的规定。"},{"i":12,"n":"第十二条","txt":"公告应当在全国公开发行的报纸、信息网络等媒体和最高人民法院的官方网站刊登、发布，并在人民法院公告栏张贴。必要时，公告可以在犯罪地、犯罪嫌疑人、被告人居住地或者被申请没收财产所在地张贴。公告最后被刊登、发布、张贴日期为公告日期。人民法院张贴公告的，应当采取拍照、录像等方式记录张贴过程。"},{"i":13,"n":"第十三条","txt":"利害关系人申请参加诉讼的，应当在公告期间内提出，并提供与犯罪嫌疑人、被告人关系的证明材料或者证明其可以对违法所得及其他涉案财产主张权利的证据材料。"},{"i":14,"n":"第十四条","txt":"人民法院在公告期满后由合议庭对没收违法所得申请案件进行审理。"},{"i":15,"n":"第十五条","txt":"出庭的检察人员应当宣读没收违法所得申请书，并在法庭调查阶段就申请没收的财产属于违法所得及其他涉案财产等相关事实出示、宣读证据。"},{"i":16,"n":"第十六条","txt":"人民法院经审理认为，申请没收的财产属于违法所得及其他涉案财产的，除依法应当返还被害人的以外，应当予以没收；申请没收的财产不属于违法所得或者其他涉案财产的，应当裁定驳回申请，解除查封、扣押、冻结措施。"},{"i":17,"n":"第十七条","txt":"申请没收的财产具有高度可能属于违法所得及其他涉案财产的，应当认定为本规定第十六条规定的“申请没收的财产属于违法所得及其他涉案财产”。"},{"i":18,"n":"第十八条","txt":"利害关系人非因故意或者重大过失在第一审期间未参加诉讼，在第二审期间申请参加诉讼的，人民法院应当准许，并发回原审人民法院重新审判。"},{"i":19,"n":"第十九条","txt":"犯罪嫌疑人、被告人逃匿境外，委托诉讼代理人申请参加诉讼，且违法所得或者其他涉案财产所在地国（区）主管机关明确提出意见予以支持的，人民法院可以准许。"},{"i":20,"n":"第二十条","txt":"人民检察院、利害关系人对第一审裁定认定的事实、证据没有争议的，第二审人民法院可以不开庭审理。"},{"i":21,"n":"第二十一条","txt":"第二审人民法院对不服第一审裁定的上诉、抗诉案件，经审理，应当按照下列情形分别处理："},{"i":22,"n":"第二十二条","txt":"违法所得或者其他涉案财产在境外的，负责立案侦查的公安机关、人民检察院等侦查机关应当制作查封、扣押、冻结的法律文书以及协助执行查封、扣押、冻结的请求函，层报公安、检察院等各系统最高上级机关后，由公安、检察院等各系统最高上级机关依照刑事司法协助条约、多边公约，或者按照对等互惠原则，向违法所得或者其他涉案财产所在地国（区）的主管机关请求协助执行。"},{"i":23,"n":"第二十三条","txt":"违法所得或者其他涉案财产在境外，受理没收违法所得申请案件的人民法院经审理裁定没收的，应当制作没收令以及协助执行没收令的请求函，层报最高人民法院后，由最高人民法院依照刑事司法协助条约、多边公约，或者按照对等互惠原则，向违法所得或者其他涉案财产所在地国（区）的主管机关请求协助执行。"},{"i":24,"n":"第二十四条","txt":"单位实施本规定第一条规定的犯罪后被撤销、注销，单位直接负责的主管人员和其他直接责任人员逃匿、死亡，导致案件无法适用刑事诉讼普通程序进行审理的，依照本规定第四条的规定处理。"},{"i":25,"n":"第二十五条","txt":"本规定自2017年1月5日起施行。之前发布的司法解释与本规定不一致的，以本规定为准。"}],"zuigaorenminfayuanrenminfayuanduiwaiweituosifajian69d85b":[{"i":1,"n":"第一条","txt":"为规范人民法院对外委托和组织司法鉴定工作，根据《人民法院司法鉴定工作暂行规定》，制定本办法。"},{"i":2,"n":"第二条","txt":"人民法院司法鉴定机构负责统一对外委托和组织司法鉴定。未设司法鉴定机构的人民法院，可在司法行政管理部门配备专职司法鉴定人员，并由司法行政管理部门代行对外委托司法鉴定的职责。"},{"i":3,"n":"第三条","txt":"人民法院司法鉴定机构建立社会鉴定机构和鉴定人（以下简称鉴定人）名册，根据鉴定对象对专业技术的要求，随机选择和委托鉴定人进行司法鉴定。"},{"i":4,"n":"第四条","txt":"自愿接受人民法院委托从事司法鉴定，申请进入人民法院司法鉴定人名册的社会鉴定、检测、评估机构，应当向人民法院司法鉴定机构提交申请书和以下材料："},{"i":5,"n":"第五条","txt":"以个人名义自愿接受人民法院委托从事司法鉴定，申请进入人民法院司法鉴定人名册的专业技术人员，应当向人民法院司法鉴定机构提交申请书和以下材料："},{"i":6,"n":"第六条","txt":"人民法院司法鉴定机构应当对提出申请的鉴定人进行全面审查，择优确定对外委托和组织司法鉴定的鉴定人候选名单。"},{"i":7,"n":"第七条","txt":"申请进入地方人民法院鉴定人名册的单位和个人，其入册资格由有关人民法院司法鉴定机构审核，报上一级人民法院司法鉴定机构批准，并报最高人民法院司法鉴定机构备案。"},{"i":8,"n":"第八条","txt":"经批准列入人民法院司法鉴定人名册的鉴定人，在《人民法院报》予以公告。"},{"i":9,"n":"第九条","txt":"已列入名册的鉴定人应当接受有关人民法院司法鉴定机构的年度审核，并提交以下材料："},{"i":10,"n":"第十条","txt":"人民法院司法鉴定机构依据尊重当事人选择和人民法院指定相结合的原则，组织诉讼双方当事人进行司法鉴定的对外委托。"},{"i":11,"n":"第十一条","txt":"司法鉴定所涉及的专业未纳入名册时，人民法院司法鉴定机构可以从社会相关专业中，择优选定受委托单位或专业人员进行鉴定。如果被选定的单位或专业人员需要进入鉴定人名册的，仍应当呈报上一级人民法院司法鉴定机构批准。"},{"i":12,"n":"第十二条","txt":"遇有鉴定人应当回避等情形时，有关人民法院司法鉴定机构应当重新选择鉴定人。"},{"i":13,"n":"第十三条","txt":"人民法院司法鉴定机构对外委托鉴定的，应当指派专人负责协调，主动了解鉴定的有关情况，及时处理可能影响鉴定的问题。"},{"i":14,"n":"第十四条","txt":"接受委托的鉴定人认为需要补充鉴定材料时，如果由申请鉴定的当事人提供确有困难的，可以向有关人民法院司法鉴定机构提出请求，由人民法院决定依据职权采集鉴定材料。"},{"i":15,"n":"第十五条","txt":"鉴定人应当依法履行出庭接受质询的义务。人民法院司法鉴定机构应当协调鉴定人做好出庭工作。"},{"i":16,"n":"第十六条","txt":"列入名册的鉴定人有不履行义务，违反司法鉴定有关规定的，由有关人民法院视情节取消入册资格，并在《人民法院报》公告。"}],"zuigaorenminfayuanguanyuqiyepochanfashixingshishan50c534":[{"i":1,"n":"第一条","txt":"债权人、债务人或者出资人向人民法院提出重整或者和解申请，符合下列条件之一的，人民法院应予受理："},{"i":2,"n":"第二条","txt":"清算组在企业破产法施行前未通知或者答复未履行完毕合同的对方当事人解除或者继续履行合同的，从企业破产法施行之日起计算，在该法第十八条第一款规定的期限内未通知或者答复的，视为解除合同。"},{"i":3,"n":"第三条","txt":"已经成立清算组的，企业破产法施行后，人民法院可以指定该清算组为管理人。"},{"i":4,"n":"第四条","txt":"债权人主张对债权债务抵销的，应当符合企业破产法第四十条规定的情形；但企业破产法施行前，已经依据有关法律规定抵销的除外。"},{"i":5,"n":"第五条","txt":"对于尚未清偿的破产费用，应当按企业破产法第四十一条和第四十二条的规定区分破产费用和共益债务，并依据企业破产法第四十三条的规定清偿。"},{"i":6,"n":"第六条","txt":"人民法院尚未宣告债务人破产的，应当适用企业破产法第四十六条的规定确认债权利息；已经宣告破产的，依据企业破产法施行前的法律规定确认债权利息。"},{"i":7,"n":"第七条","txt":"债权人已经向人民法院申报债权的，由人民法院将相关申报材料移交给管理人；尚未申报的，债权人应当直接向管理人申报。"},{"i":8,"n":"第八条","txt":"债权人未在人民法院确定的债权申报期内向人民法院申报债权的，可以依据企业破产法第五十六条的规定补充申报。"},{"i":9,"n":"第九条","txt":"债权人对债权表记载债权有异议，向受理破产申请的人民法院提起诉讼的，人民法院应当依据企业破产法第二十一条和第五十八条的规定予以受理。但人民法院对异议债权已经作出裁决的除外。"},{"i":10,"n":"第十条","txt":"债务人的职工就清单记载有异议，向受理破产申请的人民法院提起诉讼的，人民法院应当依据企业破产法第二十一条和第四十八条的规定予以受理。但人民法院对异议债权已经作出裁决的除外。"},{"i":11,"n":"第十一条","txt":"有财产担保的债权人未放弃优先受偿权利的，对于企业破产法第六十一条第一款第七项、第十项规定以外的事项享有表决权。但该债权人对于企业破产法施行前已经表决的事项主张行使表决权，或者以其未行使表决权为由请求撤销债权人会议决议的，人民法院不予支持。"},{"i":12,"n":"第十二条","txt":"债权人认为债权人会议的决议违反法律规定，损害其利益，向人民法院请求撤销该决议，裁定尚未作出的，人民法院应当依据企业破产法第六十四条的规定作出裁定。"},{"i":13,"n":"第十三条","txt":"债权人对于财产分配方案的裁定不服，已经申诉的，由上一级人民法院依据申诉程序继续审理；企业破产法施行后提起申诉的，人民法院应当告知其依据企业破产法第六十六条的规定申请复议。"},{"i":14,"n":"第十四条","txt":"企业破产法施行后，破产人的职工依据企业破产法第一百三十二条的规定主张权利的，人民法院应予支持。"},{"i":15,"n":"第十五条","txt":"破产人所欠董事、监事和高级管理人员的工资，应当依据企业破产法第一百一十三条第三款的规定予以调整。"},{"i":16,"n":"第十六条","txt":"本规定施行前本院作出的有关司法解释与本规定相抵触的，人民法院审理尚未审结的企业破产案件不再适用。"}],"zuigaorenminfayuanguanyushanghaijinrongfayuananjia2d593e":[{"i":1,"n":"第一条","txt":"上海金融法院管辖上海市辖区内应由中级人民法院受理的下列第一审金融民商事案件："},{"i":2,"n":"第二条","txt":"下列金融纠纷案件，由上海金融法院管辖："},{"i":3,"n":"第三条","txt":"在上海证券交易所科创板上市公司的证券发行纠纷、证券承销合同纠纷、证券上市保荐合同纠纷、证券上市合同纠纷和证券欺诈责任纠纷等第一审民商事案件，由上海金融法院管辖。"},{"i":4,"n":"第四条","txt":"以上海证券交易所为被告或者第三人的与证券交易所监管职能相关的第一审金融民商事和涉金融行政案件，由上海金融法院管辖。"},{"i":5,"n":"第五条","txt":"以住所地在上海市并依法设立的金融基础设施机构为被告或者第三人的与其履行职责相关的第一审金融民商事案件，由上海金融法院管辖。"},{"i":6,"n":"第六条","txt":"上海市辖区内应由中级人民法院受理的对金融监管机构以及法律、法规、规章授权的组织因履行金融监管职责作出的行政行为不服提起诉讼的第一审涉金融行政案件，由上海金融法院管辖。"},{"i":7,"n":"第七条","txt":"当事人对上海市基层人民法院作出的涉及本规定第一条第一至三项的第一审金融民商事案件和涉金融行政案件判决、裁定提起的上诉案件和申请再审案件，由上海金融法院审理。"},{"i":8,"n":"第八条","txt":"上海市辖区内应由中级人民法院受理的金融民商事案件、涉金融行政案件的再审案件，由上海金融法院审理。"},{"i":9,"n":"第九条","txt":"上海金融法院作出的第一审民商事案件和涉金融行政案件生效裁判，以及上海市辖区内应由中级人民法院执行的涉金融民商事纠纷的仲裁裁决，由上海金融法院执行。"},{"i":10,"n":"第十条","txt":"当事人对上海金融法院作出的第一审判决、裁定提起的上诉案件，由上海市高级人民法院审理。"},{"i":11,"n":"第十一条","txt":"上海市各中级人民法院在上海金融法院成立前已经受理但尚未审结的金融民商事案件和涉金融行政案件，由该中级人民法院继续审理。"},{"i":12,"n":"第十二条","txt":"本规定自2018年8月10日起施行。"}],"zuigaorenminfayuanguanyuyangezhixinganjianshenliqi731d6b":[{"i":1,"n":"第一条","txt":"适用普通程序审理的第一审刑事公诉案件、被告人被羁押的第一审刑事自诉案件和第二审刑事公诉、刑事自诉案件的期限为一个月，至迟不得超过一个半月；附带民事诉讼案件的审理期限，经本院院长批准，可以延长两个月。有刑事诉讼法第一百二十六条规定情形之一的，经省、自治区、直辖市高级人民法院批准或者决定，审理期限可以再延长一个月；最高人民法院受理的刑事上诉、刑事抗诉案件，经最高人民法院决定，审理期限可以再延长一个月。"},{"i":2,"n":"第二条","txt":"适用普通程序审理的第一审民事案件，期限为六个月；有特殊情况需要延长的，经本院院长批准，可以延长六个月，还需延长的，报请上一级人民法院批准，可以再延长三个月。"},{"i":3,"n":"第三条","txt":"审理第一审行政案件的期限为三个月；有特殊情况需要延长的，经高级人民法院批准可以延长三个月。高级人民法院审理第一审案件需要延长期限的，由最高人民法院批准，可以延长三个月。"},{"i":4,"n":"第四条","txt":"按照审判监督程序重新审理的刑事案件的期限为三个月；需要延长期限的，经本院院长批准，可以延长三个月。"},{"i":5,"n":"第五条","txt":"执行案件应当在立案之日起六个月内执结，非诉执行案件应当在立案之日起三个月内执结；有特殊情况需要延长的，经本院院长批准，可以延长三个月，还需延长的，层报高级人民法院备案。"},{"i":6,"n":"第六条","txt":"第一审人民法院收到起诉书（状）或者执行申请书后，经审查认为符合受理条件的应当在七日内立案；收到自诉人自诉状或者口头告诉的，经审查认为符合自诉案件受理条件的应当在十五日内立案。"},{"i":7,"n":"第七条","txt":"立案机构应当在决定立案的三日内将案卷材料移送审判庭。"},{"i":8,"n":"第八条","txt":"案件的审理期限从立案次日起计算。"},{"i":9,"n":"第九条","txt":"下列期间不计入审理、执行期限："},{"i":10,"n":"第十条","txt":"人民法院判决书宣判、裁定书宣告或者调解书送达最后一名当事人的日期为结案时间。如需委托宣判、送达的，委托宣判、送达的人民法院应当在审限届满前将判决书、裁定书、调解书送达受托人民法院。受托人民法院应当在收到委托书后七日内送达。"},{"i":11,"n":"第十一条","txt":"刑事公诉案件、被告人被羁押的自诉案件，需要延长审理期限的，应当在审理期限届满七日以前，向高级人民法院提出申请；被告人未被羁押的刑事自诉案件，需要延长审理期限的，应当在审理期限届满十日前向本院院长提出申请。"},{"i":12,"n":"第十二条","txt":"民事案件应当在审理期限届满十日前向本院院长提出申请；还需延长的，应当在审理期限届满十日前向上一级人民法院提出申请。"},{"i":13,"n":"第十三条","txt":"行政案件应当在审理期限届满十日前向高级人民法院或者最高人民法院提出申请。"},{"i":14,"n":"第十四条","txt":"对于下级人民法院申请延长办案期限的报告，上级人民法院应当在审理期限届满三日前作出决定，并通知提出申请延长审理期限的人民法院。"},{"i":15,"n":"第十五条","txt":"被告人、自诉人、附带民事诉讼的原告人和被告人通过第一审人民法院提出上诉的刑事案件，第一审人民法院应当在上诉期限届满后三日内将上诉状连同案卷、证据移送第二审人民法院。被告人、自诉人、附带民事诉讼的原告人和被告人直接向上级人民法院提出上诉的刑事案件，第一审人民法院应当在接到第二审人民法院移交的上诉状后三日内将案卷、证据移送上一级人民法院。"},{"i":16,"n":"第十六条","txt":"人民检察院抗诉的刑事二审案件，第一审人民法院应当在上诉、抗诉期届满后三日内将抗诉书连同案卷、证据移送第二审人民法院。"},{"i":17,"n":"第十七条","txt":"当事人提出上诉的二审民事、行政案件，第一审人民法院收到上诉状，应当在五日内将上诉状副本送达对方当事人。人民法院收到答辩状，应当在五日内将副本送达上诉人。"},{"i":18,"n":"第十八条","txt":"第二审人民法院立案时发现上诉案件材料不齐全的，应当在两日内通知第一审人民法院。第一审人民法院应当在接到第二审人民法院的通知后五日内补齐。"},{"i":19,"n":"第十九条","txt":"下级人民法院接到上级人民法院调卷通知后，应当在五日内将全部案卷和证据移送，至迟不超过十日。"},{"i":20,"n":"第二十条","txt":"各级人民法院应当将审理案件期限情况作为审判管理的重要内容，加强对案件审理期限的管理、监督和检查。"},{"i":21,"n":"第二十一条","txt":"各级人民法院应当建立审理期限届满前的催办制度。"},{"i":22,"n":"第二十二条","txt":"各级人民法院应当建立案件审理期限定期通报制度。对违反诉讼法规定，超过审理期限或者违反本规定的情况进行通报。"},{"i":23,"n":"第二十三条","txt":"审判人员故意拖延办案，或者因过失延误办案，造成严重后果的，依照《人民法院审判纪律处分办法（试行）》第五十九条的规定予以处分。"},{"i":24,"n":"第二十四条","txt":"本规定发布前有关审理期限规定与本规定不一致的，以本规定为准。"}],"zuigaorenminfayuanguanyuyangeguifanminshangshianji7ac2fa":[{"i":1,"n":"第一条","txt":"人民法院审理民商事案件时，应当严格遵守法律及司法解释有关审限的规定。适用普通程序审理的第一审案件，审限为六个月；适用简易程序审理的第一审案件，审限为三个月。审理对判决的上诉案件，审限为三个月；审理对裁定的上诉案件，审限为三十日。"},{"i":2,"n":"第二条","txt":"民事诉讼法第一百四十六条第四项规定的“其他应当延期的情形”，是指因不可抗力或者意外事件导致庭审无法正常进行的情形。"},{"i":3,"n":"第三条","txt":"人民法院应当严格限制延期开庭审理次数。适用普通程序审理民商事案件，延期开庭审理次数不超过两次；适用简易程序以及小额速裁程序审理民商事案件，延期开庭审理次数不超过一次。"},{"i":4,"n":"第四条","txt":"基层人民法院及其派出的法庭审理事实清楚、权利义务关系明确、争议不大的简单民商事案件，适用简易程序。"},{"i":5,"n":"第五条","txt":"人民法院开庭审理民商事案件后，认为需要延期开庭审理的，应当依法告知当事人下次开庭的时间。两次开庭间隔时间不得超过一个月，但因不可抗力或当事人同意的除外。"},{"i":6,"n":"第六条","txt":"独任审判员或者合议庭适用民事诉讼法第一百四十六条第四项规定决定延期开庭的，应当报本院院长批准。"},{"i":7,"n":"第七条","txt":"人民法院应当将案件的立案时间、审理期限，扣除、延长、重新计算审限，延期开庭审理的情况及事由，按照《最高人民法院关于人民法院通过互联网公开审判流程信息的规定》及时向当事人及其法定代理人、诉讼代理人公开。当事人及其法定代理人、诉讼代理人有异议的，可以依法向受理案件的法院申请监督。"},{"i":8,"n":"第八条","txt":"故意违反法律、审判纪律、审判管理规定拖延办案，或者因过失延误办案，造成严重后果的，依照《人民法院工作人员处分条例》第四十七条的规定予以处分。"},{"i":9,"n":"第九条","txt":"本规定自2018年4月26日起施行；最高人民法院此前发布的司法解释及规范性文件与本规定不一致的，以本规定为准。"}],"zuigaorenminfayuanguanyuzhongguogongminshenqingcheed80fe":[{"i":1,"n":"第一条","txt":"对与我国没有订立司法协助协议的外国法院作出的离婚判决，中国籍当事人可以根据本规定向人民法院申请承认该外国法院的离婚判决。"},{"i":2,"n":"第二条","txt":"外国法院离婚判决中的夫妻财产分割、生活费负担、子女抚养方面判决的承认执行，不适用本规定。"},{"i":3,"n":"第三条","txt":"向人民法院申请承认外国法院的离婚判决，申请人应提出书面申请书，并须附有外国法院离婚判决书正本及经证明无误的中文译本。否则，不予受理。"},{"i":4,"n":"第四条","txt":"申请书应记明以下事项："},{"i":5,"n":"第五条","txt":"申请由申请人住所地中级人民法院受理。申请人住所地与经常居住地不一致的，由经常居住地中级人民法院受理。"},{"i":6,"n":"第六条","txt":"人民法院接到申请书，经审查，符合本规定的受理条件的，应当在7日内立案；不符合的，应当在7日内通知申请人不予受理，并说明理由。"},{"i":7,"n":"第七条","txt":"人民法院审查承认外国法院离婚判决的申请，由三名审判员组成合议庭进行，作出的裁定不得上诉。"},{"i":8,"n":"第八条","txt":"人民法院受理申请后，对于外国法院离婚判决书没有指明已生效或生效时间的，应责令申请人提交作出判决的法院出具的判决已生效的证明文件。"},{"i":9,"n":"第九条","txt":"外国法院作出离婚判决的原告为申请人的，人民法院应责令其提交作出判决的外国法院已合法传唤被告出庭的有关证明文件。"},{"i":10,"n":"第十条","txt":"按照第八条、第九条要求提供的证明文件，应经该外国公证部门公证和我国驻该国使、领馆认证，或者履行中华人民共和国与该所在国订立的有关条约中规定的证明手续。同时应由申请人提供经证明无误的中文译本。"},{"i":11,"n":"第十一条","txt":"居住在我国境内的外国法院离婚判决的被告为申请人，提交第八条、第十条所要求的证明文件和公证、认证有困难的，如能提交外国法院的应诉通知或出庭传票的，可推定外国法院离婚判决书为真实和已经生效。"},{"i":12,"n":"第十二条","txt":"经审查，外国法院的离婚判决具有下列情形之一的，不予承认："},{"i":13,"n":"第十三条","txt":"对外国法院的离婚判决的承认，以裁定方式作出。没有第十二条规定的情形的，裁定承认其法律效力；具有第十二条规定的情形之一的，裁定驳回申请人的申请。"},{"i":14,"n":"第十四条","txt":"裁定书以“中华人民共和国××中级人民法院”名义作出，由合议庭成员署名，加盖人民法院印章。"},{"i":15,"n":"第十五条","txt":"裁定书一经送达，即发生法律效力。"},{"i":16,"n":"第十六条","txt":"申请承认外国法院的离婚判决，申请人应向人民法院交纳案件受理费人民币100元。"},{"i":17,"n":"第十七条","txt":"申请承认外国法院的离婚判决，委托他人代理的，必须向人民法院提交由委托人签名或盖章的授权委托书。委托人在国外出具的委托书，必须经我国驻该国的使、领馆证明，或者履行中华人民共和国与该所在国订立的有关条约中规定的证明手续。"},{"i":18,"n":"第十八条","txt":"人民法院受理离婚诉讼后，原告一方变更请求申请承认外国法院离婚判决，或者被告一方另提出承认外国法院离婚判决申请的，其申请均不受理。"},{"i":19,"n":"第十九条","txt":"人民法院受理承认外国法院离婚判决的申请后，对方当事人向人民法院起诉离婚的，人民法院不予受理。"},{"i":20,"n":"第二十条","txt":"当事人之间的婚姻虽经外国法院判决，但未向人民法院申请承认的，不妨碍当事人一方另行向人民法院提出离婚诉讼。"},{"i":21,"n":"第二十一条","txt":"申请人的申请为人民法院受理后，申请人可以撤回申请，人民法院以裁定准予撤回。申请人撤回申请后，不得再提出申请，但可以另向人民法院起诉离婚。"},{"i":22,"n":"第二十二条","txt":"申请人的申请被驳回后，不得再提出申请，但可以另行向人民法院起诉离婚。"}],"zuigaorenminfayuanguanyuhulianwangfayuanshenlianjiedadde":[{"i":1,"n":"第一条","txt":"互联网法院采取在线方式审理案件，案件的受理、送达、调解、证据交换、庭前准备、庭审、宣判等诉讼环节一般应当在线上完成。"},{"i":2,"n":"第二条","txt":"北京、广州、杭州互联网法院集中管辖所在市的辖区内应当由基层人民法院受理的下列第一审案件："},{"i":3,"n":"第三条","txt":"当事人可以在本规定第二条确定的合同及其他财产权益纠纷范围内，依法协议约定与争议有实际联系地点的互联网法院管辖。"},{"i":4,"n":"第四条","txt":"当事人对北京互联网法院作出的判决、裁定提起上诉的案件，由北京市第四中级人民法院审理，但互联网著作权权属纠纷和侵权纠纷、互联网域名纠纷的上诉案件，由北京知识产权法院审理。"},{"i":5,"n":"第五条","txt":"互联网法院应当建设互联网诉讼平台（以下简称诉讼平台），作为法院办理案件和当事人及其他诉讼参与人实施诉讼行为的专用平台。通过诉讼平台作出的诉讼行为，具有法律效力。"},{"i":6,"n":"第六条","txt":"当事人及其他诉讼参与人使用诉讼平台实施诉讼行为的，应当通过证件证照比对、生物特征识别或者国家统一身份认证平台认证等在线方式完成身份认证，并取得登录诉讼平台的专用账号。"},{"i":7,"n":"第七条","txt":"互联网法院在线接收原告提交的起诉材料，并于收到材料后七日内，在线作出以下处理："},{"i":8,"n":"第八条","txt":"互联网法院受理案件后，可以通过原告提供的手机号码、传真、电子邮箱、即时通讯账号等，通知被告、第三人通过诉讼平台进行案件关联和身份验证。"},{"i":9,"n":"第九条","txt":"互联网法院组织在线证据交换的，当事人应当将在线电子数据上传、导入诉讼平台，或者将线下证据通过扫描、翻拍、转录等方式进行电子化处理后上传至诉讼平台进行举证，也可以运用已经导入诉讼平台的电子数据证明自己的主张。"},{"i":10,"n":"第十条","txt":"当事人及其他诉讼参与人通过技术手段将身份证明、营业执照副本、授权委托书、法定代表人身份证明等诉讼材料，以及书证、鉴定意见、勘验笔录等证据材料进行电子化处理后提交的，经互联网法院审核通过后，视为符合原件形式要求。对方当事人对上述材料真实性提出异议且有合理理由的，互联网法院应当要求当事人提供原件。"},{"i":11,"n":"第十一条","txt":"当事人对电子数据真实性提出异议的，互联网法院应当结合质证情况，审查判断电子数据生成、收集、存储、传输过程的真实性，并着重审查以下内容："},{"i":12,"n":"第十二条","txt":"互联网法院采取在线视频方式开庭。存在确需当庭查明身份、核对原件、查验实物等特殊情形的，互联网法院可以决定在线下开庭，但其他诉讼环节仍应当在线完成。"},{"i":13,"n":"第十三条","txt":"互联网法院可以视情决定采取下列方式简化庭审程序："},{"i":14,"n":"第十四条","txt":"互联网法院根据在线庭审特点，适用《中华人民共和国人民法院法庭规则》的有关规定。除经查明确属网络故障、设备损坏、电力中断或者不可抗力等原因外，当事人不按时参加在线庭审的，视为“拒不到庭”，庭审中擅自退出的，视为“中途退庭”，分别按照《中华人民共和国民事诉讼法》《中华人民共和国行政诉讼法》及相关司法解释的规定处理。"},{"i":15,"n":"第十五条","txt":"经当事人同意，互联网法院应当通过中国审判流程信息公开网、诉讼平台、手机短信、传真、电子邮件、即时通讯账号等电子方式送达诉讼文书及当事人提交的证据材料等。"},{"i":16,"n":"第十六条","txt":"互联网法院进行电子送达，应当向当事人确认电子送达的具体方式和地址，并告知电子送达的适用范围、效力、送达地址变更方式以及其他需告知的送达事项。"},{"i":17,"n":"第十七条","txt":"互联网法院向受送达人主动提供或者确认的电子地址进行送达的，送达信息到达受送达人特定系统时，即为送达。"},{"i":18,"n":"第十八条","txt":"对需要进行公告送达的事实清楚、权利义务关系明确的简单民事案件，互联网法院可以适用简易程序审理。"},{"i":19,"n":"第十九条","txt":"互联网法院在线审理的案件，审判人员、法官助理、书记员、当事人及其他诉讼参与人等通过在线确认、电子签章等在线方式对调解协议、笔录、电子送达凭证及其他诉讼材料予以确认的，视为符合《中华人民共和国民事诉讼法》有关“签名”的要求。"},{"i":20,"n":"第二十条","txt":"互联网法院在线审理的案件，可以在调解、证据交换、庭审、合议等诉讼环节运用语音识别技术同步生成电子笔录。电子笔录以在线方式核对确认后，与书面笔录具有同等法律效力。"},{"i":21,"n":"第二十一条","txt":"互联网法院应当利用诉讼平台随案同步生成电子卷宗，形成电子档案。案件纸质档案已经全部转化为电子档案的，可以以电子档案代替纸质档案进行上诉移送和案卷归档。"},{"i":22,"n":"第二十二条","txt":"当事人对互联网法院审理的案件提起上诉的，第二审法院原则上采取在线方式审理。第二审法院在线审理规则参照适用本规定。"},{"i":23,"n":"第二十三条","txt":"本规定自2018年9月7日起施行。最高人民法院之前发布的司法解释与本规定不一致的，以本规定为准。"}],"zuigaorenminfayuanguanyuhulianwangfayuananjianguan72e53d":[{"i":1,"n":"第一条","txt":"互联网法院集中管辖所在市辖区内应当由基层人民法院受理的下列第一审案件："},{"i":2,"n":"第二条","txt":"对于本规定第一条确定的合同及其他财产权益民事纠纷，当事人可以依法协议约定与争议有实际联系地点的互联网法院管辖。"},{"i":3,"n":"第三条","txt":"当事人对互联网法院作出的判决、裁定提起上诉的案件，由互联网法院所在地的中级人民法院审理。所在地设有多个中级人民法院的，由高级人民法院指定的中级人民法院审理。"},{"i":4,"n":"第四条","txt":"本规定自2025年11月1日起施行。本规定施行前已经受理的案件由原受理人民法院继续审理。"}],"zuigaorenminfayuanguanyurenminfayuanbanlizhongcaic139459":[{"i":1,"n":"第一条","txt":"本规定所称的仲裁裁决执行案件，是指当事人申请人民法院执行仲裁机构依据仲裁法作出的仲裁裁决或者仲裁调解书的案件。"},{"i":2,"n":"第二条","txt":"当事人对仲裁机构作出的仲裁裁决或者仲裁调解书申请执行的，由被执行人住所地或者被执行的财产所在地的中级人民法院管辖。"},{"i":3,"n":"第三条","txt":"仲裁裁决或者仲裁调解书执行内容具有下列情形之一导致无法执行的，人民法院可以裁定驳回执行申请；导致部分无法执行的，可以裁定驳回该部分的执行申请；导致部分无法执行且该部分与其他部分不可分的，可以裁定驳回执行申请。"},{"i":4,"n":"第四条","txt":"对仲裁裁决主文或者仲裁调解书中的文字、计算错误以及仲裁庭已经认定但在裁决主文中遗漏的事项，可以补正或说明的，人民法院应当书面告知仲裁庭补正或说明，或者向仲裁机构调阅仲裁案卷查明。仲裁庭不补正也不说明，且人民法院调阅仲裁案卷后执行内容仍然不明确具体无法执行的，可以裁定驳回执行申请。"},{"i":5,"n":"第五条","txt":"申请执行人对人民法院依照本规定第三条、第四条作出的驳回执行申请裁定不服的，可以自裁定送达之日起十日内向上一级人民法院申请复议。"},{"i":6,"n":"第六条","txt":"仲裁裁决或者仲裁调解书确定交付的特定物确已毁损或者灭失的，依照《最高人民法院关于适用〈中华人民共和国民事诉讼法〉的解释》第四百九十四条的规定处理。"},{"i":7,"n":"第七条","txt":"被执行人申请撤销仲裁裁决并已由人民法院受理的，或者被执行人、案外人对仲裁裁决执行案件提出不予执行申请并提供适当担保的，执行法院应当裁定中止执行。中止执行期间，人民法院应当停止处分性措施，但申请执行人提供充分、有效的担保请求继续执行的除外；执行标的查封、扣押、冻结期限届满前，人民法院可以根据当事人申请或者依职权办理续行查封、扣押、冻结手续。"},{"i":8,"n":"第八条","txt":"被执行人向人民法院申请不予执行仲裁裁决的，应当在执行通知书送达之日起十五日内提出书面申请；有民事诉讼法第二百三十七条第二款第四、六项规定情形且执行程序尚未终结的，应当自知道或者应当知道有关事实或案件之日起十五日内提出书面申请。"},{"i":9,"n":"第九条","txt":"案外人向人民法院申请不予执行仲裁裁决或者仲裁调解书的，应当提交申请书以及证明其请求成立的证据材料，并符合下列条件："},{"i":10,"n":"第十条","txt":"被执行人申请不予执行仲裁裁决，对同一仲裁裁决的多个不予执行事由应当一并提出。不予执行仲裁裁决申请被裁定驳回后，再次提出申请的，人民法院不予审查，但有新证据证明存在民事诉讼法第二百三十七条第二款第四、六项规定情形的除外。"},{"i":11,"n":"第十一条","txt":"人民法院对不予执行仲裁裁决案件应当组成合议庭围绕被执行人申请的事由、案外人的申请进行审查；对被执行人没有申请的事由不予审查，但仲裁裁决可能违背社会公共利益的除外。"},{"i":12,"n":"第十二条","txt":"人民法院对不予执行仲裁裁决案件的审查，应当在立案之日起两个月内审查完毕并作出裁定；有特殊情况需要延长的，经本院院长批准，可以延长一个月。"},{"i":13,"n":"第十三条","txt":"下列情形经人民法院审查属实的，应当认定为民事诉讼法第二百三十七条第二款第二项规定的“裁决的事项不属于仲裁协议的范围或者仲裁机构无权仲裁的”情形："},{"i":14,"n":"第十四条","txt":"违反仲裁法规定的仲裁程序、当事人选择的仲裁规则或者当事人对仲裁程序的特别约定，可能影响案件公正裁决，经人民法院审查属实的，应当认定为民事诉讼法第二百三十七条第二款第三项规定的“仲裁庭的组成或者仲裁的程序违反法定程序的”情形。"},{"i":15,"n":"第十五条","txt":"符合下列条件的，人民法院应当认定为民事诉讼法第二百三十七条第二款第四项规定的“裁决所根据的证据是伪造的”情形："},{"i":16,"n":"第十六条","txt":"符合下列条件的，人民法院应当认定为民事诉讼法第二百三十七条第二款第五项规定的“对方当事人向仲裁机构隐瞒了足以影响公正裁决的证据的”情形："},{"i":17,"n":"第十七条","txt":"被执行人申请不予执行仲裁调解书或者根据当事人之间的和解协议、调解协议作出的仲裁裁决，人民法院不予支持，但该仲裁调解书或者仲裁裁决违背社会公共利益的除外。"},{"i":18,"n":"第十八条","txt":"案外人根据本规定第九条申请不予执行仲裁裁决或者仲裁调解书，符合下列条件的，人民法院应当支持："},{"i":19,"n":"第十九条","txt":"被执行人、案外人对仲裁裁决执行案件逾期申请不予执行的，人民法院应当裁定不予受理；已经受理的，应当裁定驳回不予执行申请。"},{"i":20,"n":"第二十条","txt":"当事人向人民法院申请撤销仲裁裁决被驳回后，又在执行程序中以相同事由提出不予执行申请的，人民法院不予支持；当事人向人民法院申请不予执行被驳回后，又以相同事由申请撤销仲裁裁决的，人民法院不予支持。"},{"i":21,"n":"第二十一条","txt":"人民法院裁定驳回撤销仲裁裁决申请或者驳回不予执行仲裁裁决、仲裁调解书申请的，执行法院应当恢复执行。"},{"i":22,"n":"第二十二条","txt":"人民法院裁定不予执行仲裁裁决、驳回或者不予受理不予执行仲裁裁决申请后，当事人对该裁定提出执行异议或者申请复议的，人民法院不予受理。"},{"i":23,"n":"第二十三条","txt":"本规定第八条、第九条关于对仲裁裁决执行案件申请不予执行的期限自本规定施行之日起重新计算。"},{"i":24,"n":"第二十四条","txt":"本规定自2018年3月1日起施行，最高人民法院以前发布的司法解释与本规定不一致的，以本规定为准。"}],"zuigaorenminfayuanguanyurenminfayuanbanlizhixingyi27fb4e":[{"i":1,"n":"第一条","txt":"异议人提出执行异议或者复议申请人申请复议，应当向人民法院提交申请书。申请书应当载明具体的异议或者复议请求、事实、理由等内容，并附下列材料："},{"i":2,"n":"第二条","txt":"执行异议符合民事诉讼法第二百二十五条或者第二百二十七条规定条件的，人民法院应当在三日内立案，并在立案后三日内通知异议人和相关当事人。不符合受理条件的，裁定不予受理；立案后发现不符合受理条件的，裁定驳回申请。"},{"i":3,"n":"第三条","txt":"执行法院收到执行异议后三日内既不立案又不作出不予受理裁定，或者受理后无正当理由超过法定期限不作出异议裁定的，异议人可以向上一级人民法院提出异议。上一级人民法院审查后认为理由成立的，应当指令执行法院在三日内立案或者在十五日内作出异议裁定。"},{"i":4,"n":"第四条","txt":"执行案件被指定执行、提级执行、委托执行后，当事人、利害关系人对原执行法院的执行行为提出异议的，由提出异议时负责该案件执行的人民法院审查处理；受指定或者受委托的人民法院是原执行法院的下级人民法院的，仍由原执行法院审查处理。"},{"i":5,"n":"第五条","txt":"有下列情形之一的，当事人以外的自然人、法人和非法人组织，可以作为利害关系人提出执行行为异议："},{"i":6,"n":"第六条","txt":"当事人、利害关系人依照民事诉讼法第二百二十五条规定提出异议的，应当在执行程序终结之前提出，但对终结执行措施提出异议的除外。"},{"i":7,"n":"第七条","txt":"当事人、利害关系人认为执行过程中或者执行保全、先予执行裁定过程中的下列行为违法提出异议的，人民法院应当依照民事诉讼法第二百二十五条规定进行审查："},{"i":8,"n":"第八条","txt":"案外人基于实体权利既对执行标的提出排除执行异议又作为利害关系人提出执行行为异议的，人民法院应当依照民事诉讼法第二百二十七条规定进行审查。"},{"i":9,"n":"第九条","txt":"被限制出境的人认为对其限制出境错误的，可以自收到限制出境决定之日起十日内向上一级人民法院申请复议。上一级人民法院应当自收到复议申请之日起十五日内作出决定。复议期间，不停止原决定的执行。"},{"i":10,"n":"第十条","txt":"当事人不服驳回不予执行公证债权文书申请的裁定的，可以自收到裁定之日起十日内向上一级人民法院申请复议。上一级人民法院应当自收到复议申请之日起三十日内审查，理由成立的，裁定撤销原裁定，不予执行该公证债权文书；理由不成立的，裁定驳回复议申请。复议期间，不停止执行。"},{"i":11,"n":"第十一条","txt":"人民法院审查执行异议或者复议案件，应当依法组成合议庭。"},{"i":12,"n":"第十二条","txt":"人民法院对执行异议和复议案件实行书面审查。案情复杂、争议较大的，应当进行听证。"},{"i":13,"n":"第十三条","txt":"执行异议、复议案件审查期间，异议人、复议申请人申请撤回异议、复议申请的，是否准许由人民法院裁定。"},{"i":14,"n":"第十四条","txt":"异议人或者复议申请人经合法传唤，无正当理由拒不参加听证，或者未经法庭许可中途退出听证，致使人民法院无法查清相关事实的，由其自行承担不利后果。"},{"i":15,"n":"第十五条","txt":"当事人、利害关系人对同一执行行为有多个异议事由，但未在异议审查过程中一并提出，撤回异议或者被裁定驳回异议后，再次就该执行行为提出异议的，人民法院不予受理。"},{"i":16,"n":"第十六条","txt":"人民法院依照民事诉讼法第二百二十五条规定作出裁定时，应当告知相关权利人申请复议的权利和期限。"},{"i":17,"n":"第十七条","txt":"人民法院对执行行为异议，应当按照下列情形，分别处理："},{"i":18,"n":"第十八条","txt":"执行过程中，第三人因书面承诺自愿代被执行人偿还债务而被追加为被执行人后，无正当理由反悔并提出异议的，人民法院不予支持。"},{"i":19,"n":"第十九条","txt":"当事人互负到期债务，被执行人请求抵销，请求抵销的债务符合下列情形的，除依照法律规定或者按照债务性质不得抵销的以外，人民法院应予支持："},{"i":20,"n":"第二十条","txt":"金钱债权执行中，符合下列情形之一，被执行人以执行标的系本人及所扶养家属维持生活必需的居住房屋为由提出异议的，人民法院不予支持："},{"i":21,"n":"第二十一条","txt":"当事人、利害关系人提出异议请求撤销拍卖，符合下列情形之一的，人民法院应予支持："},{"i":22,"n":"第二十二条","txt":"公证债权文书对主债务和担保债务同时赋予强制执行效力的，人民法院应予执行；仅对主债务赋予强制执行效力未涉及担保债务的，对担保债务的执行申请不予受理；仅对担保债务赋予强制执行效力未涉及主债务的，对主债务的执行申请不予受理。"},{"i":23,"n":"第二十三条","txt":"上一级人民法院对不服异议裁定的复议申请审查后，应当按照下列情形，分别处理："},{"i":24,"n":"第二十四条","txt":"对案外人提出的排除执行异议，人民法院应当审查下列内容："},{"i":25,"n":"第二十五条","txt":"对案外人的异议，人民法院应当按照下列标准判断其是否系权利人："},{"i":26,"n":"第二十六条","txt":"金钱债权执行中，案外人依据执行标的被查封、扣押、冻结前作出的另案生效法律文书提出排除执行异议，人民法院应当按照下列情形，分别处理："},{"i":27,"n":"第二十七条","txt":"申请执行人对执行标的依法享有对抗案外人的担保物权等优先受偿权，人民法院对案外人提出的排除执行异议不予支持，但法律、司法解释另有规定的除外。"},{"i":28,"n":"第二十八条","txt":"金钱债权执行中，买受人对登记在被执行人名下的不动产提出异议，符合下列情形且其权利能够排除执行的，人民法院应予支持："},{"i":29,"n":"第二十九条","txt":"金钱债权执行中，买受人对登记在被执行的房地产开发企业名下的商品房提出异议，符合下列情形且其权利能够排除执行的，人民法院应予支持："},{"i":30,"n":"第三十条","txt":"金钱债权执行中，对被查封的办理了受让物权预告登记的不动产，受让人提出停止处分异议的，人民法院应予支持；符合物权登记条件，受让人提出排除执行异议的，应予支持。"},{"i":31,"n":"第三十一条","txt":"承租人请求在租赁期内阻止向受让人移交占有被执行的不动产，在人民法院查封之前已签订合法有效的书面租赁合同并占有使用该不动产的，人民法院应予支持。"},{"i":32,"n":"第三十二条","txt":"本规定施行后尚未审查终结的执行异议和复议案件，适用本规定。本规定施行前已经审查终结的执行异议和复议案件，人民法院依法提起执行监督程序的，不适用本规定。"}],"zuigaorenminfayuanguanyurenminfayuanbanlijieshouza0c92fb":[{"i":1,"n":"第一条","txt":"人民法院办理接收在台湾地区服刑的大陆居民（以下简称被判刑人）回大陆服刑案件（以下简称接收被判刑人案件），应当遵循一个中国原则，遵守国家法律的基本原则，秉持人道和互惠原则，不得违反社会公共利益。"},{"i":2,"n":"第二条","txt":"接收被判刑人案件由最高人民法院指定的中级人民法院管辖。"},{"i":3,"n":"第三条","txt":"申请机关向人民法院申请接收被判刑人回大陆服刑，应当同时提交以下材料："},{"i":4,"n":"第四条","txt":"人民法院应当组成合议庭审理接收被判刑人案件。"},{"i":5,"n":"第五条","txt":"人民法院应当在立案后一个月内就是否准予接收被判刑人作出裁定，情况复杂、特殊的，可以延长一个月。"},{"i":6,"n":"第六条","txt":"被判刑人被接收回大陆服刑前被实际羁押的期间，应当以一日折抵转换后的刑期一日。"},{"i":7,"n":"第七条","txt":"被判刑人被接收回大陆前已在台湾地区被假释或保外就医的，或者被判刑人或其法定代理人在申请或者同意回大陆服刑的书面意见中同时申请暂予监外执行的，人民法院应当根据刑法、刑事诉讼法的规定一并审查，并作出是否假释或者暂予监外执行的决定。"},{"i":8,"n":"第八条","txt":"人民法院作出裁定后，应当在七日内送达申请机关。裁定一经送达，立即生效。"},{"i":9,"n":"第九条","txt":"被判刑人回大陆服刑后，有关减刑、假释、暂予监外执行、赦免等事项，适用刑法、刑事诉讼法及相关司法解释的规定。"},{"i":10,"n":"第十条","txt":"被判刑人回大陆服刑后，对其在台湾地区已被判处刑罚的行为，人民法院不再审理。"},{"i":11,"n":"第十一条","txt":"本规定自2016年5月1日起施行。"}],"zuigaorenminfayuanguanyurenminfayuanbanlihaixialia407e8c":[{"i":1,"n":"第一条","txt":"人民法院依照协议，办理海峡两岸民事、刑事、行政诉讼案件中的送达文书和调查取证司法互助业务，适用本规定。"},{"i":2,"n":"第二条","txt":"人民法院应当在法定职权范围内办理海峡两岸司法互助业务。"},{"i":3,"n":"第三条","txt":"人民法院和台湾地区业务主管部门通过各自指定的协议联络人，建立办理海峡两岸司法互助业务的直接联络渠道。"},{"i":4,"n":"第四条","txt":"最高人民法院是与台湾地区业务主管部门就海峡两岸司法互助业务进行联络的一级窗口。最高人民法院台湾司法事务办公室主任是最高人民法院指定的协议联络人。"},{"i":5,"n":"第五条","txt":"最高人民法院授权高级人民法院就办理海峡两岸送达文书司法互助案件，建立与台湾地区业务主管部门联络的二级窗口。高级人民法院应当指定专人作为经最高人民法院授权的二级联络窗口联络人。"},{"i":6,"n":"第六条","txt":"中级人民法院和基层人民法院应当指定专人负责海峡两岸司法互助业务。"},{"i":7,"n":"第七条","txt":"人民法院向住所地在台湾地区的当事人送达民事和行政诉讼司法文书，可以采用下列方式："},{"i":8,"n":"第八条","txt":"人民法院协助台湾地区法院送达司法文书，应当采用民事诉讼法、刑事诉讼法、行政诉讼法等法律和相关司法解释规定的送达方式，并应当尽可能采用直接送达方式，但不采用公告送达方式。"},{"i":9,"n":"第九条","txt":"人民法院协助台湾地区送达司法文书，应当充分负责，及时努力送达。"},{"i":10,"n":"第十条","txt":"审理案件的人民法院需要台湾地区协助送达司法文书的，应当填写《〈海峡两岸共同打击犯罪及司法互助协议〉送达文书请求书》附录部分，连同需要送达的司法文书，一式二份，及时送交高级人民法院。"},{"i":11,"n":"第十一条","txt":"高级人民法院收到本院或者下级人民法院《〈海峡两岸共同打击犯罪及司法互助协议〉送达文书请求书》附录部分和需要送达的司法文书后，应当在七个工作日内完成审查。经审查认为可以请求台湾地区协助送达的，高级人民法院联络人应当填写《〈海峡两岸共同打击犯罪及司法互助协议〉送达文书请求书》正文部分，连同附录部分和需要送达的司法文书，立即寄送台湾地区联络人；经审查认为欠缺相关材料、内容或者认为不需要请求台湾地区协助送达的，应当立即告知提出请求的人民法院补充相关材料、内容或者在说明理由后将材料退回。"},{"i":12,"n":"第十二条","txt":"台湾地区成功送达并将送达证明材料寄送高级人民法院联络人，或者未能成功送达并将相关材料送还，同时出具理由说明给高级人民法院联络人的，高级人民法院应当在收到之日起七个工作日内，完成审查并转送提出请求的人民法院。经审查认为欠缺相关材料或者内容的，高级人民法院联络人应当立即与台湾地区联络人联络并请求补充相关材料或者内容。"},{"i":13,"n":"第十三条","txt":"台湾地区请求人民法院协助送达台湾地区法院的司法文书并通过其联络人将请求书和相关司法文书寄送高级人民法院联络人的，高级人民法院应当在七个工作日内完成审查。经审查认为可以协助送达的，应当立即转送有关下级人民法院送达或者由本院送达；经审查认为欠缺相关材料、内容或者认为不宜协助送达的，高级人民法院联络人应当立即向台湾地区联络人说明情况并告知其补充相关材料、内容或者将材料送还。"},{"i":14,"n":"第十四条","txt":"具体办理送达文书司法互助案件的人民法院成功送达的，应当由送达人在《〈海峡两岸共同打击犯罪及司法互助协议〉送达回证》上签名或者盖章，并在成功送达之日起七个工作日内将送达回证送交高级人民法院；未能成功送达的，应当由送达人在《〈海峡两岸共同打击犯罪及司法互助协议〉送达回证》上注明未能成功送达的原因并签名或者盖章，在确认不能送达之日起七个工作日内，将该送达回证和未能成功送达的司法文书送交高级人民法院。"},{"i":15,"n":"第十五条","txt":"人民法院办理海峡两岸调查取证司法互助业务，限于与台湾地区法院相互协助调取与诉讼有关的证据，包括取得证言及陈述；提供书证、物证及视听资料；确定关系人所在地或者确认其身份、前科等情况；进行勘验、检查、扣押、鉴定和查询等。"},{"i":16,"n":"第十六条","txt":"人民法院协助台湾地区法院调查取证，应当采用民事诉讼法、刑事诉讼法、行政诉讼法等法律和相关司法解释规定的方式。"},{"i":17,"n":"第十七条","txt":"审理案件的人民法院需要台湾地区协助调查取证的，应当填写《〈海峡两岸共同打击犯罪及司法互助协议〉调查取证请求书》附录部分，连同相关材料，一式三份，及时送交高级人民法院。"},{"i":18,"n":"第十八条","txt":"最高人民法院收到高级人民法院转送的《〈海峡两岸共同打击犯罪及司法互助协议〉调查取证请求书》附录部分和相关材料以及高级人民法院审查意见后，应当在七个工作日内完成最终审查。经审查认为可以请求台湾地区协助调查取证的，最高人民法院联络人应当填写《〈海峡两岸共同打击犯罪及司法互助协议〉调查取证请求书》正文部分，连同附录部分和相关材料，立即寄送台湾地区联络人；经审查认为欠缺相关材料、内容或者认为不需要请求台湾地区协助调查取证的，应当立即通过高级人民法院告知提出请求的人民法院补充相关材料、内容或者在说明理由后将材料退回。"},{"i":19,"n":"第十九条","txt":"台湾地区成功调查取证并将取得的证据材料寄送最高人民法院联络人，或者未能成功调查取证并将相关材料送还，同时出具理由说明给最高人民法院联络人的，最高人民法院应当在收到之日起七个工作日内完成审查并转送高级人民法院，高级人民法院应当在收到之日起七个工作日内转送提出请求的人民法院。经审查认为欠缺相关材料或者内容的，最高人民法院联络人应当立即与台湾地区联络人联络并请求补充相关材料或者内容。"},{"i":20,"n":"第二十条","txt":"台湾地区请求人民法院协助台湾地区法院调查取证并通过其联络人将请求书和相关材料寄送最高人民法院联络人的，最高人民法院应当在收到之日起七个工作日内完成审查。经审查认为可以协助调查取证的，应当立即转送有关高级人民法院或者由本院办理，高级人民法院应当在收到之日起七个工作日内转送有关下级人民法院办理或者由本院办理；经审查认为欠缺相关材料、内容或者认为不宜协助调查取证的，最高人民法院联络人应当立即向台湾地区联络人说明情况并告知其补充相关材料、内容或者将材料送还。"},{"i":21,"n":"第二十一条","txt":"具体办理调查取证司法互助案件的人民法院成功调查取证的，应当在完成调查取证之日起七个工作日内将取得的证据材料一式三份，连同台湾地区提供的材料，并在必要时附具情况说明，送交高级人民法院；未能成功调查取证的，应当出具说明函一式三份，连同台湾地区提供的材料，在确认不能成功调查取证之日起七个工作日内送交高级人民法院。"},{"i":22,"n":"第二十二条","txt":"人民法院对于台湾地区请求协助所提供的和执行请求所取得的相关资料应当予以保密。但依据请求目的使用的除外。"},{"i":23,"n":"第二十三条","txt":"人民法院应当依据请求书载明的目的使用台湾地区协助提供的资料。但最高人民法院和台湾地区业务主管部门另有商定的除外。"},{"i":24,"n":"第二十四条","txt":"对于依照协议和本规定从台湾地区获得的证据和司法文书等材料，不需要办理公证、认证等形式证明。"},{"i":25,"n":"第二十五条","txt":"人民法院办理海峡两岸司法互助业务，应当使用统一、规范的文书样式。"},{"i":26,"n":"第二十六条","txt":"对于执行台湾地区的请求所发生的费用，由有关人民法院负担。但下列费用应当由台湾地区业务主管部门负责支付："},{"i":27,"n":"第二十七条","txt":"人民法院在办理海峡两岸司法互助案件中收到、取得、制作的各种文件和材料，应当以原件或者复制件形式，作为诉讼档案保存。"},{"i":28,"n":"第二十八条","txt":"最高人民法院审理的案件需要请求台湾地区协助送达司法文书和调查取证的，参照本规定由本院自行办理。"},{"i":29,"n":"第二十九条","txt":"办理海峡两岸司法互助案件和执行本规定的情况，应当纳入对有关人民法院及相关工作人员的工作绩效考核和案件质量评查范围。"},{"i":30,"n":"第三十条","txt":"此前发布的司法解释与本规定不一致的，以本规定为准。"}],"zuigaorenminfayuanguanyurenminfayuanbanlizipeianji1672f9":[{"i":1,"n":"第一条","txt":"本规定所称自赔案件，是指人民法院办理的本院作为赔偿义务机关的国家赔偿案件。"},{"i":2,"n":"第二条","txt":"基层人民法院国家赔偿小组、中级以上人民法院赔偿委员会负责办理本院的自赔案件。"},{"i":3,"n":"第三条","txt":"人民法院对赔偿请求人提出的赔偿申请，根据《最高人民法院关于国家赔偿案件立案工作的规定》予以审查立案。"},{"i":4,"n":"第四条","txt":"人民法院办理自赔案件，应当指定一名审判员承办。"},{"i":5,"n":"第五条","txt":"参与办理自赔案件的审判人员是赔偿请求人或其代理人的近亲属，与本案有利害关系，或者有其他关系，可能影响案件公正办理的，应当主动回避。"},{"i":6,"n":"第六条","txt":"赔偿请求人申请回避，应当在人民法院作出赔偿决定前提出。"},{"i":7,"n":"第七条","txt":"人民法院应当全面审查案件，充分听取赔偿请求人的意见。必要时可以调取原审判、执行案卷，可以向原案件承办部门或有关人员调查、核实情况。听取意见、调查核实情况，应当制作笔录。"},{"i":8,"n":"第八条","txt":"人民法院可以与赔偿请求人就赔偿方式、赔偿项目和赔偿数额在法律规定的范围内进行协商。协商应当遵循自愿、合法的原则。协商情况应当制作笔录。"},{"i":9,"n":"第九条","txt":"人民法院作出决定前，赔偿请求人撤回赔偿申请的，人民法院应当准许。"},{"i":10,"n":"第十条","txt":"有下列情形之一的，人民法院应当决定中止办理："},{"i":11,"n":"第十一条","txt":"有下列情形之一的，人民法院应当决定终结办理："},{"i":12,"n":"第十二条","txt":"人民法院应当自收到赔偿申请之日起两个月内作出是否赔偿的决定，并制作国家赔偿决定书。"},{"i":13,"n":"第十三条","txt":"国家赔偿决定书应当载明以下事项："},{"i":14,"n":"第十四条","txt":"人民法院决定赔偿或不予赔偿的，应当自作出决定之日起十日内将国家赔偿决定书送达赔偿请求人。"},{"i":15,"n":"第十五条","txt":"赔偿请求人依据国家赔偿法第三十七条第二款的规定向人民法院申请支付赔偿金的，应当递交申请书，并提交以下材料："},{"i":16,"n":"第十六条","txt":"申请支付材料真实、有效、完整的，人民法院应当受理，并书面通知赔偿请求人。人民法院受理后，应当自收到支付申请之日起七日内，依照预算管理权限向有关财政部门提出支付申请。"},{"i":17,"n":"第十七条","txt":"赔偿请求人对人民法院不予受理申请支付的通知有异议的，可以自收到通知之日起十日内向上一级人民法院申请复核。上一级人民法院应当自收到复核申请之日起五个工作日内作出复核决定，并在作出复核决定之日起三个工作日内送达赔偿请求人。"},{"i":18,"n":"第十八条","txt":"财政部门告知人民法院申请支付材料不符合要求的，人民法院应当自接到通知之日起五个工作日内按照要求提交补正材料。"},{"i":19,"n":"第十九条","txt":"财政部门告知人民法院已支付国家赔偿费用的，人民法院应当及时通知赔偿请求人。"},{"i":20,"n":"第二十条","txt":"本规定自2013年9月1日起施行。"}],"zuigaorenminfayuanguanyurenminfayuanbanlicaichanba916046":[{"i":1,"n":"第一条","txt":"当事人、利害关系人申请财产保全，应当向人民法院提交申请书，并提供相关证据材料。"},{"i":2,"n":"第二条","txt":"人民法院进行财产保全，由立案、审判机构作出裁定，一般应当移送执行机构实施。"},{"i":3,"n":"第三条","txt":"仲裁过程中，当事人申请财产保全的，应当通过仲裁机构向人民法院提交申请书及仲裁案件受理通知书等相关材料。人民法院裁定采取保全措施或者裁定驳回申请的，应当将裁定书送达当事人，并通知仲裁机构。"},{"i":4,"n":"第四条","txt":"人民法院接受财产保全申请后，应当在五日内作出裁定；需要提供担保的，应当在提供担保后五日内作出裁定；裁定采取保全措施的，应当在五日内开始执行。对情况紧急的，必须在四十八小时内作出裁定；裁定采取保全措施的，应当立即开始执行。"},{"i":5,"n":"第五条","txt":"人民法院依照民事诉讼法第一百条规定责令申请保全人提供财产保全担保的，担保数额不超过请求保全数额的百分之三十；申请保全的财产系争议标的的，担保数额不超过争议标的价值的百分之三十。"},{"i":6,"n":"第六条","txt":"申请保全人或第三人为财产保全提供财产担保的，应当向人民法院出具担保书。担保书应当载明担保人、担保方式、担保范围、担保财产及其价值、担保责任承担等内容，并附相关证据材料。"},{"i":7,"n":"第七条","txt":"保险人以其与申请保全人签订财产保全责任险合同的方式为财产保全提供担保的，应当向人民法院出具担保书。"},{"i":8,"n":"第八条","txt":"金融监管部门批准设立的金融机构以独立保函形式为财产保全提供担保的，人民法院应当依法准许。"},{"i":9,"n":"第九条","txt":"当事人在诉讼中申请财产保全，有下列情形之一的，人民法院可以不要求提供担保："},{"i":10,"n":"第十条","txt":"当事人、利害关系人申请财产保全，应当向人民法院提供明确的被保全财产信息。"},{"i":11,"n":"第十一条","txt":"人民法院依照本规定第十条第二款规定作出保全裁定的，在该裁定执行过程中，申请保全人可以向已经建立网络执行查控系统的执行法院，书面申请通过该系统查询被保全人的财产。"},{"i":12,"n":"第十二条","txt":"人民法院对查询到的被保全人财产信息，应当依法保密。除依法保全的财产外，不得泄露被保全人其他财产信息，也不得在财产保全、强制执行以外使用相关信息。"},{"i":13,"n":"第十三条","txt":"被保全人有多项财产可供保全的，在能够实现保全目的的情况下，人民法院应当选择对其生产经营活动影响较小的财产进行保全。"},{"i":14,"n":"第十四条","txt":"被保全财产系机动车、航空器等特殊动产的，除被保全人下落不明的以外，人民法院应当责令被保全人书面报告该动产的权属和占有、使用等情况，并予以核实。"},{"i":15,"n":"第十五条","txt":"人民法院应当依据财产保全裁定采取相应的查封、扣押、冻结措施。"},{"i":16,"n":"第十六条","txt":"人民法院在财产保全中采取查封、扣押、冻结措施，需要有关单位协助办理登记手续的，有关单位应当在裁定书和协助执行通知书送达后立即办理。针对同一财产有多个裁定书和协助执行通知书的，应当按照送达的时间先后办理登记手续。"},{"i":17,"n":"第十七条","txt":"利害关系人申请诉前财产保全，在人民法院采取保全措施后三十日内依法提起诉讼或者申请仲裁的，诉前财产保全措施自动转为诉讼或仲裁中的保全措施；进入执行程序后，保全措施自动转为执行中的查封、扣押、冻结措施。"},{"i":18,"n":"第十八条","txt":"申请保全人申请续行财产保全的，应当在保全期限届满七日前向人民法院提出；逾期申请或者不申请的，自行承担不能续行保全的法律后果。"},{"i":19,"n":"第十九条","txt":"再审审查期间，债务人申请保全生效法律文书确定给付的财产的，人民法院不予受理。"},{"i":20,"n":"第二十条","txt":"财产保全期间，被保全人请求对被保全财产自行处分，人民法院经审查，认为不损害申请保全人和其他执行债权人合法权益的，可以准许，但应当监督被保全人按照合理价格在指定期限内处分，并控制相应价款。"},{"i":21,"n":"第二十一条","txt":"保全法院在首先采取查封、扣押、冻结措施后超过一年未对被保全财产进行处分的，除被保全财产系争议标的外，在先轮候查封、扣押、冻结的执行法院可以商请保全法院将被保全财产移送执行。但司法解释另有特别规定的，适用其规定。"},{"i":22,"n":"第二十二条","txt":"财产纠纷案件，被保全人或第三人提供充分有效担保请求解除保全，人民法院应当裁定准许。被保全人请求对作为争议标的的财产解除保全的，须经申请保全人同意。"},{"i":23,"n":"第二十三条","txt":"人民法院采取财产保全措施后，有下列情形之一的，申请保全人应当及时申请解除保全："},{"i":24,"n":"第二十四条","txt":"财产保全裁定执行中，人民法院发现保全裁定的内容与被保全财产的实际情况不符的，应当予以撤销、变更或补正。"},{"i":25,"n":"第二十五条","txt":"申请保全人、被保全人对保全裁定或者驳回申请裁定不服的，可以自裁定书送达之日起五日内向作出裁定的人民法院申请复议一次。人民法院应当自收到复议申请后十日内审查。"},{"i":26,"n":"第二十六条","txt":"申请保全人、被保全人、利害关系人认为保全裁定实施过程中的执行行为违反法律规定提出书面异议的，人民法院应当依照民事诉讼法第二百二十五条规定审查处理。"},{"i":27,"n":"第二十七条","txt":"人民法院对诉讼争议标的以外的财产进行保全，案外人对保全裁定或者保全裁定实施过程中的执行行为不服，基于实体权利对被保全财产提出书面异议的，人民法院应当依照民事诉讼法第二百二十七条规定审查处理并作出裁定。案外人、申请保全人对该裁定不服的，可以自裁定送达之日起十五日内向人民法院提起执行异议之诉。"},{"i":28,"n":"第二十八条","txt":"海事诉讼中，海事请求人申请海事请求保全，适用《中华人民共和国海事诉讼特别程序法》及相关司法解释。"},{"i":29,"n":"第二十九条","txt":"本规定自2016年12月1日起施行。"}],"zuigaorenminfayuanguanyurenminfayuanshoulishenqingac893a":[],"zuigaorenminfayuanguanyurenminfayuansifapaimaifang75a53b":[{"i":1,"n":"第一条","txt":"人民法院组织的司法拍卖房产活动，受房产所在地限购政策约束的竞买人申请参与竞拍的，人民法院不予准许。"},{"i":2,"n":"第二条","txt":"人民法院组织司法拍卖房产活动时，发布的拍卖公告载明竞买人必须具备购房资格及其相应法律后果等内容，竞买人申请参与竞拍的，应当承诺具备购房资格及自愿承担法律后果。"},{"i":3,"n":"第三条","txt":"人民法院在司法拍卖房产成交后、向买受人出具成交裁定书前，应当审核买受人提交的自其申请参与竞拍到成交裁定书出具时具备购房资格的证明材料；经审核买受人不符合持续具备购房资格条件，买受人请求出具拍卖成交裁定书的，人民法院不予准许。"},{"i":4,"n":"第四条","txt":"买受人虚构购房资格参与司法拍卖房产活动且拍卖成交，当事人、利害关系人以违背公序良俗为由主张该拍卖行为无效的，人民法院应予支持。"},{"i":5,"n":"第五条","txt":"司法拍卖房产出现流拍等无法正常处置情形，不具备购房资格的申请执行人等当事人请求以该房抵债的，人民法院不予支持。"},{"i":6,"n":"第六条","txt":"人民法院组织的司法拍卖房产活动，竞买人虚构购房资格或者当事人之间恶意串通，侵害他人合法权益或者逃避履行法律文书确定的义务的，人民法院应当根据情节轻重予以罚款、拘留；构成犯罪的，依法追究刑事责任。"},{"i":7,"n":"第七条","txt":"除前六条规定的情形外，人民法院组织司法拍卖房产活动的其他事宜，适用《最高人民法院关于人民法院网络司法拍卖若干问题的规定》《最高人民法院关于人民法院民事执行中拍卖、变卖财产的规定》以及《最高人民法院关于适用〈中华人民共和国民事诉讼法〉的解释》的有关规定。"},{"i":8,"n":"第八条","txt":"人民法院组织司法变卖房产活动的，参照适用本规定。"},{"i":9,"n":"第九条","txt":"本规定自2022年1月1日起施行。"}],"zuigaorenminfayuanguanyurenminfayuansifajingchayiffb6e43":[{"i":1,"n":"第一条","txt":"人民法院司法警察的职责："},{"i":2,"n":"第二条","txt":"对违反法庭纪律的行为人，人民法院司法警察应当依照审判长或者独任法官的指令，予以劝阻、制止、控制，执行扣押物品、责令退出法庭、强行带出法庭、罚款、拘留等强制措施。"},{"i":3,"n":"第三条","txt":"对以暴力、威胁或者其他方法阻碍司法工作人员执行职务和在人民法院内侮辱、殴打或者打击报复司法工作人员的行为人，人民法院司法警察可以采取制止、控制、带离等强制手段，根据需要进行询问，提取、固定、保存相关证据，依法提请人民法院处以罚款、拘留等强制措施。"},{"i":4,"n":"第四条","txt":"对强行进入审判区域的行为人，人民法院司法警察可以采取制止、控制、带离等强制手段，根据需要进行询问，提取、固定、保存相关证据，依法提请人民法院处以罚款、拘留等强制措施。"},{"i":5,"n":"第五条","txt":"人民法院司法警察协助相关部门开展机关安全和涉诉信访应急处置工作时，对扰乱人民法院工作秩序、危害他人人身安全以及人民法院财产安全的行为人，可以采取制止、控制等处置措施，保存相关证据，对涉嫌违法犯罪的，及时移送公安机关。"},{"i":6,"n":"第六条","txt":"人民法院司法警察在执行职务过程中，遇当事人或者其他人员实施自杀、自伤等行为时，应当采取措施予以制止、协助救治，对无法制止或有其他暴力行为的，可以采取保护性约束措施，并视情节移送公安机关。"},{"i":7,"n":"第七条","txt":"本规定自2021年1月1日起施行；最高人民法院此前发布的文件与本规定不一致的，以本规定为准。"}],"zuigaorenminfayuanguanyurenminfayuanheyitinggongzu5d91fe":[{"i":1,"n":"第一条","txt":"人民法院实行合议制审判第一审案件，由法官或者由法官和人民陪审员组成合议庭进行；人民法院实行合议制审判第二审案件和其他应当组成合议庭审判的案件，由法官组成合议庭进行。"},{"i":2,"n":"第二条","txt":"合议庭的审判长由符合审判长任职条件的法官担任。"},{"i":3,"n":"第三条","txt":"合议庭组成人员确定后，除因回避或者其他特殊情况，不能继续参加案件审理的之外，不得在案件审理过程中更换。更换合议庭成员，应当报请院长或者庭长决定。合议庭成员的更换情况应当及时通知诉讼当事人。"},{"i":4,"n":"第四条","txt":"合议庭的审判活动由审判长主持，全体成员平等参与案件的审理、评议、裁判，共同对案件认定事实和适用法律负责。"},{"i":5,"n":"第五条","txt":"合议庭承担下列职责："},{"i":6,"n":"第六条","txt":"审判长履行下列职责："},{"i":7,"n":"第七条","txt":"合议庭接受案件后，应当根据有关规定确定案件承办法官，或者由审判长指定案件承办法官。"},{"i":8,"n":"第八条","txt":"在案件开庭审理过程中，合议庭成员必须认真履行法定职责，遵守《中华人民共和国法官职业道德基本准则》中有关司法礼仪的要求。"},{"i":9,"n":"第九条","txt":"合议庭评议案件应当在庭审结束后五个工作日内进行。"},{"i":10,"n":"第十条","txt":"合议庭评议案件时，先由承办法官对认定案件事实、证据是否确实、充分以及适用法律等发表意见，审判长最后发表意见；审判长作为承办法官的，由审判长最后发表意见。对案件的裁判结果进行评议时，由审判长最后发表意见。审判长应当根据评议情况总结合议庭评议的结论性意见。"},{"i":11,"n":"第十一条","txt":"合议庭进行评议的时候，如果意见分歧，应当按多数人的意见作出决定，但是少数人的意见应当写入笔录。"},{"i":12,"n":"第十二条","txt":"合议庭应当依照规定的权限，及时对评议意见一致或者形成多数意见的案件直接作出判决或者裁定。但是对于下列案件，合议庭应当提请院长决定提交审判委员会讨论决定："},{"i":13,"n":"第十三条","txt":"合议庭对审判委员会的决定有异议，可以提请院长决定提交审判委员会复议一次。"},{"i":14,"n":"第十四条","txt":"合议庭一般应当在作出评议结论或者审判委员会作出决定后的五个工作日内制作出裁判文书。"},{"i":15,"n":"第十五条","txt":"裁判文书一般由审判长或者承办法官制作。但是审判长或者承办法官的评议意见与合议庭评议结论或者审判委员会的决定有明显分歧的，也可以由其他合议庭成员制作裁判文书。"},{"i":16,"n":"第十六条","txt":"院长、庭长可以对合议庭的评议意见和制作的裁判文书进行审核，但是不得改变合议庭的评议结论。"},{"i":17,"n":"第十七条","txt":"院长、庭长在审核合议庭的评议意见和裁判文书过程中，对评议结论有异议的，可以建议合议庭复议，同时应当对要求复议的问题及理由提出书面意见。"},{"i":18,"n":"第十八条","txt":"合议庭应当严格执行案件审理期限的有关规定。遇有特殊情况需要延长审理期限的，应当在审限届满前按规定的时限报请审批。"}],"zuigaorenminfayuanguanyurenminfayuanzaihulianwangg458bb6":[{"i":1,"n":"第一条","txt":"人民法院在互联网公布裁判文书，应当依法、全面、及时、规范。"},{"i":2,"n":"第二条","txt":"中国裁判文书网是全国法院公布裁判文书的统一平台。各级人民法院在本院政务网站及司法公开平台设置中国裁判文书网的链接。"},{"i":3,"n":"第三条","txt":"人民法院作出的下列裁判文书应当在互联网公布："},{"i":4,"n":"第四条","txt":"人民法院作出的裁判文书有下列情形之一的，不在互联网公布："},{"i":5,"n":"第五条","txt":"人民法院应当在受理案件通知书、应诉通知书中告知当事人在互联网公布裁判文书的范围，并通过政务网站、电子触摸屏、诉讼指南等多种方式，向公众告知人民法院在互联网公布裁判文书的相关规定。"},{"i":6,"n":"第六条","txt":"不在互联网公布的裁判文书，应当公布案号、审理法院、裁判日期及不公开理由，但公布上述信息可能泄露国家秘密的除外。"},{"i":7,"n":"第七条","txt":"发生法律效力的裁判文书，应当在裁判文书生效之日起七个工作日内在互联网公布。依法提起抗诉或者上诉的一审判决书、裁定书，应当在二审裁判生效后七个工作日内在互联网公布。"},{"i":8,"n":"第八条","txt":"人民法院在互联网公布裁判文书时，应当对下列人员的姓名进行隐名处理："},{"i":9,"n":"第九条","txt":"根据本规定第八条进行隐名处理时，应当按以下情形处理："},{"i":10,"n":"第十条","txt":"人民法院在互联网公布裁判文书时，应当删除下列信息："},{"i":11,"n":"第十一条","txt":"人民法院在互联网公布裁判文书，应当保留当事人、法定代理人、委托代理人、辩护人的下列信息："},{"i":12,"n":"第十二条","txt":"办案法官认为裁判文书具有本规定第四条第五项不宜在互联网公布情形的，应当提出书面意见及理由，由部门负责人审查后报主管副院长审定。"},{"i":13,"n":"第十三条","txt":"最高人民法院监督指导全国法院在互联网公布裁判文书的工作。高级、中级人民法院监督指导辖区法院在互联网公布裁判文书的工作。"},{"i":14,"n":"第十四条","txt":"各级人民法院应当依托信息技术将裁判文书公开纳入审判流程管理，减轻裁判文书公开的工作量，实现裁判文书及时、全面、便捷公布。"},{"i":15,"n":"第十五条","txt":"在互联网公布的裁判文书，除依照本规定要求进行技术处理的以外，应当与裁判文书的原本一致。"},{"i":16,"n":"第十六条","txt":"在互联网公布的裁判文书与裁判文书原本不一致或者技术处理不当的，应当及时撤回并在纠正后重新公布。"},{"i":17,"n":"第十七条","txt":"人民法院信息技术服务中心负责中国裁判文书网的运行维护和升级完善，为社会各界合法利用在该网站公开的裁判文书提供便利。"},{"i":18,"n":"第十八条","txt":"本规定自2016年10月1日起施行。最高人民法院以前发布的司法解释和规范性文件与本规定不一致的，以本规定为准。"}],"zuigaorenminfayuanguanyurenminfayuanweituopinggupaf1c551":[{"i":1,"n":"第一条","txt":"人民法院司法技术管理部门负责本院的委托评估、拍卖和流拍财产的变卖工作，依法对委托评估、拍卖机构的评估、拍卖活动进行监督。"},{"i":2,"n":"第二条","txt":"根据工作需要，下级人民法院可将评估、拍卖和变卖工作报请上级人民法院办理。"},{"i":3,"n":"第三条","txt":"人民法院需要对异地的财产进行评估或拍卖时，可以委托财产所在地人民法院办理。"},{"i":4,"n":"第四条","txt":"人民法院按照公开、公平、择优的原则编制人民法院委托评估、拍卖机构名册。"},{"i":5,"n":"第五条","txt":"人民法院在编制委托评估、拍卖机构名册时，由司法技术管理部门、审判部门、执行部门组成评审委员会，必要时可邀请评估、拍卖行业的专家参加评审。"},{"i":6,"n":"第六条","txt":"评审委员会对申请加入人民法院委托评估、拍卖名册的机构，应当从资质等级、职业信誉、经营业绩、执业人员情况等方面进行审查、打分，按分数高低经过初审、公示、复审后确定进入名册的机构，并对名册进行动态管理。"},{"i":7,"n":"第七条","txt":"人民法院选择评估、拍卖机构，应当在人民法院委托评估、拍卖机构名册内采取公开随机的方式选定。"},{"i":8,"n":"第八条","txt":"人民法院选择评估、拍卖机构，应当通知审判、执行人员到场，视情况可邀请社会有关人员到场监督。"},{"i":9,"n":"第九条","txt":"人民法院选择评估、拍卖机构，应当提前通知各方当事人到场；当事人不到场的，人民法院可将选择机构的情况，以书面形式送达当事人。"},{"i":10,"n":"第十条","txt":"评估、拍卖机构选定后，人民法院应当向选定的机构出具委托书，委托书中应当载明本次委托的要求和工作完成的期限等事项。"},{"i":11,"n":"第十一条","txt":"评估、拍卖机构接受人民法院的委托后，在规定期限内无正当理由不能完成委托事项的，人民法院应当解除委托，重新选择机构，并对其暂停备选资格或从委托评估、拍卖机构名册内除名。"},{"i":12,"n":"第十二条","txt":"评估机构在工作中需要对现场进行勘验的，人民法院应当提前通知审判、执行人员和当事人到场。当事人不到场的，不影响勘验的进行，但应当有见证人见证。评估机构勘验现场，应当制作现场勘验笔录。"},{"i":13,"n":"第十三条","txt":"拍卖财产经过评估的，评估价即为第一次拍卖的保留价；未作评估的，保留价由人民法院参照市价确定，并应当征询有关当事人的意见。"},{"i":14,"n":"第十四条","txt":"审判、执行部门未经司法技术管理部门同意擅自委托评估、拍卖，或对流拍财产进行变卖的，按照有关纪律规定追究责任。"},{"i":15,"n":"第十五条","txt":"人民法院司法技术管理部门，在组织评审委员会审查评估、拍卖入册机构，或选择评估、拍卖机构，或对流拍财产进行变卖时，应当通知本院纪检监察部门。纪检监察部门可视情况派员参加。"},{"i":16,"n":"第十六条","txt":"施行前本院公布的司法解释与本规定不一致的，以本规定为准。"}],"zuigaorenminfayuanguanyurenminfayuanweituopinggupa789178":[{"i":1,"n":"第一条","txt":"人民法院司法辅助部门负责统一管理和协调司法委托评估、拍卖工作。"},{"i":2,"n":"第二条","txt":"取得政府管理部门行政许可并达到一定资质等级的评估、拍卖机构，可以自愿报名参加人民法院委托的评估、拍卖活动。"},{"i":3,"n":"第三条","txt":"人民法院采用随机方式确定评估、拍卖机构。高级人民法院或者中级人民法院可以根据本地实际情况统一实施对外委托。"},{"i":4,"n":"第四条","txt":"人民法院委托的拍卖活动应在有关管理部门确定的统一交易场所或网络平台上进行，另有规定的除外。"},{"i":5,"n":"第五条","txt":"受委托的拍卖机构应通过管理部门的信息平台发布拍卖信息，公示评估、拍卖结果。"},{"i":6,"n":"第六条","txt":"涉国有资产的司法委托拍卖由省级以上国有产权交易机构实施，拍卖机构负责拍卖环节相关工作，并依照相关监管部门制定的实施细则进行。"},{"i":7,"n":"第七条","txt":"《中华人民共和国证券法》规定应当在证券交易所上市交易或转让的证券资产的司法委托拍卖，通过证券交易所实施，拍卖机构负责拍卖环节相关工作；其他证券类资产的司法委托拍卖由拍卖机构实施，并依照相关监管部门制定的实施细则进行。"},{"i":8,"n":"第八条","txt":"人民法院对其委托的评估、拍卖活动实行监督。出现下列情形之一，影响评估、拍卖结果，侵害当事人合法利益的，人民法院将不再委托其从事委托评估、拍卖工作。涉及违反法律法规的，依据有关规定处理："},{"i":9,"n":"第九条","txt":"各高级人民法院可参照本规定，结合各地实际情况，制定实施细则，报最高人民法院备案。"},{"i":10,"n":"第十条","txt":"本规定自2012年1月1日起施行。此前的司法解释和有关规定，与本规定相抵触的，以本规定为准。"}],"zuigaorenminfayuanguanyurenminfayuanshenlishiyedan271202":[{"i":1,"n":"第一条","txt":"事业单位与其工作人员之间因辞职、辞退及履行聘用合同所发生的争议，适用《中华人民共和国劳动法》的规定处理。"},{"i":2,"n":"第二条","txt":"当事人对依照国家有关规定设立的人事争议仲裁机构所作的人事争议仲裁裁决不服，自收到仲裁裁决之日起十五日内向人民法院提起诉讼的，人民法院应当依法受理。一方当事人在法定期间内不起诉又不履行仲裁裁决，另一方当事人向人民法院申请执行的，人民法院应当依法执行。"},{"i":3,"n":"第三条","txt":"本规定所称人事争议是指事业单位与其工作人员之间因辞职、辞退及履行聘用合同所发生的争议。"}],"zuigaorenminfayuanguanyurenminfayuantingshenluyinlda55a8":[{"i":1,"n":"第一条","txt":"人民法院开庭审判案件，应当对庭审活动进行全程录音录像。"},{"i":2,"n":"第二条","txt":"人民法院应当在法庭内配备固定或者移动的录音录像设备。"},{"i":3,"n":"第三条","txt":"庭审录音录像应当自宣布开庭时开始，至闭庭时结束。除下列情形外，庭审录音录像不得人为中断："},{"i":4,"n":"第四条","txt":"人民法院应当采取叠加同步录制时间或者其他措施保证庭审录音录像的真实和完整。"},{"i":5,"n":"第五条","txt":"人民法院应当使用专门设备在线或离线存储、备份庭审录音录像。因设备故障等原因导致不符合技术标准的录音录像，应当一并存储。"},{"i":6,"n":"第六条","txt":"人民法院通过使用智能语音识别系统同步转换生成的庭审文字记录，经审判人员、书记员、诉讼参与人核对签字后，作为法庭笔录管理和使用。"},{"i":7,"n":"第七条","txt":"诉讼参与人对法庭笔录有异议并申请补正的，书记员可以播放庭审录音录像进行核对、补正；不予补正的，应当将申请记录在案。"},{"i":8,"n":"第八条","txt":"适用简易程序审理民事案件的庭审录音录像，经当事人同意的，可以替代法庭笔录。"},{"i":9,"n":"第九条","txt":"人民法院应当将替代法庭笔录的庭审录音录像同步保存在服务器或者刻录成光盘，并由当事人和其他诉讼参与人对其完整性校验值签字或者采取其他方法进行确认。"},{"i":10,"n":"第十条","txt":"人民法院应当通过审判流程信息公开平台、诉讼服务平台以及其他便民诉讼服务平台，为当事人、辩护律师、诉讼代理人等依法查阅庭审录音录像提供便利。"},{"i":11,"n":"第十一条","txt":"当事人、辩护律师、诉讼代理人等可以依照规定复制录音或者誊录庭审录音录像，必要时人民法院应当配备相应设施。"},{"i":12,"n":"第十二条","txt":"人民法院可以播放依法公开审理案件的庭审录音录像。"},{"i":13,"n":"第十三条","txt":"诉讼参与人、旁听人员违反法庭纪律或者有关法律规定，危害法庭安全、扰乱法庭秩序的，人民法院可以通过庭审录音录像进行调查核实，并将其作为追究法律责任的证据。"},{"i":14,"n":"第十四条","txt":"人民检察院、诉讼参与人认为庭审活动不规范或者违反法律规定的，人民法院应当结合庭审录音录像进行调查核实。"},{"i":15,"n":"第十五条","txt":"未经人民法院许可，任何人不得对庭审活动进行录音录像，不得对庭审录音录像进行拍录、复制、删除和迁移。"},{"i":16,"n":"第十六条","txt":"涉及国家秘密、商业秘密、个人隐私等庭审活动的录制，以及对庭审录音录像的存储、查阅、复制、誊录等，应当符合保密管理等相关规定。"},{"i":17,"n":"第十七条","txt":"庭审录音录像涉及的相关技术保障、技术标准和技术规范，由最高人民法院另行制定。"},{"i":18,"n":"第十八条","txt":"人民法院从事其他审判活动或者进行执行、听证、接访等活动需要进行录音录像的，参照本规定执行。"},{"i":19,"n":"第十九条","txt":"本规定自2017年3月1日起施行。最高人民法院此前发布的司法解释及规范性文件与本规定不一致的，以本规定为准。"}],"zuigaorenminfayuanguanyurenminfayuanqiangzhizhixind8f41d":[{"i":1,"n":"第一条","txt":"本规定所称股权，包括有限责任公司股权、股份有限公司股份，但是在依法设立的证券交易所上市交易以及在国务院批准的其他全国性证券交易场所交易的股份有限公司股份除外。"},{"i":2,"n":"第二条","txt":"被执行人是公司股东的，人民法院可以强制执行其在公司持有的股权，不得直接执行公司的财产。"},{"i":3,"n":"第三条","txt":"依照民事诉讼法第二百二十四条的规定以被执行股权所在地确定管辖法院的，股权所在地是指股权所在公司的住所地。"},{"i":4,"n":"第四条","txt":"人民法院可以冻结下列资料或者信息之一载明的属于被执行人的股权："},{"i":5,"n":"第五条","txt":"人民法院冻结被执行人的股权，以其价额足以清偿生效法律文书确定的债权额及执行费用为限，不得明显超标的额冻结。股权价额无法确定的，可以根据申请执行人申请冻结的比例或者数量进行冻结。"},{"i":6,"n":"第六条","txt":"人民法院冻结被执行人的股权，应当向公司登记机关送达裁定书和协助执行通知书，要求其在国家企业信用信息公示系统进行公示。股权冻结自在公示系统公示时发生法律效力。多个人民法院冻结同一股权的，以在公示系统先办理公示的为在先冻结。"},{"i":7,"n":"第七条","txt":"被执行人就被冻结股权所作的转让、出质或者其他有碍执行的行为，不得对抗申请执行人。"},{"i":8,"n":"第八条","txt":"人民法院冻结被执行人的股权，可以向股权所在公司送达协助执行通知书，要求其在实施增资、减资、合并、分立等对被冻结股权所占比例、股权价值产生重大影响的行为前向人民法院书面报告有关情况。人民法院收到报告后，应当及时通知申请执行人，但是涉及国家秘密、商业秘密的除外。"},{"i":9,"n":"第九条","txt":"人民法院冻结被执行人基于股权享有的股息、红利等收益，应当向股权所在公司送达裁定书，并要求其在该收益到期时通知人民法院。人民法院对到期的股息、红利等收益，可以书面通知股权所在公司向申请执行人或者人民法院履行。"},{"i":10,"n":"第十条","txt":"被执行人申请自行变价被冻结股权，经申请执行人及其他已知执行债权人同意或者变价款足以清偿执行债务的，人民法院可以准许，但是应当在能够控制变价款的情况下监督其在指定期限内完成，最长不超过三个月。"},{"i":11,"n":"第十一条","txt":"拍卖被执行人的股权，人民法院应当依照《最高人民法院关于人民法院确定财产处置参考价若干问题的规定》规定的程序确定股权处置参考价，并参照参考价确定起拍价。"},{"i":12,"n":"第十二条","txt":"委托评估被执行人的股权，评估机构因缺少评估所需完整材料无法进行评估或者认为影响评估结果，被执行人未能提供且人民法院无法调取补充材料的，人民法院应当通知评估机构根据现有材料进行评估，并告知当事人因缺乏材料可能产生的不利后果。"},{"i":13,"n":"第十三条","txt":"人民法院拍卖被执行人的股权，应当采取网络司法拍卖方式。"},{"i":14,"n":"第十四条","txt":"被执行人、利害关系人以具有下列情形之一为由请求不得强制拍卖股权的，人民法院不予支持："},{"i":15,"n":"第十五条","txt":"股权变更应当由相关部门批准的，人民法院应当在拍卖公告中载明法律、行政法规或者国务院决定规定的竞买人应当具备的资格或者条件。必要时，人民法院可以就竞买资格或者条件征询相关部门意见。"},{"i":16,"n":"第十六条","txt":"生效法律文书确定被执行人交付股权，因股权所在公司在生效法律文书作出后增资或者减资导致被执行人实际持股比例降低或者升高的，人民法院应当按照下列情形分别处理："},{"i":17,"n":"第十七条","txt":"在审理股东资格确认纠纷案件中，当事人提出要求公司签发出资证明书、记载于股东名册并办理公司登记机关登记的诉讼请求且其主张成立的，人民法院应当予以支持；当事人未提出前述诉讼请求的，可以根据案件具体情况向其释明。"},{"i":18,"n":"第十八条","txt":"人民法院对被执行人在其他营利法人享有的投资权益强制执行的，参照适用本规定。"},{"i":19,"n":"第十九条","txt":"本规定自2022年1月1日起施行。"}],"zuigaorenminfayuanguanyurenminfayuankouyatieluyuns1a9fa0":[],"zuigaorenminfayuanguanyurenminfayuanzhixinggongzuo90889c":[],"zuigaorenminfayuanguanyurenminfayuanminshizhixingz055daf":[{"i":1,"n":"第一条","txt":"在执行程序中，被执行人的财产被查封、扣押、冻结后，人民法院应当及时进行拍卖、变卖或者采取其他执行措施。"},{"i":2,"n":"第二条","txt":"人民法院对查封、扣押、冻结的财产进行变价处理时，应当首先采取拍卖的方式，但法律、司法解释另有规定的除外。"},{"i":3,"n":"第三条","txt":"人民法院拍卖被执行人财产，应当委托具有相应资质的拍卖机构进行，并对拍卖机构的拍卖进行监督，但法律、司法解释另有规定的除外。"},{"i":4,"n":"第四条","txt":"对拟拍卖的财产，人民法院可以委托具有相应资质的评估机构进行价格评估。对于财产价值较低或者价格依照通常方法容易确定的，可以不进行评估。"},{"i":5,"n":"第五条","txt":"拍卖应当确定保留价。"},{"i":6,"n":"第六条","txt":"保留价确定后，依据本次拍卖保留价计算，拍卖所得价款在清偿优先债权和强制执行费用后无剩余可能的，应当在实施拍卖前将有关情况通知申请执行人。申请执行人于收到通知后五日内申请继续拍卖的，人民法院应当准许，但应当重新确定保留价；重新确定的保留价应当大于该优先债权及强制执行费用的总额。"},{"i":7,"n":"第七条","txt":"执行人员应当对拍卖财产的权属状况、占有使用情况等进行必要的调查，制作拍卖财产现状的调查笔录或者收集其他有关资料。"},{"i":8,"n":"第八条","txt":"拍卖应当先期公告。"},{"i":9,"n":"第九条","txt":"拍卖公告的范围及媒体由当事人双方协商确定；协商不成的，由人民法院确定。拍卖财产具有专业属性的，应当同时在专业性报纸上进行公告。"},{"i":10,"n":"第十条","txt":"拍卖不动产、其他财产权或者价值较高的动产的，竞买人应当于拍卖前向人民法院预交保证金。申请执行人参加竞买的，可以不预交保证金。保证金的数额由人民法院确定，但不得低于评估价或者市价的百分之五。"},{"i":11,"n":"第十一条","txt":"人民法院应当在拍卖五日前以书面或者其他能够确认收悉的适当方式，通知当事人和已知的担保物权人、优先购买权人或者其他优先权人于拍卖日到场。"},{"i":12,"n":"第十二条","txt":"法律、行政法规对买受人的资格或者条件有特殊规定的，竞买人应当具备规定的资格或者条件。"},{"i":13,"n":"第十三条","txt":"拍卖过程中，有最高应价时，优先购买权人可以表示以该最高价买受，如无更高应价，则拍归优先购买权人；如有更高应价，而优先购买权人不作表示的，则拍归该应价最高的竞买人。"},{"i":14,"n":"第十四条","txt":"拍卖多项财产时，其中部分财产卖得的价款足以清偿债务和支付被执行人应当负担的费用的，对剩余的财产应当停止拍卖，但被执行人同意全部拍卖的除外。"},{"i":15,"n":"第十五条","txt":"拍卖的多项财产在使用上不可分，或者分别拍卖可能严重减损其价值的，应当合并拍卖。"},{"i":16,"n":"第十六条","txt":"拍卖时无人竞买或者竞买人的最高应价低于保留价，到场的申请执行人或者其他执行债权人申请或者同意以该次拍卖所定的保留价接受拍卖财产的，应当将该财产交其抵债。"},{"i":17,"n":"第十七条","txt":"在拍卖开始前，有下列情形之一的，人民法院应当撤回拍卖委托："},{"i":18,"n":"第十八条","txt":"人民法院委托拍卖后，遇有依法应当暂缓执行或者中止执行的情形的，应当决定暂缓执行或者裁定中止执行，并及时通知拍卖机构和当事人。拍卖机构收到通知后，应当立即停止拍卖，并通知竞买人。"},{"i":19,"n":"第十九条","txt":"被执行人在拍卖日之前向人民法院提交足额金钱清偿债务，要求停止拍卖的，人民法院应当准许，但被执行人应当负担因拍卖支出的必要费用。"},{"i":20,"n":"第二十条","txt":"拍卖成交或者以流拍的财产抵债的，人民法院应当作出裁定，并于价款或者需要补交的差价全额交付后十日内，送达买受人或者承受人。"},{"i":21,"n":"第二十一条","txt":"拍卖成交后，买受人应当在拍卖公告确定的期限或者人民法院指定的期限内将价款交付到人民法院或者汇入人民法院指定的账户。"},{"i":22,"n":"第二十二条","txt":"拍卖成交或者以流拍的财产抵债后，买受人逾期未支付价款或者承受人逾期未补交差价而使拍卖、抵债的目的难以实现的，人民法院可以裁定重新拍卖。重新拍卖时，原买受人不得参加竞买。"},{"i":23,"n":"第二十三条","txt":"拍卖时无人竞买或者竞买人的最高应价低于保留价，到场的申请执行人或者其他执行债权人不申请以该次拍卖所定的保留价抵债的，应当在六十日内再行拍卖。"},{"i":24,"n":"第二十四条","txt":"对于第二次拍卖仍流拍的动产，人民法院可以依照本规定第十六条的规定将其作价交申请执行人或者其他执行债权人抵债。申请执行人或者其他执行债权人拒绝接受或者依法不能交付其抵债的，人民法院应当解除查封、扣押，并将该动产退还被执行人。"},{"i":25,"n":"第二十五条","txt":"对于第二次拍卖仍流拍的不动产或者其他财产权，人民法院可以依照本规定第十六条的规定将其作价交申请执行人或者其他执行债权人抵债。申请执行人或者其他执行债权人拒绝接受或者依法不能交付其抵债的，应当在六十日内进行第三次拍卖。"},{"i":26,"n":"第二十六条","txt":"不动产、动产或者其他财产权拍卖成交或者抵债后，该不动产、动产的所有权、其他财产权自拍卖成交或者抵债裁定送达买受人或者承受人时起转移。"},{"i":27,"n":"第二十七条","txt":"人民法院裁定拍卖成交或者以流拍的财产抵债后，除有依法不能移交的情形外，应当于裁定送达后十五日内，将拍卖的财产移交买受人或者承受人。被执行人或者第三人占有拍卖财产应当移交而拒不移交的，强制执行。"},{"i":28,"n":"第二十八条","txt":"拍卖财产上原有的担保物权及其他优先受偿权，因拍卖而消灭，拍卖所得价款，应当优先清偿担保物权人及其他优先受偿权人的债权，但当事人另有约定的除外。"},{"i":29,"n":"第二十九条","txt":"拍卖成交的，拍卖机构可以按照下列比例向买受人收取佣金："},{"i":30,"n":"第三十条","txt":"在执行程序中拍卖上市公司国有股和社会法人股的，适用最高人民法院《关于冻结、拍卖上市公司国有股和社会法人股若干问题的规定》。"},{"i":31,"n":"第三十一条","txt":"对查封、扣押、冻结的财产，当事人双方及有关权利人同意变卖的，可以变卖。"},{"i":32,"n":"第三十二条","txt":"当事人双方及有关权利人对变卖财产的价格有约定的，按照其约定价格变卖；无约定价格但有市价的，变卖价格不得低于市价；无市价但价值较大、价格不易确定的，应当委托评估机构进行评估，并按照评估价格进行变卖。"},{"i":33,"n":"第三十三条","txt":"本规定自2005年1月1日起施行。施行前本院公布的司法解释与本规定不一致的，以本规定为准。"}],"zuigaorenminfayuanguanyurenminfayuanminshizhixingz49e931":[{"i":1,"n":"第一条","txt":"人民法院查封、扣押、冻结被执行人的动产、不动产及其他财产权，应当作出裁定，并送达被执行人和申请执行人。"},{"i":2,"n":"第二条","txt":"人民法院可以查封、扣押、冻结被执行人占有的动产、登记在被执行人名下的不动产、特定动产及其他财产权。"},{"i":3,"n":"第三条","txt":"人民法院对被执行人的下列财产不得查封、扣押、冻结："},{"i":4,"n":"第四条","txt":"对被执行人及其所扶养家属生活所必需的居住房屋，人民法院可以查封，但不得拍卖、变卖或者抵债。"},{"i":5,"n":"第五条","txt":"对于超过被执行人及其所扶养家属生活所必需的房屋和生活用品，人民法院根据申请执行人的申请，在保障被执行人及其所扶养家属最低生活标准所必需的居住房屋和普通生活必需品后，可予以执行。"},{"i":6,"n":"第六条","txt":"查封、扣押动产的，人民法院可以直接控制该项财产。人民法院将查封、扣押的动产交付其他人控制的，应当在该动产上加贴封条或者采取其他足以公示查封、扣押的适当方式。"},{"i":7,"n":"第七条","txt":"查封不动产的，人民法院应当张贴封条或者公告，并可以提取保存有关财产权证照。"},{"i":8,"n":"第八条","txt":"查封尚未进行权属登记的建筑物时，人民法院应当通知其管理人或者该建筑物的实际占有人，并在显著位置张贴公告。"},{"i":9,"n":"第九条","txt":"扣押尚未进行权属登记的机动车辆时，人民法院应当在扣押清单上记载该机动车辆的发动机编号。该车辆在扣押期间权利人要求办理权属登记手续的，人民法院应当准许并及时办理相应的扣押登记手续。"},{"i":10,"n":"第十条","txt":"查封、扣押的财产不宜由人民法院保管的，人民法院可以指定被执行人负责保管；不宜由被执行人保管的，可以委托第三人或者申请执行人保管。"},{"i":11,"n":"第十一条","txt":"查封、扣押、冻结担保物权人占有的担保财产，一般应当指定该担保物权人作为保管人；该财产由人民法院保管的，质权、留置权不因转移占有而消灭。"},{"i":12,"n":"第十二条","txt":"对被执行人与其他人共有的财产，人民法院可以查封、扣押、冻结，并及时通知共有人。"},{"i":13,"n":"第十三条","txt":"对第三人为被执行人的利益占有的被执行人的财产，人民法院可以查封、扣押、冻结；该财产被指定给第三人继续保管的，第三人不得将其交付给被执行人。"},{"i":14,"n":"第十四条","txt":"被执行人将其财产出卖给第三人，第三人已经支付部分价款并实际占有该财产，但根据合同约定被执行人保留所有权的，人民法院可以查封、扣押、冻结；第三人要求继续履行合同的，向人民法院交付全部余款后，裁定解除查封、扣押、冻结。"},{"i":15,"n":"第十五条","txt":"被执行人将其所有的需要办理过户登记的财产出卖给第三人，第三人已经支付部分或者全部价款并实际占有该财产，但尚未办理产权过户登记手续的，人民法院可以查封、扣押、冻结；第三人已经支付全部价款并实际占有，但未办理过户登记手续的，如果第三人对此没有过错，人民法院不得查封、扣押、冻结。"},{"i":16,"n":"第十六条","txt":"被执行人购买第三人的财产，已经支付部分价款并实际占有该财产，第三人依合同约定保留所有权的，人民法院可以查封、扣押、冻结。保留所有权已办理登记的，第三人的剩余价款从该财产变价款中优先支付；第三人主张取回该财产的，可以依据民事诉讼法第二百二十七条规定提出异议。"},{"i":17,"n":"第十七条","txt":"被执行人购买需要办理过户登记的第三人的财产，已经支付部分或者全部价款并实际占有该财产，虽未办理产权过户登记手续，但申请执行人已向第三人支付剩余价款或者第三人同意剩余价款从该财产变价款中优先支付的，人民法院可以查封、扣押、冻结。"},{"i":18,"n":"第十八条","txt":"查封、扣押、冻结被执行人的财产时，执行人员应当制作笔录，载明下列内容："},{"i":19,"n":"第十九条","txt":"查封、扣押、冻结被执行人的财产，以其价额足以清偿法律文书确定的债权额及执行费用为限，不得明显超标的额查封、扣押、冻结。"},{"i":20,"n":"第二十条","txt":"查封、扣押的效力及于查封、扣押物的从物和天然孳息。"},{"i":21,"n":"第二十一条","txt":"查封地上建筑物的效力及于该地上建筑物使用范围内的土地使用权，查封土地使用权的效力及于地上建筑物，但土地使用权与地上建筑物的所有权分属被执行人与他人的除外。"},{"i":22,"n":"第二十二条","txt":"查封、扣押、冻结的财产灭失或者毁损的，查封、扣押、冻结的效力及于该财产的替代物、赔偿款。人民法院应当及时作出查封、扣押、冻结该替代物、赔偿款的裁定。"},{"i":23,"n":"第二十三条","txt":"查封、扣押、冻结协助执行通知书在送达登记机关时，登记机关已经受理被执行人转让不动产、特定动产及其他财产的过户登记申请，尚未完成登记的，应当协助人民法院执行。人民法院不得对登记机关已经完成登记的被执行人已转让的财产实施查封、扣押、冻结措施。"},{"i":24,"n":"第二十四条","txt":"被执行人就已经查封、扣押、冻结的财产所作的移转、设定权利负担或者其他有碍执行的行为，不得对抗申请执行人。"},{"i":25,"n":"第二十五条","txt":"人民法院查封、扣押被执行人设定最高额抵押权的抵押物的，应当通知抵押权人。抵押权人受抵押担保的债权数额自收到人民法院通知时起不再增加。"},{"i":26,"n":"第二十六条","txt":"对已被人民法院查封、扣押、冻结的财产，其他人民法院可以进行轮候查封、扣押、冻结。查封、扣押、冻结解除的，登记在先的轮候查封、扣押、冻结即自动生效。"},{"i":27,"n":"第二十七条","txt":"查封、扣押、冻结期限届满，人民法院未办理延期手续的，查封、扣押、冻结的效力消灭。"},{"i":28,"n":"第二十八条","txt":"有下列情形之一的，人民法院应当作出解除查封、扣押、冻结裁定，并送达申请执行人、被执行人或者案外人："},{"i":29,"n":"第二十九条","txt":"财产保全裁定和先予执行裁定的执行适用本规定。"},{"i":30,"n":"第三十条","txt":"本规定自2005年1月1日起施行。施行前本院公布的司法解释与本规定不一致的，以本规定为准。"}],"zuigaorenminfayuanguanyurenminfayuanminshitiaojieg8abf47":[{"i":1,"n":"第一条","txt":"根据民事诉讼法第九十五条的规定，人民法院可以邀请与当事人有特定关系或者与案件有一定联系的企业事业单位、社会团体或者其他组织，和具有专门知识、特定社会经验、与当事人有特定关系并有利于促成调解的个人协助调解工作。"},{"i":2,"n":"第二条","txt":"当事人在诉讼过程中自行达成和解协议的，人民法院可以根据当事人的申请依法确认和解协议制作调解书。双方当事人申请庭外和解的期间，不计入审限。"},{"i":3,"n":"第三条","txt":"人民法院应当在调解前告知当事人主持调解人员和书记员姓名以及是否申请回避等有关诉讼权利和诉讼义务。"},{"i":4,"n":"第四条","txt":"在答辩期满前人民法院对案件进行调解，适用普通程序的案件在当事人同意调解之日起15天内，适用简易程序的案件在当事人同意调解之日起7天内未达成调解协议的，经各方当事人同意，可以继续调解。延长的调解期间不计入审限。"},{"i":5,"n":"第五条","txt":"当事人申请不公开进行调解的，人民法院应当准许。"},{"i":6,"n":"第六条","txt":"当事人可以自行提出调解方案，主持调解的人员也可以提出调解方案供当事人协商时参考。"},{"i":7,"n":"第七条","txt":"调解协议内容超出诉讼请求的，人民法院可以准许。"},{"i":8,"n":"第八条","txt":"人民法院对于调解协议约定一方不履行协议应当承担民事责任的，应予准许。"},{"i":9,"n":"第九条","txt":"调解协议约定一方提供担保或者案外人同意为当事人提供担保的，人民法院应当准许。"},{"i":10,"n":"第十条","txt":"调解协议具有下列情形之一的，人民法院不予确认："},{"i":11,"n":"第十一条","txt":"当事人不能对诉讼费用如何承担达成协议的，不影响调解协议的效力。人民法院可以直接决定当事人承担诉讼费用的比例，并将决定记入调解书。"},{"i":12,"n":"第十二条","txt":"对调解书的内容既不享有权利又不承担义务的当事人不签收调解书的，不影响调解书的效力。"},{"i":13,"n":"第十三条","txt":"当事人以民事调解书与调解协议的原意不一致为由提出异议，人民法院审查后认为异议成立的，应当根据调解协议裁定补正民事调解书的相关内容。"},{"i":14,"n":"第十四条","txt":"当事人就部分诉讼请求达成调解协议的，人民法院可以就此先行确认并制作调解书。"},{"i":15,"n":"第十五条","txt":"调解书确定的担保条款条件或者承担民事责任的条件成就时，当事人申请执行的，人民法院应当依法执行。"},{"i":16,"n":"第十六条","txt":"调解书约定给付特定标的物的，调解协议达成前该物上已经存在的第三人的物权和优先权不受影响。第三人在执行过程中对执行标的物提出异议的，应当按照民事诉讼法第二百二十七条规定处理。"},{"i":17,"n":"第十七条","txt":"人民法院对刑事附带民事诉讼案件进行调解，依照本规定执行。"},{"i":18,"n":"第十八条","txt":"本规定实施前人民法院已经受理的案件，在本规定施行后尚未审结的，依照本规定执行。"},{"i":19,"n":"第十九条","txt":"本规定实施前最高人民法院的有关司法解释与本规定不一致的，适用本规定。"},{"i":20,"n":"第二十条","txt":"本规定自2004年11月1日起实施。"}],"zuigaorenminfayuanguanyurenminfayuanteyaotiaojiedeae40bf":[{"i":1,"n":"第一条","txt":"特邀调解是指人民法院吸纳符合条件的人民调解、行政调解、商事调解、行业调解等调解组织或者个人成为特邀调解组织或者特邀调解员，接受人民法院立案前委派或者立案后委托依法进行调解，促使当事人在平等协商基础上达成调解协议、解决纠纷的一种调解活动。"},{"i":2,"n":"第二条","txt":"特邀调解应当遵循以下原则："},{"i":3,"n":"第三条","txt":"人民法院在特邀调解工作中，承担以下职责："},{"i":4,"n":"第四条","txt":"人民法院应当指定诉讼服务中心等部门具体负责指导特邀调解工作，并配备熟悉调解业务的工作人员。"},{"i":5,"n":"第五条","txt":"人民法院开展特邀调解工作应当建立特邀调解组织和特邀调解员名册。建立名册的法院应当为入册的特邀调解组织或者特邀调解员颁发证书，并对名册进行管理。上级法院建立的名册，下级法院可以使用。"},{"i":6,"n":"第六条","txt":"依法成立的人民调解、行政调解、商事调解、行业调解及其他具有调解职能的组织，可以申请加入特邀调解组织名册。品行良好、公道正派、热心调解工作并具有一定沟通协调能力的个人可以申请加入特邀调解员名册。"},{"i":7,"n":"第七条","txt":"特邀调解员在入册前和任职期间，应当接受人民法院组织的业务培训。"},{"i":8,"n":"第八条","txt":"人民法院应当在诉讼服务中心等场所提供特邀调解组织和特邀调解员名册，并在法院公示栏、官方网站等平台公开名册信息，方便当事人查询。"},{"i":9,"n":"第九条","txt":"人民法院可以设立家事、交通事故、医疗纠纷等专业调解委员会，并根据特定专业领域的纠纷特点，设定专业调解委员会的入册条件，规范专业领域特邀调解程序。"},{"i":10,"n":"第十条","txt":"人民法院应当建立特邀调解组织和特邀调解员业绩档案，定期组织开展特邀调解评估工作，并及时更新名册信息。"},{"i":11,"n":"第十一条","txt":"对适宜调解的纠纷，登记立案前，人民法院可以经当事人同意委派给特邀调解组织或者特邀调解员进行调解；登记立案后或者在审理过程中，可以委托给特邀调解组织或者特邀调解员进行调解。"},{"i":12,"n":"第十二条","txt":"双方当事人应当在名册中协商确定特邀调解员；协商不成的，由特邀调解组织或者人民法院指定。当事人不同意指定的，视为不同意调解。"},{"i":13,"n":"第十三条","txt":"特邀调解一般由一名调解员进行。对于重大、疑难、复杂或者当事人要求由两名以上调解员共同调解的案件，可以由两名以上调解员调解，并由特邀调解组织或者人民法院指定一名调解员主持。当事人有正当理由的，可以申请更换特邀调解员。"},{"i":14,"n":"第十四条","txt":"调解一般应当在人民法院或者调解组织所在地进行，双方当事人也可以在征得人民法院同意的情况下选择其他地点进行调解。"},{"i":15,"n":"第十五条","txt":"特邀调解员有下列情形之一的，当事人有权申请回避："},{"i":16,"n":"第十六条","txt":"特邀调解员不得在后续的诉讼程序中担任该案的人民陪审员、诉讼代理人、证人、鉴定人以及翻译人员等。"},{"i":17,"n":"第十七条","txt":"特邀调解员应当根据案件具体情况采用适当的方法进行调解，可以提出解决争议的方案建议。特邀调解员为促成当事人达成调解协议，可以邀请对达成调解协议有帮助的人员参与调解。"},{"i":18,"n":"第十八条","txt":"特邀调解员发现双方当事人存在虚假调解可能的，应当中止调解，并向人民法院或者特邀调解组织报告。"},{"i":19,"n":"第十九条","txt":"委派调解达成调解协议，特邀调解员应当将调解协议送达双方当事人，并提交人民法院备案。"},{"i":20,"n":"第二十条","txt":"委托调解达成调解协议，特邀调解员应当向人民法院提交调解协议，由人民法院审查并制作调解书结案。达成调解协议后，当事人申请撤诉的，人民法院应当依法作出裁定。"},{"i":21,"n":"第二十一条","txt":"委派调解未达成调解协议的，特邀调解员应当将当事人的起诉状等材料移送人民法院；当事人坚持诉讼的，人民法院应当依法登记立案。"},{"i":22,"n":"第二十二条","txt":"在调解过程中，当事人为达成调解协议作出妥协而认可的事实，不得在诉讼程序中作为对其不利的根据，但是当事人均同意的除外。"},{"i":23,"n":"第二十三条","txt":"经特邀调解组织或者特邀调解员调解达成调解协议的，可以制作调解协议书。当事人认为无需制作调解协议书的，可以采取口头协议方式，特邀调解员应当记录协议内容。"},{"i":24,"n":"第二十四条","txt":"调解协议书应当记载以下内容："},{"i":25,"n":"第二十五条","txt":"委派调解达成调解协议后，当事人就调解协议的履行或者调解协议的内容发生争议的，可以向人民法院提起诉讼，人民法院应当受理。一方当事人以原纠纷向人民法院起诉，对方当事人以调解协议提出抗辩的，应当提供调解协议书。"},{"i":26,"n":"第二十六条","txt":"有下列情形之一的，特邀调解员应当终止调解："},{"i":27,"n":"第二十七条","txt":"人民法院委派调解的案件，调解期限为30日。但是双方当事人同意延长调解期限的，不受此限。"},{"i":28,"n":"第二十八条","txt":"特邀调解员不得有下列行为："},{"i":29,"n":"第二十九条","txt":"人民法院应当根据实际情况向特邀调解员发放误工、交通等补贴，对表现突出的特邀调解组织和特邀调解员给予物质或者荣誉奖励。补贴经费应当纳入人民法院专项预算。"},{"i":30,"n":"第三十条","txt":"本规定自2016年7月1日起施行。"}],"zuigaorenminfayuanguanyurenminfayuandengjilianruog7f1679":[{"i":1,"n":"第一条","txt":"人民法院对依法应该受理的一审民事起诉、行政起诉和刑事自诉，实行立案登记制。"},{"i":2,"n":"第二条","txt":"对起诉、自诉，人民法院应当一律接收诉状，出具书面凭证并注明收到日期。"},{"i":3,"n":"第三条","txt":"人民法院应当提供诉状样本，为当事人书写诉状提供示范和指引。"},{"i":4,"n":"第四条","txt":"民事起诉状应当记明以下事项："},{"i":5,"n":"第五条","txt":"刑事自诉状应当记明以下事项："},{"i":6,"n":"第六条","txt":"当事人提出起诉、自诉的，应当提交以下材料："},{"i":7,"n":"第七条","txt":"当事人提交的诉状和材料不符合要求的，人民法院应当一次性书面告知在指定期限内补正。"},{"i":8,"n":"第八条","txt":"对当事人提出的起诉、自诉，人民法院当场不能判定是否符合法律规定的，应当作出以下处理："},{"i":9,"n":"第九条","txt":"人民法院对起诉、自诉不予受理或者不予立案的，应当出具书面裁定或者决定，并载明理由。"},{"i":10,"n":"第十条","txt":"人民法院对下列起诉、自诉不予登记立案："},{"i":11,"n":"第十一条","txt":"登记立案后，当事人未在法定期限内交纳诉讼费的，按撤诉处理，但符合法律规定的缓、减、免交诉讼费条件的除外。"},{"i":12,"n":"第十二条","txt":"登记立案后，人民法院立案庭应当及时将案件移送审判庭审理。"},{"i":13,"n":"第十三条","txt":"对立案工作中存在的不接收诉状、接收诉状后不出具书面凭证，不一次性告知当事人补正诉状内容，以及有案不立、拖延立案、干扰立案、既不立案又不作出裁定或者决定等违法违纪情形，当事人可以向受诉人民法院或者上级人民法院投诉。"},{"i":14,"n":"第十四条","txt":"为方便当事人行使诉权，人民法院提供网上立案、预约立案、巡回立案等诉讼服务。"},{"i":15,"n":"第十五条","txt":"人民法院推动多元化纠纷解决机制建设，尊重当事人选择人民调解、行政调解、行业调解、仲裁等多种方式维护权益，化解纠纷。"},{"i":16,"n":"第十六条","txt":"人民法院依法维护登记立案秩序，推进诉讼诚信建设。对干扰立案秩序、虚假诉讼的，根据民事诉讼法、行政诉讼法有关规定予以罚款、拘留；构成犯罪的，依法追究刑事责任。"},{"i":17,"n":"第十七条","txt":"本规定的“起诉”，是指当事人提起民事、行政诉讼；“自诉”，是指当事人提起刑事自诉。"},{"i":18,"n":"第十八条","txt":"强制执行和国家赔偿申请登记立案工作，按照本规定执行。"},{"i":19,"n":"第十九条","txt":"人民法庭登记立案工作，按照本规定执行。"},{"i":20,"n":"第二十条","txt":"本规定自2015年5月1日起施行。以前有关立案的规定与本规定不一致的，按照本规定执行。"}],"zuigaorenminfayuanguanyurenminfayuanquedingcaichan679b5c":[{"i":1,"n":"第一条","txt":"人民法院查封、扣押、冻结财产后，对需要拍卖、变卖的财产，应当在三十日内启动确定财产处置参考价程序。"},{"i":2,"n":"第二条","txt":"人民法院确定财产处置参考价，可以采取当事人议价、定向询价、网络询价、委托评估等方式。"},{"i":3,"n":"第三条","txt":"人民法院确定参考价前，应当查明财产的权属、权利负担、占有使用、欠缴税费、质量瑕疵等事项。"},{"i":4,"n":"第四条","txt":"采取当事人议价方式确定参考价的，除一方当事人拒绝议价或者下落不明外，人民法院应当以适当的方式通知或者组织当事人进行协商，当事人应当在指定期限内提交议价结果。"},{"i":5,"n":"第五条","txt":"当事人议价不能或者不成，且财产有计税基准价、政府定价或者政府指导价的，人民法院应当向确定参考价时财产所在地的有关机构进行定向询价。"},{"i":6,"n":"第六条","txt":"采取定向询价方式确定参考价的，人民法院应当向有关机构出具询价函，询价函应当载明询价要求、完成期限等内容。"},{"i":7,"n":"第七条","txt":"定向询价不能或者不成，财产无需由专业人员现场勘验或者鉴定，且具备网络询价条件的，人民法院应当通过司法网络询价平台进行网络询价。"},{"i":8,"n":"第八条","txt":"最高人民法院建立全国性司法网络询价平台名单库。"},{"i":9,"n":"第九条","txt":"最高人民法院组成专门的评审委员会，负责司法网络询价平台的选定、评审和除名。每年引入权威第三方对已纳入和新申请纳入名单库的司法网络询价平台予以评审并公布结果。"},{"i":10,"n":"第十条","txt":"采取网络询价方式确定参考价的，人民法院应当同时向名单库中的全部司法网络询价平台发出网络询价委托书。网络询价委托书应当载明财产名称、物理特征、规格数量、目的要求、完成期限以及其他需要明确的内容等。"},{"i":11,"n":"第十一条","txt":"司法网络询价平台应当在收到人民法院网络询价委托书之日起三日内出具网络询价报告。网络询价报告应当载明财产的基本情况、参照样本、计算方法、询价结果及有效期等内容。"},{"i":12,"n":"第十二条","txt":"人民法院应当对网络询价报告进行审查。网络询价报告均存在财产基本信息错误、超出财产范围或者遗漏财产等情形的，应当通知司法网络询价平台在三日内予以补正；部分网络询价报告不存在上述情形的，无需通知其他司法网络询价平台补正。"},{"i":13,"n":"第十三条","txt":"全部司法网络询价平台均在期限内出具询价结果或者补正结果的，人民法院应当以全部司法网络询价平台出具结果的平均值为参考价；部分司法网络询价平台在期限内出具询价结果或者补正结果的，人民法院应当以该部分司法网络询价平台出具结果的平均值为参考价。"},{"i":14,"n":"第十四条","txt":"法律、行政法规规定必须委托评估、双方当事人要求委托评估或者网络询价不能或不成的，人民法院应当委托评估机构进行评估。"},{"i":15,"n":"第十五条","txt":"最高人民法院根据全国性评估行业协会推荐的评估机构名单建立人民法院司法评估机构名单库。按评估专业领域和评估机构的执业范围建立名单分库，在分库下根据行政区划设省、市两级名单子库。"},{"i":16,"n":"第十六条","txt":"采取委托评估方式确定参考价的，人民法院应当通知双方当事人在指定期限内从名单分库中协商确定三家评估机构以及顺序；双方当事人在指定期限内协商不成或者一方当事人下落不明的，采取摇号方式在名单分库或者财产所在地的名单子库中随机确定三家评估机构以及顺序。双方当事人一致要求在同一名单子库中随机确定的，人民法院应当准许。"},{"i":17,"n":"第十七条","txt":"人民法院应当向顺序在先的评估机构出具评估委托书，评估委托书应当载明财产名称、物理特征、规格数量、目的要求、完成期限以及其他需要明确的内容等，同时应当将查明的财产情况及相关材料一并移交给评估机构。"},{"i":18,"n":"第十八条","txt":"评估需要进行现场勘验的，人民法院应当通知当事人到场；当事人不到场的，不影响勘验的进行，但应当有见证人见证。现场勘验需要当事人、协助义务人配合的，人民法院依法责令其配合；不予配合的，可以依法强制进行。"},{"i":19,"n":"第十九条","txt":"评估机构应当在三十日内出具评估报告。人民法院决定暂缓或者裁定中止执行的期间，应当从前述期限中扣除。"},{"i":20,"n":"第二十条","txt":"人民法院应当对评估报告进行审查。具有下列情形之一的，应当责令评估机构在三日内予以书面说明或者补正："},{"i":21,"n":"第二十一条","txt":"人民法院收到定向询价、网络询价、委托评估、说明补正等报告后，应当在三日内发送给当事人及利害关系人。"},{"i":22,"n":"第二十二条","txt":"当事人、利害关系人认为网络询价报告或者评估报告具有下列情形之一的，可以在收到报告后五日内提出书面异议："},{"i":23,"n":"第二十三条","txt":"当事人、利害关系人收到评估报告后五日内对评估报告的参照标准、计算方法或者评估结果等提出书面异议的，人民法院应当在三日内交评估机构予以书面说明。评估机构在五日内未作说明或者当事人、利害关系人对作出的说明仍有异议的，人民法院应当交由相关行业协会在指定期限内组织专业技术评审，并根据专业技术评审出具的结论认定评估结果或者责令原评估机构予以补正。"},{"i":24,"n":"第二十四条","txt":"当事人、利害关系人未在本规定第二十二条、第二十三条规定的期限内提出异议或者对网络询价平台、评估机构、行业协会按照本规定第二十二条、第二十三条所作的补正说明、专业技术评审结论提出异议的，人民法院不予受理。"},{"i":25,"n":"第二十五条","txt":"当事人、利害关系人有证据证明具有下列情形之一，且在发布一拍拍卖公告或者直接进入变卖程序之前提出异议的，人民法院应当按照执行监督程序进行审查处理："},{"i":26,"n":"第二十六条","txt":"当事人、利害关系人对评估报告未提出异议、所提异议被驳回或者评估机构已作出补正的，人民法院应当以评估结果或者补正结果为参考价；当事人、利害关系人对评估报告提出的异议成立的，人民法院应当以评估机构作出的补正结果或者重新作出的评估结果为参考价。专业技术评审对评估报告未作出否定结论的，人民法院应当以该评估结果为参考价。"},{"i":27,"n":"第二十七条","txt":"司法网络询价平台、评估机构应当确定网络询价或者委托评估结果的有效期，有效期最长不得超过一年。"},{"i":28,"n":"第二十八条","txt":"具有下列情形之一的，人民法院应当决定暂缓网络询价或者委托评估："},{"i":29,"n":"第二十九条","txt":"具有下列情形之一的，人民法院应当撤回网络询价或者委托评估："},{"i":30,"n":"第三十条","txt":"人民法院应当在参考价确定后十日内启动财产变价程序。拍卖的，参照参考价确定起拍价；直接变卖的，参照参考价确定变卖价。"},{"i":31,"n":"第三十一条","txt":"人民法院委托司法网络询价平台进行网络询价的，网络询价费用应当按次计付给出具网络询价结果与财产处置成交价最接近的司法网络询价平台；多家司法网络询价平台出具的网络询价结果相同或者与财产处置成交价差距相同的，网络询价费用平均分配。"},{"i":32,"n":"第三十二条","txt":"人民法院委托评估机构进行评估，财产处置未成交的，按照评估机构合理的实际支出计付费用；财产处置成交价高于评估价的，以评估价为基准计付费用；财产处置成交价低于评估价的，以财产处置成交价为基准计付费用。"},{"i":33,"n":"第三十三条","txt":"网络询价费及委托评估费由申请执行人先行垫付，由被执行人负担。"},{"i":34,"n":"第三十四条","txt":"最高人民法院建设全国法院询价评估系统。询价评估系统与定向询价机构、司法网络询价平台、全国性评估行业协会的系统对接，实现数据共享。"},{"i":35,"n":"第三十五条","txt":"本规定自2018年9月1日起施行。"}],"zuigaorenminfayuanguanyurenminfayuanwangluosifapaia2c740":[{"i":1,"n":"第一条","txt":"本规定所称的网络司法拍卖，是指人民法院依法通过互联网拍卖平台，以网络电子竞价方式公开处置财产的行为。"},{"i":2,"n":"第二条","txt":"人民法院以拍卖方式处置财产的，应当采取网络司法拍卖方式，但法律、行政法规和司法解释规定必须通过其他途径处置，或者不宜采用网络拍卖方式处置的除外。"},{"i":3,"n":"第三条","txt":"网络司法拍卖应当在互联网拍卖平台上向社会全程公开，接受社会监督。"},{"i":4,"n":"第四条","txt":"最高人民法院建立全国性网络服务提供者名单库。网络服务提供者申请纳入名单库的，其提供的网络司法拍卖平台应当符合下列条件："},{"i":5,"n":"第五条","txt":"网络服务提供者由申请执行人从名单库中选择；未选择或者多个申请执行人的选择不一致的，由人民法院指定。"},{"i":6,"n":"第六条","txt":"实施网络司法拍卖的，人民法院应当履行下列职责："},{"i":7,"n":"第七条","txt":"实施网络司法拍卖的，人民法院可以将下列拍卖辅助工作委托社会机构或者组织承担："},{"i":8,"n":"第八条","txt":"实施网络司法拍卖的，下列事项应当由网络服务提供者承担："},{"i":9,"n":"第九条","txt":"网络司法拍卖服务提供者从事与网络司法拍卖相关的行为，应当接受人民法院的管理、监督和指导。"},{"i":10,"n":"第十条","txt":"网络司法拍卖应当确定保留价，拍卖保留价即为起拍价。"},{"i":11,"n":"第十一条","txt":"网络司法拍卖不限制竞买人数量。一人参与竞拍，出价不低于起拍价的，拍卖成交。"},{"i":12,"n":"第十二条","txt":"网络司法拍卖应当先期公告，拍卖公告除通过法定途径发布外，还应同时在网络司法拍卖平台发布。拍卖动产的，应当在拍卖十五日前公告；拍卖不动产或者其他财产权的，应当在拍卖三十日前公告。"},{"i":13,"n":"第十三条","txt":"实施网络司法拍卖的，人民法院应当在拍卖公告发布当日通过网络司法拍卖平台公示下列信息："},{"i":14,"n":"第十四条","txt":"实施网络司法拍卖的，人民法院应当在拍卖公告发布当日通过网络司法拍卖平台对下列事项予以特别提示："},{"i":15,"n":"第十五条","txt":"被执行人应当提供拍卖财产品质的有关资料和说明。"},{"i":16,"n":"第十六条","txt":"网络司法拍卖的事项应当在拍卖公告发布三日前以书面或者其他能够确认收悉的合理方式，通知当事人、已知优先购买权人。权利人书面明确放弃权利的，可以不通知。无法通知的，应当在网络司法拍卖平台公示并说明无法通知的理由，公示满五日视为已经通知。"},{"i":17,"n":"第十七条","txt":"保证金数额由人民法院在起拍价的百分之五至百分之二十范围内确定。"},{"i":18,"n":"第十八条","txt":"竞买人在拍卖竞价程序结束前交纳保证金经人民法院或者网络服务提供者确认后，取得竞买资格。网络服务提供者应当向取得资格的竞买人赋予竞买代码、参拍密码；竞买人以该代码参与竞买。"},{"i":19,"n":"第十九条","txt":"优先购买权人经人民法院确认后，取得优先竞买资格以及优先竞买代码、参拍密码，并以优先竞买代码参与竞买；未经确认的，不得以优先购买权人身份参与竞买。"},{"i":20,"n":"第二十条","txt":"网络司法拍卖从起拍价开始以递增出价方式竞价，增价幅度由人民法院确定。竞买人以低于起拍价出价的无效。"},{"i":21,"n":"第二十一条","txt":"优先购买权人参与竞买的，可以与其他竞买人以相同的价格出价，没有更高出价的，拍卖财产由优先购买权人竞得。"},{"i":22,"n":"第二十二条","txt":"网络司法拍卖成交的，由网络司法拍卖平台以买受人的真实身份自动生成确认书并公示。"},{"i":23,"n":"第二十三条","txt":"拍卖成交后，买受人交纳的保证金可以充抵价款；其他竞买人交纳的保证金应当在竞价程序结束后二十四小时内退还或者解冻。拍卖未成交的，竞买人交纳的保证金应当在竞价程序结束后二十四小时内退还或者解冻。"},{"i":24,"n":"第二十四条","txt":"拍卖成交后买受人悔拍的，交纳的保证金不予退还，依次用于支付拍卖产生的费用损失、弥补重新拍卖价款低于原拍卖价款的差价、冲抵本案被执行人的债务以及与拍卖财产相关的被执行人的债务。"},{"i":25,"n":"第二十五条","txt":"拍卖成交后，买受人应当在拍卖公告确定的期限内将剩余价款交付人民法院指定账户。拍卖成交后二十四小时内，网络服务提供者应当将冻结的买受人交纳的保证金划入人民法院指定账户。"},{"i":26,"n":"第二十六条","txt":"网络司法拍卖竞价期间无人出价的，本次拍卖流拍。流拍后应当在三十日内在同一网络司法拍卖平台再次拍卖，拍卖动产的应当在拍卖七日前公告；拍卖不动产或者其他财产权的应当在拍卖十五日前公告。再次拍卖的起拍价降价幅度不得超过前次起拍价的百分之二十。"},{"i":27,"n":"第二十七条","txt":"起拍价及其降价幅度、竞价增价幅度、保证金数额和优先购买权人竞买资格及其顺序等事项，应当由人民法院依法组成合议庭评议确定。"},{"i":28,"n":"第二十八条","txt":"网络司法拍卖竞价程序中，有依法应当暂缓、中止执行等情形的，人民法院应当决定暂缓或者裁定中止拍卖；人民法院可以自行或者通知网络服务提供者停止拍卖。"},{"i":29,"n":"第二十九条","txt":"网络服务提供者对拍卖形成的电子数据，应当完整保存不少于十年，但法律、行政法规另有规定的除外。"},{"i":30,"n":"第三十条","txt":"因网络司法拍卖本身形成的税费，应当依照相关法律、行政法规的规定，由相应主体承担；没有规定或者规定不明的，人民法院可以根据法律原则和案件实际情况确定税费承担的相关主体、数额。"},{"i":31,"n":"第三十一条","txt":"当事人、利害关系人提出异议请求撤销网络司法拍卖，符合下列情形之一的，人民法院应当支持："},{"i":32,"n":"第三十二条","txt":"网络司法拍卖被人民法院撤销，当事人、利害关系人、案外人认为人民法院的拍卖行为违法致使其合法权益遭受损害的，可以依法申请国家赔偿；认为其他主体的行为违法致使其合法权益遭受损害的，可以另行提起诉讼。"},{"i":33,"n":"第三十三条","txt":"当事人、利害关系人、案外人认为网络司法拍卖服务提供者的行为违法致使其合法权益遭受损害的，可以另行提起诉讼；理由成立的，人民法院应当支持，但具有法定免责事由的除外。"},{"i":34,"n":"第三十四条","txt":"实施网络司法拍卖的，下列机构和人员不得竞买并不得委托他人代为竞买与其行为相关的拍卖财产："},{"i":35,"n":"第三十五条","txt":"网络服务提供者有下列情形之一的，应当将其从名单库中除名："},{"i":36,"n":"第三十六条","txt":"当事人、利害关系人认为网络司法拍卖行为违法侵害其合法权益的，可以提出执行异议。异议、复议期间，人民法院可以决定暂缓或者裁定中止拍卖。"},{"i":37,"n":"第三十七条","txt":"人民法院通过互联网平台以变卖方式处置财产的，参照本规定执行。"},{"i":38,"n":"第三十八条","txt":"本规定自2017年1月1日起施行。施行前最高人民法院公布的司法解释和规范性文件与本规定不一致的，以本规定为准。"}],"zuigaorenminfayuanguanyurenminfayuannengfouduixinya88068":[],"zuigaorenminfayuanguanyurenminfayuanpeichangweiyua0146f1":[{"i":1,"n":"第一条","txt":"赔偿请求人向赔偿委员会申请作出赔偿决定，应当递交赔偿申请书一式四份。赔偿请求人书写申请书确有困难的，可以口头申请。口头提出申请的，人民法院应当填写《申请赔偿登记表》，由赔偿请求人签名或者盖章。"},{"i":2,"n":"第二条","txt":"赔偿请求人向赔偿委员会申请作出赔偿决定，应当提供以下法律文书和证明材料："},{"i":3,"n":"第三条","txt":"赔偿委员会收到赔偿申请，经审查认为符合申请条件的，应当在七日内立案，并通知赔偿请求人、赔偿义务机关和复议机关；认为不符合申请条件的，应当在七日内决定不予受理；立案后发现不符合申请条件的，决定驳回申请。"},{"i":4,"n":"第四条","txt":"赔偿委员会应当在立案之日起五日内将赔偿申请书副本或者《申请赔偿登记表》副本送达赔偿义务机关和复议机关。"},{"i":5,"n":"第五条","txt":"赔偿请求人可以委托一至二人作为代理人。律师、提出申请的公民的近亲属、有关的社会团体或者所在单位推荐的人、经赔偿委员会许可的其他公民，都可以被委托为代理人。"},{"i":6,"n":"第六条","txt":"赔偿请求人、赔偿义务机关、复议机关委托他人代理，应当向赔偿委员会提交由委托人签名或者盖章的授权委托书。"},{"i":7,"n":"第七条","txt":"赔偿委员会审理赔偿案件，应当指定一名审判员负责具体承办。"},{"i":8,"n":"第八条","txt":"审判人员有下列情形之一的，应当回避，赔偿请求人和赔偿义务机关有权以书面或者口头方式申请其回避："},{"i":9,"n":"第九条","txt":"赔偿委员会审理赔偿案件，可以组织赔偿义务机关与赔偿请求人就赔偿方式、赔偿项目和赔偿数额依照国家赔偿法第四章的规定进行协商。"},{"i":10,"n":"第十条","txt":"组织协商应当遵循自愿和合法的原则。赔偿请求人、赔偿义务机关一方或者双方不愿协商，或者协商不成的，赔偿委员会应当及时作出决定。"},{"i":11,"n":"第十一条","txt":"赔偿请求人和赔偿义务机关经协商达成协议的，赔偿委员会审查确认后应当制作国家赔偿决定书。"},{"i":12,"n":"第十二条","txt":"赔偿请求人、赔偿义务机关对自己提出的主张或者反驳对方主张所依据的事实有责任提供证据加以证明。有国家赔偿法第二十六条第二款规定情形的，应当由赔偿义务机关提供证据。"},{"i":13,"n":"第十三条","txt":"赔偿义务机关对其职权行为的合法性负有举证责任。"},{"i":14,"n":"第十四条","txt":"有下列情形之一的，赔偿委员会可以组织赔偿请求人和赔偿义务机关进行质证："},{"i":15,"n":"第十五条","txt":"赔偿委员会认为重大、疑难的案件，应报请院长提交审判委员会讨论决定。审判委员会的决定，赔偿委员会应当执行。"},{"i":16,"n":"第十六条","txt":"赔偿委员会作出决定前，赔偿请求人撤回赔偿申请的，赔偿委员会应当依法审查并作出是否准许的决定。"},{"i":17,"n":"第十七条","txt":"有下列情形之一的，赔偿委员会应当决定中止审理："},{"i":18,"n":"第十八条","txt":"有下列情形之一的，赔偿委员会应当决定终结审理："},{"i":19,"n":"第十九条","txt":"赔偿委员会审理赔偿案件应当按照下列情形，分别作出决定："},{"i":20,"n":"第二十条","txt":"赔偿委员会审理赔偿案件作出决定，应当制作国家赔偿决定书，加盖人民法院印章。"},{"i":21,"n":"第二十一条","txt":"国家赔偿决定书应当载明以下事项："},{"i":22,"n":"第二十二条","txt":"赔偿委员会作出的决定应当分别送达赔偿请求人、赔偿义务机关和复议机关。"},{"i":23,"n":"第二十三条","txt":"人民法院办理本院为赔偿义务机关的国家赔偿案件参照本规定。"},{"i":24,"n":"第二十四条","txt":"自本规定公布之日起，《人民法院赔偿委员会审理赔偿案件程序的暂行规定》即行废止；本规定施行前本院发布的司法解释与本规定不一致的，以本规定为准。"}],"zuigaorenminfayuanguanyurenminfayuanpeichangweiyua6b3711":[{"i":1,"n":"第一条","txt":"赔偿委员会根据国家赔偿法第二十七条的规定，听取赔偿请求人、赔偿义务机关的陈述和申辩，进行质证的，适用本规定。"},{"i":2,"n":"第二条","txt":"有下列情形之一，经书面审理不能解决的，赔偿委员会可以组织赔偿请求人和赔偿义务机关进行质证："},{"i":3,"n":"第三条","txt":"除涉及国家秘密、个人隐私或者法律另有规定的以外，质证应当公开进行。"},{"i":4,"n":"第四条","txt":"赔偿请求人和赔偿义务机关在质证活动中的法律地位平等，有权委托代理人，提出回避申请，提供证据，申请查阅、复制本案质证材料，进行陈述、质询、申辩，并应当依法行使质证权利，遵守质证秩序。"},{"i":5,"n":"第五条","txt":"赔偿请求人、赔偿义务机关对其主张的有利于自己的事实负举证责任，但法律、司法解释另有规定的除外。"},{"i":6,"n":"第六条","txt":"下列事实需要证明的，由赔偿义务机关负举证责任："},{"i":7,"n":"第七条","txt":"下列情形，由赔偿义务机关负举证责任："},{"i":8,"n":"第八条","txt":"赔偿委员会认为必要时，可以通知复议机关参加质证，由复议机关对其作出复议决定的事实和法律依据进行说明。"},{"i":9,"n":"第九条","txt":"赔偿请求人可以在举证期限内申请赔偿委员会调取下列证据："},{"i":10,"n":"第十条","txt":"赔偿委员会有权要求赔偿请求人、赔偿义务机关提供或者补充证据。"},{"i":11,"n":"第十一条","txt":"赔偿请求人、赔偿义务机关应当在收到受理案件通知书之日起十日内提供证据。赔偿请求人、赔偿义务机关确因客观事由不能在该期限内提供证据的，赔偿委员会可以根据其申请适当延长举证期限。"},{"i":12,"n":"第十二条","txt":"对于证据较多或者疑难复杂的案件，赔偿委员会可以组织赔偿请求人、赔偿义务机关在质证前交换证据，明确争议焦点，并将交换证据的情况记录在卷。"},{"i":13,"n":"第十三条","txt":"赔偿委员会应当指定审判员组织质证，并在质证三日前通知赔偿请求人、赔偿义务机关和其他质证参与人。必要时，赔偿委员会可以通知赔偿义务机关实施原职权行为的工作人员或者其他利害关系人到场接受询问。"},{"i":14,"n":"第十四条","txt":"适用质证程序审理国家赔偿案件，未经质证的证据不得作为认定案件事实的依据，但法律、司法解释另有规定的除外。"},{"i":15,"n":"第十五条","txt":"赔偿请求人、赔偿义务机关应围绕证据的关联性、真实性、合法性，针对证据有无证明力以及证明力大小，进行质证。"},{"i":16,"n":"第十六条","txt":"质证开始前，由书记员查明质证参与人是否到场，宣布质证纪律。"},{"i":17,"n":"第十七条","txt":"质证一般按照下列顺序进行："},{"i":18,"n":"第十八条","txt":"赔偿委员会根据赔偿请求人申请调取的证据，作为赔偿请求人提供的证据进行质证。"},{"i":19,"n":"第十九条","txt":"赔偿请求人或者赔偿义务机关对对方主张的不利于自己的事实，在质证中明确表示承认的，对方无需举证；既未表示承认也未否认，经审判员询问并释明法律后果后，其仍不作明确表示的，视为对该项事实的承认。"},{"i":20,"n":"第二十条","txt":"下列事实无需举证证明："},{"i":21,"n":"第二十一条","txt":"有证据证明赔偿义务机关持有证据无正当理由拒不提供的，赔偿委员会可以就待证事实作出有利于赔偿请求人的推定。"},{"i":22,"n":"第二十二条","txt":"赔偿委员会应当依据法律规定，遵照法定程序，全面客观地审核证据，运用逻辑推理和日常生活经验，对证据的证明力进行独立、综合的审查判断。"},{"i":23,"n":"第二十三条","txt":"书记员应当将质证的全部活动记入笔录。质证笔录由赔偿请求人、赔偿义务机关和其他质证参与人核对无误或者补正后签名或者盖章。拒绝签名或者盖章的，应当记明情况附卷，由审判员和书记员签名。"},{"i":24,"n":"第二十四条","txt":"赔偿请求人、赔偿义务机关经通知无正当理由拒不参加质证或者未经许可中途退出质证的，视为放弃质证，赔偿委员会可以综合全案情况和对方意见认定案件事实。"},{"i":25,"n":"第二十五条","txt":"有下列情形之一的，可以延期质证："},{"i":26,"n":"第二十六条","txt":"本规定自2014年3月1日起施行。"}],"zuigaorenminfayuanguanyurenminfayuantongguohulianw416cc2":[{"i":1,"n":"第一条","txt":"人民法院审判刑事、民事、行政、国家赔偿案件的流程信息，应当通过互联网向参加诉讼的当事人及其法定代理人、诉讼代理人、辩护人公开。"},{"i":2,"n":"第二条","txt":"人民法院通过互联网公开审判流程信息，应当依法、规范、及时、便民。"},{"i":3,"n":"第三条","txt":"中国审判流程信息公开网是人民法院公开审判流程信息的统一平台。各级人民法院在本院门户网站以及司法公开平台设置中国审判流程信息公开网的链接。"},{"i":4,"n":"第四条","txt":"人民法院应当在受理案件通知书、应诉通知书、参加诉讼通知书、出庭通知书中，告知当事人及其法定代理人、诉讼代理人、辩护人通过互联网获取审判流程信息的方法和注意事项。"},{"i":5,"n":"第五条","txt":"当事人、法定代理人、诉讼代理人、辩护人的身份证件号码、律师执业证号、组织机构代码、统一社会信用代码，是其获取审判流程信息的身份验证依据。"},{"i":6,"n":"第六条","txt":"人民法院通知当事人应诉、参加诉讼，准许当事人参加诉讼，或者采用公告方式送达当事人的，自完成其身份信息采集、核对后，依照本规定公开审判流程信息。"},{"i":7,"n":"第七条","txt":"下列程序性信息应当通过互联网向当事人及其法定代理人、诉讼代理人、辩护人公开："},{"i":8,"n":"第八条","txt":"回避、管辖争议、保全、先予执行、评估、鉴定等流程信息，应当通过互联网向当事人及其法定代理人、诉讼代理人、辩护人公开。"},{"i":9,"n":"第九条","txt":"下列诉讼文书应当于送达后通过互联网向当事人及其法定代理人、诉讼代理人、辩护人公开："},{"i":10,"n":"第十条","txt":"庭审、质证、证据交换、庭前会议、调查取证、勘验、询问、宣判等诉讼活动的笔录，应当通过互联网向当事人及其法定代理人、诉讼代理人、辩护人公开。"},{"i":11,"n":"第十一条","txt":"当事人及其法定代理人、诉讼代理人、辩护人申请查阅庭审录音录像、电子卷宗的，人民法院可以通过中国审判流程信息公开网或者其他诉讼服务平台提供查阅，并设置必要的安全保护措施。"},{"i":12,"n":"第十二条","txt":"涉及国家秘密，以及法律、司法解释规定应当保密或者限制获取的审判流程信息，不得通过互联网向当事人及其法定代理人、诉讼代理人、辩护人公开。"},{"i":13,"n":"第十三条","txt":"已经公开的审判流程信息与实际情况不一致的，以实际情况为准，受理案件的人民法院应当及时更正。"},{"i":14,"n":"第十四条","txt":"经受送达人书面同意，人民法院可以通过中国审判流程信息公开网向民事、行政案件的当事人及其法定代理人、诉讼代理人电子送达除判决书、裁定书、调解书以外的诉讼文书。"},{"i":15,"n":"第十五条","txt":"最高人民法院监督指导全国法院审判流程信息公开工作。高级、中级人民法院监督指导辖区法院审判流程信息公开工作。"},{"i":16,"n":"第十六条","txt":"公开审判流程信息的业务规范和技术标准，由最高人民法院另行制定。"},{"i":17,"n":"第十七条","txt":"本规定自2018年9月1日起施行。最高人民法院以前发布的司法解释和规范性文件与本规定不一致的，以本规定为准。"}],"zuigaorenminfayuanguanyurenmintiaojiexieyisifaquer421f77":[{"i":1,"n":"第一条","txt":"当事人根据《中华人民共和国人民调解法》第三十三条的规定共同向人民法院申请确认调解协议的，人民法院应当依法受理。"},{"i":2,"n":"第二条","txt":"当事人申请确认调解协议的，由主持调解的人民调解委员会所在地基层人民法院或者它派出的法庭管辖。"},{"i":3,"n":"第三条","txt":"当事人申请确认调解协议，应当向人民法院提交司法确认申请书、调解协议和身份证明、资格证明，以及与调解协议相关的财产权利证明等证明材料，并提供双方当事人的送达地址、电话号码等联系方式。委托他人代为申请的，必须向人民法院提交由委托人签名或者盖章的授权委托书。"},{"i":4,"n":"第四条","txt":"人民法院收到当事人司法确认申请，应当在三日内决定是否受理。人民法院决定受理的，应当编立“调确字”案号，并及时向当事人送达受理通知书。双方当事人同时到法院申请司法确认的，人民法院可以当即受理并作出是否确认的决定。"},{"i":5,"n":"第五条","txt":"人民法院应当自受理司法确认申请之日起十五日内作出是否确认的决定。因特殊情况需要延长的，经本院院长批准，可以延长十日。"},{"i":6,"n":"第六条","txt":"人民法院受理司法确认申请后，应当指定一名审判人员对调解协议进行审查。人民法院在必要时可以通知双方当事人同时到场，当面询问当事人。当事人应当向人民法院如实陈述申请确认的调解协议的有关情况，保证提交的证明材料真实、合法。人民法院在审查中，认为当事人的陈述或者提供的证明材料不充分、不完备或者有疑义的，可以要求当事人补充陈述或者补充证明材料。当事人无正当理由未按时补充或者拒不接受询问的，可以按撤回司法确认申请处理。"},{"i":7,"n":"第七条","txt":"具有下列情形之一的，人民法院不予确认调解协议效力："},{"i":8,"n":"第八条","txt":"人民法院经审查认为调解协议符合确认条件的，应当作出确认决定书；决定不予确认调解协议效力的，应当作出不予确认决定书。"},{"i":9,"n":"第九条","txt":"人民法院依法作出确认决定后，一方当事人拒绝履行或者未全部履行的，对方当事人可以向作出确认决定的人民法院申请强制执行。"},{"i":10,"n":"第十条","txt":"案外人认为经人民法院确认的调解协议侵害其合法权益的，可以自知道或者应当知道权益被侵害之日起一年内，向作出确认决定的人民法院申请撤销确认决定。"},{"i":11,"n":"第十一条","txt":"人民法院办理人民调解协议司法确认案件，不收取费用。"},{"i":12,"n":"第十二条","txt":"人民法院可以将调解协议不予确认的情况定期或者不定期通报同级司法行政机关和相关人民调解委员会。"},{"i":13,"n":"第十三条","txt":"经人民法院建立的调解员名册中的调解员调解达成协议后，当事人申请司法确认的，参照本规定办理。人民法院立案后委托他人调解达成的协议的司法确认，按照《最高人民法院关于人民法院民事调解工作若干问题的规定》（法释〔2004〕12号）的有关规定办理。"}],"zuigaorenminfayuanguanyuyifayuanzhuandifangshiyoujd5e1ff":[{"i":1,"n":"第一条","txt":"人民法院直接送达诉讼文书有困难的，可以交由国家邮政机构（以下简称邮政机构）以法院专递方式邮寄送达，但有下列情形之一的除外："},{"i":2,"n":"第二条","txt":"以法院专递方式邮寄送达民事诉讼文书的，其送达与人民法院送达具有同等法律效力。"},{"i":3,"n":"第三条","txt":"当事人起诉或者答辩时应当向人民法院提供或者确认自己准确的送达地址，并填写送达地址确认书。当事人拒绝提供的，人民法院应当告知其拒不提供送达地址的不利后果，并记入笔录。"},{"i":4,"n":"第四条","txt":"送达地址确认书的内容应当包括送达地址的邮政编码、详细地址以及受送达人的联系电话等内容。"},{"i":5,"n":"第五条","txt":"当事人拒绝提供自己的送达地址，经人民法院告知后仍不提供的，自然人以其户籍登记中的住所地或者经常居住地为送达地址；法人或者其他组织以其工商登记或者其他依法登记、备案中的住所地为送达地址。"},{"i":6,"n":"第六条","txt":"邮政机构按照当事人提供或者确认的送达地址送达的，应当在规定的日期内将回执退回人民法院。"},{"i":7,"n":"第七条","txt":"受送达人指定代收人的，指定代收人的签收视为受送达人本人签收。"},{"i":8,"n":"第八条","txt":"受送达人及其代收人应当在邮件回执上签名、盖章或者捺印。"},{"i":9,"n":"第九条","txt":"有下列情形之一的，即为送达："},{"i":10,"n":"第十条","txt":"签收人是受送达人本人或者是受送达人的法定代表人、主要负责人、法定代理人、诉讼代理人的，签收人应当当场核对邮件内容。签收人发现邮件内容与回执上的文书名称不一致的，应当当场向邮政机构的投递员提出，由投递员在回执上记明情况后将邮件退回人民法院。"},{"i":11,"n":"第十一条","txt":"因受送达人自己提供或者确认的送达地址不准确、拒不提供送达地址、送达地址变更未及时告知人民法院、受送达人本人或者受送达人指定的代收人拒绝签收，导致诉讼文书未能被受送达人实际接收的，文书退回之日视为送达之日。"},{"i":12,"n":"第十二条","txt":"本规定自2005年1月1日起实施。"}],"zuigaorenminfayuanguanyuzhongcaisifashenchaanjianbd064c5":[{"i":1,"n":"第一条","txt":"本规定所称仲裁司法审查案件，包括下列案件："},{"i":2,"n":"第二条","txt":"各中级人民法院或者专门人民法院办理涉外涉港澳台仲裁司法审查案件，经审查拟认定仲裁协议无效，不予执行或者撤销我国内地仲裁机构的仲裁裁决，不予认可和执行香港特别行政区、澳门特别行政区、台湾地区仲裁裁决，不予承认和执行外国仲裁裁决，应当向本辖区所属高级人民法院报核；高级人民法院经审查拟同意的，应当向最高人民法院报核。待最高人民法院审核后，方可依最高人民法院的审核意见作出裁定。"},{"i":3,"n":"第三条","txt":"本规定第二条第二款规定的非涉外涉港澳台仲裁司法审查案件，高级人民法院经审查，拟同意中级人民法院或者专门人民法院以违背社会公共利益为由不予执行或者撤销我国内地仲裁机构的仲裁裁决的，应当向最高人民法院报核，待最高人民法院审核后，方可依最高人民法院的审核意见作出裁定。"},{"i":4,"n":"第四条","txt":"依据本规定第二条第二款由高级人民法院审核的案件，高级人民法院应当在作出审核意见之日起十五日内向最高人民法院报备。"},{"i":5,"n":"第五条","txt":"下级人民法院报请上级人民法院审核的案件，应当将书面报告和案件卷宗材料一并上报。书面报告应当写明审查意见及具体理由。"},{"i":6,"n":"第六条","txt":"上级人民法院收到下级人民法院的报核申请后，认为案件相关事实不清的，可以询问当事人或者退回下级人民法院补充查明事实后再报。"},{"i":7,"n":"第七条","txt":"上级人民法院应当以复函的形式将审核意见答复下级人民法院。"},{"i":8,"n":"第八条","txt":"在民事诉讼案件中，对于人民法院因涉及仲裁协议效力而作出的不予受理、驳回起诉、管辖权异议的裁定，当事人不服提起上诉，第二审人民法院经审查拟认定仲裁协议不成立、无效、失效、内容不明确无法执行的，须按照本规定第二条的规定逐级报核，待上级人民法院审核后，方可依上级人民法院的审核意见作出裁定。"},{"i":9,"n":"第九条","txt":"本规定自2018年1月1日起施行，本院以前发布的司法解释与本规定不一致的，以本规定为准。"}],"zuigaorenminfayuanguanyuyijuguojigongyueheshuangbi88c1e7":[{"i":1,"n":"第一条","txt":"人民法院应当根据便捷、高效的原则确定依据海牙送达公约、海牙取证公约，或者双边民事司法协助条约，对外提出民商事案件司法文书送达和调查取证请求。"},{"i":2,"n":"第二条","txt":"人民法院协助外国办理民商事案件司法文书送达和调查取证请求，适用对等原则。"},{"i":3,"n":"第三条","txt":"人民法院协助外国办理民商事案件司法文书送达和调查取证请求，应当进行审查。外国提出的司法协助请求，具有海牙送达公约、海牙取证公约或双边民事司法协助条约规定的拒绝提供协助的情形的，人民法院应当拒绝提供协助。"},{"i":4,"n":"第四条","txt":"人民法院协助外国办理民商事案件司法文书送达和调查取证请求，应当按照民事诉讼法和相关司法解释规定的方式办理。"},{"i":5,"n":"第五条","txt":"人民法院委托外国送达民商事案件司法文书和进行民商事案件调查取证，需要提供译文的，应当委托中华人民共和国领域内的翻译机构进行翻译。"},{"i":6,"n":"第六条","txt":"最高人民法院统一管理全国各级人民法院的国际司法协助工作。高级人民法院应当确定一个部门统一管理本辖区各级人民法院的国际司法协助工作并指定专人负责。中级人民法院、基层人民法院和有权受理涉外案件的专门法院，应当指定专人管理国际司法协助工作；有条件的，可以同时确定一个部门管理国际司法协助工作。"},{"i":7,"n":"第七条","txt":"人民法院应当建立独立的国际司法协助登记制度。"},{"i":8,"n":"第八条","txt":"人民法院应当建立国际司法协助档案制度。办理民商事案件司法文书送达的送达回证、送达证明在各个转递环节应当以适当方式保存。办理民商事案件调查取证的材料应当作为档案保存。"},{"i":9,"n":"第九条","txt":"经最高人民法院授权的高级人民法院，可以依据海牙送达公约、海牙取证公约直接对外发出本辖区各级人民法院提出的民商事案件司法文书送达和调查取证请求。"},{"i":10,"n":"第十条","txt":"通过外交途径办理民商事案件司法文书送达和调查取证，不适用本规定。"},{"i":11,"n":"第十一条","txt":"最高人民法院国际司法协助统一管理部门根据本规定制定实施细则。"},{"i":12,"n":"第十二条","txt":"最高人民法院以前所作的司法解释及规范性文件，凡与本规定不一致的，按本规定办理。"}],"zuigaorenminfayuanguanyuxiugaihoudeminshisusongfas257906":[{"i":1,"n":"第一条","txt":"2013年1月1日未结案件适用修改后的民事诉讼法，但本规定另有规定的除外。"},{"i":2,"n":"第二条","txt":"2013年1月1日未结案件符合修改前的民事诉讼法或者修改后的民事诉讼法管辖规定的，人民法院对该案件继续审理。"},{"i":3,"n":"第三条","txt":"2013年1月1日未结案件符合修改前的民事诉讼法或者修改后的民事诉讼法送达规定的，人民法院已经完成的送达，仍然有效。"},{"i":4,"n":"第四条","txt":"在2013年1月1日未结案件中，人民法院对2013年1月1日前发生的妨害民事诉讼行为尚未处理的，适用修改前的民事诉讼法，但下列情形应当适用修改后的民事诉讼法："},{"i":5,"n":"第五条","txt":"2013年1月1日前，利害关系人向人民法院申请诉前保全措施的，适用修改前的民事诉讼法等法律，但人民法院2013年1月1日尚未作出保全裁定的，适用修改后的民事诉讼法确定解除保全措施的期限。"},{"i":6,"n":"第六条","txt":"当事人对2013年1月1日前已经发生法律效力的判决、裁定或者调解书申请再审的，人民法院应当依据修改前的民事诉讼法第一百八十四条规定审查确定当事人申请再审的期间，但该期间在2013年6月30日尚未届满的，截止到2013年6月30日。"},{"i":7,"n":"第七条","txt":"人民法院对2013年1月1日前已经受理、2013年1月1日尚未审查完毕的申请不予执行仲裁裁决的案件，适用修改前的民事诉讼法。"},{"i":8,"n":"第八条","txt":"本规定所称修改后的民事诉讼法，是指根据《决定》作相应修改后的《中华人民共和国民事诉讼法》。"}],"zuigaorenminfayuanguanyugongbushixinbeizhixingrenm2f6331":[{"i":1,"n":"第一条","txt":"被执行人未履行生效法律文书确定的义务，并具有下列情形之一的，人民法院应当将其纳入失信被执行人名单，依法对其进行信用惩戒："},{"i":2,"n":"第二条","txt":"被执行人具有本规定第一条第二项至第六项规定情形的，纳入失信被执行人名单的期限为二年。被执行人以暴力、威胁方法妨碍、抗拒执行情节严重或具有多项失信行为的，可以延长一至三年。"},{"i":3,"n":"第三条","txt":"具有下列情形之一的，人民法院不得依据本规定第一条第一项的规定将被执行人纳入失信被执行人名单："},{"i":4,"n":"第四条","txt":"被执行人为未成年人的，人民法院不得将其纳入失信被执行人名单。"},{"i":5,"n":"第五条","txt":"人民法院向被执行人发出的执行通知中，应当载明有关纳入失信被执行人名单的风险提示等内容。"},{"i":6,"n":"第六条","txt":"记载和公布的失信被执行人名单信息应当包括："},{"i":7,"n":"第七条","txt":"各级人民法院应当将失信被执行人名单信息录入最高人民法院失信被执行人名单库，并通过该名单库统一向社会公布。"},{"i":8,"n":"第八条","txt":"人民法院应当将失信被执行人名单信息，向政府相关部门、金融监管机构、金融机构、承担行政职能的事业单位及行业协会等通报，供相关单位依照法律、法规和有关规定，在政府采购、招标投标、行政审批、政府扶持、融资信贷、市场准入、资质认定等方面，对失信被执行人予以信用惩戒。"},{"i":9,"n":"第九条","txt":"不应纳入失信被执行人名单的公民、法人或其他组织被纳入失信被执行人名单的，人民法院应当在三个工作日内撤销失信信息。"},{"i":10,"n":"第十条","txt":"具有下列情形之一的，人民法院应当在三个工作日内删除失信信息："},{"i":11,"n":"第十一条","txt":"被纳入失信被执行人名单的公民、法人或其他组织认为有下列情形之一的，可以向执行法院申请纠正："},{"i":12,"n":"第十二条","txt":"公民、法人或其他组织对被纳入失信被执行人名单申请纠正的，执行法院应当自收到书面纠正申请之日起十五日内审查，理由成立的，应当在三个工作日内纠正；理由不成立的，决定驳回。公民、法人或其他组织对驳回决定不服的，可以自决定书送达之日起十日内向上一级人民法院申请复议。上一级人民法院应当自收到复议申请之日起十五日内作出决定。"},{"i":13,"n":"第十三条","txt":"人民法院工作人员违反本规定公布、撤销、更正、删除失信信息的，参照有关规定追究责任。"}],"zuigaorenminfayuanguanyugongzhengzhaiquanwenshuzhi1689d8":[{"i":1,"n":"第一条","txt":"本规定所称公证债权文书，是指根据公证法第三十七条第一款规定经公证赋予强制执行效力的债权文书。"},{"i":2,"n":"第二条","txt":"公证债权文书执行案件，由被执行人住所地或者被执行的财产所在地人民法院管辖。"},{"i":3,"n":"第三条","txt":"债权人申请执行公证债权文书，除应当提交作为执行依据的公证债权文书等申请执行所需的材料外，还应当提交证明履行情况等内容的执行证书。"},{"i":4,"n":"第四条","txt":"债权人申请执行的公证债权文书应当包括公证证词、被证明的债权文书等内容。权利义务主体、给付内容应当在公证证词中列明。"},{"i":5,"n":"第五条","txt":"债权人申请执行公证债权文书，有下列情形之一的，人民法院应当裁定不予受理；已经受理的，裁定驳回执行申请："},{"i":6,"n":"第六条","txt":"公证债权文书赋予强制执行效力的范围同时包含主债务和担保债务的，人民法院应当依法予以执行；仅包含主债务的，对担保债务部分的执行申请不予受理；仅包含担保债务的，对主债务部分的执行申请不予受理。"},{"i":7,"n":"第七条","txt":"债权人对不予受理、驳回执行申请裁定不服的，可以自裁定送达之日起十日内向上一级人民法院申请复议。"},{"i":8,"n":"第八条","txt":"公证机构决定不予出具执行证书的，当事人可以就公证债权文书涉及的民事权利义务争议直接向人民法院提起诉讼。"},{"i":9,"n":"第九条","txt":"申请执行公证债权文书的期间自公证债权文书确定的履行期间的最后一日起计算；分期履行的，自公证债权文书确定的每次履行期间的最后一日起计算。"},{"i":10,"n":"第十条","txt":"人民法院在执行实施中，根据公证债权文书并结合申请执行人的申请依法确定给付内容。"},{"i":11,"n":"第十一条","txt":"因民间借贷形成的公证债权文书，文书中载明的利率超过人民法院依照法律、司法解释规定应予支持的上限的，对超过的利息部分不纳入执行范围；载明的利率未超过人民法院依照法律、司法解释规定应予支持的上限，被执行人主张实际超过的，可以依照本规定第二十二条第一款规定提起诉讼。"},{"i":12,"n":"第十二条","txt":"有下列情形之一的，被执行人可以依照民事诉讼法第二百三十八条第二款规定申请不予执行公证债权文书："},{"i":13,"n":"第十三条","txt":"被执行人申请不予执行公证债权文书，应当在执行通知书送达之日起十五日内向执行法院提出书面申请，并提交相关证据材料；有本规定第十二条第一款第三项、第四项规定情形且执行程序尚未终结的，应当自知道或者应当知道有关事实之日起十五日内提出。"},{"i":14,"n":"第十四条","txt":"被执行人认为公证债权文书存在本规定第十二条第一款规定的多个不予执行事由的，应当在不予执行案件审查期间一并提出。"},{"i":15,"n":"第十五条","txt":"人民法院审查不予执行公证债权文书案件，案情复杂、争议较大的，应当进行听证。必要时可以向公证机构调阅公证案卷，要求公证机构作出书面说明，或者通知公证员到庭说明情况。"},{"i":16,"n":"第十六条","txt":"人民法院审查不予执行公证债权文书案件，应当在受理之日起六十日内审查完毕并作出裁定；有特殊情况需要延长的，经本院院长批准，可以延长三十日。"},{"i":17,"n":"第十七条","txt":"人民法院审查不予执行公证债权文书案件期间，不停止执行。"},{"i":18,"n":"第十八条","txt":"被执行人依照本规定第十二条第一款规定申请不予执行，人民法院经审查认为理由成立的，裁定不予执行；理由不成立的，裁定驳回不予执行申请。"},{"i":19,"n":"第十九条","txt":"人民法院认定执行公证债权文书违背公序良俗的，裁定不予执行。"},{"i":20,"n":"第二十条","txt":"公证债权文书被裁定不予执行的，当事人可以就该公证债权文书涉及的民事权利义务争议向人民法院提起诉讼；公证债权文书被裁定部分不予执行的，当事人可以就该部分争议提起诉讼。"},{"i":21,"n":"第二十一条","txt":"当事人不服驳回不予执行申请裁定的，可以自裁定送达之日起十日内向上一级人民法院申请复议。上一级人民法院应当自收到复议申请之日起三十日内审查。经审查，理由成立的，裁定撤销原裁定，不予执行该公证债权文书；理由不成立的，裁定驳回复议申请。复议期间，不停止执行。"},{"i":22,"n":"第二十二条","txt":"有下列情形之一的，债务人可以在执行程序终结前，以债权人为被告，向执行法院提起诉讼，请求不予执行公证债权文书："},{"i":23,"n":"第二十三条","txt":"对债务人依照本规定第二十二条第一款规定提起的诉讼，人民法院经审理认为理由成立的，判决不予执行或者部分不予执行；理由不成立的，判决驳回诉讼请求。"},{"i":24,"n":"第二十四条","txt":"有下列情形之一的，债权人、利害关系人可以就公证债权文书涉及的民事权利义务争议直接向有管辖权的人民法院提起诉讼："},{"i":25,"n":"第二十五条","txt":"本规定自2018年10月1日起施行。"}],"zuigaorenminfayuanguanyujuyouzhuanmenzhishiderenmi6bce35":[{"i":1,"n":"第一条","txt":"人民法院审理的第一审环境资源刑事、民事、行政案件，符合人民陪审员法第十五条规定，且案件事实涉及复杂专门性问题的，由不少于一名具有专门知识的人民陪审员参加合议庭审理。"},{"i":2,"n":"第二条","txt":"符合下列条件的人民陪审员，为本规定所称具有专门知识的人民陪审员："},{"i":3,"n":"第三条","txt":"人民法院参与人民陪审员选任，可以根据环境资源审判活动需要，结合案件类型、数量等特点，协商司法行政机关确定一定数量具有专门知识的人民陪审员候选人。"},{"i":4,"n":"第四条","txt":"具有专门知识的人民陪审员任期届满后，人民法院认为有必要的，可以商请本人同意后协商司法行政机关经法定程序再次选任。"},{"i":5,"n":"第五条","txt":"需要具有专门知识的人民陪审员参加案件审理的，人民法院可以根据环境资源案件的特点和具有专门知识的人民陪审员选任情况，在符合专业需求的人民陪审员名单中随机抽取确定。"},{"i":6,"n":"第六条","txt":"基层人民法院可以根据环境资源案件审理的需要，协商司法行政机关选任具有专门知识的人民陪审员。"},{"i":7,"n":"第七条","txt":"基层人民法院审理的环境资源案件，需要具有专门知识的人民陪审员参加合议庭审理的，组成不少于一名具有专门知识的人民陪审员参加的三人合议庭。"},{"i":8,"n":"第八条","txt":"中级人民法院审理的环境民事公益诉讼案件、环境行政公益诉讼案件、生态环境损害赔偿诉讼案件以及其他具有重大社会影响的环境污染防治、生态保护、气候变化应对、资源开发利用、生态环境治理与服务等案件，需要具有专门知识的人民陪审员参加合议庭审理的，组成不少于一名具有专门知识的人民陪审员参加的七人合议庭。"},{"i":9,"n":"第九条","txt":"实行环境资源案件跨区域集中管辖的中级人民法院审理第一审环境资源案件，需要具有专门知识的人民陪审员参加合议庭审理的，可以从环境资源案件集中管辖区域内基层人民法院具有专门知识的人民陪审员名单中随机抽取确定。"},{"i":10,"n":"第十条","txt":"铁路运输法院等没有对应同级人民代表大会的法院审理第一审环境资源案件，需要具有专门知识的人民陪审员参加合议庭审理的，在其所在地级市辖区或案件管辖区域内基层人民法院具有专门知识的人民陪审员名单中随机抽取确定。"},{"i":11,"n":"第十一条","txt":"符合法律规定的审判人员应当回避的情形，或所在单位与案件有利害关系的，具有专门知识的人民陪审员应当自行回避。当事人也可以申请具有专门知识的人民陪审员回避。"},{"i":12,"n":"第十二条","txt":"审判长应当依照人民陪审员法第二十条的规定，对具有专门知识的人民陪审员参加的下列工作，重点进行指引和提示："},{"i":13,"n":"第十三条","txt":"具有专门知识的人民陪审员参加环境资源案件评议时，应当就案件事实涉及的专门性问题发表明确意见。"},{"i":14,"n":"第十四条","txt":"具有专门知识的人民陪审员可以参与监督生态环境修复、验收和修复效果评估。"},{"i":15,"n":"第十五条","txt":"具有专门知识的人民陪审员参加环境资源案件的审理，本规定没有规定的，适用《最高人民法院关于适用〈中华人民共和国人民陪审员法〉若干问题的解释》的规定。"},{"i":16,"n":"第十六条","txt":"本规定自2023年8月1日起施行。"}],"zuigaorenminfayuanguanyujunshifayuanguanxiaminshia6e6488":[{"i":1,"n":"第一条","txt":"下列民事案件，由军事法院管辖："},{"i":2,"n":"第二条","txt":"下列民事案件，有关军事法院与地方人民法院都有权管辖，地方当事人向军事法院提起诉讼的，军事法院应当受理："},{"i":3,"n":"第三条","txt":"当事人一方是军人或者军队单位，且合同履行地或者标的物所在地在营区内的合同或者其他财产权益纠纷，当事人书面约定军事法院管辖，不违反法律关于级别管辖、专属管辖和专门管辖规定的，应当由军事法院管辖。"},{"i":4,"n":"第四条","txt":"军事法院受理第一审民事案件，应当参照民事诉讼法关于级别管辖、地域管辖的规定确定。"},{"i":5,"n":"第五条","txt":"军事法院发现受理的民事案件属于地方人民法院管辖的，应当移送有管辖权的地方人民法院，受移送的地方人民法院应当受理。"},{"i":6,"n":"第六条","txt":"军事法院与地方人民法院依照本规定第五条移送管辖之前，可以先行协商。"},{"i":7,"n":"第七条","txt":"军事法院受理案件后，当事人对管辖权有异议的，应当在提交答辩状期间提出。军事法院对当事人提出的异议，应当审查。异议成立的，裁定将案件移送有管辖权的军事法院或者地方人民法院；异议不成立的，裁定驳回。"},{"i":8,"n":"第八条","txt":"本规定所称军人是指中国人民解放军的现役军官、军士、义务兵及具有军籍的学员，中国人民武装警察部队的现役警官、警士、义务兵及具有军籍的学员。军队中的文职人员、由军队管理的离退休人员、具有军队编制的职工，参照军人确定管辖。"},{"i":9,"n":"第九条","txt":"本规定自2025年5月1日起施行。《最高人民法院关于军事法院管辖民事案件若干问题的规定》（2020年修正）同时废止；本规定施行前的司法解释以及司法解释性文件与本规定不一致的，以本规定为准。"}],"zuigaorenminfayuanguanyudongjiepaimaishangshigongsf6c9c4":[{"i":1,"n":"第一条","txt":"人民法院在审理民事纠纷案件过程中，对股权采取冻结、评估、拍卖和办理股权过户等财产保全和执行措施，适用本规定。"},{"i":2,"n":"第二条","txt":"本规定所指上市公司国有股，包括国家股和国有法人股。国家股指有权代表国家投资的机构或部门向股份有限公司出资或依据法定程序取得的股份；国有法人股指国有法人单位，包括国有资产比例超过50%的国有控股企业，以其依法占有的法人资产向股份有限公司出资形成或者依据法定程序取得的股份。"},{"i":3,"n":"第三条","txt":"人民法院对股权采取冻结、拍卖措施时，被保全人和被执行人应当是股权的持有人或者所有权人。被冻结、拍卖股权的上市公司非依据法定程序确定为案件当事人或者被执行人，人民法院不得对其采取保全或执行措施。"},{"i":4,"n":"第四条","txt":"人民法院在审理案件过程中，股权持有人或者所有权人作为债务人，如有偿还能力的，人民法院一般不应对其股权采取冻结保全措施。"},{"i":5,"n":"第五条","txt":"人民法院裁定冻结或者解除冻结股权，除应当将法律文书送达负有协助执行义务的单位以外，还应当在作出冻结或者解除冻结裁定后7日内，将法律文书送达股权持有人或者所有权人并书面通知上市公司。"},{"i":6,"n":"第六条","txt":"冻结股权的期限不超过1年。如申请人需要延长期限的，人民法院应当根据申请，在冻结期限届满前办理续冻手续，每次续冻期限不超过6个月。逾期不办理续冻手续的，视为自动撤销冻结。"},{"i":7,"n":"第七条","txt":"人民法院采取保全措施，所冻结的股权价值不得超过股权持有人或者所有权人的债务总额。股权价值应当按照上市公司最近期报表每股资产净值计算。"},{"i":8,"n":"第八条","txt":"人民法院采取强制执行措施时，如果股权持有人或者所有权人在限期内提供了方便执行的其他财产，应当首先执行其他财产。其他财产不足以清偿债务的，方可执行股权。"},{"i":9,"n":"第九条","txt":"拍卖股权之前，人民法院应当委托具有证券从业资格的资产评估机构对股权价值进行评估。资产评估机构由债权人和债务人协商选定。不能达成一致意见的，由人民法院召集债权人和债务人提出候选评估机构，以抽签方式决定。"},{"i":10,"n":"第十条","txt":"人民法院委托资产评估机构评估时，应当要求资产评估机构严格依照国家规定的标准、程序和方法对股权价值进行评估，并说明其应当对所作出的评估报告依法承担相应责任。"},{"i":11,"n":"第十一条","txt":"人民法院收到资产评估机构作出的评估报告后，须将评估报告分别送达债权人和债务人以及上市公司。债权人和债务人以及上市公司对评估报告有异议的，应当在收到评估报告后7日内书面提出。人民法院应当将异议书交资产评估机构，要求该机构在10日之内作出说明或者补正。"},{"i":12,"n":"第十二条","txt":"对股权拍卖，人民法院应当委托依法成立的拍卖机构进行。拍卖机构的选定，参照本规定第九条规定的方法进行。"},{"i":13,"n":"第十三条","txt":"股权拍卖保留价，应当按照评估值确定。"},{"i":14,"n":"第十四条","txt":"拍卖股权，人民法院应当委托拍卖机构于拍卖日前10天，在《中国证券报》、《证券时报》或者《上海证券报》上进行公告。"},{"i":15,"n":"第十五条","txt":"国有股权竞买人应当具备依法受让国有股权的条件。"},{"i":16,"n":"第十六条","txt":"股权拍卖过程中，竞买人已经持有的该上市公司股份数额和其竞买的股份数额累计不得超过该上市公司已经发行股份数额的30%。如竞买人累计持有该上市公司股份数额已达到30%仍参与竞买的，须依照《中华人民共和国证券法》的相关规定办理，在此期间应当中止拍卖程序。"},{"i":17,"n":"第十七条","txt":"拍卖成交后，人民法院应当向证券交易市场和证券登记结算公司出具协助执行通知书，由买受人持拍卖机构出具的成交证明和财政主管部门对股权性质的界定等有关文件，向证券交易市场和证券登记结算公司办理股权变更登记。"}],"zuigaorenminfayuanguanyujianxingjiashianjianshenlia0f4b7":[{"i":1,"n":"第一条","txt":"对减刑、假释案件，应当按照下列情形分别处理："},{"i":2,"n":"第二条","txt":"人民法院受理减刑、假释案件，应当审查执行机关移送的下列材料："},{"i":3,"n":"第三条","txt":"人民法院审理减刑、假释案件，应当在立案后五日内将执行机关报请减刑、假释的建议书等材料依法向社会公示。"},{"i":4,"n":"第四条","txt":"人民法院审理减刑、假释案件，应当依法由审判员或者由审判员和人民陪审员组成合议庭进行。"},{"i":5,"n":"第五条","txt":"人民法院审理减刑、假释案件，除应当审查罪犯在执行期间的一贯表现外，还应当综合考虑犯罪的具体情节、原判刑罚情况、财产刑执行情况、附带民事裁判履行情况、罪犯退赃退赔等情况。"},{"i":6,"n":"第六条","txt":"人民法院审理减刑、假释案件，可以采取开庭审理或者书面审理的方式。但下列减刑、假释案件，应当开庭审理："},{"i":7,"n":"第七条","txt":"人民法院开庭审理减刑、假释案件，应当通知人民检察院、执行机关及被报请减刑、假释罪犯参加庭审。"},{"i":8,"n":"第八条","txt":"开庭审理应当在罪犯刑罚执行场所或者人民法院确定的场所进行。有条件的人民法院可以采取视频开庭的方式进行。"},{"i":9,"n":"第九条","txt":"人民法院对于决定开庭审理的减刑、假释案件，应当在开庭三日前将开庭的时间、地点通知人民检察院、执行机关、被报请减刑、假释罪犯和有必要参加庭审的其他人员，并于开庭三日前进行公告。"},{"i":10,"n":"第十条","txt":"减刑、假释案件的开庭审理由审判长主持，应当按照以下程序进行："},{"i":11,"n":"第十一条","txt":"庭审过程中，合议庭人员对报请理由有疑问的，可以向被报请减刑、假释罪犯、证人、执行机关代表、检察人员提问。"},{"i":12,"n":"第十二条","txt":"庭审过程中，合议庭对证据有疑问需要进行调查核实，或者检察人员、执行机关代表提出申请的，可以宣布休庭。"},{"i":13,"n":"第十三条","txt":"人民法院开庭审理减刑、假释案件，能够当庭宣判的应当当庭宣判；不能当庭宣判的，可以择期宣判。"},{"i":14,"n":"第十四条","txt":"人民法院书面审理减刑、假释案件，可以就被报请减刑、假释罪犯是否符合减刑、假释条件进行调查核实或听取有关方面意见。"},{"i":15,"n":"第十五条","txt":"人民法院书面审理减刑案件，可以提讯被报请减刑罪犯；书面审理假释案件，应当提讯被报请假释罪犯。"},{"i":16,"n":"第十六条","txt":"人民法院审理减刑、假释案件，应当按照下列情形分别处理："},{"i":17,"n":"第十七条","txt":"减刑、假释裁定书应当写明罪犯原判和历次减刑情况，确有悔改表现或者立功、重大立功表现的事实和理由，以及减刑、假释的法律依据。"},{"i":18,"n":"第十八条","txt":"人民法院作出减刑、假释裁定后，应当在七日内送达报请减刑、假释的执行机关、同级人民检察院以及罪犯本人。作出假释裁定的，还应当送达社区矫正机构或者基层组织。"},{"i":19,"n":"第十九条","txt":"减刑、假释裁定书应当通过互联网依法向社会公布。"},{"i":20,"n":"第二十条","txt":"人民检察院认为人民法院减刑、假释裁定不当，在法定期限内提出书面纠正意见的，人民法院应当在收到纠正意见后另行组成合议庭审理，并在一个月内作出裁定。"},{"i":21,"n":"第二十一条","txt":"人民法院发现本院已经生效的减刑、假释裁定确有错误的，应当依法重新组成合议庭进行审理并作出裁定；上级人民法院发现下级人民法院已经生效的减刑、假释裁定确有错误的，应当指令下级人民法院另行组成合议庭审理，也可以自行依法组成合议庭进行审理并作出裁定。"},{"i":22,"n":"第二十二条","txt":"最高人民法院以前发布的司法解释和规范性文件，与本规定不一致的，以本规定为准。"}],"zuigaorenminfayuanguanyuxingshicaipanshecaichanbuf25ea8a":[{"i":1,"n":"第一条","txt":"本规定所称刑事裁判涉财产部分的执行，是指发生法律效力的刑事裁判主文确定的下列事项的执行："},{"i":2,"n":"第二条","txt":"刑事裁判涉财产部分，由第一审人民法院执行。第一审人民法院可以委托财产所在地的同级人民法院执行。"},{"i":3,"n":"第三条","txt":"人民法院办理刑事裁判涉财产部分执行案件的期限为六个月。有特殊情况需要延长的，经本院院长批准，可以延长。"},{"i":4,"n":"第四条","txt":"人民法院刑事审判中可能判处被告人财产刑、责令退赔的，刑事审判部门应当依法对被告人的财产状况进行调查；发现可能隐匿、转移财产的，应当及时查封、扣押、冻结其相应财产。"},{"i":5,"n":"第五条","txt":"刑事审判或者执行中，对于侦查机关已经采取的查封、扣押、冻结，人民法院应当在期限届满前及时续行查封、扣押、冻结。人民法院续行查封、扣押、冻结的顺位与侦查机关查封、扣押、冻结的顺位相同。"},{"i":6,"n":"第六条","txt":"刑事裁判涉财产部分的裁判内容，应当明确、具体。涉案财物或者被害人人数较多，不宜在判决主文中详细列明的，可以概括叙明并另附清单。"},{"i":7,"n":"第七条","txt":"由人民法院执行机构负责执行的刑事裁判涉财产部分，刑事审判部门应当及时移送立案部门审查立案。"},{"i":8,"n":"第八条","txt":"人民法院可以向刑罚执行机关、社区矫正机构等有关单位调查被执行人的财产状况，并可以根据不同情形要求有关单位协助采取查封、扣押、冻结、划拨等执行措施。"},{"i":9,"n":"第九条","txt":"判处没收财产的，应当执行刑事裁判生效时被执行人合法所有的财产。"},{"i":10,"n":"第十条","txt":"对赃款赃物及其收益，人民法院应当一并追缴。"},{"i":11,"n":"第十一条","txt":"被执行人将刑事裁判认定为赃款赃物的涉案财物用于清偿债务、转让或者设置其他权利负担，具有下列情形之一的，人民法院应予追缴："},{"i":12,"n":"第十二条","txt":"被执行财产需要变价的，人民法院执行机构应当依法采取拍卖、变卖等变价措施。"},{"i":13,"n":"第十三条","txt":"被执行人在执行中同时承担刑事责任、民事责任，其财产不足以支付的，按照下列顺序执行："},{"i":14,"n":"第十四条","txt":"执行过程中，当事人、利害关系人认为执行行为违反法律规定，或者案外人对执行标的主张足以阻止执行的实体权利，向执行法院提出书面异议的，执行法院应当依照民事诉讼法第二百二十五条的规定处理。"},{"i":15,"n":"第十五条","txt":"执行过程中，案外人或被害人认为刑事裁判中对涉案财物是否属于赃款赃物认定错误或者应予认定而未认定，向执行法院提出书面异议，可以通过裁定补正的，执行机构应当将异议材料移送刑事审判部门处理；无法通过裁定补正的，应当告知异议人通过审判监督程序处理。"},{"i":16,"n":"第十六条","txt":"人民法院办理刑事裁判涉财产部分执行案件，刑法、刑事诉讼法及有关司法解释没有相应规定的，参照适用民事执行的有关规定。"},{"i":17,"n":"第十七条","txt":"最高人民法院此前发布的司法解释与本规定不一致的，以本规定为准。"}],"zuigaorenminfayuanguanyubanlirenshenanquanbaohulin83a688":[{"i":1,"n":"第一条","txt":"当事人因遭受家庭暴力或者面临家庭暴力的现实危险，依照反家庭暴力法向人民法院申请人身安全保护令的，人民法院应当受理。"},{"i":2,"n":"第二条","txt":"当事人因年老、残疾、重病等原因无法申请人身安全保护令，其近亲属、公安机关、民政部门、妇女联合会、居民委员会、村民委员会、残疾人联合会、依法设立的老年人组织、救助管理机构等，根据当事人意愿，依照反家庭暴力法第二十三条规定代为申请的，人民法院应当依法受理。"},{"i":3,"n":"第三条","txt":"家庭成员之间以冻饿或者经常性侮辱、诽谤、威胁、跟踪、骚扰等方式实施的身体或者精神侵害行为，应当认定为反家庭暴力法第二条规定的“家庭暴力”。"},{"i":4,"n":"第四条","txt":"反家庭暴力法第三十七条规定的“家庭成员以外共同生活的人”一般包括共同生活的儿媳、女婿、公婆、岳父母以及其他有监护、扶养、寄养等关系的人。"},{"i":5,"n":"第五条","txt":"当事人及其代理人对因客观原因不能自行收集的证据，申请人民法院调查收集，符合《最高人民法院关于适用〈中华人民共和国民事诉讼法〉的解释》第九十四条第一款规定情形的，人民法院应当调查收集。"},{"i":6,"n":"第六条","txt":"人身安全保护令案件中，人民法院根据相关证据，认为申请人遭受家庭暴力或者面临家庭暴力现实危险的事实存在较大可能性的，可以依法作出人身安全保护令。"},{"i":7,"n":"第七条","txt":"人民法院可以通过在线诉讼平台、电话、短信、即时通讯工具、电子邮件等简便方式询问被申请人。被申请人未发表意见的，不影响人民法院依法作出人身安全保护令。"},{"i":8,"n":"第八条","txt":"被申请人认可存在家庭暴力行为，但辩称申请人有过错的，不影响人民法院依法作出人身安全保护令。"},{"i":9,"n":"第九条","txt":"离婚等案件中，当事人仅以人民法院曾作出人身安全保护令为由，主张存在家庭暴力事实的，人民法院应当根据《最高人民法院关于适用〈中华人民共和国民事诉讼法〉的解释》第一百零八条的规定，综合认定是否存在该事实。"},{"i":10,"n":"第十条","txt":"反家庭暴力法第二十九条第四项规定的“保护申请人人身安全的其他措施”可以包括下列措施："},{"i":11,"n":"第十一条","txt":"离婚案件中，判决不准离婚或者调解和好后，被申请人违反人身安全保护令实施家庭暴力的，可以认定为民事诉讼法第一百二十七条第七项规定的“新情况、新理由”。"},{"i":12,"n":"第十二条","txt":"被申请人违反人身安全保护令，符合《中华人民共和国刑法》第三百一十三条规定的，以拒不执行判决、裁定罪定罪处罚；同时构成其他犯罪的，依照刑法有关规定处理。"},{"i":13,"n":"第十三条","txt":"本规定自2022年8月1日起施行。"}],"zuigaorenminfayuanguanyubanlijianxingjiashianjianjc8f243":[{"i":1,"n":"第一条","txt":"对拒不认罪悔罪的，或者确有履行能力而不履行或者不全部履行生效裁判中财产性判项的，不予假释，一般不予减刑。"},{"i":2,"n":"第二条","txt":"被判处十年以上有期徒刑，符合减刑条件的，执行三年以上方可减刑；被判处不满十年有期徒刑，符合减刑条件的，执行二年以上方可减刑。"},{"i":3,"n":"第三条","txt":"被判处无期徒刑，符合减刑条件的，执行四年以上方可减刑。"},{"i":4,"n":"第四条","txt":"被判处死刑缓期执行的，减为无期徒刑后，符合减刑条件的，执行四年以上方可减刑。"},{"i":5,"n":"第五条","txt":"罪犯有重大立功表现的，减刑时可以不受上述起始时间和间隔时间的限制。"},{"i":6,"n":"第六条","txt":"对本规定所指贪污贿赂罪犯适用假释时，应当从严掌握。"},{"i":7,"n":"第七条","txt":"本规定自2019年6月1日起施行。此前发布的司法解释与本规定不一致的，以本规定为准。"}],"zuigaorenminfayuanguanyubanlijianxingjiashianjianjac84fa":[{"i":1,"n":"第一条","txt":"减刑、假释是激励罪犯改造的刑罚制度，减刑、假释的适用应当贯彻宽严相济刑事政策，最大限度地发挥刑罚的功能，实现刑罚的目的。"},{"i":2,"n":"第二条","txt":"对于罪犯符合刑法第七十八条第一款规定“可以减刑”条件的案件，在办理时应当综合考察罪犯犯罪的性质和具体情节、社会危害程度、原判刑罚及生效裁判中财产性判项的履行情况、交付执行后的一贯表现等因素。"},{"i":3,"n":"第三条","txt":"“确有悔改表现”是指同时具备以下条件："},{"i":4,"n":"第四条","txt":"具有下列情形之一的，可以认定为有“立功表现”："},{"i":5,"n":"第五条","txt":"具有下列情形之一的，应当认定为有“重大立功表现”："},{"i":6,"n":"第六条","txt":"被判处有期徒刑的罪犯减刑起始时间为：不满五年有期徒刑的，应当执行一年以上方可减刑；五年以上不满十年有期徒刑的，应当执行一年六个月以上方可减刑；十年以上有期徒刑的，应当执行二年以上方可减刑。有期徒刑减刑的起始时间自判决执行之日起计算。"},{"i":7,"n":"第七条","txt":"对符合减刑条件的职务犯罪罪犯，破坏金融管理秩序和金融诈骗犯罪罪犯，组织、领导、参加、包庇、纵容黑社会性质组织犯罪罪犯，危害国家安全犯罪罪犯，恐怖活动犯罪罪犯，毒品犯罪集团的首要分子及毒品再犯，累犯，确有履行能力而不履行或者不全部履行生效裁判中财产性判项的罪犯，被判处十年以下有期徒刑的，执行二年以上方可减刑，减刑幅度应当比照本规定第六条从严掌握，一次减刑不超过一年有期徒刑，两次减刑之间应当间隔一年以上。"},{"i":8,"n":"第八条","txt":"被判处无期徒刑的罪犯在刑罚执行期间，符合减刑条件的，执行二年以上，可以减刑。减刑幅度为：确有悔改表现或者有立功表现的，可以减为二十二年有期徒刑；确有悔改表现并有立功表现的，可以减为二十一年以上二十二年以下有期徒刑；有重大立功表现的，可以减为二十年以上二十一年以下有期徒刑；确有悔改表现并有重大立功表现的，可以减为十九年以上二十年以下有期徒刑。无期徒刑罪犯减为有期徒刑后再减刑时，减刑幅度依照本规定第六条的规定执行。两次减刑间隔时间不得少于二年。"},{"i":9,"n":"第九条","txt":"对被判处无期徒刑的职务犯罪罪犯，破坏金融管理秩序和金融诈骗犯罪罪犯，组织、领导、参加、包庇、纵容黑社会性质组织犯罪罪犯，危害国家安全犯罪罪犯，恐怖活动犯罪罪犯，毒品犯罪集团的首要分子及毒品再犯，累犯以及因故意杀人、强奸、抢劫、绑架、放火、爆炸、投放危险物质或者有组织的暴力性犯罪的罪犯，确有履行能力而不履行或者不全部履行生效裁判中财产性判项的罪犯，数罪并罚被判处无期徒刑的罪犯，符合减刑条件的，执行三年以上方可减刑，减刑幅度应当比照本规定第八条从严掌握，减刑后的刑期最低不得少于二十年有期徒刑；减为有期徒刑后再减刑时，减刑幅度比照本规定第六条从严掌握，一次不超过一年有期徒刑，两次减刑之间应当间隔二年以上。"},{"i":10,"n":"第十条","txt":"被判处死刑缓期执行的罪犯减为无期徒刑后，符合减刑条件的，执行三年以上方可减刑。减刑幅度为：确有悔改表现或者有立功表现的，可以减为二十五年有期徒刑；确有悔改表现并有立功表现的，可以减为二十四年以上二十五年以下有期徒刑；有重大立功表现的，可以减为二十三年以上二十四年以下有期徒刑；确有悔改表现并有重大立功表现的，可以减为二十二年以上二十三年以下有期徒刑。"},{"i":11,"n":"第十一条","txt":"对被判处死刑缓期执行的职务犯罪罪犯，破坏金融管理秩序和金融诈骗犯罪罪犯，组织、领导、参加、包庇、纵容黑社会性质组织犯罪罪犯，危害国家安全犯罪罪犯，恐怖活动犯罪罪犯，毒品犯罪集团的首要分子及毒品再犯，累犯以及因故意杀人、强奸、抢劫、绑架、放火、爆炸、投放危险物质或者有组织的暴力性犯罪的罪犯，确有履行能力而不履行或者不全部履行生效裁判中财产性判项的罪犯，数罪并罚被判处死刑缓期执行的罪犯，减为无期徒刑后，符合减刑条件的，执行三年以上方可减刑，一般减为二十五年有期徒刑，有立功表现或者重大立功表现的，可以比照本规定第十条减为二十三年以上二十五年以下有期徒刑；减为有期徒刑后再减刑时，减刑幅度比照本规定第六条从严掌握，一次不超过一年有期徒刑，两次减刑之间应当间隔二年以上。"},{"i":12,"n":"第十二条","txt":"被判处死刑缓期执行的罪犯经过一次或者几次减刑后，其实际执行的刑期不得少于十五年，死刑缓期执行期间不包括在内。"},{"i":13,"n":"第十三条","txt":"被限制减刑的死刑缓期执行罪犯，减为无期徒刑后，符合减刑条件的，执行五年以上方可减刑。减刑间隔时间和减刑幅度依照本规定第十一条的规定执行。"},{"i":14,"n":"第十四条","txt":"被限制减刑的死刑缓期执行罪犯，减为有期徒刑后再减刑时，一次减刑不超过六个月有期徒刑，两次减刑间隔时间不得少于二年。有重大立功表现的，间隔时间可以适当缩短，但一次减刑不超过一年有期徒刑。"},{"i":15,"n":"第十五条","txt":"对被判处终身监禁的罪犯，在死刑缓期执行期满依法减为无期徒刑的裁定中，应当明确终身监禁，不得再减刑或者假释。"},{"i":16,"n":"第十六条","txt":"被判处管制、拘役的罪犯，以及判决生效后剩余刑期不满二年有期徒刑的罪犯，符合减刑条件的，可以酌情减刑，减刑起始时间可以适当缩短，但实际执行的刑期不得少于原判刑期的二分之一。"},{"i":17,"n":"第十七条","txt":"被判处有期徒刑罪犯减刑时，对附加剥夺政治权利的期限可以酌减。酌减后剥夺政治权利的期限，不得少于一年。"},{"i":18,"n":"第十八条","txt":"被判处拘役或者三年以下有期徒刑，并宣告缓刑的罪犯，一般不适用减刑。"},{"i":19,"n":"第十九条","txt":"对在报请减刑前的服刑期间不满十八周岁，且所犯罪行不属于刑法第八十一条第二款规定情形的罪犯，认罪悔罪，遵守法律法规及监规，积极参加学习、劳动，应当视为确有悔改表现。"},{"i":20,"n":"第二十条","txt":"老年罪犯、患严重疾病罪犯或者身体残疾罪犯减刑时，应当主要考察其认罪悔罪的实际表现。"},{"i":21,"n":"第二十一条","txt":"被判处有期徒刑、无期徒刑的罪犯在刑罚执行期间又故意犯罪，新罪被判处有期徒刑的，自新罪判决确定之日起三年内不予减刑；新罪被判处无期徒刑的，自新罪判决确定之日起四年内不予减刑。"},{"i":22,"n":"第二十二条","txt":"办理假释案件，认定“没有再犯罪的危险”，除符合刑法第八十一条规定的情形外，还应当根据犯罪的具体情节、原判刑罚情况，在刑罚执行中的一贯表现，罪犯的年龄、身体状况、性格特征，假释后生活来源以及监管条件等因素综合考虑。"},{"i":23,"n":"第二十三条","txt":"被判处有期徒刑的罪犯假释时，执行原判刑期二分之一的时间，应当从判决执行之日起计算，判决执行以前先行羁押的，羁押一日折抵刑期一日。"},{"i":24,"n":"第二十四条","txt":"刑法第八十一条第一款规定的“特殊情况”，是指有国家政治、国防、外交等方面特殊需要的情况。"},{"i":25,"n":"第二十五条","txt":"对累犯以及因故意杀人、强奸、抢劫、绑架、放火、爆炸、投放危险物质或者有组织的暴力性犯罪被判处十年以上有期徒刑、无期徒刑的罪犯，不得假释。"},{"i":26,"n":"第二十六条","txt":"对下列罪犯适用假释时可以依法从宽掌握："},{"i":27,"n":"第二十七条","txt":"对于生效裁判中有财产性判项，罪犯确有履行能力而不履行或者不全部履行的，不予假释。"},{"i":28,"n":"第二十八条","txt":"罪犯减刑后又假释的，间隔时间不得少于一年；对一次减去一年以上有期徒刑后，决定假释的，间隔时间不得少于一年六个月。"},{"i":29,"n":"第二十九条","txt":"罪犯在假释考验期内违反法律、行政法规或者国务院有关部门关于假释的监督管理规定的，作出假释裁定的人民法院，应当在收到报请机关或者检察机关撤销假释建议书后及时审查，作出是否撤销假释的裁定，并送达报请机关，同时抄送人民检察院、公安机关和原刑罚执行机关。"},{"i":30,"n":"第三十条","txt":"依照刑法第八十六条规定被撤销假释的罪犯，一般不得再假释。但依照该条第二款被撤销假释的罪犯，如果罪犯对漏罪曾作如实供述但原判未予认定，或者漏罪系其自首，符合假释条件的，可以再假释。"},{"i":31,"n":"第三十一条","txt":"年满八十周岁、身患疾病或者生活难以自理、没有再犯罪危险的罪犯，既符合减刑条件，又符合假释条件的，优先适用假释；不符合假释条件的，参照本规定第二十条有关的规定从宽处理。"},{"i":32,"n":"第三十二条","txt":"人民法院按照审判监督程序重新审理的案件，裁定维持原判决、裁定的，原减刑、假释裁定继续有效。"},{"i":33,"n":"第三十三条","txt":"罪犯被裁定减刑后，刑罚执行期间因故意犯罪而数罪并罚时，经减刑裁定减去的刑期不计入已经执行的刑期。原判死刑缓期执行减为无期徒刑、有期徒刑，或者无期徒刑减为有期徒刑的裁定继续有效。"},{"i":34,"n":"第三十四条","txt":"罪犯被裁定减刑后，刑罚执行期间因发现漏罪而数罪并罚的，原减刑裁定自动失效。如漏罪系罪犯主动交代的，对其原减去的刑期，由执行机关报请有管辖权的人民法院重新作出减刑裁定，予以确认；如漏罪系有关机关发现或者他人检举揭发的，由执行机关报请有管辖权的人民法院，在原减刑裁定减去的刑期总和之内，酌情重新裁定。"},{"i":35,"n":"第三十五条","txt":"被判处死刑缓期执行的罪犯，在死刑缓期执行期内被发现漏罪，依据刑法第七十条规定数罪并罚，决定执行死刑缓期执行的，死刑缓期执行期间自新判决确定之日起计算，已经执行的死刑缓期执行期间计入新判决的死刑缓期执行期间内，但漏罪被判处死刑缓期执行的除外。"},{"i":36,"n":"第三十六条","txt":"被判处死刑缓期执行的罪犯，在死刑缓期执行期满后被发现漏罪，依据刑法第七十条规定数罪并罚，决定执行死刑缓期执行的，交付执行时对罪犯实际执行无期徒刑，死缓考验期不再执行，但漏罪被判处死刑缓期执行的除外。"},{"i":37,"n":"第三十七条","txt":"被判处无期徒刑的罪犯在减为有期徒刑后因发现漏罪，依据刑法第七十条规定数罪并罚，决定执行无期徒刑的，前罪无期徒刑生效之日起至新判决生效之日止已经实际执行的刑期，应当在新判决的无期徒刑减为有期徒刑时，在减刑裁定决定执行的刑期内扣减。"},{"i":38,"n":"第三十八条","txt":"人民法院作出的刑事判决、裁定发生法律效力后，在依照刑事诉讼法第二百五十三条、第二百五十四条的规定将罪犯交付执行刑罚时，如果生效裁判中有财产性判项，人民法院应当将反映财产性判项执行、履行情况的有关材料一并随案移送刑罚执行机关。罪犯在服刑期间本人履行或者其亲属代为履行生效裁判中财产性判项的，应当及时向刑罚执行机关报告。刑罚执行机关报请减刑时应随案移送以上材料。"},{"i":39,"n":"第三十九条","txt":"本规定所称“老年罪犯”，是指报请减刑、假释时年满六十五周岁的罪犯。"},{"i":40,"n":"第四十条","txt":"本规定所称“判决执行之日”，是指罪犯实际送交刑罚执行机关之日。"},{"i":41,"n":"第四十一条","txt":"本规定所称“财产性判项”是指判决罪犯承担的附带民事赔偿义务判项，以及追缴、责令退赔、罚金、没收财产等判项。"},{"i":42,"n":"第四十二条","txt":"本规定自2017年1月1日起施行。以前发布的司法解释与本规定不一致的，以本规定为准。"}],"zuigaorenminfayuanguanyubanlijianxingjiashianjians1ed2a5":[{"i":1,"n":"第一条","txt":"人民法院办理减刑、假释案件必须审查原生效刑事或者刑事附带民事裁判中财产性判项的执行情况，以此作为判断罪犯是否确有悔改表现的因素之一。"},{"i":2,"n":"第二条","txt":"人民法院审查财产性判项的执行情况，应将执行法院出具的结案通知书、缴付款票据、执行情况说明等作为审查判断的依据。"},{"i":3,"n":"第三条","txt":"财产性判项未执行完毕的，人民法院应当着重审查罪犯的履行能力。"},{"i":4,"n":"第四条","txt":"罪犯有财产性判项履行能力的，应在履行后方可减刑、假释。"},{"i":5,"n":"第五条","txt":"财产性判项未执行完毕的减刑、假释案件，人民法院在受理时应当重点审查下列材料："},{"i":6,"n":"第六条","txt":"财产性判项未履行完毕，具有下列情形之一的，应当认定罪犯确有履行能力而不履行："},{"i":7,"n":"第七条","txt":"罪犯经执行法院查控未发现有可供执行财产，且不具有本规定第六条所列情形的，应认定其确无履行能力。"},{"i":8,"n":"第八条","txt":"罪犯被判处的罚金被执行法院裁定免除的，其他财产性判项未履行完毕不影响对其确有悔改表现的认定，但罪犯确有履行能力的除外。"},{"i":9,"n":"第九条","txt":"判处没收财产的，判决生效后，应当立即执行，所执行财产为判决生效时罪犯个人合法所有的财产。除具有本规定第六条第一款所列情形外，没收财产判项执行情况一般不影响对罪犯确有悔改表现的认定。"},{"i":10,"n":"第十条","txt":"承担民事赔偿义务的罪犯，具有下列情形之一的，不影响对其确有悔改表现的认定："},{"i":11,"n":"第十一条","txt":"因犯罪行为造成损害，受害人单独提起民事赔偿诉讼的，人民法院办理减刑、假释案件时应对相关生效民事判决确定的赔偿义务判项执行情况进行审查，并结合本规定综合判断罪犯是否确有悔改表现。"},{"i":12,"n":"第十二条","txt":"对职务犯罪、破坏金融管理秩序和金融诈骗犯罪、组织（领导、参加、包庇、纵容）黑社会性质组织犯罪等罪犯，不积极退赃、协助追缴赃款赃物、赔偿损失的，不认定其确有悔改表现。"},{"i":13,"n":"第十三条","txt":"人民法院将罪犯交付执行刑罚时，对生效裁判中有财产性判项的，应当将财产性判项实际执行情况的材料一并移送刑罚执行机关。"},{"i":14,"n":"第十四条","txt":"人民法院办理减刑、假释案件中发现罪犯确有履行能力而不履行的，裁定不予减刑、假释，或者依法由刑罚执行机关撤回减刑、假释建议。"},{"i":15,"n":"第十五条","txt":"本规定自2024年5月1日起施行，此前发布的司法解释与本规定不一致的，以本规定为准。"}],"zuigaorenminfayuanguanyubanlishenqingrenminfayuanqa56e2a":[{"i":1,"n":"第一条","txt":"申请人民法院强制执行征收补偿决定案件，由房屋所在地基层人民法院管辖，高级人民法院可以根据本地实际情况决定管辖法院。"},{"i":2,"n":"第二条","txt":"申请机关向人民法院申请强制执行，除提供《条例》第二十八条规定的强制执行申请书及附具材料外，还应当提供下列材料："},{"i":3,"n":"第三条","txt":"人民法院认为强制执行的申请符合形式要件且材料齐全的，应当在接到申请后五日内立案受理，并通知申请机关；不符合形式要件或者材料不全的应当限期补正，并在最终补正的材料提供后五日内立案受理；不符合形式要件或者逾期无正当理由不补正材料的，裁定不予受理。"},{"i":4,"n":"第四条","txt":"人民法院应当自立案之日起三十日内作出是否准予执行的裁定；有特殊情况需要延长审查期限的，由高级人民法院批准。"},{"i":5,"n":"第五条","txt":"人民法院在审查期间，可以根据需要调取相关证据、询问当事人、组织听证或者进行现场调查。"},{"i":6,"n":"第六条","txt":"征收补偿决定存在下列情形之一的，人民法院应当裁定不准予执行："},{"i":7,"n":"第七条","txt":"申请机关对不准予执行的裁定有异议的，可以自收到裁定之日起十五日内向上一级人民法院申请复议，上一级人民法院应当自收到复议申请之日起三十日内作出裁定。"},{"i":8,"n":"第八条","txt":"人民法院裁定准予执行的，应当在五日内将裁定送达申请机关和被执行人，并可以根据实际情况建议申请机关依法采取必要措施，保障征收与补偿活动顺利实施。"},{"i":9,"n":"第九条","txt":"人民法院裁定准予执行的，一般由作出征收补偿决定的市、县级人民政府组织实施，也可以由人民法院执行。"},{"i":10,"n":"第十条","txt":"《条例》施行前已依法取得房屋拆迁许可证的项目，人民法院裁定准予执行房屋拆迁裁决的，参照本规定第九条精神办理。"},{"i":11,"n":"第十一条","txt":"最高人民法院以前所作的司法解释与本规定不一致的，按本规定执行。"}],"zuigaorenminfayuanguanyubanlixingzhengshenqingzaisc9c327":[{"i":1,"n":"第一条","txt":"当事人不服高级人民法院已经发生法律效力的判决、裁定，依照行政诉讼法第九十条的规定向最高人民法院申请再审的，最高人民法院应当依法审查，分别情况予以处理。"},{"i":2,"n":"第二条","txt":"下列行政申请再审案件中，原判决、裁定适用法律、法规确有错误的，最高人民法院应当裁定再审："},{"i":3,"n":"第三条","txt":"行政申请再审案件有下列情形之一的，最高人民法院可以决定由作出生效判决、裁定的高级人民法院审查："},{"i":4,"n":"第四条","txt":"已经发生法律效力的判决、裁定认定事实清楚，适用法律、法规正确，当事人主张的再审事由不成立的，最高人民法院可以迳行裁定驳回再审申请。"},{"i":5,"n":"第五条","txt":"当事人不服人民法院再审判决、裁定的，可以依法向人民检察院申请抗诉或者检察建议。"},{"i":6,"n":"第六条","txt":"本解释自2021年4月1日起施行。本解释施行后，最高人民法院此前作出的相关司法解释与本解释相抵触的，以本解释为准。"}],"zuigaorenminfayuanguanyubeijingshanghaiguangzhouzh979578":[{"i":1,"n":"第一条","txt":"知识产权法院管辖所在市辖区内的下列第一审案件："},{"i":2,"n":"第二条","txt":"广州知识产权法院对广东省内本规定第一条第（一）项和第（三）项规定的案件实行跨区域管辖。"},{"i":3,"n":"第三条","txt":"北京市、上海市各中级人民法院和广州市中级人民法院不再受理知识产权民事和行政案件。"},{"i":4,"n":"第四条","txt":"案件标的既包含本规定第一条第（一）项和第（三）项规定的内容，又包含其他内容的，按本规定第一条和第二条的规定确定管辖。"},{"i":5,"n":"第五条","txt":"下列第一审行政案件由北京知识产权法院管辖："},{"i":6,"n":"第六条","txt":"当事人对知识产权法院所在市的基层人民法院作出的第一审著作权、商标、技术合同、不正当竞争等知识产权民事和行政判决、裁定提起的上诉案件，由知识产权法院审理。"},{"i":7,"n":"第七条","txt":"当事人对知识产权法院作出的第一审判决、裁定提起的上诉案件和依法申请上一级法院复议的案件，由知识产权法院所在地的高级人民法院知识产权审判庭审理，但依法应由最高人民法院审理的除外。"},{"i":8,"n":"第八条","txt":"知识产权法院所在省（直辖市）的基层人民法院在知识产权法院成立前已经受理但尚未审结的本规定第一条第（一）项和第（三）项规定的案件，由该基层人民法院继续审理。"}],"zuigaorenminfayuanguanyubeijingjinrongfayuananjian1cc796":[{"i":1,"n":"第一条","txt":"北京金融法院管辖北京市辖区内应由中级人民法院受理的下列第一审金融民商事案件："},{"i":2,"n":"第二条","txt":"下列金融纠纷案件，由北京金融法院管辖："},{"i":3,"n":"第三条","txt":"在全国中小企业股份转让系统向不特定合格投资者公开发行股票并在精选层挂牌的公司的证券发行纠纷、证券承销合同纠纷、证券交易合同纠纷、证券欺诈责任纠纷以及证券推荐保荐和持续督导合同、证券挂牌合同引起的纠纷等第一审民商事案件，由北京金融法院管辖。"},{"i":4,"n":"第四条","txt":"以全国中小企业股份转让系统有限责任公司为被告或者第三人的与证券交易场所监管职能相关的第一审金融民商事和涉金融行政案件，由北京金融法院管辖。"},{"i":5,"n":"第五条","txt":"以住所地在北京市并依法设立的金融基础设施机构为被告或者第三人的与其履行职责相关的第一审金融民商事案件，由北京金融法院管辖。"},{"i":6,"n":"第六条","txt":"北京市辖区内应由中级人民法院受理的对中国人民银行、中国银行保险监督管理委员会、中国证券监督管理委员会、国家外汇管理局等国家金融管理部门以及其他国务院组成部门和法律、法规、规章授权的组织因履行金融监管职责作出的行政行为不服提起诉讼的第一审涉金融行政案件，由北京金融法院管辖。"},{"i":7,"n":"第七条","txt":"当事人对北京市基层人民法院作出的涉及本规定第一条第一至三项的第一审金融民商事案件和涉金融行政案件判决、裁定提起的上诉案件和申请再审案件，由北京金融法院审理。"},{"i":8,"n":"第八条","txt":"北京市辖区内应由中级人民法院受理的金融民商事案件、涉金融行政案件的再审案件，由北京金融法院审理。"},{"i":9,"n":"第九条","txt":"北京金融法院作出的第一审民商事案件和涉金融行政案件生效裁判，以及北京市辖区内应由中级人民法院执行的涉金融民商事纠纷的仲裁裁决，由北京金融法院执行。"},{"i":10,"n":"第十条","txt":"中国人民银行、中国银行保险监督管理委员会、中国证券监督管理委员会、国家外汇管理局等国家金融管理部门，以及其他国务院组成部门因履行金融监管职责作为申请人的非诉行政执行案件，由北京金融法院审查和执行。"},{"i":11,"n":"第十一条","txt":"当事人对北京金融法院作出的第一审判决、裁定提起的上诉案件，由北京市高级人民法院审理。"},{"i":12,"n":"第十二条","txt":"北京市各中级人民法院在北京金融法院成立前已经受理但尚未审结的金融民商事案件和涉金融行政案件，由该中级人民法院继续审理。"},{"i":13,"n":"第十三条","txt":"本规定自2021年3月16日起施行。"}],"zuigaorenminfayuanguanyuguojiapeichanganjianliangob30143":[{"i":1,"n":"第一条","txt":"本规定所称国家赔偿案件，是指国家赔偿法第十七条、第十八条、第二十一条、第三十八条规定的下列案件："},{"i":2,"n":"第二条","txt":"赔偿请求人向作为赔偿义务机关的人民法院提出赔偿申请，或者依照国家赔偿法第二十四条、第二十五条的规定向人民法院赔偿委员会提出赔偿申请的，收到申请的人民法院根据本规定予以审查立案。"},{"i":3,"n":"第三条","txt":"赔偿请求人当面递交赔偿申请的，收到申请的人民法院应当依照国家赔偿法第十二条的规定，当场出具加盖本院专用印章并注明收讫日期的书面凭证。"},{"i":4,"n":"第四条","txt":"赔偿请求人向作为赔偿义务机关的人民法院提出赔偿申请，收到申请的人民法院经审查认为其申请符合下列条件的，应予立案："},{"i":5,"n":"第五条","txt":"赔偿请求人对作为赔偿义务机关的人民法院作出的是否赔偿的决定不服，依照国家赔偿法第二十四条的规定向其上一级人民法院赔偿委员会提出赔偿申请，收到申请的人民法院经审查认为其申请符合下列条件的，应予立案："},{"i":6,"n":"第六条","txt":"作为赔偿义务机关的人民法院逾期未作出是否赔偿的决定，赔偿请求人依照国家赔偿法第二十四条的规定向其上一级人民法院赔偿委员会提出赔偿申请，收到申请的人民法院经审查认为其申请符合下列条件的，应予立案："},{"i":7,"n":"第七条","txt":"赔偿请求人对行使侦查、检察职权的机关以及看守所、监狱管理机关作出的决定不服，经向其上一级机关申请复议，对复议机关的复议决定仍不服，依照国家赔偿法第二十五条的规定向复议机关所在地的同级人民法院赔偿委员会提出赔偿申请，收到申请的人民法院经审查认为其申请符合下列条件的，应予立案："},{"i":8,"n":"第八条","txt":"复议机关逾期未作出复议决定，赔偿请求人依照国家赔偿法第二十五条的规定向复议机关所在地的同级人民法院赔偿委员会提出赔偿申请，收到申请的人民法院经审查认为其申请符合下列条件的，应予立案："},{"i":9,"n":"第九条","txt":"人民法院应当在收到申请之日起七日内决定是否立案。"},{"i":10,"n":"第十条","txt":"赔偿请求人对复议机关或者作为赔偿义务机关的人民法院作出的决定不予受理的文书不服，依照国家赔偿法第二十四条、第二十五条的规定向人民法院赔偿委员会提出赔偿申请，收到申请的人民法院可以依照本规定第六条、第八条予以审查立案。"},{"i":11,"n":"第十一条","txt":"自本规定施行之日起，《最高人民法院关于刑事赔偿和非刑事司法赔偿案件立案工作的暂行规定（试行）》即行废止；本规定施行前本院发布的司法解释与本规定不一致的，以本规定为准。"}],"zuigaorenminfayuanguanyuguojiapeichangjianduchengxd4aff1":[{"i":1,"n":"第一条","txt":"依照国家赔偿法第三十条的规定，有下列情形之一的，适用本规定予以处理："},{"i":2,"n":"第二条","txt":"赔偿请求人或者赔偿义务机关对赔偿委员会生效决定，认为确有错误的，可以向上一级人民法院赔偿委员会提出申诉。申诉审查期间，不停止生效决定的执行。"},{"i":3,"n":"第三条","txt":"赔偿委员会决定生效后，赔偿请求人死亡或者其主体资格终止的，其权利义务承继者可以依法提出申诉。"},{"i":4,"n":"第四条","txt":"赔偿请求人、法定代理人可以委托一至二人作为代理人代为申诉。申诉代理人的范围包括："},{"i":5,"n":"第五条","txt":"赔偿请求人或者赔偿义务机关申诉，应当提交以下材料："},{"i":6,"n":"第六条","txt":"申诉符合下列条件的，人民法院应当在收到申诉材料之日起七日内予以立案："},{"i":7,"n":"第七条","txt":"赔偿请求人或者赔偿义务机关申诉，有下列情形之一的，人民法院不予受理："},{"i":8,"n":"第八条","txt":"赔偿委员会对于立案受理的申诉案件，应当着重围绕申诉人的申诉事由进行审查。必要时，应当对原决定认定的事实、证据和适用法律进行全面审查。"},{"i":9,"n":"第九条","txt":"赔偿委员会审查申诉案件采取书面审查的方式，根据需要可以听取申诉人和被申诉人的陈述和申辩。"},{"i":10,"n":"第十条","txt":"赔偿委员会审查申诉案件，一般应当在三个月内作出处理，至迟不得超过六个月。有特殊情况需要延长的，由本院院长批准。"},{"i":11,"n":"第十一条","txt":"有下列情形之一的，应当决定重新审理："},{"i":12,"n":"第十二条","txt":"申诉人在申诉阶段提供新的证据，应当说明逾期提供的理由。"},{"i":13,"n":"第十三条","txt":"赔偿委员会经审查，对申诉人的申诉按照下列情形分别处理："},{"i":14,"n":"第十四条","txt":"人民法院院长发现本院赔偿委员会生效决定违反国家赔偿法规定，认为需要重新审理的，应当提交审判委员会讨论决定。"},{"i":15,"n":"第十五条","txt":"最高人民检察院对各级人民法院赔偿委员会生效决定，上级人民检察院对下级人民法院赔偿委员会生效决定，向同级人民法院赔偿委员会提出重新审查意见的，同级人民法院赔偿委员会应当决定直接审理，并将决定书送达提出意见的人民检察院。"},{"i":16,"n":"第十六条","txt":"赔偿委员会重新审理案件，适用国家赔偿法和相关司法解释关于赔偿委员会审理程序的规定；本规定依据国家赔偿法和相关法律对重新审理程序有特别规定的，适用本规定。"},{"i":17,"n":"第十七条","txt":"决定重新审理的案件，可以根据案件情形中止原决定的执行。"},{"i":18,"n":"第十八条","txt":"赔偿委员会重新审理案件，采取书面审理的方式，必要时可以向有关单位和人员调查情况、收集证据，听取申诉人、被申诉人或者赔偿请求人、赔偿义务机关的陈述和申辩。有本规定第十一条第一项、第三项情形，或者赔偿委员会认为确有必要的，可以组织申诉人、被申诉人或者赔偿请求人、赔偿义务机关公开质证。"},{"i":19,"n":"第十九条","txt":"赔偿委员会重新审理案件，应当对原决定认定的事实、证据和适用法律进行全面审理。"},{"i":20,"n":"第二十条","txt":"赔偿委员会重新审理的案件，应当在两个月内依法作出决定。"},{"i":21,"n":"第二十一条","txt":"案件经重新审理后，应当根据下列情形分别处理："},{"i":22,"n":"第二十二条","txt":"赔偿委员会重新审理后作出的决定，应当及时送达申诉人、被申诉人或者赔偿请求人、赔偿义务机关和提出意见的人民检察院。"},{"i":23,"n":"第二十三条","txt":"在申诉审查或者重新审理期间，有下列情形之一的，赔偿委员会应当决定中止审查或者审理："},{"i":24,"n":"第二十四条","txt":"在申诉审查期间，有下列情形之一的，赔偿委员会应当决定终结审查："},{"i":25,"n":"第二十五条","txt":"申诉人在申诉审查或者重新审理期间申请撤回申诉的，赔偿委员会应当依法审查并作出是否准许的决定。"},{"i":26,"n":"第二十六条","txt":"赔偿请求人在重新审理期间申请撤回赔偿申请的，赔偿委员会应当依法审查并作出是否准许的决定。准许撤回赔偿申请的，应当一并撤销原决定。"},{"i":27,"n":"第二十七条","txt":"本规定自2017年5月1日起施行。最高人民法院以前发布的司法解释和规范性文件，与本规定不一致的，以本规定为准。"}],"zuigaorenminfayuanguanyuzaishenlijingjijiufenanjia24f3c3":[{"i":1,"n":"第一条","txt":"同一自然人、法人或非法人组织因不同的法律事实，分别涉及经济纠纷和经济犯罪嫌疑的，经济纠纷案件和经济犯罪嫌疑案件应当分开审理。"},{"i":2,"n":"第二条","txt":"单位直接负责的主管人员和其他直接责任人员，以为单位骗取财物为目的，采取欺骗手段对外签订经济合同，骗取的财物被该单位占有、使用或处分构成犯罪的，除依法追究有关人员的刑事责任，责令该单位返还骗取的财物外，如给被害人造成经济损失的，单位应当承担赔偿责任。"},{"i":3,"n":"第三条","txt":"单位直接负责的主管人员和其他直接责任人员，以该单位的名义对外签订经济合同，将取得的财物部分或全部占为己有构成犯罪的，除依法追究行为人的刑事责任外，该单位对行为人因签订、履行该经济合同造成的后果，依法应当承担民事责任。"},{"i":4,"n":"第四条","txt":"个人借用单位的业务介绍信、合同专用章或者盖有公章的空白合同书，以出借单位名义签订经济合同，骗取财物归个人占有、使用、处分或者进行其他犯罪活动，给对方造成经济损失构成犯罪的，除依法追究借用人的刑事责任外，出借业务介绍信、合同专用章或者盖有公章的空白合同书的单位，依法应当承担赔偿责任。但是，有证据证明被害人明知签订合同对方当事人是借用行为，仍与之签订合同的除外。"},{"i":5,"n":"第五条","txt":"行为人盗窃、盗用单位的公章、业务介绍信、盖有公章的空白合同书，或者私刻单位的公章签订经济合同，骗取财物归个人占有、使用、处分或者进行其他犯罪活动构成犯罪的，单位对行为人该犯罪行为所造成的经济损失不承担民事责任。"},{"i":6,"n":"第六条","txt":"企业承包、租赁经营合同期满后，企业按规定办理了企业法定代表人的变更登记，而企业法人未采取有效措施收回其公章、业务介绍信、盖有公章的空白合同书，或者没有及时采取措施通知相对人，致原企业承包人、租赁人得以用原承包、租赁企业的名义签订经济合同，骗取财物占为己有构成犯罪的，该企业对被害人的经济损失，依法应当承担赔偿责任。但是，原承包人、承租人利用擅自保留的公章、业务介绍信、盖有公章的空白合同书以原承包、租赁企业的名义签订经济合同，骗取财物占为己有构成犯罪的，企业一般不承担民事责任。"},{"i":7,"n":"第七条","txt":"单位直接负责的主管人员和其他直接责任人员，将单位进行走私或其他犯罪活动所得财物以签订经济合同的方法予以销售，买方明知或者应当知道的，如因此造成经济损失，其损失由买方自负。但是，如果买方不知该经济合同的标的物是犯罪行为所得财物而购买的，卖方对买方所造成的经济损失应当承担民事责任。"},{"i":8,"n":"第八条","txt":"根据《中华人民共和国刑事诉讼法》第一百零一条第一款的规定，被害人或其法定代理人、近亲属对本规定第二条因单位犯罪行为造成经济损失的，对第四条、第五条第一款、第六条应当承担刑事责任的被告人未能返还财物而遭受经济损失提起附带民事诉讼的，受理刑事案件的人民法院应当依法一并审理。被害人或其法定代理人、近亲属因被害人遭受经济损失也有权对单位另行提起民事诉讼。若被害人或其法定代理人、近亲属另行提起民事诉讼的，有管辖权的人民法院应当依法受理。"},{"i":9,"n":"第九条","txt":"被害人请求保护其民事权利的诉讼时效在公安机关、检察机关查处经济犯罪嫌疑期间中断。如果公安机关决定撤销涉嫌经济犯罪案件或者检察机关决定不起诉的，诉讼时效从撤销案件或决定不起诉之次日起重新计算。"},{"i":10,"n":"第十条","txt":"人民法院在审理经济纠纷案件中，发现与本案有牵连，但与本案不是同一法律关系的经济犯罪嫌疑线索、材料，应将犯罪嫌疑线索、材料移送有关公安机关或检察机关查处，经济纠纷案件继续审理。"},{"i":11,"n":"第十一条","txt":"人民法院作为经济纠纷受理的案件，经审理认为不属经济纠纷案件而有经济犯罪嫌疑的，应当裁定驳回起诉，将有关材料移送公安机关或检察机关。"},{"i":12,"n":"第十二条","txt":"人民法院已立案审理的经济纠纷案件，公安机关或检察机关认为有经济犯罪嫌疑，并说明理由附有关材料函告受理该案的人民法院的，有关人民法院应当认真审查。经过审查，认为确有经济犯罪嫌疑的，应当将案件移送公安机关或检察机关，并书面通知当事人，退还案件受理费；如认为确属经济纠纷案件的，应当依法继续审理，并将结果函告有关公安机关或检察机关。"}],"zuigaorenminfayuanguanyuweituozhixingruoganwentide14ef1f":[{"i":1,"n":"第一条","txt":"执行法院经调查发现被执行人在本辖区内已无财产可供执行，且在其他省、自治区、直辖市内有可供执行财产的，可以将案件委托异地的同级人民法院执行。"},{"i":2,"n":"第二条","txt":"案件委托执行后，受托法院应当依法立案，委托法院应当在收到受托法院的立案通知书后作销案处理。"},{"i":3,"n":"第三条","txt":"委托执行应当以执行标的物所在地或者执行行为实施地的同级人民法院为受托执行法院。有两处以上财产在异地的，可以委托主要财产所在地的人民法院执行。"},{"i":4,"n":"第四条","txt":"委托执行案件应当由委托法院直接向受托法院办理委托手续，并层报各自所在的高级人民法院备案。"},{"i":5,"n":"第五条","txt":"案件委托执行时，委托法院应当提供下列材料："},{"i":6,"n":"第六条","txt":"委托执行时，委托法院应当将已经查封、扣押、冻结的被执行人的异地财产，一并移交受托法院处理，并在委托执行函中说明。"},{"i":7,"n":"第七条","txt":"受托法院收到委托执行函后，应当在7日内予以立案，并及时将立案通知书通过委托法院送达申请执行人，同时将指定的承办人、联系电话等书面告知委托法院。"},{"i":8,"n":"第八条","txt":"受托法院如发现委托执行的手续、材料不全，可以要求委托法院补办。委托法院应当在30日内完成补办事项，在上述期限内未完成的，应当作出书面说明。委托法院既不补办又不说明原因的，视为撤回委托，受托法院可以将委托材料退回委托法院。"},{"i":9,"n":"第九条","txt":"受托法院退回委托的，应当层报所在辖区高级人民法院审批。高级人民法院同意退回后，受托法院应当在15日内将有关委托手续和案卷材料退回委托法院，并作出书面说明。"},{"i":10,"n":"第十条","txt":"委托法院在案件委托执行后又发现有可供执行财产的，应当及时告知受托法院。受托法院发现被执行人在受托法院辖区外另有可供执行财产的，可以直接异地执行，一般不再行委托执行。根据情况确需再行委托的，应当按照委托执行案件的程序办理，并通知案件当事人。"},{"i":11,"n":"第十一条","txt":"受托法院未能在6个月内将受托案件执结的，申请执行人有权请求受托法院的上一级人民法院提级执行或者指定执行，上一级人民法院应当立案审查，发现受托法院无正当理由不予执行的，应当限期执行或者作出裁定提级执行或者指定执行。"},{"i":12,"n":"第十二条","txt":"异地执行时，可以根据案件具体情况，请求当地法院协助执行，当地法院应当积极配合，保证执行人员的人身安全和执行装备、执行标的物不受侵害。"},{"i":13,"n":"第十三条","txt":"高级人民法院应当对辖区内委托执行和异地执行工作实行统一管理和协调，履行以下职责："},{"i":14,"n":"第十四条","txt":"本规定所称的异地是指本省、自治区、直辖市以外的区域。各省、自治区、直辖市内的委托执行，由各高级人民法院参照本规定，结合实际情况，制定具体办法。"},{"i":15,"n":"第十五条","txt":"本规定施行之后，其他有关委托执行的司法解释不再适用。"}],"zuigaorenminfayuanguanyushenpanrenyuanzaisusonghuo48f101":[{"i":1,"n":"第一条","txt":"审判人员具有下列情形之一的，应当自行回避，当事人及其法定代理人有权以口头或者书面形式申请其回避："},{"i":2,"n":"第二条","txt":"当事人及其法定代理人发现审判人员违反规定，具有下列情形之一的，有权申请其回避："},{"i":3,"n":"第三条","txt":"凡在一个审判程序中参与过本案审判工作的审判人员，不得再参与该案其他程序的审判。但是，经过第二审程序发回重审的案件，在一审法院作出裁判后又进入第二审程序的，原第二审程序中合议庭组成人员不受本条规定的限制。"},{"i":4,"n":"第四条","txt":"审判人员应当回避，本人没有自行回避，当事人及其法定代理人也没有申请其回避的，院长或者审判委员会应当决定其回避。"},{"i":5,"n":"第五条","txt":"人民法院应当依法告知当事人及其法定代理人有申请回避的权利，以及合议庭组成人员、书记员的姓名、职务等相关信息。"},{"i":6,"n":"第六条","txt":"人民法院依法调解案件，应当告知当事人及其法定代理人有申请回避的权利，以及主持调解工作的审判人员及其他参与调解工作的人员的姓名、职务等相关信息。"},{"i":7,"n":"第七条","txt":"第二审人民法院认为第一审人民法院的审理有违反本规定第一条至第三条规定的，应当裁定撤销原判，发回原审人民法院重新审判。"},{"i":8,"n":"第八条","txt":"审判人员及法院其他工作人员从人民法院离任后二年内，不得以律师身份担任诉讼代理人或者辩护人。"},{"i":9,"n":"第九条","txt":"审判人员及法院其他工作人员的配偶、子女或者父母不得担任其所任职法院审理案件的诉讼代理人或者辩护人。"},{"i":10,"n":"第十条","txt":"人民法院发现诉讼代理人或者辩护人违反本规定第八条、第九条的规定的，应当责令其停止相关诉讼代理或者辩护行为。"},{"i":11,"n":"第十一条","txt":"当事人及其法定代理人、诉讼代理人、辩护人认为审判人员有违反本规定行为的，可以向法院纪检、监察部门或者其他有关部门举报。受理举报的人民法院应当及时处理，并将相关意见反馈给举报人。"},{"i":12,"n":"第十二条","txt":"对明知具有本规定第一条至第三条规定情形不依法自行回避的审判人员，依照《人民法院工作人员处分条例》的规定予以处分。"},{"i":13,"n":"第十三条","txt":"本规定所称审判人员，包括各级人民法院院长、副院长、审判委员会委员、庭长、副庭长、审判员和助理审判员。"},{"i":14,"n":"第十四条","txt":"人民陪审员、书记员和执行员适用审判人员回避的有关规定，但不属于本规定第十三条所规定人员的，不适用本规定第八条、第九条的规定。"},{"i":15,"n":"第十五条","txt":"自本规定施行之日起，《最高人民法院关于审判人员严格执行回避制度的若干规定》（法发〔2000〕5号）即行废止；本规定施行前本院发布的司法解释与本规定不一致的，以本规定为准。"}],"zuigaorenminfayuanguanyushenchazhishichanquanjiufeac73e9":[{"i":1,"n":"第一条","txt":"本规定中的知识产权纠纷是指《民事案件案由规定》中的知识产权与竞争纠纷。"},{"i":2,"n":"第二条","txt":"知识产权纠纷的当事人在判决、裁定或者仲裁裁决生效前，依据民事诉讼法第一百条、第一百零一条规定申请行为保全的，人民法院应当受理。"},{"i":3,"n":"第三条","txt":"申请诉前行为保全，应当向被申请人住所地具有相应知识产权纠纷管辖权的人民法院或者对案件具有管辖权的人民法院提出。"},{"i":4,"n":"第四条","txt":"向人民法院申请行为保全，应当递交申请书和相应证据。申请书应当载明下列事项："},{"i":5,"n":"第五条","txt":"人民法院裁定采取行为保全措施前，应当询问申请人和被申请人，但因情况紧急或者询问可能影响保全措施执行等情形除外。"},{"i":6,"n":"第六条","txt":"有下列情况之一，不立即采取行为保全措施即足以损害申请人利益的，应当认定属于民事诉讼法第一百条、第一百零一条规定的“情况紧急”："},{"i":7,"n":"第七条","txt":"人民法院审查行为保全申请，应当综合考量下列因素："},{"i":8,"n":"第八条","txt":"人民法院审查判断申请人请求保护的知识产权效力是否稳定，应当综合考量下列因素："},{"i":9,"n":"第九条","txt":"申请人以实用新型或者外观设计专利权为依据申请行为保全的，应当提交由国务院专利行政部门作出的检索报告、专利权评价报告或者专利复审委员会维持该专利权有效的决定。申请人无正当理由拒不提交的，人民法院应当裁定驳回其申请。"},{"i":10,"n":"第十条","txt":"在知识产权与不正当竞争纠纷行为保全案件中，有下列情形之一的，应当认定属于民事诉讼法第一百零一条规定的“难以弥补的损害”："},{"i":11,"n":"第十一条","txt":"申请人申请行为保全的，应当依法提供担保。"},{"i":12,"n":"第十二条","txt":"人民法院采取的行为保全措施，一般不因被申请人提供担保而解除，但是申请人同意的除外。"},{"i":13,"n":"第十三条","txt":"人民法院裁定采取行为保全措施的，应当根据申请人的请求或者案件具体情况等因素合理确定保全措施的期限。"},{"i":14,"n":"第十四条","txt":"当事人不服行为保全裁定申请复议的，人民法院应当在收到复议申请后十日内审查并作出裁定。"},{"i":15,"n":"第十五条","txt":"人民法院采取行为保全的方法和措施，依照执行程序相关规定处理。"},{"i":16,"n":"第十六条","txt":"有下列情形之一的，应当认定属于民事诉讼法第一百零五条规定的“申请有错误”："},{"i":17,"n":"第十七条","txt":"当事人申请解除行为保全措施，人民法院收到申请后经审查符合《最高人民法院关于适用〈中华人民共和国民事诉讼法〉的解释》第一百六十六条规定的情形的，应当在五日内裁定解除。"},{"i":18,"n":"第十八条","txt":"被申请人依据民事诉讼法第一百零五条规定提起赔偿诉讼，申请人申请诉前行为保全后没有起诉或者当事人约定仲裁的，由采取保全措施的人民法院管辖；申请人已经起诉的，由受理起诉的人民法院管辖。"},{"i":19,"n":"第十九条","txt":"申请人同时申请行为保全、财产保全或者证据保全的，人民法院应当依法分别审查不同类型保全申请是否符合条件，并作出裁定。"},{"i":20,"n":"第二十条","txt":"申请人申请行为保全，应当依照《诉讼费用交纳办法》关于申请采取行为保全措施的规定交纳申请费。"},{"i":21,"n":"第二十一条","txt":"本规定自2019年1月1日起施行。最高人民法院以前发布的相关司法解释与本规定不一致的，以本规定为准。"}],"zuigaorenminfayuanguanyushenliyuqiyegaizhixiangguac3e6e7":[{"i":1,"n":"第一条","txt":"人民法院受理以下平等民事主体间在企业产权制度改造中发生的民事纠纷案件："},{"i":2,"n":"第二条","txt":"当事人起诉符合本规定第一条所列情形，并符合民事诉讼法第一百一十九条规定的起诉条件的，人民法院应当予以受理。"},{"i":3,"n":"第三条","txt":"政府主管部门在对企业国有资产进行行政性调整、划转过程中发生的纠纷，当事人向人民法院提起民事诉讼的，人民法院不予受理。"},{"i":4,"n":"第四条","txt":"国有企业依公司法整体改造为国有独资有限责任公司的，原企业的债务，由改造后的有限责任公司承担。"},{"i":5,"n":"第五条","txt":"企业通过增资扩股或者转让部分产权，实现他人对企业的参股，将企业整体改造为有限责任公司或者股份有限公司的，原企业债务由改造后的新设公司承担。"},{"i":6,"n":"第六条","txt":"企业以其部分财产和相应债务与他人组建新公司，对所转移的债务债权人认可的，由新组建的公司承担民事责任；对所转移的债务未通知债权人或者虽通知债权人，而债权人不予认可的，由原企业承担民事责任。原企业无力偿还债务，债权人就此向新设公司主张债权的，新设公司在所接收的财产范围内与原企业承担连带民事责任。"},{"i":7,"n":"第七条","txt":"企业以其优质财产与他人组建新公司，而将债务留在原企业，债权人以新设公司和原企业作为共同被告提起诉讼主张债权的，新设公司应当在所接收的财产范围内与原企业共同承担连带责任。"},{"i":8,"n":"第八条","txt":"由企业职工买断企业产权，将原企业改造为股份合作制的，原企业的债务，由改造后的股份合作制企业承担。"},{"i":9,"n":"第九条","txt":"企业向其职工转让部分产权，由企业与职工共同组建股份合作制企业的，原企业的债务由改造后的股份合作制企业承担。"},{"i":10,"n":"第十条","txt":"企业通过其职工投资增资扩股，将原企业改造为股份合作制企业的，原企业的债务由改造后的股份合作制企业承担。"},{"i":11,"n":"第十一条","txt":"企业在进行股份合作制改造时，参照公司法的有关规定，公告通知了债权人。企业股份合作制改造后，债权人就原企业资产管理人（出资人）隐瞒或者遗漏的债务起诉股份合作制企业的，如债权人在公告期内申报过该债权，股份合作制企业在承担民事责任后，可再向原企业资产管理人（出资人）追偿。如债权人在公告期内未申报过该债权，则股份合作制企业不承担民事责任，人民法院可告知债权人另行起诉原企业资产管理人（出资人）。"},{"i":12,"n":"第十二条","txt":"债权人向分立后的企业主张债权，企业分立时对原企业的债务承担有约定，并经债权人认可的，按照当事人的约定处理；企业分立时对原企业债务承担没有约定或者约定不明，或者虽然有约定但债权人不予认可的，分立后的企业应当承担连带责任。"},{"i":13,"n":"第十三条","txt":"分立的企业在承担连带责任后，各分立的企业间对原企业债务承担有约定的，按照约定处理；没有约定或者约定不明的，根据企业分立时的资产比例分担。"},{"i":14,"n":"第十四条","txt":"债权人与债务人自愿达成债权转股权协议，且不违反法律和行政法规强制性规定的，人民法院在审理相关的民事纠纷案件中，应当确认债权转股权协议有效。"},{"i":15,"n":"第十五条","txt":"债务人以隐瞒企业资产或者虚列企业资产为手段，骗取债权人与其签订债权转股权协议，债权人在法定期间内行使撤销权的，人民法院应当予以支持。"},{"i":16,"n":"第十六条","txt":"部分债权人进行债权转股权的行为，不影响其他债权人向债务人主张债权。"},{"i":17,"n":"第十七条","txt":"以协议转让形式出售企业，企业出售合同未经有审批权的地方人民政府或其授权的职能部门审批的，人民法院在审理相关的民事纠纷案件时，应当确认该企业出售合同不生效。"},{"i":18,"n":"第十八条","txt":"企业出售中，当事人双方恶意串通，损害国家利益的，人民法院在审理相关的民事纠纷案件时，应当确认该企业出售行为无效。"},{"i":19,"n":"第十九条","txt":"企业出售中，出卖人实施的行为具有法律规定的撤销情形，买受人在法定期限内行使撤销权的，人民法院应当予以支持。"},{"i":20,"n":"第二十条","txt":"企业出售合同约定的履行期限届满，一方当事人拒不履行合同，或者未完全履行合同义务，致使合同目的不能实现，对方当事人要求解除合同并要求赔偿损失的，人民法院应当予以支持。"},{"i":21,"n":"第二十一条","txt":"企业出售合同约定的履行期限届满，一方当事人未完全履行合同义务，对方当事人要求继续履行合同并要求赔偿损失的，人民法院应当予以支持。双方当事人均未完全履行合同义务的，应当根据当事人的过错，确定各自应当承担的民事责任。"},{"i":22,"n":"第二十二条","txt":"企业出售时，出卖人对所售企业的资产负债状况、损益状况等重大事项未履行如实告知义务，影响企业出售价格，买受人就此向人民法院起诉主张补偿的，人民法院应当予以支持。"},{"i":23,"n":"第二十三条","txt":"企业出售合同被确认无效或者被撤销的，企业售出后买受人经营企业期间发生的经营盈亏，由买受人享有或者承担。"},{"i":24,"n":"第二十四条","txt":"企业售出后，买受人将所购企业资产纳入本企业或者将所购企业变更为所属分支机构的，所购企业的债务，由买受人承担。但买卖双方另有约定，并经债权人认可的除外。"},{"i":25,"n":"第二十五条","txt":"企业售出后，买受人将所购企业资产作价入股与他人重新组建新公司，所购企业法人予以注销的，对所购企业出售前的债务，买受人应当以其所有财产，包括在新组建公司中的股权承担民事责任。"},{"i":26,"n":"第二十六条","txt":"企业售出后，买受人将所购企业重新注册为新的企业法人，所购企业法人被注销的，所购企业出售前的债务，应当由新注册的企业法人承担。但买卖双方另有约定，并经债权人认可的除外。"},{"i":27,"n":"第二十七条","txt":"企业售出后，应当办理而未办理企业法人注销登记，债权人起诉该企业的，人民法院应当根据企业资产转让后的具体情况，告知债权人追加责任主体，并判令责任主体承担民事责任。"},{"i":28,"n":"第二十八条","txt":"出售企业时，参照公司法的有关规定，出卖人公告通知了债权人。企业售出后，债权人就出卖人隐瞒或者遗漏的原企业债务起诉买受人的，如债权人在公告期内申报过该债权，买受人在承担民事责任后，可再行向出卖人追偿。如债权人在公告期内未申报过该债权，则买受人不承担民事责任。人民法院可告知债权人另行起诉出卖人。"},{"i":29,"n":"第二十九条","txt":"出售企业的行为具有民法典第五百三十八条、第五百三十九条规定的情形，债权人在法定期限内行使撤销权的，人民法院应当予以支持。"},{"i":30,"n":"第三十条","txt":"企业兼并协议自当事人签字盖章之日起生效。需经政府主管部门批准的，兼并协议自批准之日起生效；未经批准的，企业兼并协议不生效。但当事人在一审法庭辩论终结前补办报批手续的，人民法院应当确认该兼并协议有效。"},{"i":31,"n":"第三十一条","txt":"企业吸收合并后，被兼并企业的债务应当由兼并方承担。"},{"i":32,"n":"第三十二条","txt":"企业新设合并后，被兼并企业的债务由新设合并后的企业法人承担。"},{"i":33,"n":"第三十三条","txt":"企业吸收合并或新设合并后，被兼并企业应当办理而未办理工商注销登记，债权人起诉被兼并企业的，人民法院应当根据企业兼并后的具体情况，告知债权人追加责任主体，并判令责任主体承担民事责任。"},{"i":34,"n":"第三十四条","txt":"以收购方式实现对企业控股的，被控股企业的债务，仍由其自行承担。但因控股企业抽逃资金、逃避债务，致被控股企业无力偿还债务的，被控股企业的债务则由控股企业承担。"},{"i":35,"n":"第三十五条","txt":"本规定自二〇〇三年二月一日起施行。在本规定施行前，本院制定的有关企业改制方面的司法解释与本规定相抵触的，不再适用。"}],"zuigaorenminfayuanguanyushenlizhuanlishouquanquequc6e711":[{"i":1,"n":"第一条","txt":"本规定所称专利授权行政案件，是指专利申请人因不服国务院专利行政部门作出的专利复审请求审查决定，向人民法院提起诉讼的案件。"},{"i":2,"n":"第二条","txt":"人民法院应当以所属技术领域的技术人员在阅读权利要求书、说明书及附图后所理解的通常含义，界定权利要求的用语。权利要求的用语在说明书及附图中有明确定义或者说明的，按照其界定。"},{"i":3,"n":"第三条","txt":"人民法院在专利确权行政案件中界定权利要求的用语时，可以参考已被专利侵权民事案件生效裁判采纳的专利权人的相关陈述。"},{"i":4,"n":"第四条","txt":"权利要求书、说明书及附图中的语法、文字、数字、标点、图形、符号等有明显错误或者歧义，但所属技术领域的技术人员通过阅读权利要求书、说明书及附图可以得出唯一理解的，人民法院应当根据该唯一理解作出认定。"},{"i":5,"n":"第五条","txt":"当事人有证据证明专利申请人、专利权人违反诚实信用原则，虚构、编造说明书及附图中的具体实施方式、技术效果以及数据、图表等有关技术内容，并据此主张相关权利要求不符合专利法有关规定的，人民法院应予支持。"},{"i":6,"n":"第六条","txt":"说明书未充分公开特定技术内容，导致在专利申请日有下列情形之一的，人民法院应当认定说明书及与该特定技术内容相关的权利要求不符合专利法第二十六条第三款的规定："},{"i":7,"n":"第七条","txt":"所属技术领域的技术人员根据说明书及附图，认为权利要求有下列情形之一的，人民法院应当认定该权利要求不符合专利法第二十六条第四款关于清楚地限定要求专利保护的范围的规定："},{"i":8,"n":"第八条","txt":"所属技术领域的技术人员阅读说明书及附图后，在申请日不能得到或者合理概括得出权利要求限定的技术方案的，人民法院应当认定该权利要求不符合专利法第二十六条第四款关于“权利要求书应当以说明书为依据”的规定。"},{"i":9,"n":"第九条","txt":"以功能或者效果限定的技术特征，是指对于结构、组分、步骤、条件等技术特征或者技术特征之间的相互关系等，仅通过其在发明创造中所起的功能或者效果进行限定的技术特征，但所属技术领域的技术人员通过阅读权利要求即可直接、明确地确定实现该功能或者效果的具体实施方式的除外。"},{"i":10,"n":"第十条","txt":"药品专利申请人在申请日以后提交补充实验数据，主张依赖该数据证明专利申请符合专利法第二十二条第三款、第二十六条第三款等规定的，人民法院应予审查。"},{"i":11,"n":"第十一条","txt":"当事人对实验数据的真实性产生争议的，提交实验数据的一方当事人应当举证证明实验数据的来源和形成过程。人民法院可以通知实验负责人到庭，就实验原料、步骤、条件、环境或者参数以及完成实验的人员、机构等作出说明。"},{"i":12,"n":"第十二条","txt":"人民法院确定权利要求限定的技术方案的技术领域，应当综合考虑主题名称等权利要求的全部内容、说明书关于技术领域和背景技术的记载，以及该技术方案所实现的功能和用途等。"},{"i":13,"n":"第十三条","txt":"说明书及附图未明确记载区别技术特征在权利要求限定的技术方案中所能达到的技术效果的，人民法院可以结合所属技术领域的公知常识，根据区别技术特征与权利要求中其他技术特征的关系，区别技术特征在权利要求限定的技术方案中的作用等，认定所属技术领域的技术人员所能确定的该权利要求实际解决的技术问题。"},{"i":14,"n":"第十四条","txt":"人民法院认定外观设计专利产品的一般消费者所具有的知识水平和认知能力，应当考虑申请日时外观设计专利产品的设计空间。设计空间较大的，人民法院可以认定一般消费者通常不容易注意到不同设计之间的较小区别；设计空间较小的，人民法院可以认定一般消费者通常更容易注意到不同设计之间的较小区别。"},{"i":15,"n":"第十五条","txt":"外观设计的图片、照片存在矛盾、缺失或者模糊不清等情形，导致一般消费者无法根据图片、照片及简要说明确定所要保护的外观设计的，人民法院应当认定其不符合专利法第二十七条第二款关于“清楚地显示要求专利保护的产品的外观设计”的规定。"},{"i":16,"n":"第十六条","txt":"人民法院认定外观设计是否符合专利法第二十三条的规定，应当综合判断外观设计的整体视觉效果。"},{"i":17,"n":"第十七条","txt":"外观设计与相同或者相近种类产品的一项现有设计相比，整体视觉效果相同或者属于仅具有局部细微区别等实质相同的情形的，人民法院应当认定其构成专利法第二十三条第一款规定的“属于现有设计”。"},{"i":18,"n":"第十八条","txt":"外观设计专利与相同种类产品上同日申请的另一项外观设计专利相比，整体视觉效果相同或者属于仅具有局部细微区别等实质相同的情形的，人民法院应当认定其不符合专利法第九条关于“同样的发明创造只能授予一项专利权”的规定。"},{"i":19,"n":"第十九条","txt":"外观设计与申请日以前提出申请、申请日以后公告，且属于相同或者相近种类产品的另一项外观设计相比，整体视觉效果相同或者属于仅具有局部细微区别等实质相同的情形的，人民法院应当认定其构成专利法第二十三条第一款规定的“同样的外观设计”。"},{"i":20,"n":"第二十条","txt":"根据现有设计整体上给出的设计启示，以一般消费者容易想到的设计特征转用、拼合或者替换等方式，获得与外观设计专利的整体视觉效果相同或者仅具有局部细微区别等实质相同的外观设计，且不具有独特视觉效果的，人民法院应当认定该外观设计专利与现有设计特征的组合相比不具有专利法第二十三条第二款规定的“明显区别”。"},{"i":21,"n":"第二十一条","txt":"人民法院在认定本规定第二十条所称的独特视觉效果时，可以综合考虑下列因素："},{"i":22,"n":"第二十二条","txt":"专利法第二十三条第三款所称的“合法权利”，包括就作品、商标、地理标志、姓名、企业名称、肖像，以及有一定影响的商品名称、包装、装潢等享有的合法权利或者权益。"},{"i":23,"n":"第二十三条","txt":"当事人主张专利复审、无效宣告请求审查程序中的下列情形属于行政诉讼法第七十条第三项规定的“违反法定程序的”，人民法院应予支持："},{"i":24,"n":"第二十四条","txt":"被诉决定有下列情形之一的，人民法院可以依照行政诉讼法第七十条的规定，判决部分撤销："},{"i":25,"n":"第二十五条","txt":"被诉决定对当事人主张的全部无效理由和证据均已评述并宣告权利要求无效，人民法院认为被诉决定认定该权利要求无效的理由均不能成立的，应当判决撤销或者部分撤销该决定，并可视情判决被告就该权利要求重新作出审查决定。"},{"i":26,"n":"第二十六条","txt":"审查决定系直接依据生效裁判重新作出且未引入新的事实和理由，当事人对该决定提起诉讼的，人民法院依法裁定不予受理；已经受理的，依法裁定驳回起诉。"},{"i":27,"n":"第二十七条","txt":"被诉决定查明事实或者适用法律确有不当，但对专利授权确权的认定结论正确的，人民法院可以在纠正相关事实查明和法律适用的基础上判决驳回原告的诉讼请求。"},{"i":28,"n":"第二十八条","txt":"当事人主张有关技术内容属于公知常识或者有关设计特征属于惯常设计的，人民法院可以要求其提供证据证明或者作出说明。"},{"i":29,"n":"第二十九条","txt":"专利申请人、专利权人在专利授权确权行政案件中提供新的证据，用于证明专利申请不应当被驳回或者专利权应当维持有效的，人民法院一般应予审查。"},{"i":30,"n":"第三十条","txt":"无效宣告请求人在专利确权行政案件中提供新的证据，人民法院一般不予审查，但下列证据除外："},{"i":31,"n":"第三十一条","txt":"人民法院可以要求当事人提供本规定第二十九条、第三十条规定的新的证据。"},{"i":32,"n":"第三十二条","txt":"本规定自2020年9月12日起施行。"}],"zuigaorenminfayuanguanyushenlizhuanlijiufenanjiansabb4f3":[{"i":1,"n":"第一条","txt":"人民法院受理下列专利纠纷案件："},{"i":2,"n":"第二条","txt":"因侵犯专利权行为提起的诉讼，由侵权行为地或者被告住所地人民法院管辖。"},{"i":3,"n":"第三条","txt":"原告仅对侵权产品制造者提起诉讼，未起诉销售者，侵权产品制造地与销售地不一致的，制造地人民法院有管辖权；以制造者与销售者为共同被告起诉的，销售地人民法院有管辖权。"},{"i":4,"n":"第四条","txt":"对申请日在2009年10月1日前（不含该日）的实用新型专利提起侵犯专利权诉讼，原告可以出具由国务院专利行政部门作出的检索报告；对申请日在2009年10月1日以后的实用新型或者外观设计专利提起侵犯专利权诉讼，原告可以出具由国务院专利行政部门作出的专利权评价报告。根据案件审理需要，人民法院可以要求原告提交检索报告或者专利权评价报告。原告无正当理由不提交的，人民法院可以裁定中止诉讼或者判令原告承担可能的不利后果。"},{"i":5,"n":"第五条","txt":"人民法院受理的侵犯实用新型、外观设计专利权纠纷案件，被告在答辩期间内请求宣告该项专利权无效的，人民法院应当中止诉讼，但具备下列情形之一的，可以不中止诉讼："},{"i":6,"n":"第六条","txt":"人民法院受理的侵犯实用新型、外观设计专利权纠纷案件，被告在答辩期间届满后请求宣告该项专利权无效的，人民法院不应当中止诉讼，但经审查认为有必要中止诉讼的除外。"},{"i":7,"n":"第七条","txt":"人民法院受理的侵犯发明专利权纠纷案件或者经国务院专利行政部门审查维持专利权的侵犯实用新型、外观设计专利权纠纷案件，被告在答辩期间内请求宣告该项专利权无效的，人民法院可以不中止诉讼。"},{"i":8,"n":"第八条","txt":"人民法院决定中止诉讼，专利权人或者利害关系人请求责令被告停止有关行为或者采取其他制止侵权损害继续扩大的措施，并提供了担保，人民法院经审查符合有关法律规定的，可以在裁定中止诉讼的同时一并作出有关裁定。"},{"i":9,"n":"第九条","txt":"人民法院对专利权进行财产保全，应当向国务院专利行政部门发出协助执行通知书，载明要求协助执行的事项，以及对专利权保全的期限，并附人民法院作出的裁定书。"},{"i":10,"n":"第十条","txt":"2001年7月1日以前利用本单位的物质技术条件所完成的发明创造，单位与发明人或者设计人订有合同，对申请专利的权利和专利权的归属作出约定的，从其约定。"},{"i":11,"n":"第十一条","txt":"人民法院受理的侵犯专利权纠纷案件，涉及权利冲突的，应当保护在先依法享有权利的当事人的合法权益。"},{"i":12,"n":"第十二条","txt":"专利法第二十三条第三款所称的合法权利，包括就作品、商标、地理标志、姓名、企业名称、肖像，以及有一定影响的商品名称、包装、装潢等享有的合法权利或者权益。"},{"i":13,"n":"第十三条","txt":"专利法第五十九条第一款所称的“发明或者实用新型专利权的保护范围以其权利要求的内容为准，说明书及附图可以用于解释权利要求的内容”，是指专利权的保护范围应当以权利要求记载的全部技术特征所确定的范围为准，也包括与该技术特征相等同的特征所确定的范围。"},{"i":14,"n":"第十四条","txt":"专利法第六十五条规定的权利人因被侵权所受到的实际损失可以根据专利权人的专利产品因侵权所造成销售量减少的总数乘以每件专利产品的合理利润所得之积计算。权利人销售量减少的总数难以确定的，侵权产品在市场上销售的总数乘以每件专利产品的合理利润所得之积可以视为权利人因被侵权所受到的实际损失。"},{"i":15,"n":"第十五条","txt":"权利人的损失或者侵权人获得的利益难以确定，有专利许可使用费可以参照的，人民法院可以根据专利权的类型、侵权行为的性质和情节、专利许可的性质、范围、时间等因素，参照该专利许可使用费的倍数合理确定赔偿数额；没有专利许可使用费可以参照或者专利许可使用费明显不合理的，人民法院可以根据专利权的类型、侵权行为的性质和情节等因素，依照专利法第六十五条第二款的规定确定赔偿数额。"},{"i":16,"n":"第十六条","txt":"权利人主张其为制止侵权行为所支付合理开支的，人民法院可以在专利法第六十五条确定的赔偿数额之外另行计算。"},{"i":17,"n":"第十七条","txt":"侵犯专利权的诉讼时效为三年，自专利权人或者利害关系人知道或者应当知道权利受到损害以及义务人之日起计算。权利人超过三年起诉的，如果侵权行为在起诉时仍在继续，在该项专利权有效期内，人民法院应当判决被告停止侵权行为，侵权损害赔偿数额应当自权利人向人民法院起诉之日起向前推算三年计算。"},{"i":18,"n":"第十八条","txt":"专利法第十一条、第六十九条所称的许诺销售，是指以做广告、在商店橱窗中陈列或者在展销会上展出等方式作出销售商品的意思表示。"},{"i":19,"n":"第十九条","txt":"人民法院受理的侵犯专利权纠纷案件，已经过管理专利工作的部门作出侵权或者不侵权认定的，人民法院仍应当就当事人的诉讼请求进行全面审查。"},{"i":20,"n":"第二十条","txt":"以前的有关司法解释与本规定不一致的，以本规定为准。"}],"zuigaorenminfayuanguanyushenlirenminjianchayuananzf0ffc1":[{"i":1,"n":"第一条","txt":"人民法院收到人民检察院的抗诉书后，应在一个月内立案。经审查，具有下列情形之一的，应当决定退回人民检察院："},{"i":2,"n":"第二条","txt":"人民检察院按照审判监督程序提出的刑事抗诉案件，接受抗诉的人民法院应当组成合议庭进行审理。涉及新证据需要指令下级人民法院再审的，接受抗诉的人民法院应当在接受抗诉之日起一个月以内作出决定，并将指令再审决定书送达提出抗诉的人民检察院。"},{"i":3,"n":"第三条","txt":"本规定所指的新证据，是指具有下列情形之一，指向原起诉事实并可能改变原判决、裁定据以定罪量刑的事实的证据："},{"i":4,"n":"第四条","txt":"对于原判决、裁定事实不清或者证据不足的案件，接受抗诉的人民法院进行重新审理后，应当按照下列情形分别处理："},{"i":5,"n":"第五条","txt":"对于指令再审的案件，如果原来是第一审案件，接受抗诉的人民法院应当指令第一审人民法院依照第一审程序进行审判，所作的判决、裁定，可以上诉、抗诉；如果原来是第二审案件，接受抗诉的人民法院应当指令第二审人民法院依照第二审程序进行审判，所作的判决、裁定，是终审的判决、裁定。"},{"i":6,"n":"第六条","txt":"在开庭审理前，人民检察院撤回抗诉的，人民法院应当裁定准许。"},{"i":7,"n":"第七条","txt":"在送达抗诉书后被提出抗诉的原审被告人未到案的，人民法院应当裁定中止审理；原审被告人到案后，恢复审理。"},{"i":8,"n":"第八条","txt":"被提出抗诉的原审被告人已经死亡或者在审理过程中死亡的，人民法院应当裁定终止审理，但对能够查清事实，确认原审被告人无罪的案件，应当予以改判。"},{"i":9,"n":"第九条","txt":"人民法院作出裁判后，当庭宣告判决的，应当在五日内将裁判文书送达当事人、法定代理人、诉讼代理人、提出抗诉的人民检察院、辩护人和原审被告人的近亲属；定期宣告判决的，应当在判决宣告后立即将裁判文书送达当事人、法定代理人、诉讼代理人、提出抗诉的人民检察院、辩护人和原审被告人的近亲属。"},{"i":10,"n":"第十条","txt":"以前发布的有关规定与本规定不一致的，以本规定为准。"}],"zuigaorenminfayuanguanyushenlizhongcaisifashenchaabf64f7":[{"i":1,"n":"第一条","txt":"本规定所称仲裁司法审查案件，包括下列案件："},{"i":2,"n":"第二条","txt":"申请确认仲裁协议效力的案件，由仲裁协议约定的仲裁机构所在地、仲裁协议签订地、申请人住所地、被申请人住所地的中级人民法院或者专门人民法院管辖。"},{"i":3,"n":"第三条","txt":"外国仲裁裁决与人民法院审理的案件存在关联，被申请人住所地、被申请人财产所在地均不在我国内地，申请人申请承认外国仲裁裁决的，由受理关联案件的人民法院管辖。受理关联案件的人民法院为基层人民法院的，申请承认外国仲裁裁决的案件应当由该基层人民法院的上一级人民法院管辖。受理关联案件的人民法院是高级人民法院或者最高人民法院的，由上述法院决定自行审查或者指定中级人民法院审查。"},{"i":4,"n":"第四条","txt":"申请人向两个以上有管辖权的人民法院提出申请的，由最先立案的人民法院管辖。"},{"i":5,"n":"第五条","txt":"申请人向人民法院申请确认仲裁协议效力的，应当提交申请书及仲裁协议正本或者经证明无误的副本。"},{"i":6,"n":"第六条","txt":"申请人向人民法院申请执行或者撤销我国内地仲裁机构的仲裁裁决、申请承认和执行外国仲裁裁决的，应当提交申请书及裁决书正本或者经证明无误的副本。"},{"i":7,"n":"第七条","txt":"申请人提交的文件不符合第五条、第六条的规定，经人民法院释明后提交的文件仍然不符合规定的，裁定不予受理。"},{"i":8,"n":"第八条","txt":"人民法院立案后发现不符合受理条件的，裁定驳回申请。"},{"i":9,"n":"第九条","txt":"对于申请人的申请，人民法院应当在七日内审查决定是否受理。"},{"i":10,"n":"第十条","txt":"人民法院受理仲裁司法审查案件后，被申请人对管辖权有异议的，应当自收到人民法院通知之日起十五日内提出。人民法院对被申请人提出的异议，应当审查并作出裁定。当事人对裁定不服的，可以提起上诉。"},{"i":11,"n":"第十一条","txt":"人民法院审查仲裁司法审查案件，应当组成合议庭并询问当事人。"},{"i":12,"n":"第十二条","txt":"仲裁协议或者仲裁裁决具有《最高人民法院关于适用〈中华人民共和国涉外民事关系法律适用法〉若干问题的解释（一）》第一条规定情形的，为涉外仲裁协议或者涉外仲裁裁决。"},{"i":13,"n":"第十三条","txt":"当事人协议选择确认涉外仲裁协议效力适用的法律，应当作出明确的意思表示，仅约定合同适用的法律，不能作为确认合同中仲裁条款效力适用的法律。"},{"i":14,"n":"第十四条","txt":"人民法院根据《中华人民共和国涉外民事关系法律适用法》第十八条的规定，确定确认涉外仲裁协议效力适用的法律时，当事人没有选择适用的法律，适用仲裁机构所在地的法律与适用仲裁地的法律将对仲裁协议的效力作出不同认定的，人民法院应当适用确认仲裁协议有效的法律。"},{"i":15,"n":"第十五条","txt":"仲裁协议未约定仲裁机构和仲裁地，但根据仲裁协议约定适用的仲裁规则可以确定仲裁机构或者仲裁地的，应当认定其为《中华人民共和国涉外民事关系法律适用法》第十八条中规定的仲裁机构或者仲裁地。"},{"i":16,"n":"第十六条","txt":"人民法院适用《承认及执行外国仲裁裁决公约》审查当事人申请承认和执行外国仲裁裁决案件时，被申请人以仲裁协议无效为由提出抗辩的，人民法院应当依照该公约第五条第一款（甲）项的规定，确定确认仲裁协议效力应当适用的法律。"},{"i":17,"n":"第十七条","txt":"人民法院对申请执行我国内地仲裁机构作出的非涉外仲裁裁决案件的审查，适用《中华人民共和国民事诉讼法》第二百三十七条的规定。"},{"i":18,"n":"第十八条","txt":"《中华人民共和国仲裁法》第五十八条第一款第六项和《中华人民共和国民事诉讼法》第二百三十七条第二款第六项规定的仲裁员在仲裁该案时有索贿受贿，徇私舞弊，枉法裁决行为，是指已经由生效刑事法律文书或者纪律处分决定所确认的行为。"},{"i":19,"n":"第十九条","txt":"人民法院受理仲裁司法审查案件后，作出裁定前，申请人请求撤回申请的，裁定准许。"},{"i":20,"n":"第二十条","txt":"人民法院在仲裁司法审查案件中作出的裁定，除不予受理、驳回申请、管辖权异议的裁定外，一经送达即发生法律效力。当事人申请复议、提出上诉或者申请再审的，人民法院不予受理，但法律和司法解释另有规定的除外。"},{"i":21,"n":"第二十一条","txt":"人民法院受理的申请确认涉及香港特别行政区、澳门特别行政区、台湾地区仲裁协议效力的案件，申请执行或者撤销我国内地仲裁机构作出的涉及香港特别行政区、澳门特别行政区、台湾地区仲裁裁决的案件，参照适用涉外仲裁司法审查案件的规定审查。"},{"i":22,"n":"第二十二条","txt":"本规定自2018年1月1日起施行，本院以前发布的司法解释与本规定不一致的，以本规定为准。"}],"zuigaorenminfayuanguanyushenliqiyepochananjianzhidaef767":[{"i":1,"n":"第一条","txt":"人民法院审理企业破产案件应当指定管理人。除企业破产法和本规定另有规定外，管理人应当从管理人名册中指定。"},{"i":2,"n":"第二条","txt":"高级人民法院应当根据本辖区律师事务所、会计师事务所、破产清算事务所等社会中介机构及专职从业人员数量和企业破产案件数量，确定由本院或者所辖中级人民法院编制管理人名册。"},{"i":3,"n":"第三条","txt":"符合企业破产法规定条件的社会中介机构及其具备相关专业知识并取得执业资格的人员，均可申请编入管理人名册。已被编入机构管理人名册的社会中介机构中，具备相关专业知识并取得执业资格的人员，可以申请编入个人管理人名册。"},{"i":4,"n":"第四条","txt":"社会中介机构及个人申请编入管理人名册的，应当向所在地区编制管理人名册的人民法院提出，由该人民法院予以审定。"},{"i":5,"n":"第五条","txt":"人民法院应当通过本辖区有影响的媒体就编制管理人名册的有关事项进行公告。公告应当包括以下内容："},{"i":6,"n":"第六条","txt":"律师事务所、会计师事务所申请编入管理人名册的，应当提供下列材料："},{"i":7,"n":"第七条","txt":"破产清算事务所申请编入管理人名册的，应当提供以下材料："},{"i":8,"n":"第八条","txt":"个人申请编入管理人名册的，应当提供下列材料："},{"i":9,"n":"第九条","txt":"社会中介机构及个人具有下列情形之一的，人民法院可以适用企业破产法第二十四条第三款第四项的规定："},{"i":10,"n":"第十条","txt":"编制管理人名册的人民法院应当组成专门的评审委员会，决定编入管理人名册的社会中介机构和个人名单。评审委员会成员应不少于七人。"},{"i":11,"n":"第十一条","txt":"人民法院应当将管理人初审名册通过本辖区有影响的媒体进行公示，公示期为十日。"},{"i":12,"n":"第十二条","txt":"公示期满后，人民法院应审定管理人名册，并通过全国有影响的媒体公布，同时逐级报最高人民法院备案。"},{"i":13,"n":"第十三条","txt":"人民法院可以根据本辖区的实际情况，分批确定编入管理人名册的社会中介机构及个人。"},{"i":14,"n":"第十四条","txt":"人民法院可以根据企业破产案件受理情况、管理人履行职务以及管理人资格变化等因素，对管理人名册适时进行调整。新编入管理人名册的社会中介机构和个人应当按照本规定的程序办理。"},{"i":15,"n":"第十五条","txt":"受理企业破产案件的人民法院指定管理人，一般应从本地管理人名册中指定。"},{"i":16,"n":"第十六条","txt":"受理企业破产案件的人民法院，一般应指定管理人名册中的社会中介机构担任管理人。"},{"i":17,"n":"第十七条","txt":"对于事实清楚、债权债务关系简单、债务人财产相对集中的企业破产案件，人民法院可以指定管理人名册中的个人为管理人。"},{"i":18,"n":"第十八条","txt":"企业破产案件有下列情形之一的，人民法院可以指定清算组为管理人："},{"i":19,"n":"第十九条","txt":"清算组为管理人的，人民法院可以从政府有关部门、编入管理人名册的社会中介机构、金融资产管理公司中指定清算组成员，人民银行及金融监督管理机构可以按照有关法律和行政法规的规定派人参加清算组。"},{"i":20,"n":"第二十条","txt":"人民法院一般应当按照管理人名册所列名单采取轮候、抽签、摇号等随机方式公开指定管理人。"},{"i":21,"n":"第二十一条","txt":"对于商业银行、证券公司、保险公司等金融机构或者在全国范围有重大影响、法律关系复杂、债务人财产分散的企业破产案件，人民法院可以采取公告的方式，邀请编入各地人民法院管理人名册中的社会中介机构参与竞争，从参与竞争的社会中介机构中指定管理人。参与竞争的社会中介机构不得少于三家。"},{"i":22,"n":"第二十二条","txt":"对于经过行政清理、清算的商业银行、证券公司、保险公司等金融机构的破产案件，人民法院除可以按照本规定第十八条第一项的规定指定管理人外，也可以在金融监督管理机构推荐的已编入管理人名册的社会中介机构中指定管理人。"},{"i":23,"n":"第二十三条","txt":"社会中介机构、清算组成员有下列情形之一，可能影响其忠实履行管理人职责的，人民法院可以认定为企业破产法第二十四条第三款第三项规定的利害关系："},{"i":24,"n":"第二十四条","txt":"清算组成员的派出人员、社会中介机构的派出人员、个人管理人有下列情形之一，可能影响其忠实履行管理人职责的，可以认定为企业破产法第二十四条第三款第三项规定的利害关系："},{"i":25,"n":"第二十五条","txt":"在进入指定管理人程序后，社会中介机构或者个人发现与本案有利害关系的，应主动申请回避并向人民法院书面说明情况。人民法院认为社会中介机构或者个人与本案有利害关系的，不应指定该社会中介机构或者个人为本案管理人。"},{"i":26,"n":"第二十六条","txt":"社会中介机构或者个人有重大债务纠纷或者因涉嫌违法行为正被相关部门调查的，人民法院不应指定该社会中介机构或者个人为本案管理人。"},{"i":27,"n":"第二十七条","txt":"人民法院指定管理人应当制作决定书，并向被指定为管理人的社会中介机构或者个人、破产申请人、债务人、债务人的企业登记机关送达。决定书应与受理破产申请的民事裁定书一并公告。"},{"i":28,"n":"第二十八条","txt":"管理人无正当理由，不得拒绝人民法院的指定。"},{"i":29,"n":"第二十九条","txt":"管理人凭指定管理人决定书按照国家有关规定刻制管理人印章，并交人民法院封样备案后启用。"},{"i":30,"n":"第三十条","txt":"受理企业破产案件的人民法院应当将指定管理人过程中形成的材料存入企业破产案件卷宗，债权人会议或者债权人委员会有权查阅。"},{"i":31,"n":"第三十一条","txt":"债权人会议根据企业破产法第二十二条第二款的规定申请更换管理人的，应由债权人会议作出决议并向人民法院提出书面申请。"},{"i":32,"n":"第三十二条","txt":"人民法院认为申请理由不成立的，应当自收到管理人书面说明之日起十日内作出驳回申请的决定。"},{"i":33,"n":"第三十三条","txt":"社会中介机构管理人有下列情形之一的，人民法院可以根据债权人会议的申请或者依职权径行决定更换管理人："},{"i":34,"n":"第三十四条","txt":"个人管理人有下列情形之一的，人民法院可以根据债权人会议的申请或者依职权径行决定更换管理人："},{"i":35,"n":"第三十五条","txt":"管理人无正当理由申请辞去职务的，人民法院不予许可。正当理由的认定，可参照适用本规定第三十三条、第三十四条规定的情形。"},{"i":36,"n":"第三十六条","txt":"人民法院对管理人申请辞去职务未予许可，管理人仍坚持辞去职务并不再履行管理人职责的，人民法院应当决定更换管理人。"},{"i":37,"n":"第三十七条","txt":"人民法院决定更换管理人的，原管理人应当自收到决定书之次日起，在人民法院监督下向新任管理人移交全部资料、财产、营业事务及管理人印章，并及时向新任管理人书面说明工作进展情况。原管理人不能履行上述职责的，新任管理人可以直接接管相关事务。"},{"i":38,"n":"第三十八条","txt":"人民法院决定更换管理人的，应将决定书送达原管理人、新任管理人、破产申请人、债务人以及债务人的企业登记机关，并予公告。"},{"i":39,"n":"第三十九条","txt":"管理人申请辞去职务未获人民法院许可，但仍坚持辞职并不再履行管理人职责，或者人民法院决定更换管理人后，原管理人拒不向新任管理人移交相关事务，人民法院可以根据企业破产法第一百三十条的规定和具体情况，决定对管理人罚款。对社会中介机构为管理人的罚款5万元至20万元人民币，对个人为管理人的罚款1万元至5万元人民币。"},{"i":40,"n":"第四十条","txt":"管理人不服罚款决定的，可以向上一级人民法院申请复议，上级人民法院应在收到复议申请后五日内作出决定，并将复议结果通知下级人民法院和当事人。"}],"zuigaorenminfayuanguanyushenliqiyepochananjianqued51f017":[{"i":1,"n":"第一条","txt":"管理人履行企业破产法第二十五条规定的职责，有权获得相应报酬。"},{"i":2,"n":"第二条","txt":"人民法院应根据债务人最终清偿的财产价值总额，在以下比例限制范围内分段确定管理人报酬："},{"i":3,"n":"第三条","txt":"人民法院可以根据破产案件的实际情况，确定管理人分期或者最后一次性收取报酬。"},{"i":4,"n":"第四条","txt":"人民法院受理企业破产申请后，应当对债务人可供清偿的财产价值和管理人的工作量作出预测，初步确定管理人报酬方案。管理人报酬方案应当包括管理人报酬比例和收取时间。"},{"i":5,"n":"第五条","txt":"人民法院采取公开竞争方式指定管理人的，可以根据社会中介机构提出的报价确定管理人报酬方案，但报酬比例不得超出本规定第二条规定的限制范围。"},{"i":6,"n":"第六条","txt":"人民法院应当自确定管理人报酬方案之日起三日内，书面通知管理人。"},{"i":7,"n":"第七条","txt":"管理人、债权人会议对管理人报酬方案有意见的，可以进行协商。双方就调整管理人报酬方案内容协商一致的，管理人应向人民法院书面提出具体的请求和理由，并附相应的债权人会议决议。"},{"i":8,"n":"第八条","txt":"人民法院确定管理人报酬方案后，可以根据破产案件和管理人履行职责的实际情况进行调整。"},{"i":9,"n":"第九条","txt":"人民法院确定或者调整管理人报酬方案时，应当考虑以下因素："},{"i":10,"n":"第十条","txt":"最终确定的管理人报酬及收取情况，应列入破产财产分配方案。在和解、重整程序中，管理人报酬方案内容应列入和解协议草案或重整计划草案。"},{"i":11,"n":"第十一条","txt":"管理人收取报酬，应当向人民法院提出书面申请。申请书应当包括以下内容："},{"i":12,"n":"第十二条","txt":"管理人报酬从债务人财产中优先支付。"},{"i":13,"n":"第十三条","txt":"管理人对担保物的维护、变现、交付等管理工作付出合理劳动的，有权向担保权人收取适当的报酬。管理人与担保权人就上述报酬数额不能协商一致的，人民法院应当参照本规定第二条规定的方法确定，但报酬比例不得超出该条规定限制范围的10%。"},{"i":14,"n":"第十四条","txt":"律师事务所、会计师事务所通过聘请本专业的其他社会中介机构或者人员协助履行管理人职责的，所需费用从其报酬中支付。"},{"i":15,"n":"第十五条","txt":"清算组中有关政府部门派出的工作人员参与工作的不收取报酬。其他机构或人员的报酬根据其履行职责的情况确定。"},{"i":16,"n":"第十六条","txt":"管理人发生更换的，人民法院应当分别确定更换前后的管理人报酬。其报酬比例总和不得超出本规定第二条规定的限制范围。"},{"i":17,"n":"第十七条","txt":"债权人会议对管理人报酬有异议的，应当向人民法院书面提出具体的请求和理由。异议书应当附有相应的债权人会议决议。"},{"i":18,"n":"第十八条","txt":"人民法院应当自收到债权人会议异议书之日起三日内通知管理人。管理人应当自收到通知之日起三日内作出书面说明。"}],"zuigaorenminfayuanguanyushenliqiyepochananjianruogfe8521":[{"i":1,"n":"第一条","txt":"企业破产案件由债务人住所地人民法院管辖。债务人住所地指债务人的主要办事机构所在地。债务人无办事机构的，由其注册地人民法院管辖。"},{"i":2,"n":"第二条","txt":"基层人民法院一般管辖县、县级市或者区的工商行政管理机关核准登记企业的破产案件；"},{"i":3,"n":"第三条","txt":"上级人民法院审理下级人民法院管辖的企业破产案件，或者将本院管辖的企业破产案件移交下级人民法院审理，以及下级人民法院需要将自己管辖的企业破产案件交由上级人民法院审理的，依照民事诉讼法第三十九条的规定办理；省、自治区、直辖市范围内因特殊情况需对个别企业破产案件的地域管辖作调整的，须经共同上级人民法院批准。"},{"i":4,"n":"第四条","txt":"申请（被申请）破产的债务人应当具备法人资格，不具备法人资格的企业、个体工商户、合伙组织、农村承包经营户不具备破产主体资格。"},{"i":5,"n":"第五条","txt":"国有企业向人民法院申请破产时，应当提交其上级主管部门同意其破产的文件；其他企业应当提供其开办人或者股东会议决定企业破产的文件。"},{"i":6,"n":"第六条","txt":"债务人申请破产，应当向人民法院提交下列材料："},{"i":7,"n":"第七条","txt":"债权人申请债务人破产，应当向人民法院提交下列材料："},{"i":8,"n":"第八条","txt":"债权人申请债务人破产，人民法院可以通知债务人核对以下情况："},{"i":9,"n":"第九条","txt":"债权人申请债务人破产，债务人对债权人的债权提出异议，人民法院认为异议成立的，应当告知债权人先行提起民事诉讼。破产申请不予受理。"},{"i":10,"n":"第十条","txt":"人民法院收到破产申请后，应当在7日内决定是否立案；破产申请人提交的材料需要更正、补充的，人民法院可以责令申请人限期更正、补充。按期更正、补充材料的，人民法院自收到更正补充材料之日起7日内决定是否立案；未按期更正、补充的，视为撤回申请。"},{"i":11,"n":"第十一条","txt":"在人民法院决定受理企业破产案件前，破产申请人可以请求撤回破产申请。"},{"i":12,"n":"第十二条","txt":"人民法院经审查发现有下列情况的，破产申请不予受理："},{"i":13,"n":"第十三条","txt":"人民法院对破产申请不予受理的，应当作出裁定。"},{"i":14,"n":"第十四条","txt":"人民法院受理企业破产案件后，发现不符合法律规定的受理条件或者有本规定第十二条所列情形的，应当裁定驳回破产申请。"},{"i":15,"n":"第十五条","txt":"人民法院决定受理企业破产案件后，应当组成合议庭，并在10日内完成下列工作："},{"i":16,"n":"第十六条","txt":"人民法院受理债权人提出的企业破产案件后，应当通知债务人在15日内向人民法院提交有关会计报表、债权债务清册、企业资产清册以及人民法院认为应当提交的资料。"},{"i":17,"n":"第十七条","txt":"人民法院受理企业破产案件后，除应当按照企业破产法第九条的规定通知已知的债权人外，还应当于30日内在国家、地方有影响的报纸上刊登公告，公告内容同第十五条第（一）项的规定。"},{"i":18,"n":"第十八条","txt":"人民法院受理企业破产案件后，除可以随即进行破产宣告成立清算组的外，在企业原管理组织不能正常履行管理职责的情况下，可以成立企业监管组。企业监管组成员从企业上级主管部门或者股东会议代表、企业原管理人员、主要债权人中产生，也可以聘请会计师、律师等中介机构参加。企业监管组主要负责处理以下事务："},{"i":19,"n":"第十九条","txt":"人民法院受理企业破产案件后，以债务人为原告的其他民事纠纷案件尚在一审程序的，受诉人民法院应当将案件移送受理破产案件的人民法院；案件已进行到二审程序的，受诉人民法院应当继续审理。"},{"i":20,"n":"第二十条","txt":"人民法院受理企业破产案件后，对债务人财产的其他民事执行程序应当中止。"},{"i":21,"n":"第二十一条","txt":"债权人申报债权应当提交债权证明和合法有效的身份证明；代理申报人应当提交委托人的有效身份证明、授权委托书和债权证明。"},{"i":22,"n":"第二十二条","txt":"人民法院在登记申报的债权时，应当记明债权人名称、住所、开户银行、申报债权数额、申报债权的证据、财产担保情况、申报时间、联系方式以及其他必要的情况。"},{"i":23,"n":"第二十三条","txt":"连带债务人之一或者数人破产的，债权人可就全部债权向该债务人或者各债务人行使权利，申报债权。债权人未申报债权的，其他连带债务人可就将来可能承担的债务申报债权。"},{"i":24,"n":"第二十四条","txt":"债权人虽未在法定期间申报债权，但有民事诉讼法第七十六条规定情形的，在破产财产分配前可向清算组申报债权。清算组负责审查其申报的债权，并由人民法院审查确定。债权人会议对人民法院同意该债权人参加破产财产分配有异议的，可以向人民法院申请复议。"},{"i":25,"n":"第二十五条","txt":"人民法院受理企业破产案件后，在破产程序终结前，债务人可以向人民法院申请和解。人民法院在破产案件审理过程中，可以根据债权人、债务人具体情况向双方提出和解建议。"},{"i":26,"n":"第二十六条","txt":"债务人不按和解协议规定的内容清偿全部债务的，相关债权人可以申请人民法院强制执行。"},{"i":27,"n":"第二十七条","txt":"债务人不履行或者不能履行和解协议的，经债权人申请，人民法院应当裁定恢复破产程序。和解协议系在破产宣告前达成的，人民法院应当在裁定恢复破产程序的同时裁定宣告债务人破产。"},{"i":28,"n":"第二十八条","txt":"企业由债权人申请破产的，如被申请破产的企业系国有企业，依照企业破产法第四章的规定，其上级主管部门可以申请对该企业进行整顿。整顿申请应当在债务人被宣告破产前提出。"},{"i":29,"n":"第二十九条","txt":"企业整顿期间，企业的上级主管部门或者负责实施整顿方案的人员应当定期向债权人会议和人民法院报告整顿情况、和解协议执行情况。"},{"i":30,"n":"第三十条","txt":"企业整顿期间，对于债务人财产的执行仍适用企业破产法第十一条的规定。"},{"i":31,"n":"第三十一条","txt":"企业破产法第三条第一款规定的“不能清偿到期债务”是指："},{"i":32,"n":"第三十二条","txt":"人民法院受理债务人破产案件后，有下列情形之一的，应当裁定宣告债务人破产："},{"i":33,"n":"第三十三条","txt":"债务人自破产宣告之日起停止生产经营活动。为债权人利益确有必要继续生产经营的，须经人民法院许可。"},{"i":34,"n":"第三十四条","txt":"人民法院宣告债务人破产后，应当通知债务人的开户银行，限定其银行账户只能由清算组使用。人民法院通知开户银行时应当附破产宣告裁定书。"},{"i":35,"n":"第三十五条","txt":"人民法院裁定宣告债务人破产后应当发布公告，公告内容包括债务人亏损情况、资产负债状况、破产宣告时间、破产宣告理由和法律依据以及对债务人的财产、账册、文书、资料和印章的保护等内容。"},{"i":36,"n":"第三十六条","txt":"破产宣告后，破产企业的财产在其他民事诉讼程序中被查封、扣押、冻结的，受理破产案件的人民法院应当立即通知采取查封、扣押、冻结措施的人民法院予以解除，并向受理破产案件的人民法院办理移交手续。"},{"i":37,"n":"第三十七条","txt":"企业被宣告破产后，人民法院应当指定必要的留守人员。破产企业的法定代表人、财会、财产保管人员必须留守。"},{"i":38,"n":"第三十八条","txt":"破产宣告后，债权人或者债务人对破产宣告有异议的，可以在人民法院宣告企业破产之日起10日内，向上一级人民法院申诉。上一级人民法院应当组成合议庭进行审理，并在30日内作出裁定。"},{"i":39,"n":"第三十九条","txt":"债权人会议由申报债权的债权人组成。"},{"i":40,"n":"第四十条","txt":"第一次债权人会议应当在人民法院受理破产案件公告3个月期满后召开。除债务人的财产不足以支付破产费用，破产程序提前终结外，不得以一般债权的清偿率为零为理由取消债权人会议。"},{"i":41,"n":"第四十一条","txt":"第一次债权人会议由人民法院召集并主持。人民法院除完成本规定第十七条确定的工作外，还应当做好以下准备工作："},{"i":42,"n":"第四十二条","txt":"债权人会议一般包括以下内容："},{"i":43,"n":"第四十三条","txt":"债权人认为债权人会议决议违反法律规定或者侵害其合法权益的，可以在债权人会议作出决议后7日内向人民法院提出，由人民法院依法裁定。"},{"i":44,"n":"第四十四条","txt":"清算组财产分配方案经债权人会议两次讨论未获通过的，由人民法院依法裁定。"},{"i":45,"n":"第四十五条","txt":"债权人可以委托代理人出席债权人会议，并可以授权代理人行使表决权。代理人应当向人民法院或者债权人会议主席提交授权委托书。"},{"i":46,"n":"第四十六条","txt":"第一次债权人会议后又召开债权人会议的，债权人会议主席应当在发出会议通知前3日报告人民法院，并由会议召集人在开会前15日将会议时间、地点、内容、目的等事项通知债权人。"},{"i":47,"n":"第四十七条","txt":"人民法院应当自裁定宣告企业破产之日起15日内成立清算组。"},{"i":48,"n":"第四十八条","txt":"清算组成员可以从破产企业上级主管部门、清算中介机构以及会计、律师中产生，也可以从政府财政、工商管理、计委、经委、审计、税务、物价、劳动、社会保险、土地管理、国有资产管理、人事等部门中指定。人民银行分（支）行可以按照有关规定派人参加清算组。"},{"i":49,"n":"第四十九条","txt":"清算组经人民法院同意可以聘请破产清算机构、律师事务所、会计事务所等中介机构承担一定的破产清算工作。中介机构就清算工作向清算组负责。"},{"i":50,"n":"第五十条","txt":"清算组的主要职责是："},{"i":51,"n":"第五十一条","txt":"清算组对人民法院负责并且报告工作，接受人民法院的监督。人民法院应当及时指导清算组的工作，明确清算组的职权与责任，帮助清算组拟订工作计划，听取清算组汇报工作。"},{"i":52,"n":"第五十二条","txt":"清算组应当列席债权人会议，接受债权人会议的询问。债权人有权查阅有关资料、询问有关事项；清算组的决定违背债权人利益的，债权人可以申请人民法院裁定撤销该决定。"},{"i":53,"n":"第五十三条","txt":"清算组对破产财产应当及时登记、清理、审计、评估、变价。必要时，可以请求人民法院对破产企业财产进行保全。"},{"i":54,"n":"第五十四条","txt":"清算组应当采取有效措施保护破产企业的财产。债务人的财产权利如不依法登记或者及时行使将丧失权利的，应当及时予以登记或者行使；对易损、易腐、跌价或者保管费用较高的财产应当及时变卖。"},{"i":55,"n":"第五十五条","txt":"下列债权属于破产债权："},{"i":56,"n":"第五十六条","txt":"因企业破产解除劳动合同，劳动者依法或者依据劳动合同对企业享有的补偿金请求权，参照企业破产法第三十七条第二款第（一）项规定的顺序清偿。"},{"i":57,"n":"第五十七条","txt":"债务人所欠非正式职工（含短期劳动工）的劳动报酬，参照企业破产法第三十七条第二款第（一）项规定的顺序清偿。"},{"i":58,"n":"第五十八条","txt":"债务人所欠企业职工集资款，参照企业破产法第三十七条第二款第（一）项规定的顺序清偿。但对违反法律规定的高额利息部分不予保护。"},{"i":59,"n":"第五十九条","txt":"债务人退出联营应当对该联营企业的债务承担责任的，联营企业的债权人对该债务人享有的债权属于破产债权。"},{"i":60,"n":"第六十条","txt":"与债务人互负债权债务的债权人可以向清算组请求行使抵销权，抵销权的行使应当具备以下条件："},{"i":61,"n":"第六十一条","txt":"下列债权不属于破产债权："},{"i":62,"n":"第六十二条","txt":"政府无偿拨付给债务人的资金不属于破产债权。但财政、扶贫、科技管理等行政部门通过签订合同，按有偿使用、定期归还原则发放的款项，可以作为破产债权。"},{"i":63,"n":"第六十三条","txt":"债权人对清算组确认或者否认的债权有异议的，可以向清算组提出。债权人对清算组的处理仍有异议的，可以向人民法院提出。人民法院应当在查明事实的基础上依法作出裁决。"},{"i":64,"n":"第六十四条","txt":"破产财产由下列财产构成："},{"i":65,"n":"第六十五条","txt":"债务人与他人共有的物、债权、知识产权等财产或者财产权，应当在破产清算中予以分割，债务人分割所得属于破产财产；不能分割的，应当就其应得部分转让，转让所得属于破产财产。"},{"i":66,"n":"第六十六条","txt":"债务人的开办人注册资金投入不足的，应当由该开办人予以补足，补足部分属于破产财产。"},{"i":67,"n":"第六十七条","txt":"企业破产前受让他人财产并依法取得所有权或者土地使用权的，即便未支付或者未完全支付对价，该财产仍属于破产财产。"},{"i":68,"n":"第六十八条","txt":"债务人的财产被采取民事诉讼执行措施的，在受理破产案件后尚未执行的或者未执行完毕的剩余部分，在该企业被宣告破产后列入破产财产。因错误执行应当执行回转的财产，在执行回转后列入破产财产。"},{"i":69,"n":"第六十九条","txt":"债务人依照法律规定取得代位求偿权的，依该代位求偿权享有的债权属于破产财产。"},{"i":70,"n":"第七十条","txt":"债务人在被宣告破产时未到期的债权视为已到期，属于破产财产，但应当减去未到期的利息。"},{"i":71,"n":"第七十一条","txt":"下列财产不属于破产财产："},{"i":72,"n":"第七十二条","txt":"本规定第七十一条第（一）项所列的财产，财产权利人有权取回。"},{"i":73,"n":"第七十三条","txt":"清算组应当向破产企业的债务人和财产持有人发出书面通知，要求债务人和财产持有人于限定的时间向清算组清偿债务或者交付财产。"},{"i":74,"n":"第七十四条","txt":"债务人享有的债权，其诉讼时效自人民法院受理债务人的破产申请之日起，适用《中华人民共和国民法通则》第一百四十条关于诉讼时效中断的规定。债务人与债权人达成和解协议，中止破产程序的，诉讼时效自人民法院中止破产程序裁定之日起重新计算。"},{"i":75,"n":"第七十五条","txt":"经人民法院同意，清算组可以聘用律师或者其他中介机构的人员追收债权。"},{"i":76,"n":"第七十六条","txt":"债务人设立的分支机构和没有法人资格的全资机构的财产，应当一并纳入破产程序进行清理。"},{"i":77,"n":"第七十七条","txt":"债务人在其开办的全资企业中的投资权益应当予以追收。"},{"i":78,"n":"第七十八条","txt":"债务人对外投资形成的股权及其收益应当予以追收。对该股权可以出售或者转让，出售、转让所得列入破产财产进行分配。"},{"i":79,"n":"第七十九条","txt":"债务人开办的全资企业，以及由其参股、控股的企业不能清偿到期债务，需要进行破产还债的，应当另行提出破产申请。"},{"i":80,"n":"第八十条","txt":"清算组处理集体所有土地使用权时，应当遵守相关法律规定。未办理土地征用手续的集体所有土地使用权，应当在该集体范围内转让。"},{"i":81,"n":"第八十一条","txt":"破产企业的职工住房，已经签订合同、交付房款，进行房改给个人的，不属于破产财产。未进行房改的，可由清算组向有关部门申请办理房改事项，向职工出售。按照国家规定不具备房改条件，或者职工在房改中不购买住房的，由清算组根据实际情况处理。"},{"i":82,"n":"第八十二条","txt":"债务人的幼儿园、学校、医院等公益福利性设施，按国家有关规定处理，不作为破产财产分配。"},{"i":83,"n":"第八十三条","txt":"处理破产财产前，可以确定有相应评估资质的评估机构对破产财产进行评估，债权人会议、清算组对破产财产的评估结论、评估费用有异议的，参照最高人民法院《关于民事诉讼证据的若干规定》第二十七条的规定处理。"},{"i":84,"n":"第八十四条","txt":"债权人会议对破产财产的市场价格无异议的，经人民法院同意后，可以不进行评估。但是国有资产除外。"},{"i":85,"n":"第八十五条","txt":"破产财产的变现应当以拍卖方式进行。由清算组负责委托有拍卖资格的拍卖机构进行拍卖。"},{"i":86,"n":"第八十六条","txt":"破产财产中的成套设备，一般应当整体出售。"},{"i":87,"n":"第八十七条","txt":"依法属于限制流通的破产财产，应当由国家指定的部门收购或者按照有关法律规定处理。"},{"i":88,"n":"第八十八条","txt":"破产费用包括："},{"i":89,"n":"第八十九条","txt":"人民法院受理企业破产案件可以按照《人民法院诉讼收费办法补充规定》预收案件受理费。"},{"i":90,"n":"第九十条","txt":"清算期间职工生活费、医疗费可以从破产财产中优先拨付。"},{"i":91,"n":"第九十一条","txt":"破产费用可随时支付，破产财产不足以支付破产费用的，人民法院根据清算组的申请裁定终结破产程序。"},{"i":92,"n":"第九十二条","txt":"破产财产分配方案经债权人会议通过后，由清算组负责执行。财产分配可以一次分配，也可以多次分配。"},{"i":93,"n":"第九十三条","txt":"破产财产分配方案应当包括以下内容："},{"i":94,"n":"第九十四条","txt":"列入破产财产的债权，可以进行债权分配。债权分配以便于债权人实现债权为原则。"},{"i":95,"n":"第九十五条","txt":"债权人未在指定期限内领取分配的财产的，对该财产可以进行提存或者变卖后提存价款，并由清算组向债权人发出催领通知书。债权人在收到催领通知书一个月后或者在清算组发出催领通知书两个月后，债权人仍未领取的，清算组应当对该部分财产进行追加分配。"},{"i":96,"n":"第九十六条","txt":"破产财产分配完毕，由清算组向人民法院报告分配情况，并申请人民法院终结破产程序。"},{"i":97,"n":"第九十七条","txt":"破产程序终结后，由清算组向破产企业原登记机关办理企业注销登记。"},{"i":98,"n":"第九十八条","txt":"破产程序终结后出现可供分配的财产的，应当追加分配。追加分配的财产，除企业破产法第四十条规定的由人民法院追回的财产外，还包括破产程序中因纠正错误支出收回的款项，因权利被承认追回的财产，债权人放弃的财产和破产程序终结后实现的财产权利等。"},{"i":99,"n":"第九十九条","txt":"破产程序终结后，破产企业的账册、文书等卷宗材料由清算组移交破产企业上级主管机关保存；无上级主管机关的，由破产企业的开办人或者股东保存。"},{"i":100,"n":"第一百条","txt":"人民法院在审理企业破产案件中，发现破产企业的原法定代表人或者直接责任人员有企业破产法第三十五条所列行为的，应当向有关部门建议，对该法定代表人或者直接责任人员给予行政处分；涉嫌犯罪的，应当将有关材料移送相关国家机关处理。"},{"i":101,"n":"第一百零一条","txt":"破产企业有企业破产法第三十五条所列行为，致使企业财产无法收回，造成实际损失的，清算组可以对破产企业的原法定代表人、直接责任人员提起民事诉讼，要求其承担民事赔偿责任。"},{"i":102,"n":"第一百零二条","txt":"人民法院受理企业破产案件后，发现企业有巨额财产下落不明的，应当将有关涉嫌犯罪的情况和材料，移送相关国家机关处理。"},{"i":103,"n":"第一百零三条","txt":"人民法院可以建议有关部门对破产企业的主要责任人员限制其再行开办企业，在法定期限内禁止其担任公司的董事、监事、经理。"},{"i":104,"n":"第一百零四条","txt":"最高人民法院发现各级人民法院，或者上级人民法院发现下级人民法院在破产程序中作出的裁定确有错误的，应当通知其纠正；不予纠正的，可以裁定指令下级人民法院重新作出裁定。"},{"i":105,"n":"第一百零五条","txt":"纳入国家计划调整的企业破产案件，除适用本规定外，还应当适用国家有关企业破产的相关规定。"},{"i":106,"n":"第一百零六条","txt":"本规定自2002年9月1日起施行。在本规定发布前制定的有关审理企业破产案件的司法解释，与本规定相抵触的，不再适用。"}],"zuigaorenminfayuanguanyushenlishiyongrenlianshibie583319":[{"i":1,"n":"第一条","txt":"因信息处理者违反法律、行政法规的规定或者双方的约定使用人脸识别技术处理人脸信息、处理基于人脸识别技术生成的人脸信息所引起的民事案件，适用本规定。"},{"i":2,"n":"第二条","txt":"信息处理者处理人脸信息有下列情形之一的，人民法院应当认定属于侵害自然人人格权益的行为："},{"i":3,"n":"第三条","txt":"人民法院认定信息处理者承担侵害自然人人格权益的民事责任，应当适用民法典第九百九十八条的规定，并结合案件具体情况综合考量受害人是否为未成年人、告知同意情况以及信息处理的必要程度等因素。"},{"i":4,"n":"第四条","txt":"有下列情形之一，信息处理者以已征得自然人或者其监护人同意为由抗辩的，人民法院不予支持："},{"i":5,"n":"第五条","txt":"有下列情形之一，信息处理者主张其不承担民事责任的，人民法院依法予以支持："},{"i":6,"n":"第六条","txt":"当事人请求信息处理者承担民事责任的，人民法院应当依据民事诉讼法第六十四条及《最高人民法院关于适用〈中华人民共和国民事诉讼法〉的解释》第九十条、第九十一条，《最高人民法院关于民事诉讼证据的若干规定》的相关规定确定双方当事人的举证责任。"},{"i":7,"n":"第七条","txt":"多个信息处理者处理人脸信息侵害自然人人格权益，该自然人主张多个信息处理者按照过错程度和造成损害结果的大小承担侵权责任的，人民法院依法予以支持；符合民法典第一千一百六十八条、第一千一百六十九条第一款、第一千一百七十条、第一千一百七十一条等规定的相应情形，该自然人主张多个信息处理者承担连带责任的，人民法院依法予以支持。"},{"i":8,"n":"第八条","txt":"信息处理者处理人脸信息侵害自然人人格权益造成财产损失，该自然人依据民法典第一千一百八十二条主张财产损害赔偿的，人民法院依法予以支持。"},{"i":9,"n":"第九条","txt":"自然人有证据证明信息处理者使用人脸识别技术正在实施或者即将实施侵害其隐私权或者其他人格权益的行为，不及时制止将使其合法权益受到难以弥补的损害，向人民法院申请采取责令信息处理者停止有关行为的措施的，人民法院可以根据案件具体情况依法作出人格权侵害禁令。"},{"i":10,"n":"第十条","txt":"物业服务企业或者其他建筑物管理人以人脸识别作为业主或者物业使用人出入物业服务区域的唯一验证方式，不同意的业主或者物业使用人请求其提供其他合理验证方式的，人民法院依法予以支持。"},{"i":11,"n":"第十一条","txt":"信息处理者采用格式条款与自然人订立合同，要求自然人授予其无期限限制、不可撤销、可任意转授权等处理人脸信息的权利，该自然人依据民法典第四百九十七条请求确认格式条款无效的，人民法院依法予以支持。"},{"i":12,"n":"第十二条","txt":"信息处理者违反约定处理自然人的人脸信息，该自然人请求其承担违约责任的，人民法院依法予以支持。该自然人请求信息处理者承担违约责任时，请求删除人脸信息的，人民法院依法予以支持；信息处理者以双方未对人脸信息的删除作出约定为由抗辩的，人民法院不予支持。"},{"i":13,"n":"第十三条","txt":"基于同一信息处理者处理人脸信息侵害自然人人格权益发生的纠纷，多个受害人分别向同一人民法院起诉的，经当事人同意，人民法院可以合并审理。"},{"i":14,"n":"第十四条","txt":"信息处理者处理人脸信息的行为符合民事诉讼法第五十五条、消费者权益保护法第四十七条或者其他法律关于民事公益诉讼的相关规定，法律规定的机关和有关组织提起民事公益诉讼的，人民法院应予受理。"},{"i":15,"n":"第十五条","txt":"自然人死亡后，信息处理者违反法律、行政法规的规定或者双方的约定处理人脸信息，死者的近亲属依据民法典第九百九十四条请求信息处理者承担民事责任的，适用本规定。"},{"i":16,"n":"第十六条","txt":"本规定自2021年8月1日起施行。"}],"zuigaorenminfayuanguanyushenliqinhaixinxiwangluoch2c2237":[{"i":1,"n":"第一条","txt":"人民法院审理侵害信息网络传播权民事纠纷案件，在依法行使裁量权时，应当兼顾权利人、网络服务提供者和社会公众的利益。"},{"i":2,"n":"第二条","txt":"本规定所称信息网络，包括以计算机、电视机、固定电话机、移动电话机等电子设备为终端的计算机互联网、广播电视网、固定通信网、移动通信网等信息网络，以及向公众开放的局域网络。"},{"i":3,"n":"第三条","txt":"网络用户、网络服务提供者未经许可，通过信息网络提供权利人享有信息网络传播权的作品、表演、录音录像制品，除法律、行政法规另有规定外，人民法院应当认定其构成侵害信息网络传播权行为。"},{"i":4,"n":"第四条","txt":"有证据证明网络服务提供者与他人以分工合作等方式共同提供作品、表演、录音录像制品，构成共同侵权行为的，人民法院应当判令其承担连带责任。网络服务提供者能够证明其仅提供自动接入、自动传输、信息存储空间、搜索、链接、文件分享技术等网络服务，主张其不构成共同侵权行为的，人民法院应予支持。"},{"i":5,"n":"第五条","txt":"网络服务提供者以提供网页快照、缩略图等方式实质替代其他网络服务提供者向公众提供相关作品的，人民法院应当认定其构成提供行为。"},{"i":6,"n":"第六条","txt":"原告有初步证据证明网络服务提供者提供了相关作品、表演、录音录像制品，但网络服务提供者能够证明其仅提供网络服务，且无过错的，人民法院不应认定为构成侵权。"},{"i":7,"n":"第七条","txt":"网络服务提供者在提供网络服务时教唆或者帮助网络用户实施侵害信息网络传播权行为的，人民法院应当判令其承担侵权责任。"},{"i":8,"n":"第八条","txt":"人民法院应当根据网络服务提供者的过错，确定其是否承担教唆、帮助侵权责任。网络服务提供者的过错包括对于网络用户侵害信息网络传播权行为的明知或者应知。"},{"i":9,"n":"第九条","txt":"人民法院应当根据网络用户侵害信息网络传播权的具体事实是否明显，综合考虑以下因素，认定网络服务提供者是否构成应知："},{"i":10,"n":"第十条","txt":"网络服务提供者在提供网络服务时，对热播影视作品等以设置榜单、目录、索引、描述性段落、内容简介等方式进行推荐，且公众可以在其网页上直接以下载、浏览或者其他方式获得的，人民法院可以认定其应知网络用户侵害信息网络传播权。"},{"i":11,"n":"第十一条","txt":"网络服务提供者从网络用户提供的作品、表演、录音录像制品中直接获得经济利益的，人民法院应当认定其对该网络用户侵害信息网络传播权的行为负有较高的注意义务。"},{"i":12,"n":"第十二条","txt":"有下列情形之一的，人民法院可以根据案件具体情况，认定提供信息存储空间服务的网络服务提供者应知网络用户侵害信息网络传播权："},{"i":13,"n":"第十三条","txt":"网络服务提供者接到权利人以书信、传真、电子邮件等方式提交的通知及构成侵权的初步证据，未及时根据初步证据和服务类型采取必要措施的，人民法院应当认定其明知相关侵害信息网络传播权行为。"},{"i":14,"n":"第十四条","txt":"人民法院认定网络服务提供者转送通知、采取必要措施是否及时，应当根据权利人提交通知的形式，通知的准确程度，采取措施的难易程度，网络服务的性质，所涉作品、表演、录音录像制品的类型、知名度、数量等因素综合判断。"},{"i":15,"n":"第十五条","txt":"侵害信息网络传播权民事纠纷案件由侵权行为地或者被告住所地人民法院管辖。侵权行为地包括实施被诉侵权行为的网络服务器、计算机终端等设备所在地。侵权行为地和被告住所地均难以确定或者在境外的，原告发现侵权内容的计算机终端等设备所在地可以视为侵权行为地。"},{"i":16,"n":"第十六条","txt":"本规定施行之日起，《最高人民法院关于审理涉及计算机网络著作权纠纷案件适用法律若干问题的解释》（法释〔2006〕11号）同时废止。"}],"zuigaorenminfayuanguanyushenliqinhaizhiwuxinpinzho27f0c8":[{"i":1,"n":"第一条","txt":"植物新品种权所有人（以下称品种权人）或者利害关系人认为植物新品种权受到侵害的，可以依法向人民法院提起诉讼。"},{"i":2,"n":"第二条","txt":"未经品种权人许可，生产、繁殖或者销售授权品种的繁殖材料，或者为商业目的将授权品种的繁殖材料重复使用于生产另一品种的繁殖材料的，人民法院应当认定为侵害植物新品种权。"},{"i":3,"n":"第三条","txt":"侵害植物新品种权纠纷案件涉及的专门性问题需要鉴定的，由双方当事人协商确定的有鉴定资格的鉴定机构、鉴定人鉴定；协商不成的，由人民法院指定的有鉴定资格的鉴定机构、鉴定人鉴定。"},{"i":4,"n":"第四条","txt":"对于侵害植物新品种权纠纷案件涉及的专门性问题可以采取田间观察检测、基因指纹图谱检测等方法鉴定。"},{"i":5,"n":"第五条","txt":"品种权人或者利害关系人向人民法院提起侵害植物新品种权诉讼前，可以提出行为保全或者证据保全请求，人民法院经审查作出裁定。"},{"i":6,"n":"第六条","txt":"人民法院审理侵害植物新品种权纠纷案件，应当依照民法典第一百七十九条、第一千一百八十五条和种子法第七十三条的规定，结合案件具体情况，判决侵权人承担停止侵害、赔偿损失等民事责任。"},{"i":7,"n":"第七条","txt":"权利人和侵权人均同意将侵权物折价抵扣权利人所受损失的，人民法院应当准许。权利人或者侵权人不同意折价抵扣的，人民法院依照当事人的请求，责令侵权人对侵权物作消灭活性等使其不能再被用作繁殖材料的处理。"},{"i":8,"n":"第八条","txt":"以农业或者林业种植为业的个人、农村承包经营户接受他人委托代为繁殖侵害品种权的繁殖材料，不知道代繁物是侵害品种权的繁殖材料并说明委托人的，不承担赔偿责任。"}],"zuigaorenminfayuanguanyushenliqinhaizhiwuxinpinzhofc5c40":[{"i":1,"n":"第一条","txt":"植物新品种权（以下简称品种权）或者植物新品种申请权的共有人对权利行使有约定的，人民法院按照其约定处理。没有约定或者约定不明的，共有人主张其可以单独实施或者以普通许可方式许可他人实施的，人民法院应予支持。"},{"i":2,"n":"第二条","txt":"品种权转让未经国务院农业、林业主管部门登记、公告，受让人以品种权人名义提起侵害品种权诉讼的，人民法院不予受理。"},{"i":3,"n":"第三条","txt":"受品种权保护的繁殖材料应当具有繁殖能力，且繁殖出的新个体与该授权品种的特征、特性相同。"},{"i":4,"n":"第四条","txt":"以广告、展陈等方式作出销售授权品种的繁殖材料的意思表示的，人民法院可以以销售行为认定处理。"},{"i":5,"n":"第五条","txt":"种植授权品种的繁殖材料的，人民法院可以根据案件具体情况，以生产、繁殖行为认定处理。"},{"i":6,"n":"第六条","txt":"品种权人或者利害关系人（以下合称权利人）举证证明被诉侵权品种繁殖材料使用的名称与授权品种相同的，人民法院可以推定该被诉侵权品种繁殖材料属于授权品种的繁殖材料；有证据证明不属于该授权品种的繁殖材料的，人民法院可以认定被诉侵权人构成假冒品种行为，并参照假冒注册商标行为的有关规定确定民事责任。"},{"i":7,"n":"第七条","txt":"受托人、被许可人超出与品种权人约定的规模或者区域生产、繁殖授权品种的繁殖材料，或者超出与品种权人约定的规模销售授权品种的繁殖材料，品种权人请求判令受托人、被许可人承担侵权责任的，人民法院依法予以支持。"},{"i":8,"n":"第八条","txt":"被诉侵权人知道或者应当知道他人实施侵害品种权的行为，仍然提供收购、存储、运输、以繁殖为目的的加工处理等服务或者提供相关证明材料等条件的，人民法院可以依据民法典第一千一百六十九条的规定认定为帮助他人实施侵权行为。"},{"i":9,"n":"第九条","txt":"被诉侵权物既可以作为繁殖材料又可以作为收获材料，被诉侵权人主张被诉侵权物系作为收获材料用于消费而非用于生产、繁殖的，应当承担相应的举证责任。"},{"i":10,"n":"第十条","txt":"授权品种的繁殖材料经品种权人或者经其许可的单位、个人售出后，权利人主张他人生产、繁殖、销售该繁殖材料构成侵权的，人民法院一般不予支持，但是下列情形除外："},{"i":11,"n":"第十一条","txt":"被诉侵权人主张对授权品种进行的下列生产、繁殖行为属于科研活动的，人民法院应予支持："},{"i":12,"n":"第十二条","txt":"农民在其家庭农村土地承包经营合同约定的土地范围内自繁自用授权品种的繁殖材料，权利人对此主张构成侵权的，人民法院不予支持。"},{"i":13,"n":"第十三条","txt":"销售不知道也不应当知道是未经品种权人许可而售出的被诉侵权品种繁殖材料，且举证证明具有合法来源的，人民法院可以不判令销售者承担赔偿责任，但应当判令其停止销售并承担权利人为制止侵权行为所支付的合理开支。"},{"i":14,"n":"第十四条","txt":"人民法院根据已经查明侵害品种权的事实，认定侵权行为成立的，可以先行判决停止侵害，并可以依据当事人的请求和具体案情，责令采取消灭活性等阻止被诉侵权物扩散、繁殖的措施。"},{"i":15,"n":"第十五条","txt":"人民法院为确定赔偿数额，在权利人已经尽力举证，而与侵权行为相关的账簿、资料主要由被诉侵权人掌握的情况下，可以责令被诉侵权人提供与侵权行为相关的账簿、资料；被诉侵权人不提供或者提供虚假账簿、资料的，人民法院可以参考权利人的主张和提供的证据判定赔偿数额。"},{"i":16,"n":"第十六条","txt":"被诉侵权人有抗拒保全或者擅自拆封、转移、毁损被保全物等举证妨碍行为，致使案件相关事实无法查明的，人民法院可以推定权利人就该证据所涉证明事项的主张成立。构成民事诉讼法第一百一十一条规定情形的，依法追究法律责任。"},{"i":17,"n":"第十七条","txt":"除有关法律和司法解释规定的情形以外，以下情形也可以认定为侵权行为情节严重："},{"i":18,"n":"第十八条","txt":"品种权终止后依法恢复权利，权利人要求实施品种权的单位或者个人支付终止期间实施品种权的费用的，人民法院可以参照有关品种权实施许可费，结合品种类型、种植时间、经营规模、当时的市场价值等因素合理确定。"},{"i":19,"n":"第十九条","txt":"他人未经许可，自品种权初步审查合格公告之日起至被授予品种权之日止，生产、繁殖或者销售该授权品种的繁殖材料，或者为商业目的将该授权品种的繁殖材料重复使用于生产另一品种的繁殖材料，权利人对此主张追偿利益损失的，人民法院可以按照临时保护期使用费纠纷处理，并参照有关品种权实施许可费，结合品种类型、种植时间、经营规模、当时的市场价值等因素合理确定该使用费数额。"},{"i":20,"n":"第二十条","txt":"侵害品种权纠纷案件涉及的专门性问题需要鉴定的，由当事人在相关领域鉴定人名录或者国务院农业、林业主管部门向人民法院推荐的鉴定人中协商确定；协商不成的，由人民法院从中指定。"},{"i":21,"n":"第二十一条","txt":"对于没有基因指纹图谱等分子标记检测方法进行鉴定的品种，可以采用行业通用方法对授权品种与被诉侵权物的特征、特性进行同一性判断。"},{"i":22,"n":"第二十二条","txt":"对鉴定意见有异议的一方当事人向人民法院申请复检、补充鉴定或者重新鉴定，但未提出合理理由和证据的，人民法院不予准许。"},{"i":23,"n":"第二十三条","txt":"通过基因指纹图谱等分子标记检测方法进行鉴定，待测样品与对照样品的差异位点小于但接近临界值，被诉侵权人主张二者特征、特性不同的，应当承担举证责任；人民法院也可以根据当事人的申请，采取扩大检测位点进行加测或者提取授权品种标准样品进行测定等方法，并结合其他相关因素作出认定。"},{"i":24,"n":"第二十四条","txt":"田间观察检测与基因指纹图谱等分子标记检测的结论不同的，人民法院应当以田间观察检测结论为准。"},{"i":25,"n":"第二十五条","txt":"本规定自2021年7月7日起施行。本院以前发布的相关司法解释与本规定不一致的，按照本规定执行。"}],"zuigaorenminfayuanguanyushenliqinfanshangyemimimin3d5dcf":[{"i":1,"n":"第一条","txt":"与技术有关的结构、原料、组分、配方、材料、样品、样式、植物新品种繁殖材料、工艺、方法或其步骤、算法、数据、计算机程序及其有关文档等信息，人民法院可以认定构成反不正当竞争法第九条第四款所称的技术信息。"},{"i":2,"n":"第二条","txt":"当事人仅以与特定客户保持长期稳定交易关系为由，主张该特定客户属于商业秘密的，人民法院不予支持。"},{"i":3,"n":"第三条","txt":"权利人请求保护的信息在被诉侵权行为发生时不为所属领域的相关人员普遍知悉和容易获得的，人民法院应当认定为反不正当竞争法第九条第四款所称的不为公众所知悉。"},{"i":4,"n":"第四条","txt":"具有下列情形之一的，人民法院可以认定有关信息为公众所知悉："},{"i":5,"n":"第五条","txt":"权利人为防止商业秘密泄露，在被诉侵权行为发生以前所采取的合理保密措施，人民法院应当认定为反不正当竞争法第九条第四款所称的相应保密措施。"},{"i":6,"n":"第六条","txt":"具有下列情形之一，在正常情况下足以防止商业秘密泄露的，人民法院应当认定权利人采取了相应保密措施："},{"i":7,"n":"第七条","txt":"权利人请求保护的信息因不为公众所知悉而具有现实的或者潜在的商业价值的，人民法院经审查可以认定为反不正当竞争法第九条第四款所称的具有商业价值。"},{"i":8,"n":"第八条","txt":"被诉侵权人以违反法律规定或者公认的商业道德的方式获取权利人的商业秘密的，人民法院应当认定属于反不正当竞争法第九条第一款所称的以其他不正当手段获取权利人的商业秘密。"},{"i":9,"n":"第九条","txt":"被诉侵权人在生产经营活动中直接使用商业秘密，或者对商业秘密进行修改、改进后使用，或者根据商业秘密调整、优化、改进有关生产经营活动的，人民法院应当认定属于反不正当竞争法第九条所称的使用商业秘密。"},{"i":10,"n":"第十条","txt":"当事人根据法律规定或者合同约定所承担的保密义务，人民法院应当认定属于反不正当竞争法第九条第一款所称的保密义务。"},{"i":11,"n":"第十一条","txt":"法人、非法人组织的经营、管理人员以及具有劳动关系的其他人员，人民法院可以认定为反不正当竞争法第九条第三款所称的员工、前员工。"},{"i":12,"n":"第十二条","txt":"人民法院认定员工、前员工是否有渠道或者机会获取权利人的商业秘密，可以考虑与其有关的下列因素："},{"i":13,"n":"第十三条","txt":"被诉侵权信息与商业秘密不存在实质性区别的，人民法院可以认定被诉侵权信息与商业秘密构成反不正当竞争法第三十二条第二款所称的实质上相同。"},{"i":14,"n":"第十四条","txt":"通过自行开发研制或者反向工程获得被诉侵权信息的，人民法院应当认定不属于反不正当竞争法第九条规定的侵犯商业秘密行为。"},{"i":15,"n":"第十五条","txt":"被申请人试图或者已经以不正当手段获取、披露、使用或者允许他人使用权利人所主张的商业秘密，不采取行为保全措施会使判决难以执行或者造成当事人其他损害，或者将会使权利人的合法权益受到难以弥补的损害的，人民法院可以依法裁定采取行为保全措施。"},{"i":16,"n":"第十六条","txt":"经营者以外的其他自然人、法人和非法人组织侵犯商业秘密，权利人依据反不正当竞争法第十七条的规定主张侵权人应当承担的民事责任的，人民法院应予支持。"},{"i":17,"n":"第十七条","txt":"人民法院对于侵犯商业秘密行为判决停止侵害的民事责任时，停止侵害的时间一般应当持续到该商业秘密已为公众所知悉时为止。"},{"i":18,"n":"第十八条","txt":"权利人请求判决侵权人返还或者销毁商业秘密载体，清除其控制的商业秘密信息的，人民法院一般应予支持。"},{"i":19,"n":"第十九条","txt":"因侵权行为导致商业秘密为公众所知悉的，人民法院依法确定赔偿数额时，可以考虑商业秘密的商业价值。"},{"i":20,"n":"第二十条","txt":"权利人请求参照商业秘密许可使用费确定因被侵权所受到的实际损失的，人民法院可以根据许可的性质、内容、实际履行情况以及侵权行为的性质、情节、后果等因素确定。"},{"i":21,"n":"第二十一条","txt":"对于涉及当事人或者案外人的商业秘密的证据、材料，当事人或者案外人书面申请人民法院采取保密措施的，人民法院应当在保全、证据交换、质证、委托鉴定、询问、庭审等诉讼活动中采取必要的保密措施。"},{"i":22,"n":"第二十二条","txt":"人民法院审理侵犯商业秘密民事案件时，对在侵犯商业秘密犯罪刑事诉讼程序中形成的证据，应当按照法定程序，全面、客观地审查。"},{"i":23,"n":"第二十三条","txt":"当事人主张依据生效刑事裁判认定的实际损失或者违法所得确定涉及同一侵犯商业秘密行为的民事案件赔偿数额的，人民法院应予支持。"},{"i":24,"n":"第二十四条","txt":"权利人已经提供侵权人因侵权所获得的利益的初步证据，但与侵犯商业秘密行为相关的账簿、资料由侵权人掌握的，人民法院可以根据权利人的申请，责令侵权人提供该账簿、资料。侵权人无正当理由拒不提供或者不如实提供的，人民法院可以根据权利人的主张和提供的证据认定侵权人因侵权所获得的利益。"},{"i":25,"n":"第二十五条","txt":"当事人以涉及同一被诉侵犯商业秘密行为的刑事案件尚未审结为由，请求中止审理侵犯商业秘密民事案件，人民法院在听取当事人意见后认为必须以该刑事案件的审理结果为依据的，应予支持。"},{"i":26,"n":"第二十六条","txt":"对于侵犯商业秘密行为，商业秘密独占使用许可合同的被许可人提起诉讼的，人民法院应当依法受理。"},{"i":27,"n":"第二十七条","txt":"权利人应当在一审法庭辩论结束前明确所主张的商业秘密具体内容。仅能明确部分的，人民法院对该明确的部分进行审理。"},{"i":28,"n":"第二十八条","txt":"人民法院审理侵犯商业秘密民事案件，适用被诉侵权行为发生时的法律。被诉侵权行为在法律修改之前已经发生且持续到法律修改之后的，适用修改后的法律。"},{"i":29,"n":"第二十九条","txt":"本规定自2020年9月12日起施行。最高人民法院以前发布的相关司法解释与本规定不一致的，以本规定为准。"}],"zuigaorenminfayuanguanyushenlixinyongzhengjiufenan99ad31":[{"i":1,"n":"第一条","txt":"本规定所指的信用证纠纷案件，是指在信用证开立、通知、修改、撤销、保兑、议付、偿付等环节产生的纠纷。"},{"i":2,"n":"第二条","txt":"人民法院审理信用证纠纷案件时，当事人约定适用相关国际惯例或者其他规定的，从其约定；当事人没有约定的，适用国际商会《跟单信用证统一惯例》或者其他相关国际惯例。"},{"i":3,"n":"第三条","txt":"开证申请人与开证行之间因申请开立信用证而产生的欠款纠纷、委托人和受托人之间因委托开立信用证产生的纠纷、担保人为申请开立信用证或者委托开立信用证提供担保而产生的纠纷以及信用证项下融资产生的纠纷，适用本规定。"},{"i":4,"n":"第四条","txt":"因申请开立信用证而产生的欠款纠纷、委托开立信用证纠纷和因此产生的担保纠纷以及信用证项下融资产生的纠纷应当适用中华人民共和国相关法律。涉外合同当事人对法律适用另有约定的除外。"},{"i":5,"n":"第五条","txt":"开证行在作出付款、承兑或者履行信用证项下其他义务的承诺后，只要单据与信用证条款、单据与单据之间在表面上相符，开证行应当履行在信用证规定的期限内付款的义务。当事人以开证申请人与受益人之间的基础交易提出抗辩的，人民法院不予支持。具有本规定第八条的情形除外。"},{"i":6,"n":"第六条","txt":"人民法院在审理信用证纠纷案件中涉及单证审查的，应当根据当事人约定适用的相关国际惯例或者其他规定进行；当事人没有约定的，应当按照国际商会《跟单信用证统一惯例》以及国际商会确定的相关标准，认定单据与信用证条款、单据与单据之间是否在表面上相符。"},{"i":7,"n":"第七条","txt":"开证行有独立审查单据的权利和义务，有权自行作出单据与信用证条款、单据与单据之间是否在表面上相符的决定，并自行决定接受或者拒绝接受单据与信用证条款、单据与单据之间的不符点。"},{"i":8,"n":"第八条","txt":"凡有下列情形之一的，应当认定存在信用证欺诈："},{"i":9,"n":"第九条","txt":"开证申请人、开证行或者其他利害关系人发现有本规定第八条的情形，并认为将会给其造成难以弥补的损害时，可以向有管辖权的人民法院申请中止支付信用证项下的款项。"},{"i":10,"n":"第十条","txt":"人民法院认定存在信用证欺诈的，应当裁定中止支付或者判决终止支付信用证项下款项，但有下列情形之一的除外："},{"i":11,"n":"第十一条","txt":"当事人在起诉前申请中止支付信用证项下款项符合下列条件的，人民法院应予受理："},{"i":12,"n":"第十二条","txt":"人民法院接受中止支付信用证项下款项申请后，必须在四十八小时内作出裁定；裁定中止支付的，应当立即开始执行。"},{"i":13,"n":"第十三条","txt":"当事人对人民法院作出中止支付信用证项下款项的裁定有异议的，可以在裁定书送达之日起十日内向上一级人民法院申请复议。上一级人民法院应当自收到复议申请之日起十日内作出裁定。"},{"i":14,"n":"第十四条","txt":"人民法院在审理信用证欺诈案件过程中，必要时可以将信用证纠纷与基础交易纠纷一并审理。"},{"i":15,"n":"第十五条","txt":"人民法院通过实体审理，认定构成信用证欺诈并且不存在本规定第十条的情形的，应当判决终止支付信用证项下的款项。"},{"i":16,"n":"第十六条","txt":"保证人以开证行或者开证申请人接受不符点未征得其同意为由请求免除保证责任的，人民法院不予支持。保证合同另有约定的除外。"},{"i":17,"n":"第十七条","txt":"开证申请人与开证行对信用证进行修改未征得保证人同意的，保证人只在原保证合同约定的或者法律规定的期间和范围内承担保证责任。保证合同另有约定的除外。"},{"i":18,"n":"第十八条","txt":"本规定自2006年1月1日起施行。"}],"zuigaorenminfayuanguanyushenlijunduiwujingbuduizheccdfda":[{"i":1,"n":"第一条","txt":"军队、武警部队、政法机关和党政机关开办的企业（以下简称被开办企业）具备法人条件并领取了企业法人营业执照的，根据民法典第六十条的规定，应当以其全部财产独立承担民事责任。"},{"i":2,"n":"第二条","txt":"被开办企业领取了企业法人营业执照，虽然实际投入的资金与注册资金不符，但已达到了《中华人民共和国企业法人登记管理条例施行细则》第十二条第七项规定数额的，应当认定其具备法人资格，开办单位应当在该企业实际投入资金与注册资金的差额范围内承担民事责任。"},{"i":3,"n":"第三条","txt":"被开办企业虽然领取了企业法人营业执照，但投入的资金未达到《中华人民共和国企业法人登记管理条例施行细则》第十二条第七项规定数额的，或者不具备企业法人其他条件的，应当认定其不具备法人资格，其民事责任由开办单位承担。"},{"i":4,"n":"第四条","txt":"开办单位抽逃、转移资金或者隐匿财产以逃避被开办企业债务的，应当将所抽逃、转移的资金或者隐匿的财产退回，用以清偿被开办企业的债务。"},{"i":5,"n":"第五条","txt":"开办单位或其主管部门在被开办企业撤销时，向工商行政管理机关出具证明文件，自愿对被开办企业的债务承担责任的，应当按照承诺对被开办企业的债务承担民事责任。"},{"i":6,"n":"第六条","txt":"开办单位已经在被开办企业注册资金不实的范围内承担了民事责任的，应视为开办单位的注册资金已经足额到位，不再继续承担注册资金不实的责任。"},{"i":7,"n":"第七条","txt":"被开办企业或者债权人向人民法院申请破产的，不论开办单位的注册资金是否足额到位，人民法院均应当受理。"},{"i":8,"n":"第八条","txt":"被开办企业被宣告破产的，开办单位对其没有投足的注册资金、收取的资金和实物、转移的资金或者隐匿的财产，都应当由清算组负责收回。"},{"i":9,"n":"第九条","txt":"被开办企业向社会或者向企业内部职工集资未清偿的，在破产财产分配时，应当按照《中华人民共和国企业破产法》第一百一十三条第一款第一项的规定予以清偿。"},{"i":10,"n":"第十条","txt":"人民法院在审理有关移交、撤销、脱钩的企业的案件时，认定开办单位应当承担民事责任的，不得对开办单位的国库款、军费、财政经费账户、办公用房、车辆等其他办公必需品采取查封、扣押、冻结、拍卖等保全和执行措施。"},{"i":11,"n":"第十一条","txt":"本规定仅适用于审理此次军队、武警部队、政法机关移交、撤销企业和与党政机关脱钩的企业所发生的债务纠纷案件和破产案件。"}],"zuigaorenminfayuanguanyushenliliyongxinxiwangluoqi941e77":[{"i":1,"n":"第一条","txt":"本规定所称的利用信息网络侵害人身权益民事纠纷案件，是指利用信息网络侵害他人姓名权、名称权、名誉权、荣誉权、肖像权、隐私权等人身权益引起的纠纷案件。"},{"i":2,"n":"第二条","txt":"原告依据民法典第一千一百九十五条、第一千一百九十七条的规定起诉网络用户或者网络服务提供者的，人民法院应予受理。"},{"i":3,"n":"第三条","txt":"原告起诉网络服务提供者，网络服务提供者以涉嫌侵权的信息系网络用户发布为由抗辩的，人民法院可以根据原告的请求及案件的具体情况，责令网络服务提供者向人民法院提供能够确定涉嫌侵权的网络用户的姓名（名称）、联系方式、网络地址等信息。"},{"i":4,"n":"第四条","txt":"人民法院适用民法典第一千一百九十五条第二款的规定，认定网络服务提供者采取的删除、屏蔽、断开链接等必要措施是否及时，应当根据网络服务的类型和性质、有效通知的形式和准确程度、网络信息侵害权益的类型和程度等因素综合判断。"},{"i":5,"n":"第五条","txt":"其发布的信息被采取删除、屏蔽、断开链接等措施的网络用户，主张网络服务提供者承担违约责任或者侵权责任，网络服务提供者以收到民法典第一千一百九十五条第一款规定的有效通知为由抗辩的，人民法院应予支持。"},{"i":6,"n":"第六条","txt":"人民法院依据民法典第一千一百九十七条认定网络服务提供者是否“知道或者应当知道”，应当综合考虑下列因素："},{"i":7,"n":"第七条","txt":"人民法院认定网络用户或者网络服务提供者转载网络信息行为的过错及其程度，应当综合以下因素："},{"i":8,"n":"第八条","txt":"网络用户或者网络服务提供者采取诽谤、诋毁等手段，损害公众对经营主体的信赖，降低其产品或者服务的社会评价，经营主体请求网络用户或者网络服务提供者承担侵权责任的，人民法院应依法予以支持。"},{"i":9,"n":"第九条","txt":"网络用户或者网络服务提供者，根据国家机关依职权制作的文书和公开实施的职权行为等信息来源所发布的信息，有下列情形之一，侵害他人人身权益，被侵权人请求侵权人承担侵权责任的，人民法院应予支持："},{"i":10,"n":"第十条","txt":"被侵权人与构成侵权的网络用户或者网络服务提供者达成一方支付报酬，另一方提供删除、屏蔽、断开链接等服务的协议，人民法院应认定为无效。"},{"i":11,"n":"第十一条","txt":"网络用户或者网络服务提供者侵害他人人身权益，造成财产损失或者严重精神损害，被侵权人依据民法典第一千一百八十二条和第一千一百八十三条的规定，请求其承担赔偿责任的，人民法院应予支持。"},{"i":12,"n":"第十二条","txt":"被侵权人为制止侵权行为所支付的合理开支，可以认定为民法典第一千一百八十二条规定的财产损失。合理开支包括被侵权人或者委托代理人对侵权行为进行调查、取证的合理费用。人民法院根据当事人的请求和具体案情，可以将符合国家有关部门规定的律师费用计算在赔偿范围内。"},{"i":13,"n":"第十三条","txt":"本规定施行后人民法院正在审理的一审、二审案件适用本规定。"}],"zuigaorenminfayuanguanyushenlifanqingxiaoxingzheng3d88c1":[{"i":1,"n":"第一条","txt":"人民法院依法受理对下列反倾销行政行为提起的行政诉讼："},{"i":2,"n":"第二条","txt":"与反倾销行政行为具有法律上利害关系的个人或者组织为利害关系人，可以依照行政诉讼法及其他有关法律、行政法规的规定，向人民法院提起行政诉讼。"},{"i":3,"n":"第三条","txt":"反倾销行政案件的被告，应当是作出相应被诉反倾销行政行为的国务院主管部门。"},{"i":4,"n":"第四条","txt":"与被诉反倾销行政行为具有法律上利害关系的其他国务院主管部门，可以作为第三人参加诉讼。"},{"i":5,"n":"第五条","txt":"第一审反倾销行政案件由下列人民法院管辖："},{"i":6,"n":"第六条","txt":"人民法院依照行政诉讼法及其他有关反倾销的法律、行政法规，参照国务院部门规章，对被诉反倾销行政行为的事实问题和法律问题，进行合法性审查。"},{"i":7,"n":"第七条","txt":"被告对其作出的被诉反倾销行政行为负举证责任，应当提供作出反倾销行政行为的证据和所依据的规范性文件。"},{"i":8,"n":"第八条","txt":"原告对其主张的事实有责任提供证据。"},{"i":9,"n":"第九条","txt":"在反倾销行政调查程序中，利害关系人无正当理由拒不提供证据、不如实提供证据或者以其他方式严重妨碍调查的，国务院主管部门根据能够获得的证据得出的事实结论，可以认定为证据充分。"},{"i":10,"n":"第十条","txt":"人民法院审理反倾销行政案件，根据不同情况，分别作出以下判决："},{"i":11,"n":"第十一条","txt":"人民法院审理反倾销行政案件，可以参照有关涉外民事诉讼程序的规定。"},{"i":12,"n":"第十二条","txt":"本规定自2003年1月1日起实施。"}],"zuigaorenminfayuanguanyushenlifanbutiexingzhenganjee2a0d":[{"i":1,"n":"第一条","txt":"人民法院依法受理对下列反补贴行政行为提起的行政诉讼："},{"i":2,"n":"第二条","txt":"与反补贴行政行为具有法律上利害关系的个人或者组织为利害关系人，可以依照行政诉讼法及其他有关法律、行政法规的规定，向人民法院提起行政诉讼。"},{"i":3,"n":"第三条","txt":"反补贴行政案件的被告，应当是作出相应被诉反补贴行政行为的国务院主管部门。"},{"i":4,"n":"第四条","txt":"与被诉反补贴行政行为具有法律上利害关系的其他国务院主管部门，可以作为第三人参加诉讼。"},{"i":5,"n":"第五条","txt":"第一审反补贴行政案件由下列人民法院管辖："},{"i":6,"n":"第六条","txt":"人民法院依照行政诉讼法及其他有关反补贴的法律、行政法规，参照国务院部门规章，对被诉反补贴行政行为的事实问题和法律问题，进行合法性审查。"},{"i":7,"n":"第七条","txt":"被告对其作出的被诉反补贴行政行为负举证责任，应当提供作出反补贴行政行为的证据和所依据的规范性文件。"},{"i":8,"n":"第八条","txt":"原告对其主张的事实有责任提供证据。"},{"i":9,"n":"第九条","txt":"在反补贴行政调查程序中，利害关系人无正当理由拒不提供证据、不如实提供证据或者以其他方式严重妨碍调查的，国务院主管部门根据能够获得的证据得出的事实结论，可以认定为证据充分。"},{"i":10,"n":"第十条","txt":"人民法院审理反补贴行政案件，根据不同情况，分别作出以下判决："},{"i":11,"n":"第十一条","txt":"人民法院审理反补贴行政案件，可以参照有关涉外民事诉讼程序的规定。"},{"i":12,"n":"第十二条","txt":"本规定自2003年1月1日起实施。"}],"zuigaorenminfayuanguanyushenlifashengzaiwoguoguanxb8b63d":[{"i":1,"n":"第一条","txt":"本规定所称我国管辖海域，是指中华人民共和国内水、领海、毗连区、专属经济区、大陆架，以及中华人民共和国管辖的其他海域。"},{"i":2,"n":"第二条","txt":"中国公民或组织在我国与有关国家缔结的协定确定的共同管理的渔区或公海从事捕捞等作业的，适用本规定。"},{"i":3,"n":"第三条","txt":"中国公民或者外国人在我国管辖海域实施非法猎捕、杀害珍贵濒危野生动物或者非法捕捞水产品等犯罪的，依照我国刑法追究刑事责任。"},{"i":4,"n":"第四条","txt":"有关部门依据出境入境管理法、治安管理处罚法，对非法进入我国内水从事渔业生产或者渔业资源调查的外国人，作出行政强制措施或行政处罚决定，行政相对人不服的，可分别依据出境入境管理法第六十四条和治安管理处罚法第一百零二条的规定，向有关机关申请复议或向有管辖权的人民法院提起行政诉讼。"},{"i":5,"n":"第五条","txt":"因在我国管辖海域内发生海损事故，请求损害赔偿提起的诉讼，由管辖该海域的海事法院、事故船舶最先到达地的海事法院、船舶被扣押地或者被告住所地海事法院管辖。"},{"i":6,"n":"第六条","txt":"在我国管辖海域内，因海上航运、渔业生产及其他海上作业造成污染，破坏海洋生态环境，请求损害赔偿提起的诉讼，由管辖该海域的海事法院管辖。"},{"i":7,"n":"第七条","txt":"本规定施行后尚未审结的案件，适用本规定；本规定施行前已经终审，当事人申请再审或者按照审判监督程序决定再审的案件，不适用本规定。"},{"i":8,"n":"第八条","txt":"本规定自2016年8月2日起施行。"}],"zuigaorenminfayuanguanyushenlifashengzaiwoguoguanx065d00":[{"i":1,"n":"第一条","txt":"当事人因船舶碰撞、海洋污染等事故受到损害，请求侵权人赔偿渔船、渔具、渔货损失以及收入损失的，人民法院应予支持。"},{"i":2,"n":"第二条","txt":"人民法院在审判执行工作中，发现违法行为，需要有关单位对其依法处理的，应及时向相关单位提出司法建议，必要时可以抄送该单位的上级机关或者主管部门。违法行为涉嫌犯罪的，依法移送刑事侦查部门处理。"},{"i":3,"n":"第三条","txt":"违反我国国（边）境管理法规，非法进入我国领海，具有下列情形之一的，应当认定为刑法第三百二十二条规定的“情节严重”："},{"i":4,"n":"第四条","txt":"违反保护水产资源法规，在海洋水域，在禁渔区、禁渔期或者使用禁用的工具、方法捕捞水产品，具有下列情形之一的，应当认定为刑法第三百四十条规定的“情节严重”："},{"i":5,"n":"第五条","txt":"非法采捕珊瑚、砗磲或者其他珍贵、濒危水生野生动物，具有下列情形之一的，应当认定为刑法第三百四十一条第一款规定的“情节严重”："},{"i":6,"n":"第六条","txt":"非法收购、运输、出售珊瑚、砗磲或者其他珍贵、濒危水生野生动物及其制品，具有下列情形之一的，应当认定为刑法第三百四十一条第一款规定的“情节严重”："},{"i":7,"n":"第七条","txt":"对案件涉及的珍贵、濒危水生野生动物的种属难以确定的，由司法鉴定机构出具鉴定意见，或者由国务院渔业行政主管部门指定的机构出具报告。"},{"i":8,"n":"第八条","txt":"实施破坏海洋资源犯罪行为，同时构成非法捕捞罪、非法猎捕、杀害珍贵濒危、野生动物罪、组织他人偷越国（边）境罪、偷越国（边）境罪等犯罪的，依照处罚较重的规定定罪处罚。"},{"i":9,"n":"第九条","txt":"行政机关在行政诉讼中提交的于中华人民共和国领域外形成的，符合我国相关法律规定的证据，可以作为人民法院认定案件事实的依据。"},{"i":10,"n":"第十条","txt":"行政相对人未依法取得捕捞许可证擅自进行捕捞，行政机关认为该行为构成渔业法第四十一条规定的“情节严重”情形的，人民法院应当从以下方面综合审查，并作出认定："},{"i":11,"n":"第十一条","txt":"行政机关对停靠在渔港，无船名、船籍港和船舶证书的船舶，采取禁止离港、指定地点停放等强制措施，行政相对人以行政机关超越法定职权为由提起诉讼的，人民法院不予支持。"},{"i":12,"n":"第十二条","txt":"无船名、无船籍港、无渔业船舶证书的船舶从事非法捕捞，行政机关经审慎调查，在无相反证据的情况下，将现场负责人或者实际负责人认定为违法行为人的，人民法院应予支持。"},{"i":13,"n":"第十三条","txt":"行政机关有证据证明行政相对人采取将装载物品倒入海中等故意毁灭证据的行为，但行政相对人予以否认的，人民法院可以根据行政相对人的行为给行政机关举证造成困难的实际情况，适当降低行政机关的证明标准或者决定由行政相对人承担相反事实的证明责任。"},{"i":14,"n":"第十四条","txt":"外国公民、无国籍人、外国组织，认为我国海洋、公安、海关、渔业行政主管部门及其所属的渔政监督管理机构等执法部门在行政执法过程中侵害其合法权益的，可以依据行政诉讼法等相关法律规定提起行政诉讼。"},{"i":15,"n":"第十五条","txt":"本规定施行后尚未审结的一审、二审案件，适用本规定；本规定施行前已经终审，当事人申请再审或者按照审判监督程序决定再审的案件，不适用本规定。"},{"i":16,"n":"第十六条","txt":"本规定自2016年8月2日起施行。"}],"zuigaorenminfayuanguanyushenlishangbiaoshouquanque526d35":[{"i":1,"n":"第一条","txt":"本规定所称商标授权确权行政案件，是指相对人或者利害关系人因不服国家知识产权局作出的商标驳回复审、商标不予注册复审、商标撤销复审、商标无效宣告及无效宣告复审等行政行为，向人民法院提起诉讼的案件。"},{"i":2,"n":"第二条","txt":"人民法院对商标授权确权行政行为进行审查的范围，一般应根据原告的诉讼请求及理由确定。原告在诉讼中未提出主张，但国家知识产权局相关认定存在明显不当的，人民法院在各方当事人陈述意见后，可以对相关事由进行审查并作出裁判。"},{"i":3,"n":"第三条","txt":"商标法第十条第一款第（一）项规定的同中华人民共和国的国家名称等“相同或者近似”，是指商标标志整体上与国家名称等相同或者近似。"},{"i":4,"n":"第四条","txt":"商标标志或者其构成要素带有欺骗性，容易使公众对商品的质量等特点或者产地产生误认，国家知识产权局认定其属于2001年修正的商标法第十条第一款第（七）项规定情形的，人民法院予以支持。"},{"i":5,"n":"第五条","txt":"商标标志或者其构成要素可能对我国社会公共利益和公共秩序产生消极、负面影响的，人民法院可以认定其属于商标法第十条第一款第（八）项规定的“其他不良影响”。"},{"i":6,"n":"第六条","txt":"商标标志由县级以上行政区划的地名或者公众知晓的外国地名和其他要素组成，如果整体上具有区别于地名的含义，人民法院应当认定其不属于商标法第十条第二款所指情形。"},{"i":7,"n":"第七条","txt":"人民法院审查诉争商标是否具有显著特征，应当根据商标所指定使用商品的相关公众的通常认识，判断该商标整体上是否具有显著特征。商标标志中含有描述性要素，但不影响其整体具有显著特征的；或者描述性标志以独特方式加以表现，相关公众能够以其识别商品来源的，应当认定其具有显著特征。"},{"i":8,"n":"第八条","txt":"诉争商标为外文标志时，人民法院应当根据中国境内相关公众的通常认识，对该外文商标是否具有显著特征进行审查判断。标志中外文的固有含义可能影响其在指定使用商品上的显著特征，但相关公众对该固有含义的认知程度较低，能够以该标志识别商品来源的，可以认定其具有显著特征。"},{"i":9,"n":"第九条","txt":"仅以商品自身形状或者自身形状的一部分作为三维标志申请注册商标，相关公众一般情况下不易将其识别为指示商品来源标志的，该三维标志不具有作为商标的显著特征。"},{"i":10,"n":"第十条","txt":"诉争商标属于法定的商品名称或者约定俗成的商品名称的，人民法院应当认定其属于商标法第十一条第一款第（一）项所指的通用名称。依据法律规定或者国家标准、行业标准属于商品通用名称的，应当认定为通用名称。相关公众普遍认为某一名称能够指代一类商品的，应当认定为约定俗成的通用名称。被专业工具书、辞典等列为商品名称的，可以作为认定约定俗成的通用名称的参考。"},{"i":11,"n":"第十一条","txt":"商标标志只是或者主要是描述、说明所使用商品的质量、主要原料、功能、用途、重量、数量、产地等的，人民法院应当认定其属于商标法第十一条第一款第（二）项规定的情形。商标标志或者其构成要素暗示商品的特点，但不影响其识别商品来源功能的，不属于该项所规定的情形。"},{"i":12,"n":"第十二条","txt":"当事人依据商标法第十三条第二款主张诉争商标构成对其未注册的驰名商标的复制、摹仿或者翻译而不应予以注册或者应予无效的，人民法院应当综合考量如下因素以及因素之间的相互影响，认定是否容易导致混淆："},{"i":13,"n":"第十三条","txt":"当事人依据商标法第十三条第三款主张诉争商标构成对其已注册的驰名商标的复制、摹仿或者翻译而不应予以注册或者应予无效的，人民法院应当综合考虑如下因素，以认定诉争商标的使用是否足以使相关公众认为其与驰名商标具有相当程度的联系，从而误导公众，致使驰名商标注册人的利益可能受到损害："},{"i":14,"n":"第十四条","txt":"当事人主张诉争商标构成对其已注册的驰名商标的复制、摹仿或者翻译而不应予以注册或者应予无效，国家知识产权局依据商标法第三十条规定裁决支持其主张的，如果诉争商标注册未满五年，人民法院在当事人陈述意见之后，可以按照商标法第三十条规定进行审理；如果诉争商标注册已满五年，应当适用商标法第十三条第三款进行审理。"},{"i":15,"n":"第十五条","txt":"商标代理人、代表人或者经销、代理等销售代理关系意义上的代理人、代表人未经授权，以自己的名义将与被代理人或者被代表人的商标相同或者近似的商标在相同或者类似商品上申请注册的，人民法院适用商标法第十五条第一款的规定进行审理。"},{"i":16,"n":"第十六条","txt":"以下情形可以认定为商标法第十五条第二款中规定的“其他关系”："},{"i":17,"n":"第十七条","txt":"地理标志利害关系人依据商标法第十六条主张他人商标不应予以注册或者应予无效，如果诉争商标指定使用的商品与地理标志产品并非相同商品，而地理标志利害关系人能够证明诉争商标使用在该产品上仍然容易导致相关公众误认为该产品来源于该地区并因此具有特定的质量、信誉或者其他特征的，人民法院予以支持。"},{"i":18,"n":"第十八条","txt":"商标法第三十二条规定的在先权利，包括当事人在诉争商标申请日之前享有的民事权利或者其他应予保护的合法权益。诉争商标核准注册时在先权利已不存在的，不影响诉争商标的注册。"},{"i":19,"n":"第十九条","txt":"当事人主张诉争商标损害其在先著作权的，人民法院应当依照著作权法等相关规定，对所主张的客体是否构成作品、当事人是否为著作权人或者其他有权主张著作权的利害关系人以及诉争商标是否构成对著作权的侵害等进行审查。"},{"i":20,"n":"第二十条","txt":"当事人主张诉争商标损害其姓名权，如果相关公众认为该商标标志指代了该自然人，容易认为标记有该商标的商品系经过该自然人许可或者与该自然人存在特定联系的，人民法院应当认定该商标损害了该自然人的姓名权。"},{"i":21,"n":"第二十一条","txt":"当事人主张的字号具有一定的市场知名度，他人未经许可申请注册与该字号相同或者近似的商标，容易导致相关公众对商品来源产生混淆，当事人以此主张构成在先权益的，人民法院予以支持。"},{"i":22,"n":"第二十二条","txt":"当事人主张诉争商标损害角色形象著作权的，人民法院按照本规定第十九条进行审查。"},{"i":23,"n":"第二十三条","txt":"在先使用人主张商标申请人以不正当手段抢先注册其在先使用并有一定影响的商标的，如果在先使用商标已经有一定影响，而商标申请人明知或者应知该商标，即可推定其构成“以不正当手段抢先注册”。但商标申请人举证证明其没有利用在先使用商标商誉的恶意的除外。"},{"i":24,"n":"第二十四条","txt":"以欺骗手段以外的其他方式扰乱商标注册秩序、损害公共利益、不正当占用公共资源或者谋取不正当利益的，人民法院可以认定其属于商标法第四十四条第一款规定的“其他不正当手段”。"},{"i":25,"n":"第二十五条","txt":"人民法院判断诉争商标申请人是否“恶意注册”他人驰名商标，应综合考虑引证商标的知名度、诉争商标申请人申请诉争商标的理由以及使用诉争商标的具体情形来判断其主观意图。引证商标知名度高、诉争商标申请人没有正当理由的，人民法院可以推定其注册构成商标法第四十五条第一款所指的“恶意注册”。"},{"i":26,"n":"第二十六条","txt":"商标权人自行使用、他人经许可使用以及其他不违背商标权人意志的使用，均可认定为商标法第四十九条第二款所称的使用。"},{"i":27,"n":"第二十七条","txt":"当事人主张国家知识产权局下列情形属于行政诉讼法第七十条第（三）项规定的“违反法定程序”的，人民法院予以支持："},{"i":28,"n":"第二十八条","txt":"人民法院审理商标授权确权行政案件的过程中，国家知识产权局对诉争商标予以驳回、不予核准注册或者予以无效宣告的事由不复存在的，人民法院可以依据新的事实撤销国家知识产权局相关裁决，并判令其根据变更后的事实重新作出裁决。"},{"i":29,"n":"第二十九条","txt":"当事人依据在原行政行为之后新发现的证据，或者在原行政程序中因客观原因无法取得或在规定的期限内不能提供的证据，或者新的法律依据提出的评审申请，不属于“以相同的事实和理由”再次提出评审申请。"},{"i":30,"n":"第三十条","txt":"人民法院生效裁判对于相关事实和法律适用已作出明确认定，相对人或者利害关系人对于国家知识产权局依据该生效裁判重新作出的裁决提起诉讼的，人民法院依法裁定不予受理；已经受理的，裁定驳回起诉。"},{"i":31,"n":"第三十一条","txt":"本规定自2017年3月1日起施行。人民法院依据2001年修正的商标法审理的商标授权确权行政案件可参照适用本规定。"}],"zuigaorenminfayuanguanyushenliguojimaoyixingzhenga938199":[{"i":1,"n":"第一条","txt":"下列案件属于本规定所称国际贸易行政案件："},{"i":2,"n":"第二条","txt":"人民法院行政审判庭依法审理国际贸易行政案件。"},{"i":3,"n":"第三条","txt":"自然人、法人或者其他组织认为中华人民共和国具有国家行政职权的机关和组织及其工作人员（以下统称行政机关）有关国际贸易的具体行政行为侵犯其合法权益的，可以依照行政诉讼法以及其他有关法律、法规的规定，向人民法院提起行政诉讼。"},{"i":4,"n":"第四条","txt":"当事人的行为发生在新法生效之前，行政机关在新法生效之后对该行为作出行政处理决定的，当事人可以依照新法的规定提起行政诉讼。"},{"i":5,"n":"第五条","txt":"第一审国际贸易行政案件由具有管辖权的中级以上人民法院管辖。"},{"i":6,"n":"第六条","txt":"人民法院审理国际贸易行政案件，应当依照行政诉讼法，并根据案件具体情况，从以下方面对被诉具体行政行为进行合法性审查："},{"i":7,"n":"第七条","txt":"根据行政诉讼法第五十二条第一款及立法法第六十三条第一款和第二款规定，人民法院审理国际贸易行政案件，应当依据中华人民共和国法律、行政法规以及地方立法机关在法定立法权限范围内制定的有关或者影响国际贸易的地方性法规。地方性法规适用于本行政区域内发生的国际贸易行政案件。"},{"i":8,"n":"第八条","txt":"根据行政诉讼法第五十三条第一款及立法法第七十一条、第七十二条和第七十三条规定，人民法院审理国际贸易行政案件，参照国务院部门根据法律和国务院的行政法规、决定、命令，在本部门权限范围内制定的有关或者影响国际贸易的部门规章，以及省、自治区、直辖市和省、自治区的人民政府所在地的市、经济特区所在地的市、国务院批准的较大的市的人民政府根据法律、行政法规和地方性法规制定的有关或者影响国际贸易的地方政府规章。"},{"i":9,"n":"第九条","txt":"人民法院审理国际贸易行政案件所适用的法律、行政法规的具体条文存在两种以上的合理解释，其中有一种解释与中华人民共和国缔结或者参加的国际条约的有关规定相一致的，应当选择与国际条约的有关规定相一致的解释，但中华人民共和国声明保留的条款除外。"},{"i":10,"n":"第十条","txt":"外国人、无国籍人、外国组织在中华人民共和国进行国际贸易行政诉讼，同中华人民共和国公民、组织有同等的诉讼权利和义务，但有行政诉讼法第七十一条第二款规定的情形的，适用对等原则。"},{"i":11,"n":"第十一条","txt":"涉及香港特别行政区、澳门特别行政区和台湾地区当事人的国际贸易行政案件，参照本规定处理。"},{"i":12,"n":"第十二条","txt":"本规定自2002年10月1日起施行。"}],"zuigaorenminfayuanguanyushenliwaishangtouziqiyejiu0f91fb":[{"i":1,"n":"第一条","txt":"当事人在外商投资企业设立、变更等过程中订立的合同，依法律、行政法规的规定应当经外商投资企业审批机关批准后才生效的，自批准之日起生效；未经批准的，人民法院应当认定该合同未生效。当事人请求确认该合同无效的，人民法院不予支持。"},{"i":2,"n":"第二条","txt":"当事人就外商投资企业相关事项达成的补充协议对已获批准的合同不构成重大或实质性变更的，人民法院不应以未经外商投资企业审批机关批准为由认定该补充协议未生效。"},{"i":3,"n":"第三条","txt":"人民法院在审理案件中，发现经外商投资企业审批机关批准的外商投资企业合同具有法律、行政法规规定的无效情形的，应当认定合同无效；该合同具有法律、行政法规规定的可撤销情形，当事人请求撤销的，人民法院应予支持。"},{"i":4,"n":"第四条","txt":"外商投资企业合同约定一方当事人以需要办理权属变更登记的标的物出资或者提供合作条件，标的物已交付外商投资企业实际使用，且负有办理权属变更登记义务的一方当事人在人民法院指定的合理期限内完成了登记的，人民法院应当认定该方当事人履行了出资或者提供合作条件的义务。外商投资企业或其股东以该方当事人未履行出资义务为由主张该方当事人不享有股东权益的，人民法院不予支持。"},{"i":5,"n":"第五条","txt":"外商投资企业股权转让合同成立后，转让方和外商投资企业不履行报批义务，经受让方催告后在合理的期限内仍未履行，受让方请求解除合同并由转让方返还其已支付的转让款、赔偿因未履行报批义务而造成的实际损失的，人民法院应予支持。"},{"i":6,"n":"第六条","txt":"外商投资企业股权转让合同成立后，转让方和外商投资企业不履行报批义务，受让方以转让方为被告、以外商投资企业为第三人提起诉讼，请求转让方与外商投资企业在一定期限内共同履行报批义务的，人民法院应予支持。受让方同时请求在转让方和外商投资企业于生效判决确定的期限内不履行报批义务时自行报批的，人民法院应予支持。"},{"i":7,"n":"第七条","txt":"转让方、外商投资企业或者受让方根据本规定第六条第一款的规定就外商投资企业股权转让合同报批，未获外商投资企业审批机关批准，受让方另行起诉，请求转让方返还其已支付的转让款的，人民法院应予支持。受让方请求转让方赔偿因此造成的损失的，人民法院应根据转让方是否存在过错以及过错大小认定其是否承担赔偿责任及具体赔偿数额。"},{"i":8,"n":"第八条","txt":"外商投资企业股权转让合同约定受让方支付转让款后转让方才办理报批手续，受让方未支付股权转让款，经转让方催告后在合理的期限内仍未履行，转让方请求解除合同并赔偿因迟延履行而造成的实际损失的，人民法院应予支持。"},{"i":9,"n":"第九条","txt":"外商投资企业股权转让合同成立后，受让方未支付股权转让款，转让方和外商投资企业亦未履行报批义务，转让方请求受让方支付股权转让款的，人民法院应当中止审理，指令转让方在一定期限内办理报批手续。该股权转让合同获得外商投资企业审批机关批准的，对转让方关于支付转让款的诉讼请求，人民法院应予支持。"},{"i":10,"n":"第十条","txt":"外商投资企业股权转让合同成立后，受让方已实际参与外商投资企业的经营管理并获取收益，但合同未获外商投资企业审批机关批准，转让方请求受让方退出外商投资企业的经营管理并将受让方因实际参与经营管理而获得的收益在扣除相关成本费用后支付给转让方的，人民法院应予支持。"},{"i":11,"n":"第十一条","txt":"外商投资企业一方股东将股权全部或部分转让给股东之外的第三人，应当经其他股东一致同意，其他股东以未征得其同意为由请求撤销股权转让合同的，人民法院应予支持。具有以下情形之一的除外："},{"i":12,"n":"第十二条","txt":"外商投资企业一方股东将股权全部或部分转让给股东之外的第三人，其他股东以该股权转让侵害了其优先购买权为由请求撤销股权转让合同的，人民法院应予支持。其他股东在知道或者应当知道股权转让合同签订之日起一年内未主张优先购买权的除外。"},{"i":13,"n":"第十三条","txt":"外商投资企业股东与债权人订立的股权质押合同，除法律、行政法规另有规定或者合同另有约定外，自成立时生效。未办理质权登记的，不影响股权质押合同的效力。"},{"i":14,"n":"第十四条","txt":"当事人之间约定一方实际投资、另一方作为外商投资企业名义股东，实际投资者请求确认其在外商投资企业中的股东身份或者请求变更外商投资企业股东的，人民法院不予支持。同时具备以下条件的除外："},{"i":15,"n":"第十五条","txt":"合同约定一方实际投资、另一方作为外商投资企业名义股东，不具有法律、行政法规规定的无效情形的，人民法院应认定该合同有效。一方当事人仅以未经外商投资企业审批机关批准为由主张该合同无效或者未生效的，人民法院不予支持。"},{"i":16,"n":"第十六条","txt":"外商投资企业名义股东不履行与实际投资者之间的合同，致使实际投资者不能实现合同目的，实际投资者请求解除合同并由外商投资企业名义股东承担违约责任的，人民法院应予支持。"},{"i":17,"n":"第十七条","txt":"实际投资者根据其与外商投资企业名义股东的约定，直接向外商投资企业请求分配利润或者行使其他股东权利的，人民法院不予支持。"},{"i":18,"n":"第十八条","txt":"实际投资者与外商投资企业名义股东之间的合同被认定无效，名义股东持有的股权价值高于实际投资额，实际投资者请求名义股东向其返还投资款并根据其实际投资情况以及名义股东参与外商投资企业经营管理的情况对股权收益在双方之间进行合理分配的，人民法院应予支持。"},{"i":19,"n":"第十九条","txt":"实际投资者与外商投资企业名义股东之间的合同被认定无效，名义股东持有的股权价值低于实际投资额，实际投资者请求名义股东向其返还现有股权的等值价款的，人民法院应予支持；外商投资企业名义股东明确表示放弃股权或者拒绝继续持有股权的，人民法院可以判令以拍卖、变卖名义股东持有的外商投资企业股权所得向实际投资者返还投资款。"},{"i":20,"n":"第二十条","txt":"实际投资者与外商投资企业名义股东之间的合同因恶意串通，损害国家、集体或者第三人利益，被认定无效的，人民法院应当将因此取得的财产收归国家所有或者返还集体、第三人。"},{"i":21,"n":"第二十一条","txt":"外商投资企业一方股东或者外商投资企业以提供虚假材料等欺诈或者其他不正当手段向外商投资企业审批机关申请变更外商投资企业批准证书所载股东，导致外商投资企业他方股东丧失股东身份或原有股权份额，他方股东请求确认股东身份或原有股权份额的，人民法院应予支持。第三人已经善意取得该股权的除外。"},{"i":22,"n":"第二十二条","txt":"人民法院审理香港特别行政区、澳门特别行政区、台湾地区的投资者、定居在国外的中国公民在内地投资设立企业产生的相关纠纷案件，参照适用本规定。"},{"i":23,"n":"第二十三条","txt":"本规定施行后，案件尚在一审或者二审阶段的，适用本规定；本规定施行前已经终审的案件，人民法院进行再审时，不适用本规定。"},{"i":24,"n":"第二十四条","txt":"本规定施行前本院作出的有关司法解释与本规定相抵触的，以本规定为准。"}],"zuigaorenminfayuanguanyushenlicundanjiufenanjiandef27406":[{"i":1,"n":"第一条","txt":"存单纠纷案件的范围"},{"i":2,"n":"第二条","txt":"存单纠纷案件的案由"},{"i":3,"n":"第三条","txt":"存单纠纷案件的受理与中止"},{"i":4,"n":"第四条","txt":"存单纠纷案件的管辖"},{"i":5,"n":"第五条","txt":"对一般存单纠纷案件的认定和处理"},{"i":6,"n":"第六条","txt":"对以存单为表现形式的借贷纠纷案件的认定和处理"},{"i":7,"n":"第七条","txt":"对存单纠纷案件中存在的委托贷款关系和信托贷款关系的认定和纠纷的处理"},{"i":8,"n":"第八条","txt":"对存单质押的认定和处理"},{"i":9,"n":"第九条","txt":"其他"}],"zuigaorenminfayuanguanyushenligongshangbaoxianxing4fb62e":[{"i":1,"n":"第一条","txt":"人民法院审理工伤认定行政案件，在认定是否存在《工伤保险条例》第十四条第（六）项“本人主要责任”、第十六条第（二）项“醉酒或者吸毒”和第十六条第（三）项“自残或者自杀”等情形时，应当以有权机构出具的事故责任认定书、结论性意见和人民法院生效裁判等法律文书为依据，但有相反证据足以推翻事故责任认定书和结论性意见的除外。"},{"i":2,"n":"第二条","txt":"人民法院受理工伤认定行政案件后，发现原告或者第三人在提起行政诉讼前已经就是否存在劳动关系申请劳动仲裁或者提起民事诉讼的，应当中止行政案件的审理。"},{"i":3,"n":"第三条","txt":"社会保险行政部门认定下列单位为承担工伤保险责任单位的，人民法院应予支持："},{"i":4,"n":"第四条","txt":"社会保险行政部门认定下列情形为工伤的，人民法院应予支持："},{"i":5,"n":"第五条","txt":"社会保险行政部门认定下列情形为“因工外出期间”的，人民法院应予支持："},{"i":6,"n":"第六条","txt":"对社会保险行政部门认定下列情形为“上下班途中”的，人民法院应予支持："},{"i":7,"n":"第七条","txt":"由于不属于职工或者其近亲属自身原因超过工伤认定申请期限的，被耽误的时间不计算在工伤认定申请期限内。"},{"i":8,"n":"第八条","txt":"职工因第三人的原因受到伤害，社会保险行政部门以职工或者其近亲属已经对第三人提起民事诉讼或者获得民事赔偿为由，作出不予受理工伤认定申请或者不予认定工伤决定的，人民法院不予支持。"},{"i":9,"n":"第九条","txt":"因工伤认定申请人或者用人单位隐瞒有关情况或者提供虚假材料，导致工伤认定错误的，社会保险行政部门可以在诉讼中依法予以更正。"}],"zuigaorenminfayuanguanyushenlifangwudengjianjianruff515d":[{"i":1,"n":"第一条","txt":"公民、法人或者其他组织对房屋登记机构的房屋登记行为以及与查询、复制登记资料等事项相关的行政行为或者相应的不作为不服，提起行政诉讼的，人民法院应当依法受理。"},{"i":2,"n":"第二条","txt":"房屋登记机构根据人民法院、仲裁委员会的法律文书或者有权机关的协助执行通知书以及人民政府的征收决定办理的房屋登记行为，公民、法人或者其他组织不服提起行政诉讼的，人民法院不予受理，但公民、法人或者其他组织认为登记与有关文书内容不一致的除外。"},{"i":3,"n":"第三条","txt":"公民、法人或者其他组织对房屋登记行为不服提起行政诉讼的，不受下列情形的影响："},{"i":4,"n":"第四条","txt":"房屋登记机构为债务人办理房屋转移登记，债权人不服提起诉讼，符合下列情形之一的，人民法院应当依法受理："},{"i":5,"n":"第五条","txt":"同一房屋多次转移登记，原房屋权利人、原利害关系人对首次转移登记行为提起行政诉讼的，人民法院应当依法受理。"},{"i":6,"n":"第六条","txt":"人民法院受理房屋登记行政案件后，应当通知没有起诉的下列利害关系人作为第三人参加行政诉讼："},{"i":7,"n":"第七条","txt":"房屋登记行政案件由房屋所在地人民法院管辖，但有下列情形之一的也可由被告所在地人民法院管辖："},{"i":8,"n":"第八条","txt":"当事人以作为房屋登记行为基础的买卖、共有、赠与、抵押、婚姻、继承等民事法律关系无效或者应当撤销为由，对房屋登记行为提起行政诉讼的，人民法院应当告知当事人先行解决民事争议，民事争议处理期间不计算在行政诉讼起诉期限内；已经受理的，裁定中止诉讼。"},{"i":9,"n":"第九条","txt":"被告对被诉房屋登记行为的合法性负举证责任。被告保管证据原件的，应当在法庭上出示。被告不保管原件的，应当提交与原件核对一致的复印件、复制件并作出说明。当事人对被告提交的上述证据提出异议的，应当提供相应的证据。"},{"i":10,"n":"第十条","txt":"被诉房屋登记行为合法的，人民法院应当判决驳回原告的诉讼请求。"},{"i":11,"n":"第十一条","txt":"被诉房屋登记行为涉及多个权利主体或者房屋可分，其中部分主体或者房屋的登记违法应予撤销的，可以判决部分撤销。"},{"i":12,"n":"第十二条","txt":"申请人提供虚假材料办理房屋登记，给原告造成损害，房屋登记机构未尽合理审慎职责的，应当根据其过错程度及其在损害发生中所起作用承担相应的赔偿责任。"},{"i":13,"n":"第十三条","txt":"房屋登记机构工作人员与第三人恶意串通违法登记，侵犯原告合法权益的，房屋登记机构与第三人承担连带赔偿责任。"},{"i":14,"n":"第十四条","txt":"最高人民法院以前所作的相关的司法解释，凡与本规定不一致的，以本规定为准。"}],"zuigaorenminfayuanguanyushenlilvyoujiufenanjianshi553b7e":[{"i":1,"n":"第一条","txt":"本规定所称的旅游纠纷，是指旅游者与旅游经营者、旅游辅助服务者之间因旅游发生的合同纠纷或者侵权纠纷。"},{"i":2,"n":"第二条","txt":"以单位、家庭等集体形式与旅游经营者订立旅游合同，在履行过程中发生纠纷，除集体以合同一方当事人名义起诉外，旅游者个人提起旅游合同纠纷诉讼的，人民法院应予受理。"},{"i":3,"n":"第三条","txt":"因旅游经营者方面的同一原因造成旅游者人身损害、财产损失，旅游者选择请求旅游经营者承担违约责任或者侵权责任的，人民法院应当根据当事人选择的案由进行审理。"},{"i":4,"n":"第四条","txt":"因旅游辅助服务者的原因导致旅游经营者违约，旅游者仅起诉旅游经营者的，人民法院可以将旅游辅助服务者追加为第三人。"},{"i":5,"n":"第五条","txt":"旅游经营者已投保责任险，旅游者因保险责任事故仅起诉旅游经营者的，人民法院可以应当事人的请求将保险公司列为第三人。"},{"i":6,"n":"第六条","txt":"旅游经营者以格式条款、通知、声明、店堂告示等方式作出排除或者限制旅游者权利、减轻或者免除旅游经营者责任、加重旅游者责任等对旅游者不公平、不合理的规定，旅游者依据消费者权益保护法第二十六条的规定请求认定该内容无效的，人民法院应予支持。"},{"i":7,"n":"第七条","txt":"旅游经营者、旅游辅助服务者未尽到安全保障义务，造成旅游者人身损害、财产损失，旅游者请求旅游经营者、旅游辅助服务者承担责任的，人民法院应予支持。"},{"i":8,"n":"第八条","txt":"旅游经营者、旅游辅助服务者对可能危及旅游者人身、财产安全的旅游项目未履行告知、警示义务，造成旅游者人身损害、财产损失，旅游者请求旅游经营者、旅游辅助服务者承担责任的，人民法院应予支持。"},{"i":9,"n":"第九条","txt":"旅游经营者、旅游辅助服务者以非法收集、存储、使用、加工、传输、买卖、提供、公开等方式处理旅游者个人信息，旅游者请求其承担相应责任的，人民法院应予支持。"},{"i":10,"n":"第十条","txt":"旅游经营者将旅游业务转让给其他旅游经营者，旅游者不同意转让，请求解除旅游合同、追究旅游经营者违约责任的，人民法院应予支持。"},{"i":11,"n":"第十一条","txt":"除合同性质不宜转让或者合同另有约定之外，在旅游行程开始前的合理期间内，旅游者将其在旅游合同中的权利义务转让给第三人，请求确认转让合同效力的，人民法院应予支持。"},{"i":12,"n":"第十二条","txt":"旅游行程开始前或者进行中，因旅游者单方解除合同，旅游者请求旅游经营者退还尚未实际发生的费用，或者旅游经营者请求旅游者支付合理费用的，人民法院应予支持。"},{"i":13,"n":"第十三条","txt":"签订旅游合同的旅游经营者将其部分旅游业务委托旅游目的地的旅游经营者，因受托方未尽旅游合同义务，旅游者在旅游过程中受到损害，要求作出委托的旅游经营者承担赔偿责任的，人民法院应予支持。"},{"i":14,"n":"第十四条","txt":"旅游经营者准许他人挂靠其名下从事旅游业务，造成旅游者人身损害、财产损失，旅游者依据民法典第一千一百六十八条的规定请求旅游经营者与挂靠人承担连带责任的，人民法院应予支持。"},{"i":15,"n":"第十五条","txt":"旅游经营者违反合同约定，有擅自改变旅游行程、遗漏旅游景点、减少旅游服务项目、降低旅游服务标准等行为，旅游者请求旅游经营者赔偿未完成约定旅游服务项目等合理费用的，人民法院应予支持。"},{"i":16,"n":"第十六条","txt":"因飞机、火车、班轮、城际客运班车等公共客运交通工具延误，导致合同不能按照约定履行，旅游者请求旅游经营者退还未实际发生的费用的，人民法院应予支持。合同另有约定的除外。"},{"i":17,"n":"第十七条","txt":"旅游者在自行安排活动期间遭受人身损害、财产损失，旅游经营者未尽到必要的提示义务、救助义务，旅游者请求旅游经营者承担相应责任的，人民法院应予支持。"},{"i":18,"n":"第十八条","txt":"旅游者在旅游行程中未经导游或者领队许可，故意脱离团队，遭受人身损害、财产损失，请求旅游经营者赔偿损失的，人民法院不予支持。"},{"i":19,"n":"第十九条","txt":"旅游经营者或者旅游辅助服务者为旅游者代管的行李物品损毁、灭失，旅游者请求赔偿损失的，人民法院应予支持，但下列情形除外："},{"i":20,"n":"第二十条","txt":"旅游者要求旅游经营者返还下列费用的，人民法院应予支持："},{"i":21,"n":"第二十一条","txt":"旅游经营者因过错致其代办的手续、证件存在瑕疵，或者未尽妥善保管义务而遗失、毁损，旅游者请求旅游经营者补办或者协助补办相关手续、证件并承担相应费用的，人民法院应予支持。"},{"i":22,"n":"第二十二条","txt":"旅游经营者事先设计，并以确定的总价提供交通、住宿、游览等一项或者多项服务，不提供导游和领队服务，由旅游者自行安排游览行程的旅游过程中，旅游经营者提供的服务不符合合同约定，侵害旅游者合法权益，旅游者请求旅游经营者承担相应责任的，人民法院应予支持。"},{"i":23,"n":"第二十三条","txt":"本规定施行前已经终审，本规定施行后当事人申请再审或者按照审判监督程序决定再审的案件，不适用本规定。"}],"zuigaorenminfayuanguanyushenliwuzhengbentidanjiaofc3d305":[{"i":1,"n":"第一条","txt":"本规定所称正本提单包括记名提单、指示提单和不记名提单。"},{"i":2,"n":"第二条","txt":"承运人违反法律规定，无正本提单交付货物，损害正本提单持有人提单权利的，正本提单持有人可以要求承运人承担由此造成损失的民事责任。"},{"i":3,"n":"第三条","txt":"承运人因无正本提单交付货物造成正本提单持有人损失的，正本提单持有人可以要求承运人承担违约责任，或者承担侵权责任。"},{"i":4,"n":"第四条","txt":"承运人因无正本提单交付货物承担民事责任的，不适用海商法第五十六条关于限制赔偿责任的规定。"},{"i":5,"n":"第五条","txt":"提货人凭伪造的提单向承运人提取了货物，持有正本提单的收货人可以要求承运人承担无正本提单交付货物的民事责任。"},{"i":6,"n":"第六条","txt":"承运人因无正本提单交付货物造成正本提单持有人损失的赔偿额，按照货物装船时的价值加运费和保险费计算。"},{"i":7,"n":"第七条","txt":"承运人依照提单载明的卸货港所在地法律规定，必须将承运到港的货物交付给当地海关或者港口当局的，不承担无正本提单交付货物的民事责任。"},{"i":8,"n":"第八条","txt":"承运到港的货物超过法律规定期限无人向海关申报，被海关提取并依法变卖处理，或者法院依法裁定拍卖承运人留置的货物，承运人主张免除交付货物责任的，人民法院应予支持。"},{"i":9,"n":"第九条","txt":"承运人按照记名提单托运人的要求中止运输、返还货物、变更到达地或者将货物交给其他收货人，持有记名提单的收货人要求承运人承担无正本提单交付货物民事责任的，人民法院不予支持。"},{"i":10,"n":"第十条","txt":"承运人签发一式数份正本提单，向最先提交正本提单的人交付货物后，其他持有相同正本提单的人要求承运人承担无正本提单交付货物民事责任的，人民法院不予支持。"},{"i":11,"n":"第十一条","txt":"正本提单持有人可以要求无正本提单交付货物的承运人与无正本提单提取货物的人承担连带赔偿责任。"},{"i":12,"n":"第十二条","txt":"向承运人实际交付货物并持有指示提单的托运人，虽然在正本提单上没有载明其托运人身份，因承运人无正本提单交付货物，要求承运人依据海上货物运输合同承担无正本提单交付货物民事责任的，人民法院应予支持。"},{"i":13,"n":"第十三条","txt":"在承运人未凭正本提单交付货物后，正本提单持有人与无正本提单提取货物的人就货款支付达成协议，在协议款项得不到赔付时，不影响正本提单持有人就其遭受的损失，要求承运人承担无正本提单交付货物的民事责任。"},{"i":14,"n":"第十四条","txt":"正本提单持有人以承运人无正本提单交付货物为由提起的诉讼，适用海商法第二百五十七条的规定，时效期间为一年，自承运人应当交付货物之日起计算。"},{"i":15,"n":"第十五条","txt":"正本提单持有人以承运人无正本提单交付货物为由提起的诉讼，时效中断适用海商法第二百六十七条的规定。"}],"zuigaorenminfayuanguanyushenliqihuojiufenanjianruof4e324":[{"i":1,"n":"第一条","txt":"人民法院审理期货纠纷案件，应当依法保护当事人的合法权益，正确确定其应承担的风险责任，并维护期货市场秩序。"},{"i":2,"n":"第二条","txt":"人民法院审理期货合同纠纷案件，应当严格按照当事人在合同中的约定确定违约方承担的责任，当事人的约定违反法律、行政法规强制性规定的除外。"},{"i":3,"n":"第三条","txt":"人民法院审理期货侵权纠纷和无效的期货交易合同纠纷案件，应当根据各方当事人是否有过错，以及过错的性质、大小，过错和损失之间的因果关系，确定过错方承担的民事责任。"},{"i":4,"n":"第四条","txt":"人民法院应当依据民事诉讼法第二十三条、第二十八条和第三十四条的规定确定期货纠纷案件的管辖。"},{"i":5,"n":"第五条","txt":"在期货公司的分公司、营业部等分支机构进行期货交易的，该分支机构住所地为合同履行地。"},{"i":6,"n":"第六条","txt":"侵权与违约竞合的期货纠纷案件，依当事人选择的诉由确定管辖。当事人既以违约又以侵权起诉的，以当事人起诉状中在先的诉讼请求确定管辖。"},{"i":7,"n":"第七条","txt":"期货纠纷案件由中级人民法院管辖。"},{"i":8,"n":"第八条","txt":"期货公司的从业人员在本公司经营范围内从事期货交易行为产生的民事责任，由其所在的期货公司承担。"},{"i":9,"n":"第九条","txt":"期货公司授权非本公司人员以本公司的名义从事期货交易行为的，期货公司应当承担由此产生的民事责任；非期货公司人员以期货公司名义从事期货交易行为，具备民法典第一百七十二条所规定的表见代理条件的，期货公司应当承担由此产生的民事责任。"},{"i":10,"n":"第十条","txt":"公民、法人受期货公司或者客户的委托，作为居间人为其提供订约的机会或者订立期货经纪合同的中介服务的，期货公司或者客户应当按照约定向居间人支付报酬。居间人应当独立承担基于居间经纪关系所产生的民事责任。"},{"i":11,"n":"第十一条","txt":"不以真实身份从事期货交易的单位或者个人，交易行为符合期货交易所交易规则的，交易结果由其自行承担。"},{"i":12,"n":"第十二条","txt":"期货公司设立的取得营业执照和经营许可证的分公司、营业部等分支机构超出经营范围开展经营活动所产生的民事责任，该分支机构不能承担的，由期货公司承担。"},{"i":13,"n":"第十三条","txt":"有下列情形之一的，应当认定期货经纪合同无效："},{"i":14,"n":"第十四条","txt":"因期货经纪合同无效给客户造成经济损失的，应当根据无效行为与损失之间的因果关系确定责任的承担。一方的损失系对方行为所致，应当由对方赔偿损失；双方有过错的，根据过错大小各自承担相应的民事责任。"},{"i":15,"n":"第十五条","txt":"不具有主体资格的经营机构因从事期货经纪业务而导致期货经纪合同无效，该机构按客户的交易指令入市交易的，收取的佣金应当返还给客户，交易结果由客户承担。"},{"i":16,"n":"第十六条","txt":"期货公司在与客户订立期货经纪合同时，未提示客户注意《期货交易风险说明书》内容，并由客户签字或者盖章，对于客户在交易中的损失，应当依据民法典第五百条第三项的规定承担相应的赔偿责任。但是，根据以往交易结果记载，证明客户已有交易经历的，应当免除期货公司的责任。"},{"i":17,"n":"第十七条","txt":"期货公司接受客户全权委托进行期货交易的，对交易产生的损失，承担主要赔偿责任，赔偿额不超过损失的百分之八十，法律、行政法规另有规定的除外。"},{"i":18,"n":"第十八条","txt":"期货公司与客户签订的期货经纪合同对下达交易指令的方式未作约定或者约定不明确的，期货公司不能证明其所进行的交易是依据客户交易指令进行的，对该交易造成客户的损失，期货公司应当承担赔偿责任，客户予以追认的除外。"},{"i":19,"n":"第十九条","txt":"期货公司执行非受托人的交易指令造成客户损失，应当由期货公司承担赔偿责任，非受托人承担连带责任，客户予以追认的除外。"},{"i":20,"n":"第二十条","txt":"客户下达的交易指令没有品种、数量、买卖方向的，期货公司未予拒绝而进行交易造成客户的损失，由期货公司承担赔偿责任，客户予以追认的除外。"},{"i":21,"n":"第二十一条","txt":"客户下达的交易指令数量和买卖方向明确，没有有效期限的，应当视为当日有效；没有成交价格的，应当视为按市价交易；没有开平仓方向的，应当视为开仓交易。"},{"i":22,"n":"第二十二条","txt":"期货公司错误执行客户交易指令，除客户认可的以外，交易的后果由期货公司承担，并按下列方式分别处理："},{"i":23,"n":"第二十三条","txt":"期货公司不当延误执行客户交易指令给客户造成损失的，应当承担赔偿责任，但由于市场原因致客户交易指令未能全部或者部分成交的，期货公司不承担责任。"},{"i":24,"n":"第二十四条","txt":"期货公司超出客户指令价位的范围，将高于客户指令价格卖出或者低于客户指令价格买入后的差价利益占为己有的，客户要求期货公司返还的，人民法院应予支持，期货公司与客户另有约定的除外。"},{"i":25,"n":"第二十五条","txt":"期货交易所未按交易规则规定的期限、方式，将交易或者持仓头寸的结算结果通知期货公司，造成期货公司损失的，由期货交易所承担赔偿责任。"},{"i":26,"n":"第二十六条","txt":"期货公司与客户对交易结算结果的通知方式未作约定或者约定不明确，期货公司未能提供证据证明已经发出上述通知的，对客户因继续持仓而造成扩大的损失，应当承担主要赔偿责任，赔偿额不超过损失的百分之八十。"},{"i":27,"n":"第二十七条","txt":"客户对当日交易结算结果的确认，应当视为对该日之前所有持仓和交易结算结果的确认，所产生的交易后果由客户自行承担。"},{"i":28,"n":"第二十八条","txt":"期货公司对交易结算结果提出异议，期货交易所未及时采取措施导致损失扩大的，对造成期货公司扩大的损失应当承担赔偿责任。"},{"i":29,"n":"第二十九条","txt":"期货公司对期货交易所或者客户对期货公司的交易结算结果有异议，而未在期货交易所交易规则规定或者期货经纪合同约定的时间内提出的，视为期货公司或者客户对交易结算结果已予以确认。"},{"i":30,"n":"第三十条","txt":"期货公司进行混码交易的，客户不承担责任，但期货公司能够举证证明其已按照客户交易指令入市交易的，客户应当承担相应的交易结果。"},{"i":31,"n":"第三十一条","txt":"期货交易所在期货公司没有保证金或者保证金不足的情况下，允许期货公司开仓交易或者继续持仓，应当认定为透支交易。"},{"i":32,"n":"第三十二条","txt":"期货公司的交易保证金不足，期货交易所未按规定通知期货公司追加保证金的，由于行情向持仓不利的方向变化导致期货公司透支发生的扩大损失，期货交易所应当承担主要赔偿责任，赔偿额不超过损失的百分之六十。"},{"i":33,"n":"第三十三条","txt":"期货公司的交易保证金不足，期货交易所履行了通知义务，而期货公司未及时追加保证金，期货公司要求保留持仓并经书面协商一致的，对保留持仓期间造成的损失，由期货公司承担；穿仓造成的损失，由期货交易所承担。"},{"i":34,"n":"第三十四条","txt":"期货交易所允许期货公司开仓透支交易的，对透支交易造成的损失，由期货交易所承担主要赔偿责任，赔偿额不超过损失的百分之六十。"},{"i":35,"n":"第三十五条","txt":"期货交易所允许期货公司透支交易，并与其约定分享利益，共担风险的，对透支交易造成的损失，期货交易所承担相应的赔偿责任。"},{"i":36,"n":"第三十六条","txt":"期货公司的交易保证金不足，又未能按期货交易所规定的时间追加保证金的，按交易规则的规定处理；规定不明确的，期货交易所有权就其未平仓的期货合约强行平仓，强行平仓所造成的损失，由期货公司承担。"},{"i":37,"n":"第三十七条","txt":"期货交易所因期货公司违规超仓或者其他违规行为而必须强行平仓的，强行平仓所造成的损失，由期货公司承担。"},{"i":38,"n":"第三十八条","txt":"期货公司或者客户交易保证金不足，符合强行平仓条件后，应当自行平仓而未平仓造成的扩大损失，由期货公司或者客户自行承担。法律、行政法规另有规定或者当事人另有约定的除外。"},{"i":39,"n":"第三十九条","txt":"期货交易所或者期货公司强行平仓数额应当与期货公司或者客户需追加的保证金数额基本相当。因超量平仓引起的损失，由强行平仓者承担。"},{"i":40,"n":"第四十条","txt":"期货交易所对期货公司、期货公司对客户未按期货交易所交易规则规定或者期货经纪合同约定的强行平仓条件、时间、方式进行强行平仓，造成期货公司或者客户损失的，期货交易所或者期货公司应当承担赔偿责任。"},{"i":41,"n":"第四十一条","txt":"期货交易所依法或依交易规则强行平仓发生的费用，由被平仓的期货公司承担；期货公司承担责任后有权向有过错的客户追偿。"},{"i":42,"n":"第四十二条","txt":"交割仓库未履行货物验收职责或者因保管不善给仓单持有人造成损失的，应当承担赔偿责任。"},{"i":43,"n":"第四十三条","txt":"期货公司没有代客户履行申请交割义务的，应当承担违约责任；造成客户损失的，应当承担赔偿责任。"},{"i":44,"n":"第四十四条","txt":"在交割日，卖方期货公司未向期货交易所交付标准仓单，或者买方期货公司未向期货交易所账户交付足额货款，构成交割违约。"},{"i":45,"n":"第四十五条","txt":"在期货合约交割期内，买方或者卖方客户违约的，期货交易所应当代期货公司、期货公司应当代客户向对方承担违约责任。"},{"i":46,"n":"第四十六条","txt":"买方客户未在期货交易所交易规则规定的期限内对货物的质量、数量提出异议的，应视为其对货物的数量、质量无异议。"},{"i":47,"n":"第四十七条","txt":"交割仓库不能在期货交易所交易规则规定的期限内，向标准仓单持有人交付符合期货合约要求的货物，造成标准仓单持有人损失的，交割仓库应当承担责任，期货交易所承担连带责任。"},{"i":48,"n":"第四十八条","txt":"期货公司未按照每日无负债结算制度的要求，履行相应的金钱给付义务，期货交易所亦未代期货公司履行，造成交易对方损失的，期货交易所应当承担赔偿责任。"},{"i":49,"n":"第四十九条","txt":"期货交易所未代期货公司履行期货合约，期货公司应当根据客户请求向期货交易所主张权利。"},{"i":50,"n":"第五十条","txt":"因期货交易所的过错导致信息发布、交易指令处理错误，造成期货公司或者客户直接经济损失的，期货交易所应当承担赔偿责任，但其能够证明系不可抗力的除外。"},{"i":51,"n":"第五十一条","txt":"期货交易所依据有关规定对期货市场出现的异常情况采取合理的紧急措施造成客户损失的，期货交易所不承担赔偿责任。"},{"i":52,"n":"第五十二条","txt":"期货交易所、期货公司故意提供虚假信息误导客户下单的，由此造成客户的经济损失由期货交易所、期货公司承担。"},{"i":53,"n":"第五十三条","txt":"期货公司私下对冲、与客户对赌等不将客户指令入市交易的行为，应当认定为无效，期货公司应当赔偿由此给客户造成的经济损失；期货公司与客户均有过错的，应当根据过错大小，分别承担相应的赔偿责任。"},{"i":54,"n":"第五十四条","txt":"期货公司擅自以客户的名义进行交易，客户对交易结果不予追认的，所造成的损失由期货公司承担。"},{"i":55,"n":"第五十五条","txt":"期货公司挪用客户保证金，或者违反有关规定划转客户保证金造成客户损失的，应当承担赔偿责任。"},{"i":56,"n":"第五十六条","txt":"期货公司应当对客户的交易指令是否入市交易承担举证责任。"},{"i":57,"n":"第五十七条","txt":"期货交易所通知期货公司追加保证金，期货公司否认收到上述通知的，由期货交易所承担举证责任。"},{"i":58,"n":"第五十八条","txt":"人民法院保全与会员资格相应的会员资格费或者交易席位，应当依法裁定不得转让该会员资格，但不得停止该会员交易席位的使用。人民法院在执行过程中，有权依法采取强制措施转让该交易席位。"},{"i":59,"n":"第五十九条","txt":"期货交易所、期货公司为债务人的，人民法院不得冻结、划拨期货公司在期货交易所或者客户在期货公司保证金账户中的资金。"},{"i":60,"n":"第六十条","txt":"期货公司为债务人的，人民法院不得冻结、划拨专用结算账户中未被期货合约占用的用于担保期货合约履行的最低限额的结算准备金；期货公司已经结清所有持仓并清偿客户资金的，人民法院可以对结算准备金依法予以冻结、划拨。"},{"i":61,"n":"第六十一条","txt":"客户、自营会员为债务人的，人民法院可以对其保证金、持仓依法采取保全和执行措施。"},{"i":62,"n":"第六十二条","txt":"本规定所称期货公司是指经依法批准代理投资者从事期货交易业务的经营机构及其分公司、营业部等分支机构。客户是指委托期货公司从事期货交易的投资者。"},{"i":63,"n":"第六十三条","txt":"本规定自2003年7月1日起施行。"}],"zuigaorenminfayuanguanyushenliqihuojiufenanjianruod7d5f0":[{"i":1,"n":"第一条","txt":"以期货交易所为被告或者第三人的因期货交易所履行职责引起的商事案件，由期货交易所所在地的中级人民法院管辖。"},{"i":2,"n":"第二条","txt":"期货交易所履行职责引起的商事案件是指："},{"i":3,"n":"第三条","txt":"期货交易所为债务人，债权人请求冻结、划拨以下账户中资金或者有价证券的，人民法院不予支持："},{"i":4,"n":"第四条","txt":"期货公司为债务人，债权人请求冻结、划拨以下账户中资金或者有价证券的，人民法院不予支持："},{"i":5,"n":"第五条","txt":"实行会员分级结算制度的期货交易所的结算会员为债务人，债权人请求冻结、划拨结算会员以下资金或者有价证券的，人民法院不予支持："},{"i":6,"n":"第六条","txt":"有证据证明保证金账户中有超过上述第三条、第四条、第五条规定的资金或者有价证券部分权益的，期货交易所、期货公司或者期货交易所结算会员在人民法院指定的合理期限内不能提出相反证据的，人民法院可以依法冻结、划拨超出部分的资金或者有价证券。"},{"i":7,"n":"第七条","txt":"实行会员分级结算制度的期货交易所或者其结算会员为债务人，债权人请求冻结、划拨期货交易所向其结算会员依法收取的结算担保金的，人民法院不予支持。"},{"i":8,"n":"第八条","txt":"人民法院在办理案件过程中，依法需要通过期货交易所、期货公司查询、冻结、划拨资金或者有价证券的，期货交易所、期货公司应当予以协助。应当协助而拒不协助的，按照《中华人民共和国民事诉讼法》第一百一十四条之规定办理。"},{"i":9,"n":"第九条","txt":"本规定施行前已经受理的上述案件不再移送。"},{"i":10,"n":"第十条","txt":"本规定施行前本院作出的有关司法解释与本规定不一致的，以本规定为准。"}],"zuigaorenminfayuanguanyushenliminshianjianshiyongs995f16":[{"i":1,"n":"第一条","txt":"当事人可以对债权请求权提出诉讼时效抗辩，但对下列债权请求权提出诉讼时效抗辩的，人民法院不予支持："},{"i":2,"n":"第二条","txt":"当事人未提出诉讼时效抗辩，人民法院不应对诉讼时效问题进行释明。"},{"i":3,"n":"第三条","txt":"当事人在一审期间未提出诉讼时效抗辩，在二审期间提出的，人民法院不予支持，但其基于新的证据能够证明对方当事人的请求权已过诉讼时效期间的情形除外。"},{"i":4,"n":"第四条","txt":"未约定履行期限的合同，依照民法典第五百一十条、第五百一十一条的规定，可以确定履行期限的，诉讼时效期间从履行期限届满之日起计算；不能确定履行期限的，诉讼时效期间从债权人要求债务人履行义务的宽限期届满之日起计算，但债务人在债权人第一次向其主张权利之时明确表示不履行义务的，诉讼时效期间从债务人明确表示不履行义务之日起计算。"},{"i":5,"n":"第五条","txt":"享有撤销权的当事人一方请求撤销合同的，应适用民法典关于除斥期间的规定。对方当事人对撤销合同请求权提出诉讼时效抗辩的，人民法院不予支持。"},{"i":6,"n":"第六条","txt":"返还不当得利请求权的诉讼时效期间，从当事人一方知道或者应当知道不当得利事实及对方当事人之日起计算。"},{"i":7,"n":"第七条","txt":"管理人因无因管理行为产生的给付必要管理费用、赔偿损失请求权的诉讼时效期间，从无因管理行为结束并且管理人知道或者应当知道本人之日起计算。"},{"i":8,"n":"第八条","txt":"具有下列情形之一的，应当认定为民法典第一百九十五条规定的“权利人向义务人提出履行请求”，产生诉讼时效中断的效力："},{"i":9,"n":"第九条","txt":"权利人对同一债权中的部分债权主张权利，诉讼时效中断的效力及于剩余债权，但权利人明确表示放弃剩余债权的情形除外。"},{"i":10,"n":"第十条","txt":"当事人一方向人民法院提交起诉状或者口头起诉的，诉讼时效从提交起诉状或者口头起诉之日起中断。"},{"i":11,"n":"第十一条","txt":"下列事项之一，人民法院应当认定与提起诉讼具有同等诉讼时效中断的效力："},{"i":12,"n":"第十二条","txt":"权利人向人民调解委员会以及其他依法有权解决相关民事纠纷的国家机关、事业单位、社会团体等社会组织提出保护相应民事权利的请求，诉讼时效从提出请求之日起中断。"},{"i":13,"n":"第十三条","txt":"权利人向公安机关、人民检察院、人民法院报案或者控告，请求保护其民事权利的，诉讼时效从其报案或者控告之日起中断。"},{"i":14,"n":"第十四条","txt":"义务人作出分期履行、部分履行、提供担保、请求延期履行、制定清偿债务计划等承诺或者行为的，应当认定为民法典第一百九十五条规定的“义务人同意履行义务”。"},{"i":15,"n":"第十五条","txt":"对于连带债权人中的一人发生诉讼时效中断效力的事由，应当认定对其他连带债权人也发生诉讼时效中断的效力。"},{"i":16,"n":"第十六条","txt":"债权人提起代位权诉讼的，应当认定对债权人的债权和债务人的债权均发生诉讼时效中断的效力。"},{"i":17,"n":"第十七条","txt":"债权转让的，应当认定诉讼时效从债权转让通知到达债务人之日起中断。"},{"i":18,"n":"第十八条","txt":"主债务诉讼时效期间届满，保证人享有主债务人的诉讼时效抗辩权。"},{"i":19,"n":"第十九条","txt":"诉讼时效期间届满，当事人一方向对方当事人作出同意履行义务的意思表示或者自愿履行义务后，又以诉讼时效期间届满为由进行抗辩的，人民法院不予支持。"},{"i":20,"n":"第二十条","txt":"本规定施行后，案件尚在一审或者二审阶段的，适用本规定；本规定施行前已经终审的案件，人民法院进行再审时，不适用本规定。"},{"i":21,"n":"第二十一条","txt":"本规定施行前本院作出的有关司法解释与本规定相抵触的，以本规定为准。"}],"zuigaorenminfayuanguanyushenliminshijibieguanxiayi978b52":[{"i":1,"n":"第一条","txt":"被告在提交答辩状期间提出管辖权异议，认为受诉人民法院违反级别管辖规定，案件应当由上级人民法院或者下级人民法院管辖的，受诉人民法院应当审查，并在受理异议之日起十五日内作出裁定："},{"i":2,"n":"第二条","txt":"在管辖权异议裁定作出前，原告申请撤回起诉，受诉人民法院作出准予撤回起诉裁定的，对管辖权异议不再审查，并在裁定书中一并写明。"},{"i":3,"n":"第三条","txt":"提交答辩状期间届满后，原告增加诉讼请求金额致使案件标的额超过受诉人民法院级别管辖标准，被告提出管辖权异议，请求由上级人民法院管辖的，人民法院应当按照本规定第一条审查并作出裁定。"},{"i":4,"n":"第四条","txt":"对于应由上级人民法院管辖的第一审民事案件，下级人民法院不得报请上级人民法院交其审理。"},{"i":5,"n":"第五条","txt":"被告以受诉人民法院同时违反级别管辖和地域管辖规定为由提出管辖权异议的，受诉人民法院应当一并作出裁定。"},{"i":6,"n":"第六条","txt":"当事人未依法提出管辖权异议，但受诉人民法院发现其没有级别管辖权的，应当将案件移送有管辖权的人民法院审理。"},{"i":7,"n":"第七条","txt":"对人民法院就级别管辖异议作出的裁定，当事人不服提起上诉的，第二审人民法院应当依法审理并作出裁定。"},{"i":8,"n":"第八条","txt":"对于将案件移送上级人民法院管辖的裁定，当事人未提出上诉，但受移送的上级人民法院认为确有错误的，可以依职权裁定撤销。"},{"i":9,"n":"第九条","txt":"经最高人民法院批准的第一审民事案件级别管辖标准的规定，应当作为审理民事级别管辖异议案件的依据。"},{"i":10,"n":"第十条","txt":"本规定施行前颁布的有关司法解释与本规定不一致的，以本规定为准。"}],"zuigaorenminfayuanguanyushenliminjianjiedaianjians1575d9":[{"i":1,"n":"第一条","txt":"本规定所称的民间借贷，是指自然人、法人和非法人组织之间进行资金融通的行为。"},{"i":2,"n":"第二条","txt":"出借人向人民法院提起民间借贷诉讼时，应当提供借据、收据、欠条等债权凭证以及其他能够证明借贷法律关系存在的证据。"},{"i":3,"n":"第三条","txt":"借贷双方就合同履行地未约定或者约定不明确，事后未达成补充协议，按照合同相关条款或者交易习惯仍不能确定的，以接受货币一方所在地为合同履行地。"},{"i":4,"n":"第四条","txt":"保证人为借款人提供连带责任保证，出借人仅起诉借款人的，人民法院可以不追加保证人为共同被告；出借人仅起诉保证人的，人民法院可以追加借款人为共同被告。"},{"i":5,"n":"第五条","txt":"人民法院立案后，发现民间借贷行为本身涉嫌非法集资等犯罪的，应当裁定驳回起诉，并将涉嫌非法集资等犯罪的线索、材料移送公安或者检察机关。"},{"i":6,"n":"第六条","txt":"人民法院立案后，发现与民间借贷纠纷案件虽有关联但不是同一事实的涉嫌非法集资等犯罪的线索、材料的，人民法院应当继续审理民间借贷纠纷案件，并将涉嫌非法集资等犯罪的线索、材料移送公安或者检察机关。"},{"i":7,"n":"第七条","txt":"民间借贷纠纷的基本案件事实必须以刑事案件的审理结果为依据，而该刑事案件尚未审结的，人民法院应当裁定中止诉讼。"},{"i":8,"n":"第八条","txt":"借款人涉嫌犯罪或者生效判决认定其有罪，出借人起诉请求担保人承担民事责任的，人民法院应予受理。"},{"i":9,"n":"第九条","txt":"自然人之间的借款合同具有下列情形之一的，可以视为合同成立："},{"i":10,"n":"第十条","txt":"法人之间、非法人组织之间以及它们相互之间为生产、经营需要订立的民间借贷合同，除存在民法典第一百四十六条、第一百五十三条、第一百五十四条以及本规定第十三条规定的情形外，当事人主张民间借贷合同有效的，人民法院应予支持。"},{"i":11,"n":"第十一条","txt":"法人或者非法人组织在本单位内部通过借款形式向职工筹集资金，用于本单位生产、经营，且不存在民法典第一百四十四条、第一百四十六条、第一百五十三条、第一百五十四条以及本规定第十三条规定的情形，当事人主张民间借贷合同有效的，人民法院应予支持。"},{"i":12,"n":"第十二条","txt":"借款人或者出借人的借贷行为涉嫌犯罪，或者已经生效的裁判认定构成犯罪，当事人提起民事诉讼的，民间借贷合同并不当然无效。人民法院应当依据民法典第一百四十四条、第一百四十六条、第一百五十三条、第一百五十四条以及本规定第十三条之规定，认定民间借贷合同的效力。"},{"i":13,"n":"第十三条","txt":"具有下列情形之一的，人民法院应当认定民间借贷合同无效："},{"i":14,"n":"第十四条","txt":"原告以借据、收据、欠条等债权凭证为依据提起民间借贷诉讼，被告依据基础法律关系提出抗辩或者反诉，并提供证据证明债权纠纷非民间借贷行为引起的，人民法院应当依据查明的案件事实，按照基础法律关系审理。"},{"i":15,"n":"第十五条","txt":"原告仅依据借据、收据、欠条等债权凭证提起民间借贷诉讼，被告抗辩已经偿还借款的，被告应当对其主张提供证据证明。被告提供相应证据证明其主张后，原告仍应就借贷关系的存续承担举证责任。"},{"i":16,"n":"第十六条","txt":"原告仅依据金融机构的转账凭证提起民间借贷诉讼，被告抗辩转账系偿还双方之前借款或者其他债务的，被告应当对其主张提供证据证明。被告提供相应证据证明其主张后，原告仍应就借贷关系的成立承担举证责任。"},{"i":17,"n":"第十七条","txt":"依据《最高人民法院关于适用〈中华人民共和国民事诉讼法〉的解释》第一百七十四条第二款之规定，负有举证责任的原告无正当理由拒不到庭，经审查现有证据无法确认借贷行为、借贷金额、支付方式等案件主要事实的，人民法院对原告主张的事实不予认定。"},{"i":18,"n":"第十八条","txt":"人民法院审理民间借贷纠纷案件时发现有下列情形之一的，应当严格审查借贷发生的原因、时间、地点、款项来源、交付方式、款项流向以及借贷双方的关系、经济状况等事实，综合判断是否属于虚假民事诉讼："},{"i":19,"n":"第十九条","txt":"经查明属于虚假民间借贷诉讼，原告申请撤诉的，人民法院不予准许，并应当依据民事诉讼法第一百一十二条之规定，判决驳回其请求。"},{"i":20,"n":"第二十条","txt":"他人在借据、收据、欠条等债权凭证或者借款合同上签名或者盖章，但是未表明其保证人身份或者承担保证责任，或者通过其他事实不能推定其为保证人，出借人请求其承担保证责任的，人民法院不予支持。"},{"i":21,"n":"第二十一条","txt":"借贷双方通过网络贷款平台形成借贷关系，网络贷款平台的提供者仅提供媒介服务，当事人请求其承担担保责任的，人民法院不予支持。"},{"i":22,"n":"第二十二条","txt":"法人的法定代表人或者非法人组织的负责人以单位名义与出借人签订民间借贷合同，有证据证明所借款项系法定代表人或者负责人个人使用，出借人请求将法定代表人或者负责人列为共同被告或者第三人的，人民法院应予准许。"},{"i":23,"n":"第二十三条","txt":"当事人以订立买卖合同作为民间借贷合同的担保，借款到期后借款人不能还款，出借人请求履行买卖合同的，人民法院应当按照民间借贷法律关系审理。当事人根据法庭审理情况变更诉讼请求的，人民法院应当准许。"},{"i":24,"n":"第二十四条","txt":"借贷双方没有约定利息，出借人主张支付利息的，人民法院不予支持。"},{"i":25,"n":"第二十五条","txt":"出借人请求借款人按照合同约定利率支付利息的，人民法院应予支持，但是双方约定的利率超过合同成立时一年期贷款市场报价利率四倍的除外。"},{"i":26,"n":"第二十六条","txt":"借据、收据、欠条等债权凭证载明的借款金额，一般认定为本金。预先在本金中扣除利息的，人民法院应当将实际出借的金额认定为本金。"},{"i":27,"n":"第二十七条","txt":"借贷双方对前期借款本息结算后将利息计入后期借款本金并重新出具债权凭证，如果前期利率没有超过合同成立时一年期贷款市场报价利率四倍，重新出具的债权凭证载明的金额可认定为后期借款本金。超过部分的利息，不应认定为后期借款本金。"},{"i":28,"n":"第二十八条","txt":"借贷双方对逾期利率有约定的，从其约定，但是以不超过合同成立时一年期贷款市场报价利率四倍为限。"},{"i":29,"n":"第二十九条","txt":"出借人与借款人既约定了逾期利率，又约定了违约金或者其他费用，出借人可以选择主张逾期利息、违约金或者其他费用，也可以一并主张，但是总计超过合同成立时一年期贷款市场报价利率四倍的部分，人民法院不予支持。"},{"i":30,"n":"第三十条","txt":"借款人可以提前偿还借款，但是当事人另有约定的除外。"},{"i":31,"n":"第三十一条","txt":"本规定施行后，人民法院新受理的一审民间借贷纠纷案件，适用本规定。"}],"zuigaorenminfayuanguanyushenlizhuceshangbiaoqiyemica3a80":[{"i":1,"n":"第一条","txt":"原告以他人注册商标使用的文字、图形等侵犯其著作权、外观设计专利权、企业名称权等在先权利为由提起诉讼，符合民事诉讼法第一百一十九条规定的，人民法院应当受理。"},{"i":2,"n":"第二条","txt":"原告以他人企业名称与其在先的企业名称相同或者近似，足以使相关公众对其商品的来源产生混淆，违反反不正当竞争法第六条第（二）项的规定为由提起诉讼，符合民事诉讼法第一百一十九条规定的，人民法院应当受理。"},{"i":3,"n":"第三条","txt":"人民法院应当根据原告的诉讼请求和争议民事法律关系的性质，按照民事案件案由规定，确定注册商标或者企业名称与在先权利冲突的民事纠纷案件的案由，并适用相应的法律。"},{"i":4,"n":"第四条","txt":"被诉企业名称侵犯注册商标专用权或者构成不正当竞争的，人民法院可以根据原告的诉讼请求和案件具体情况，确定被告承担停止使用、规范使用等民事责任。"}],"zuigaorenminfayuanguanyushenlihaishangbaoxianjiufead66e9":[{"i":1,"n":"第一条","txt":"审理海上保险合同纠纷案件，适用海商法的规定；海商法没有规定的，适用保险法的有关规定；海商法、保险法均没有规定的，适用民法典等其他相关法律的规定。"},{"i":2,"n":"第二条","txt":"审理非因海上事故引起的港口设施或者码头作为保险标的的保险合同纠纷案件，适用保险法等法律的规定。"},{"i":3,"n":"第三条","txt":"审理保险人因发生船舶触碰港口设施或者码头等保险事故，行使代位请求赔偿权利向造成保险事故的第三人追偿的案件，适用海商法的规定。"},{"i":4,"n":"第四条","txt":"保险人知道被保险人未如实告知海商法第二百二十二条第一款规定的重要情况，仍收取保险费或者支付保险赔偿，保险人又以被保险人未如实告知重要情况为由请求解除合同的，人民法院不予支持。"},{"i":5,"n":"第五条","txt":"被保险人未按照海商法第二百三十四条的规定向保险人支付约定的保险费的，保险责任开始前，保险人有权解除保险合同，但保险人已经签发保险单证的除外；保险责任开始后，保险人以被保险人未支付保险费请求解除合同的，人民法院不予支持。"},{"i":6,"n":"第六条","txt":"保险人以被保险人违反合同约定的保证条款未立即书面通知保险人为由，要求从违反保证条款之日起解除保险合同的，人民法院应予支持。"},{"i":7,"n":"第七条","txt":"保险人收到被保险人违反合同约定的保证条款书面通知后仍支付保险赔偿，又以被保险人违反合同约定的保证条款为由请求解除合同的，人民法院不予支持。"},{"i":8,"n":"第八条","txt":"保险人收到被保险人违反合同约定的保证条款的书面通知后，就修改承保条件、增加保险费等事项与被保险人协商未能达成一致的，保险合同于违反保证条款之日解除。"},{"i":9,"n":"第九条","txt":"在航次之中发生船舶转让的，未经保险人同意转让的船舶保险合同至航次终了时解除。船舶转让时起至航次终了时止的船舶保险合同的权利、义务由船舶出让人享有、承担，也可以由船舶受让人继受。"},{"i":10,"n":"第十条","txt":"保险人与被保险人在订立保险合同时均不知道保险标的已经发生保险事故而遭受损失，或者保险标的已经不可能因发生保险事故而遭受损失的，不影响保险合同的效力。"},{"i":11,"n":"第十一条","txt":"海上货物运输中因承运人无正本提单交付货物造成的损失不属于保险人的保险责任范围。保险合同当事人另有约定的，依约定。"},{"i":12,"n":"第十二条","txt":"发生保险事故后，被保险人为防止或者减少损失而采取的合理措施没有效果，要求保险人支付由此产生的合理费用的，人民法院应予支持。"},{"i":13,"n":"第十三条","txt":"保险人在行使代位请求赔偿权利时，未依照海事诉讼特别程序法的规定，向人民法院提交其已经向被保险人实际支付保险赔偿凭证的，人民法院不予受理；已经受理的，裁定驳回起诉。"},{"i":14,"n":"第十四条","txt":"受理保险人行使代位请求赔偿权利纠纷案件的人民法院应当仅就造成保险事故的第三人与被保险人之间的法律关系进行审理。"},{"i":15,"n":"第十五条","txt":"保险人取得代位请求赔偿权利后，以被保险人向第三人提起诉讼、提交仲裁、申请扣押船舶或者第三人同意履行义务为由主张诉讼时效中断的，人民法院应予支持。"},{"i":16,"n":"第十六条","txt":"保险人取得代位请求赔偿权利后，主张享有被保险人因申请扣押船舶取得的担保权利的，人民法院应予支持。"},{"i":17,"n":"第十七条","txt":"本规定自2007年1月1日起施行。"}],"zuigaorenminfayuanguanyushenlihaishanghuoyundailijad5321":[{"i":1,"n":"第一条","txt":"本规定适用于货运代理企业接受委托人委托处理与海上货物运输有关的货运代理事务时发生的下列纠纷："},{"i":2,"n":"第二条","txt":"人民法院审理海上货运代理纠纷案件，认定货运代理企业因处理海上货运代理事务与委托人之间形成代理、运输、仓储等不同法律关系的，应分别适用相关的法律规定。"},{"i":3,"n":"第三条","txt":"人民法院应根据书面合同约定的权利义务的性质，并综合考虑货运代理企业取得报酬的名义和方式、开具发票的种类和收费项目、当事人之间的交易习惯以及合同实际履行的其他情况，认定海上货运代理合同关系是否成立。"},{"i":4,"n":"第四条","txt":"货运代理企业在处理海上货运代理事务过程中以自己的名义签发提单、海运单或者其他运输单证，委托人据此主张货运代理企业承担承运人责任的，人民法院应予支持。"},{"i":5,"n":"第五条","txt":"委托人与货运代理企业约定了转委托权限，当事人就权限范围内的海上货运代理事务主张委托人同意转委托的，人民法院应予支持。"},{"i":6,"n":"第六条","txt":"一方当事人根据双方的交易习惯，有理由相信行为人有权代表对方当事人订立海上货运代理合同，该方当事人依据民法典第一百七十二条的规定主张合同成立的，人民法院应予支持。"},{"i":7,"n":"第七条","txt":"海上货运代理合同约定货运代理企业交付处理海上货运代理事务取得的单证以委托人支付相关费用为条件，货运代理企业以委托人未支付相关费用为由拒绝交付单证的，人民法院应予支持。"},{"i":8,"n":"第八条","txt":"货运代理企业接受契约托运人的委托办理订舱事务，同时接受实际托运人的委托向承运人交付货物，实际托运人请求货运代理企业交付其取得的提单、海运单或者其他运输单证的，人民法院应予支持。"},{"i":9,"n":"第九条","txt":"货运代理企业按照概括委托权限完成海上货运代理事务，请求委托人支付相关合理费用的，人民法院应予支持。"},{"i":10,"n":"第十条","txt":"委托人以货运代理企业处理海上货运代理事务给委托人造成损失为由，主张由货运代理企业承担相应赔偿责任的，人民法院应予支持，但货运代理企业证明其没有过错的除外。"},{"i":11,"n":"第十一条","txt":"货运代理企业未尽谨慎义务，与未在我国交通主管部门办理提单登记的无船承运业务经营者订立海上货物运输合同，造成委托人损失的，应承担相应的赔偿责任。"},{"i":12,"n":"第十二条","txt":"货运代理企业接受未在我国交通主管部门办理提单登记的无船承运业务经营者的委托签发提单，当事人主张由货运代理企业和无船承运业务经营者对提单项下的损失承担连带责任的，人民法院应予支持。"},{"i":13,"n":"第十三条","txt":"因本规定第一条所列纠纷提起的诉讼，由海事法院管辖。"},{"i":14,"n":"第十四条","txt":"人民法院在案件审理过程中，发现不具有无船承运业务经营资格的货运代理企业违反《中华人民共和国国际海运条例》的规定，以自己的名义签发提单、海运单或者其他运输单证的，应当向有关交通主管部门发出司法建议，建议交通主管部门予以处罚。"},{"i":15,"n":"第十五条","txt":"本规定不适用于与沿海、内河货物运输有关的货运代理纠纷案件。"},{"i":16,"n":"第十六条","txt":"本规定施行前本院作出的有关司法解释与本规定相抵触的，以本规定为准。"}],"zuigaorenminfayuanguanyushenlihaishipeichangzerenx8d5d4d":[{"i":1,"n":"第一条","txt":"审理海事赔偿责任限制相关纠纷案件，适用海事诉讼特别程序法、海商法的规定；海事诉讼特别程序法、海商法没有规定的，适用其他相关法律、行政法规的规定。"},{"i":2,"n":"第二条","txt":"同一海事事故中，不同的责任人在起诉前依据海事诉讼特别程序法第一百零二条的规定向不同的海事法院申请设立海事赔偿责任限制基金的，后立案的海事法院应当依照民事诉讼法的规定，将案件移送先立案的海事法院管辖。"},{"i":3,"n":"第三条","txt":"责任人在诉讼中申请设立海事赔偿责任限制基金的，应当向受理相关海事纠纷案件的海事法院提出。"},{"i":4,"n":"第四条","txt":"海事赔偿责任限制基金设立后，设立基金的海事法院对海事请求人就与海事事故相关纠纷向责任人提起的诉讼具有管辖权。"},{"i":5,"n":"第五条","txt":"海事诉讼特别程序法第一百零六条第二款规定的海事法院在十五日内作出裁定的期间，自海事法院受理设立海事赔偿责任限制基金申请的最后一次公告发布之次日起第三十日开始计算。"},{"i":6,"n":"第六条","txt":"海事诉讼特别程序法第一百一十二条规定的申请债权登记期间的届满之日，为海事法院受理设立海事赔偿责任限制基金申请的最后一次公告发布之次日起第六十日。"},{"i":7,"n":"第七条","txt":"债权人申请登记债权，符合有关规定的，海事法院应当在海事赔偿责任限制基金设立后，依照海事诉讼特别程序法第一百一十四条的规定作出裁定；海事赔偿责任限制基金未依法设立的，海事法院应当裁定终结债权登记程序。债权人已经交纳的申请费由申请设立海事赔偿责任限制基金的人负担。"},{"i":8,"n":"第八条","txt":"海事赔偿责任限制基金设立后，海事请求人基于责任人依法不能援引海事赔偿责任限制抗辩的海事赔偿请求，可以对责任人的财产申请保全。"},{"i":9,"n":"第九条","txt":"海事赔偿责任限制基金设立后，海事请求人就同一海事事故产生的属于海商法第二百零七条规定的可以限制赔偿责任的海事赔偿请求，以行使船舶优先权为由申请扣押船舶的，人民法院不予支持。"},{"i":10,"n":"第十条","txt":"债权人提起确权诉讼时，依据海商法第二百零九条的规定主张责任人无权限制赔偿责任的，应当以书面形式提出。案件的审理不适用海事诉讼特别程序法规定的确权诉讼程序，当事人对海事法院作出的判决、裁定可以依法提起上诉。"},{"i":11,"n":"第十一条","txt":"债权人依据海事诉讼特别程序法第一百一十六条第一款的规定提起确权诉讼后，需要判定碰撞船舶过失程度比例的，案件的审理不适用海事诉讼特别程序法规定的确权诉讼程序，当事人对海事法院作出的判决、裁定可以依法提起上诉。"},{"i":12,"n":"第十二条","txt":"海商法第二百零四条规定的船舶经营人是指登记的船舶经营人，或者接受船舶所有人委托实际使用和控制船舶并应当承担船舶责任的人，但不包括无船承运业务经营者。"},{"i":13,"n":"第十三条","txt":"责任人未申请设立海事赔偿责任限制基金，不影响其在诉讼中对海商法第二百零七条规定的海事请求提出海事赔偿责任限制抗辩。"},{"i":14,"n":"第十四条","txt":"责任人未提出海事赔偿责任限制抗辩的，海事法院不应主动适用海商法关于海事赔偿责任限制的规定进行裁判。"},{"i":15,"n":"第十五条","txt":"责任人在一审判决作出前未提出海事赔偿责任限制抗辩，在二审、再审期间提出的，人民法院不予支持。"},{"i":16,"n":"第十六条","txt":"责任人对海商法第二百零七条规定的海事赔偿请求未提出海事赔偿责任限制抗辩，债权人依据有关生效裁判文书或者仲裁裁决书，申请执行责任人海事赔偿责任限制基金以外的财产的，人民法院应予支持，但债权人以上述文书作为债权证据申请登记债权并经海事法院裁定准予的除外。"},{"i":17,"n":"第十七条","txt":"海商法第二百零七条规定的可以限制赔偿责任的海事赔偿请求不包括因沉没、遇难、搁浅或者被弃船舶的起浮、清除、拆毁或者使之无害提起的索赔，或者因船上货物的清除、拆毁或者使之无害提起的索赔。"},{"i":18,"n":"第十八条","txt":"海商法第二百零九条规定的“责任人”是指海事事故的责任人本人。"},{"i":19,"n":"第十九条","txt":"海事请求人以发生海事事故的船舶不适航为由主张责任人无权限制赔偿责任，但不能证明引起赔偿请求的损失是由于责任人本人的故意或者明知可能造成损失而轻率地作为或者不作为造成的，人民法院不予支持。"},{"i":20,"n":"第二十条","txt":"海事赔偿责任限制基金应当以人民币设立，其数额按法院准予设立基金的裁定生效之日的特别提款权对人民币的换算办法计算。"},{"i":21,"n":"第二十一条","txt":"海商法第二百一十三条规定的利息，自海事事故发生之日起至基金设立之日止，按同期全国银行间同业拆借中心公布的贷款市场报价利率计算。"},{"i":22,"n":"第二十二条","txt":"本规定施行前已经终审的案件，人民法院进行再审时，不适用本规定。"},{"i":23,"n":"第二十三条","txt":"本规定施行前本院发布的司法解释与本规定不一致的，以本规定为准。"}],"zuigaorenminfayuanguanyushenlihaiyangziranziyuanyu1994b4":[{"i":1,"n":"第一条","txt":"人民法院审理为请求赔偿海洋环境保护法第八十九条第二款规定的海洋自然资源与生态环境损害而提起的诉讼，适用本规定。"},{"i":2,"n":"第二条","txt":"在海上或者沿海陆域内从事活动，对中华人民共和国管辖海域内海洋自然资源与生态环境造成损害，由此提起的海洋自然资源与生态环境损害赔偿诉讼，由损害行为发生地、损害结果地或者采取预防措施地海事法院管辖。"},{"i":3,"n":"第三条","txt":"海洋环境保护法第五条规定的行使海洋环境监督管理权的机关，根据其职能分工提起海洋自然资源与生态环境损害赔偿诉讼，人民法院应予受理。"},{"i":4,"n":"第四条","txt":"人民法院受理海洋自然资源与生态环境损害赔偿诉讼，应当在立案之日起五日内公告案件受理情况。"},{"i":5,"n":"第五条","txt":"在人民法院依照本规定第四条的规定发布公告之日起三十日内，或者书面告知之日起七日内，对同一损害有权提起诉讼的其他机关申请参加诉讼，经审查符合法定条件的，人民法院应当将其列为共同原告；逾期申请的，人民法院不予准许。裁判生效后另行起诉的，人民法院参照《最高人民法院关于审理环境民事公益诉讼案件适用法律若干问题的解释》第二十八条的规定处理。"},{"i":6,"n":"第六条","txt":"依法行使海洋环境监督管理权的机关请求造成海洋自然资源与生态环境损害的责任者承担停止侵害、排除妨碍、消除危险、恢复原状、赔礼道歉、赔偿损失等民事责任的，人民法院应当根据诉讼请求以及具体案情，合理判定责任者承担民事责任。"},{"i":7,"n":"第七条","txt":"海洋自然资源与生态环境损失赔偿范围包括："},{"i":8,"n":"第八条","txt":"恢复费用，限于现实修复实际发生和未来修复必然发生的合理费用，包括制定和实施修复方案和监测、监管产生的费用。"},{"i":9,"n":"第九条","txt":"依照本规定第八条的规定难以确定恢复费用和恢复期间损失的，人民法院可以根据责任者因损害行为所获得的收益或者所减少支付的污染防治费用，合理确定损失赔偿数额。"},{"i":10,"n":"第十条","txt":"人民法院判决责任者赔偿海洋自然资源与生态环境损失的，可以一并写明依法行使海洋环境监督管理权的机关受领赔款后向国库账户交纳。"},{"i":11,"n":"第十一条","txt":"海洋自然资源与生态环境损害赔偿诉讼当事人达成调解协议或者自行达成和解协议的，人民法院依照《最高人民法院关于审理环境民事公益诉讼案件适用法律若干问题的解释》第二十五条的规定处理。"},{"i":12,"n":"第十二条","txt":"人民法院审理海洋自然资源与生态环境损害赔偿纠纷案件，本规定没有规定的，适用《最高人民法院关于审理环境侵权责任纠纷案件适用法律若干问题的解释》《最高人民法院关于审理环境民事公益诉讼案件适用法律若干问题的解释》等相关司法解释的规定。"},{"i":13,"n":"第十三条","txt":"本规定自2018年1月15日起施行，人民法院尚未审结的一审、二审案件适用本规定；本规定施行前已经作出生效裁判的案件，本规定施行后依法再审的，不适用本规定。"}],"zuigaorenminfayuanguanyushenlishejikuaijishishiwus06e01d":[{"i":1,"n":"第一条","txt":"利害关系人以会计师事务所在从事注册会计师法第十四条规定的审计业务活动中出具不实报告并致其遭受损失为由，向人民法院提起民事侵权赔偿诉讼的，人民法院应当依法受理。"},{"i":2,"n":"第二条","txt":"因合理信赖或者使用会计师事务所出具的不实报告，与被审计单位进行交易或者从事与被审计单位的股票、债券等有关的交易活动而遭受损失的自然人、法人或者其他组织，应认定为注册会计师法规定的利害关系人。"},{"i":3,"n":"第三条","txt":"利害关系人未对被审计单位提起诉讼而直接对会计师事务所提起诉讼的，人民法院应当告知其对会计师事务所和被审计单位一并提起诉讼；利害关系人拒不起诉被审计单位的，人民法院应当通知被审计单位作为共同被告参加诉讼。"},{"i":4,"n":"第四条","txt":"会计师事务所因在审计业务活动中对外出具不实报告给利害关系人造成损失的，应当承担侵权赔偿责任，但其能够证明自己没有过错的除外。"},{"i":5,"n":"第五条","txt":"注册会计师在审计业务活动中存在下列情形之一，出具不实报告并给利害关系人造成损失的，应当认定会计师事务所与被审计单位承担连带赔偿责任："},{"i":6,"n":"第六条","txt":"会计师事务所在审计业务活动中因过失出具不实报告，并给利害关系人造成损失的，人民法院应当根据其过失大小确定其赔偿责任。"},{"i":7,"n":"第七条","txt":"会计师事务所能够证明存在以下情形之一的，不承担民事赔偿责任："},{"i":8,"n":"第八条","txt":"利害关系人明知会计师事务所出具的报告为不实报告而仍然使用的，人民法院应当酌情减轻会计师事务所的赔偿责任。"},{"i":9,"n":"第九条","txt":"会计师事务所在报告中注明“本报告仅供年检使用”、“本报告仅供工商登记使用”等类似内容的，不能作为其免责的事由。"},{"i":10,"n":"第十条","txt":"人民法院根据本规定第六条确定会计师事务所承担与其过失程度相应的赔偿责任时，应按照下列情形处理："},{"i":11,"n":"第十一条","txt":"会计师事务所与其分支机构作为共同被告的，会计师事务所对其分支机构的责任部分承担连带赔偿责任。"},{"i":12,"n":"第十二条","txt":"本规定所涉会计师事务所侵权赔偿纠纷未经审判，人民法院不得将会计师事务所追加为被执行人。"},{"i":13,"n":"第十三条","txt":"本规定自公布之日起施行。本院过去发布的有关会计师事务所民事责任的相关规定，与本规定相抵触的，不再适用。"}],"zuigaorenminfayuanguanyushenlishejigongzhenghuodonf5a1bd":[{"i":1,"n":"第一条","txt":"当事人、公证事项的利害关系人依照公证法第四十三条规定向人民法院起诉请求民事赔偿的，应当以公证机构为被告，人民法院应作为侵权责任纠纷案件受理。"},{"i":2,"n":"第二条","txt":"当事人、公证事项的利害关系人起诉请求变更、撤销公证书或者确认公证书无效的，人民法院不予受理，告知其依照公证法第三十九条规定可以向出具公证书的公证机构提出复查。"},{"i":3,"n":"第三条","txt":"当事人、公证事项的利害关系人对公证书所公证的民事权利义务有争议的，可以依照公证法第四十条规定就该争议向人民法院提起民事诉讼。"},{"i":4,"n":"第四条","txt":"当事人、公证事项的利害关系人提供证据证明公证机构及其公证员在公证活动中具有下列情形之一的，人民法院应当认定公证机构有过错："},{"i":5,"n":"第五条","txt":"当事人提供虚假证明材料申请公证致使公证书错误造成他人损失的，当事人应当承担赔偿责任。公证机构依法尽到审查、核实义务的，不承担赔偿责任；未依法尽到审查、核实义务的，应当承担与其过错相应的补充赔偿责任；明知公证证明的材料虚假或者与当事人恶意串通的，承担连带赔偿责任。"},{"i":6,"n":"第六条","txt":"当事人、公证事项的利害关系人明知公证机构所出具的公证书不真实、不合法而仍然使用造成自己损失，请求公证机构承担赔偿责任的，人民法院不予支持。"},{"i":7,"n":"第七条","txt":"本规定施行后，涉及公证活动的民事案件尚未终审的，适用本规定；本规定施行前已经终审，当事人申请再审或者按照审判监督程序决定再审的，不适用本规定。"}],"zuigaorenminfayuanguanyushenlishejinongcunjititudid32c69":[{"i":1,"n":"第一条","txt":"农村集体土地的权利人或者利害关系人（以下简称土地权利人）认为行政机关作出的涉及农村集体土地的行政行为侵犯其合法权益，提起诉讼的，属于人民法院行政诉讼的受案范围。"},{"i":2,"n":"第二条","txt":"土地登记机构根据人民法院生效裁判文书、协助执行通知书或者仲裁机构的法律文书办理的土地权属登记行为，土地权利人不服提起诉讼的，人民法院不予受理，但土地权利人认为登记内容与有关文书内容不一致的除外。"},{"i":3,"n":"第三条","txt":"村民委员会或者农村集体经济组织对涉及农村集体土地的行政行为不起诉的，过半数的村民可以以集体经济组织名义提起诉讼。"},{"i":4,"n":"第四条","txt":"土地使用权人或者实际使用人对行政机关作出涉及其使用或实际使用的集体土地的行政行为不服的，可以以自己的名义提起诉讼。"},{"i":5,"n":"第五条","txt":"土地权利人认为土地储备机构作出的行为侵犯其依法享有的农村集体土地所有权或使用权的，向人民法院提起诉讼的，应当以土地储备机构所隶属的土地管理部门为被告。"},{"i":6,"n":"第六条","txt":"土地权利人认为乡级以上人民政府作出的土地确权决定侵犯其依法享有的农村集体土地所有权或者使用权，经复议后向人民法院提起诉讼的，人民法院应当依法受理。"},{"i":7,"n":"第七条","txt":"土地权利人认为行政机关作出的行政处罚、行政强制措施等行政行为侵犯其依法享有的农村集体土地所有权或者使用权，直接向人民法院提起诉讼的，人民法院应当依法受理。"},{"i":8,"n":"第八条","txt":"土地权属登记（包括土地权属证书）在生效裁判和仲裁裁决中作为定案证据，利害关系人对该登记行为提起诉讼的，人民法院应当依法受理。"},{"i":9,"n":"第九条","txt":"涉及农村集体土地的行政决定以公告方式送达的，起诉期限自公告确定的期限届满之日起计算。"},{"i":10,"n":"第十条","txt":"土地权利人对土地管理部门组织实施过程中确定的土地补偿有异议，直接向人民法院提起诉讼的，人民法院不予受理，但应当告知土地权利人先申请行政机关裁决。"},{"i":11,"n":"第十一条","txt":"土地权利人以土地管理部门超过两年对非法占地行为进行处罚违法，向人民法院起诉的，人民法院应当按照行政处罚法第二十九条第二款的规定处理。"},{"i":12,"n":"第十二条","txt":"征收农村集体土地时涉及被征收土地上的房屋及其他不动产，土地权利人可以请求依照物权法第四十二条第二款的规定给予补偿的。"},{"i":13,"n":"第十三条","txt":"在审理土地行政案件中，人民法院经当事人同意进行协调的期间，不计算在审理期限内。当事人不同意继续协商的，人民法院应当及时审理，并恢复计算审理期限。"},{"i":14,"n":"第十四条","txt":"县级以上人民政府土地管理部门根据土地管理法实施条例第四十五条的规定，申请人民法院执行其作出的责令交出土地决定的，应当符合下列条件："},{"i":15,"n":"第十五条","txt":"最高人民法院以前所作的司法解释与本规定不一致的，以本规定为准。"}],"zuigaorenminfayuanguanyushenlishetaiminshangshianj2eb61c":[{"i":1,"n":"第一条","txt":"人民法院审理涉台民商事案件，应当适用法律和司法解释的有关规定。"},{"i":2,"n":"第二条","txt":"台湾地区当事人在人民法院参与民事诉讼，与大陆当事人有同等的诉讼权利和义务，其合法权益受法律平等保护。"},{"i":3,"n":"第三条","txt":"根据本规定确定适用有关法律违反国家法律的基本原则或者社会公共利益的，不予适用。"}],"zuigaorenminfayuanguanyushenlishecailijiufenanjian91f8ea":[{"i":1,"n":"第一条","txt":"以婚姻为目的依据习俗给付彩礼后，因要求返还产生的纠纷，适用本规定。"},{"i":2,"n":"第二条","txt":"禁止借婚姻索取财物。一方以彩礼为名借婚姻索取财物，另一方要求返还的，人民法院应予支持。"},{"i":3,"n":"第三条","txt":"人民法院在审理涉彩礼纠纷案件中，可以根据一方给付财物的目的，综合考虑双方当地习俗、给付的时间和方式、财物价值、给付人及接收人等事实，认定彩礼范围。"},{"i":4,"n":"第四条","txt":"婚约财产纠纷中，婚约一方及其实际给付彩礼的父母可以作为共同原告；婚约另一方及其实际接收彩礼的父母可以作为共同被告。"},{"i":5,"n":"第五条","txt":"双方已办理结婚登记且共同生活，离婚时一方请求返还按照习俗给付的彩礼的，人民法院一般不予支持。但是，如果共同生活时间较短且彩礼数额过高的，人民法院可以根据彩礼实际使用及嫁妆情况，综合考虑彩礼数额、共同生活及孕育情况、双方过错等事实，结合当地习俗，确定是否返还以及返还的具体比例。"},{"i":6,"n":"第六条","txt":"双方未办理结婚登记但已共同生活，一方请求返还按照习俗给付的彩礼的，人民法院应当根据彩礼实际使用及嫁妆情况，综合考虑共同生活及孕育情况、双方过错等事实，结合当地习俗，确定是否返还以及返还的具体比例。"},{"i":7,"n":"第七条","txt":"本规定自2024年2月1日起施行。"}],"zuigaorenminfayuanguanyushenlishechuanyuanjiufenan136ba1":[{"i":1,"n":"第一条","txt":"船员与船舶所有人之间的劳动争议不涉及船员登船、在船工作、离船遣返，当事人直接向海事法院提起诉讼的，海事法院告知当事人依照《中华人民共和国劳动争议调解仲裁法》的规定处理。"},{"i":2,"n":"第二条","txt":"船员与船舶所有人之间的劳务合同纠纷，当事人向原告住所地、合同签订地、船员登船港或者离船港所在地、被告住所地海事法院提起诉讼的，海事法院应予受理。"},{"i":3,"n":"第三条","txt":"船员服务机构仅代理船员办理相关手续，或者仅为船员提供就业信息，且不属于劳务派遣情形，船员服务机构主张其与船员仅成立居间或委托合同关系的，应予支持。"},{"i":4,"n":"第四条","txt":"船舶所有人以被挂靠单位的名义对外经营，船舶所有人未与船员签订书面劳动合同，其聘用的船员因工伤亡，船员主张被挂靠单位为承担工伤保险责任的单位的，应予支持。船舶所有人与船员成立劳动关系的除外。"},{"i":5,"n":"第五条","txt":"与船员登船、在船工作、离船遣返无关的劳动争议提交劳动争议仲裁委员会仲裁，仲裁庭根据船员的申请，就船员工资和其他劳动报酬、工伤医疗费、经济补偿或赔偿金裁决先予执行的，移送地方人民法院审查。"},{"i":6,"n":"第六条","txt":"具有船舶优先权的海事请求，船员未依照《中华人民共和国海商法》第二十八条的规定请求扣押产生船舶优先权的船舶，仅请求确认其在一定期限内对该产生船舶优先权的船舶享有优先权的，应予支持。"},{"i":7,"n":"第七条","txt":"具有船舶优先权的海事请求，船员未申请限制船舶继续营运，仅申请对船舶采取限制处分、限制抵押等保全措施的，应予支持。船员主张该保全措施构成《中华人民共和国海商法》第二十八条规定的船舶扣押的，不予支持。"},{"i":8,"n":"第八条","txt":"因登船、在船工作、离船遣返产生的下列工资、其他劳动报酬，船员主张船舶优先权的，应予支持："},{"i":9,"n":"第九条","txt":"船员因登船、在船工作、离船遣返而产生的工资、其他劳动报酬、船员遣返费用、社会保险费用，船舶所有人未依约支付，第三方向船员垫付全部或部分费用，船员将相应的海事请求权转让给第三方，第三方就受让的海事请求权请求确认或行使船舶优先权的，应予支持。"},{"i":10,"n":"第十条","txt":"船员境外工作期间被遗弃，或遭遇其他突发事件，船舶所有人或其财务担保人、船员外派机构未承担相应责任，船员请求财务担保人、船员外派机构从财务担保费用、海员外派备用金中先行支付紧急救助所需相关费用的，应予支持。"},{"i":11,"n":"第十一条","txt":"对于船员工资构成是否涵盖船员登船、在船工作、离船遣返期间的工作日加班工资、休息日加班工资、法定休假日加班工资，当事人有约定并主张依据约定确定双方加班工资的，应予支持。但约定标准低于法定最低工资标准的，不予支持。"},{"i":12,"n":"第十二条","txt":"标准工时制度下，船员就休息日加班主张加班工资，船舶所有人举证证明已做补休安排，不应按法定标准支付加班工资的，应予支持。  综合计算工时工作制下，船员对综合计算周期内的工作时间总量超过标准工作时间总量的部分主张加班工资的，应予支持。"},{"i":13,"n":"第十三条","txt":"当事人对船员工资或其他劳动报酬的支付标准、支付方式未作约定或约定不明，当事人主张以同工种、同级别、同时期市场的平均标准确定的，应予支持。"},{"i":14,"n":"第十四条","txt":"船员因受欺诈、受胁迫在禁渔期、禁渔区或使用禁用的工具、方法捕捞水产品，或者捕捞珍稀、濒危海洋生物，或者进行其他违法作业，对船员主张的登船、在船工作、离船遣返期间的船员工资、其他劳动报酬，应予支持。"},{"i":15,"n":"第十五条","txt":"船员因劳务受到损害，船舶所有人举证证明船员自身存在过错，并请求判令船员自担相应责任的，对船舶所有人的抗辩予以支持。"},{"i":16,"n":"第十六条","txt":"因第三人的原因遭受工伤，船员对第三人提起民事诉讼请求民事赔偿，第三人以船员已获得工伤保险待遇为由，抗辩其不应承担民事赔偿责任的，对第三人的抗辩不予支持。但船员已经获得医疗费用的，对船员关于医疗费用的诉讼请求不予支持。"},{"i":17,"n":"第十七条","txt":"船员与船舶所有人之间的劳动合同具有涉外因素，当事人请求依照《中华人民共和国涉外民事关系法律适用法》第四十三条确定应适用的法律的，应予支持。"},{"i":18,"n":"第十八条","txt":"本规定中的船舶所有人，包括光船承租人、船舶管理人、船舶经营人。"},{"i":19,"n":"第十九条","txt":"本规定施行后尚未终审的案件，适用本规定；本规定施行前已经终审，当事人申请再审或者按照审判监督程序决定再审的案件，不适用本规定。"},{"i":20,"n":"第二十条","txt":"本院以前发布的规定与本规定不一致的，以本规定为准。"},{"i":21,"n":"第二十一条","txt":"本规定自2020年9月29日起实施。"}],"zuigaorenminfayuanguanyushenlidulibaohanjiufenanji5d43d1":[{"i":1,"n":"第一条","txt":"本规定所称的独立保函，是指银行或非银行金融机构作为开立人，以书面形式向受益人出具的，同意在受益人请求付款并提交符合保函要求的单据时，向其支付特定款项或在保函最高金额内付款的承诺。"},{"i":2,"n":"第二条","txt":"本规定所称的独立保函纠纷，是指在独立保函的开立、撤销、修改、转让、付款、追偿等环节产生的纠纷。"},{"i":3,"n":"第三条","txt":"保函具有下列情形之一，当事人主张保函性质为独立保函的，人民法院应予支持，但保函未载明据以付款的单据和最高金额的除外："},{"i":4,"n":"第四条","txt":"独立保函的开立时间为开立人发出独立保函的时间。"},{"i":5,"n":"第五条","txt":"独立保函载明适用《见索即付保函统一规则》等独立保函交易示范规则，或开立人和受益人在一审法庭辩论终结前一致援引的，人民法院应当认定交易示范规则的内容构成独立保函条款的组成部分。"},{"i":6,"n":"第六条","txt":"受益人提交的单据与独立保函条款之间、单据与单据之间表面相符，受益人请求开立人依据独立保函承担付款责任的，人民法院应予支持。"},{"i":7,"n":"第七条","txt":"人民法院在认定是否构成表面相符时，应当根据独立保函载明的审单标准进行审查；独立保函未载明的，可以参照适用国际商会确定的相关审单标准。"},{"i":8,"n":"第八条","txt":"开立人有独立审查单据的权利与义务，有权自行决定单据与独立保函条款之间、单据与单据之间是否表面相符，并自行决定接受或拒绝接受不符点。"},{"i":9,"n":"第九条","txt":"开立人依据独立保函付款后向保函申请人追偿的，人民法院应予支持，但受益人提交的单据存在不符点的除外。"},{"i":10,"n":"第十条","txt":"独立保函未同时载明可转让和据以确定新受益人的单据，开立人主张受益人付款请求权的转让对其不发生效力的，人民法院应予支持。独立保函对受益人付款请求权的转让有特别约定的，从其约定。"},{"i":11,"n":"第十一条","txt":"独立保函具有下列情形之一，当事人主张独立保函权利义务终止的，人民法院应予支持："},{"i":12,"n":"第十二条","txt":"具有下列情形之一的，人民法院应当认定构成独立保函欺诈："},{"i":13,"n":"第十三条","txt":"独立保函的申请人、开立人或指示人发现有本规定第十二条情形的，可以在提起诉讼或申请仲裁前，向开立人住所地或其他对独立保函欺诈纠纷案件具有管辖权的人民法院申请中止支付独立保函项下的款项，也可以在诉讼或仲裁过程中提出申请。"},{"i":14,"n":"第十四条","txt":"人民法院裁定中止支付独立保函项下的款项，必须同时具备下列条件："},{"i":15,"n":"第十五条","txt":"因止付申请错误造成损失，当事人请求止付申请人赔偿的，人民法院应予支持。"},{"i":16,"n":"第十六条","txt":"人民法院受理止付申请后，应当在四十八小时内作出书面裁定。裁定应当列明申请人、被申请人和第三人，并包括初步查明的事实和是否准许止付申请的理由。"},{"i":17,"n":"第十七条","txt":"当事人对人民法院就止付申请作出的裁定有异议的，可以在裁定书送达之日起十日内向作出裁定的人民法院申请复议。复议期间不停止裁定的执行。"},{"i":18,"n":"第十八条","txt":"人民法院审理独立保函欺诈纠纷案件或处理止付申请，可以就当事人主张的本规定第十二条的具体情形，审查认定基础交易的相关事实。"},{"i":19,"n":"第十九条","txt":"保函申请人在独立保函欺诈诉讼中仅起诉受益人的，独立保函的开立人、指示人可以作为第三人申请参加，或由人民法院通知其参加。"},{"i":20,"n":"第二十条","txt":"人民法院经审理独立保函欺诈纠纷案件，能够排除合理怀疑地认定构成独立保函欺诈，并且不存在本规定第十四条第三款情形的，应当判决开立人终止支付独立保函项下被请求的款项。"},{"i":21,"n":"第二十一条","txt":"受益人和开立人之间因独立保函而产生的纠纷案件，由开立人住所地或被告住所地人民法院管辖，独立保函载明由其他法院管辖或提交仲裁的除外。当事人主张根据基础交易合同争议解决条款确定管辖法院或提交仲裁的，人民法院不予支持。"},{"i":22,"n":"第二十二条","txt":"涉外独立保函未载明适用法律，开立人和受益人在一审法庭辩论终结前亦未就适用法律达成一致的，开立人和受益人之间因涉外独立保函而产生的纠纷适用开立人经常居所地法律；独立保函由金融机构依法登记设立的分支机构开立的，适用分支机构登记地法律。"},{"i":23,"n":"第二十三条","txt":"当事人约定在国内交易中适用独立保函，一方当事人以独立保函不具有涉外因素为由，主张保函独立性的约定无效的，人民法院不予支持。"},{"i":24,"n":"第二十四条","txt":"对于按照特户管理并移交开立人占有的独立保函开立保证金，人民法院可以采取冻结措施，但不得扣划。保证金账户内的款项丧失开立保证金的功能时，人民法院可以依法采取扣划措施。"},{"i":25,"n":"第二十五条","txt":"本规定施行后尚未终审的案件，适用本规定；本规定施行前已经终审的案件，当事人申请再审或者人民法院按照审判监督程序再审的，不适用本规定。"},{"i":26,"n":"第二十六条","txt":"本规定自2016年12月1日起施行。"}],"zuigaorenminfayuanguanyushenlishengtaihuanjingsunh94ed16":[{"i":1,"n":"第一条","txt":"具有下列情形之一，省级、市地级人民政府及其指定的相关部门、机构，或者受国务院委托行使全民所有自然资源资产所有权的部门，因与造成生态环境损害的自然人、法人或者其他组织经磋商未达成一致或者无法进行磋商的，可以作为原告提起生态环境损害赔偿诉讼："},{"i":2,"n":"第二条","txt":"下列情形不适用本规定："},{"i":3,"n":"第三条","txt":"第一审生态环境损害赔偿诉讼案件由生态环境损害行为实施地、损害结果发生地或者被告住所地的中级以上人民法院管辖。"},{"i":4,"n":"第四条","txt":"人民法院审理第一审生态环境损害赔偿诉讼案件，应当由法官和人民陪审员组成合议庭进行。"},{"i":5,"n":"第五条","txt":"原告提起生态环境损害赔偿诉讼，符合民事诉讼法和本规定并提交下列材料的，人民法院应当登记立案："},{"i":6,"n":"第六条","txt":"原告主张被告承担生态环境损害赔偿责任的，应当就以下事实承担举证责任："},{"i":7,"n":"第七条","txt":"被告反驳原告主张的，应当提供证据加以证明。被告主张具有法律规定的不承担责任或者减轻责任情形的，应当承担举证责任。"},{"i":8,"n":"第八条","txt":"已为发生法律效力的刑事裁判所确认的事实，当事人在生态环境损害赔偿诉讼案件中无须举证证明，但有相反证据足以推翻的除外。"},{"i":9,"n":"第九条","txt":"负有相关环境资源保护监督管理职责的部门或者其委托的机构在行政执法过程中形成的事件调查报告、检验报告、检测报告、评估报告、监测数据等，经当事人质证并符合证据标准的，可以作为认定案件事实的根据。"},{"i":10,"n":"第十条","txt":"当事人在诉前委托具备环境司法鉴定资质的鉴定机构出具的鉴定意见，以及委托国务院环境资源保护监督管理相关主管部门推荐的机构出具的检验报告、检测报告、评估报告、监测数据等，经当事人质证并符合证据标准的，可以作为认定案件事实的根据。"},{"i":11,"n":"第十一条","txt":"被告违反国家规定造成生态环境损害的，人民法院应当根据原告的诉讼请求以及具体案情，合理判决被告承担修复生态环境、赔偿损失、停止侵害、排除妨碍、消除危险、赔礼道歉等民事责任。"},{"i":12,"n":"第十二条","txt":"受损生态环境能够修复的，人民法院应当依法判决被告承担修复责任，并同时确定被告不履行修复义务时应承担的生态环境修复费用。"},{"i":13,"n":"第十三条","txt":"受损生态环境无法修复或者无法完全修复，原告请求被告赔偿生态环境功能永久性损害造成的损失的，人民法院根据具体案情予以判决。"},{"i":14,"n":"第十四条","txt":"原告请求被告承担下列费用的，人民法院根据具体案情予以判决："},{"i":15,"n":"第十五条","txt":"人民法院判决被告承担的生态环境服务功能损失赔偿资金、生态环境功能永久性损害造成的损失赔偿资金，以及被告不履行生态环境修复义务时所应承担的修复费用，应当依照法律、法规、规章予以缴纳、管理和使用。"},{"i":16,"n":"第十六条","txt":"在生态环境损害赔偿诉讼案件审理过程中，同一损害生态环境行为又被提起民事公益诉讼，符合起诉条件的，应当由受理生态环境损害赔偿诉讼案件的人民法院受理并由同一审判组织审理。"},{"i":17,"n":"第十七条","txt":"人民法院受理因同一损害生态环境行为提起的生态环境损害赔偿诉讼案件和民事公益诉讼案件，应先中止民事公益诉讼案件的审理，待生态环境损害赔偿诉讼案件审理完毕后，就民事公益诉讼案件未被涵盖的诉讼请求依法作出裁判。"},{"i":18,"n":"第十八条","txt":"生态环境损害赔偿诉讼案件的裁判生效后，有权提起民事公益诉讼的国家规定的机关或者法律规定的组织就同一损害生态环境行为有证据证明存在前案审理时未发现的损害，并提起民事公益诉讼的，人民法院应予受理。"},{"i":19,"n":"第十九条","txt":"实际支出应急处置费用的机关提起诉讼主张该费用的，人民法院应予受理，但人民法院已经受理就同一损害生态环境行为提起的生态环境损害赔偿诉讼案件且该案原告已经主张应急处置费用的除外。"},{"i":20,"n":"第二十条","txt":"经磋商达成生态环境损害赔偿协议的，当事人可以向人民法院申请司法确认。"},{"i":21,"n":"第二十一条","txt":"一方当事人在期限内未履行或者未全部履行发生法律效力的生态环境损害赔偿诉讼案件裁判或者经司法确认的生态环境损害赔偿协议的，对方当事人可以向人民法院申请强制执行。需要修复生态环境的，依法由省级、市地级人民政府及其指定的相关部门、机构组织实施。"},{"i":22,"n":"第二十二条","txt":"人民法院审理生态环境损害赔偿案件，本规定没有规定的，参照适用《最高人民法院关于审理环境民事公益诉讼案件适用法律若干问题的解释》《最高人民法院关于审理环境侵权责任纠纷案件适用法律若干问题的解释》等相关司法解释的规定。"},{"i":23,"n":"第二十三条","txt":"本规定自2019年6月5日起施行。"}],"zuigaorenminfayuanguanyushenlishenqingzhucedeyaopi9b5af3":[{"i":1,"n":"第一条","txt":"当事人依据专利法第七十六条规定提起的确认是否落入专利权保护范围纠纷的第一审案件，由北京知识产权法院管辖。"},{"i":2,"n":"第二条","txt":"专利法第七十六条所称相关的专利，是指适用国务院有关行政部门关于药品上市许可审批与药品上市许可申请阶段专利权纠纷解决的具体衔接办法（以下简称衔接办法）的专利。"},{"i":3,"n":"第三条","txt":"专利权人或者利害关系人依据专利法第七十六条起诉的，应当按照民事诉讼法第一百一十九条第三项的规定提交下列材料："},{"i":4,"n":"第四条","txt":"专利权人或者利害关系人在衔接办法规定的期限内未向人民法院提起诉讼的，药品上市许可申请人可以向人民法院起诉，请求确认申请注册药品未落入相关专利权保护范围。"},{"i":5,"n":"第五条","txt":"当事人以国务院专利行政部门已经受理专利法第七十六条所称行政裁决请求为由，主张不应当受理专利法第七十六条所称诉讼或者申请中止诉讼的，人民法院不予支持。"},{"i":6,"n":"第六条","txt":"当事人依据专利法第七十六条起诉后，以国务院专利行政部门已经受理宣告相关专利权无效的请求为由，申请中止诉讼的，人民法院一般不予支持。"},{"i":7,"n":"第七条","txt":"药品上市许可申请人主张具有专利法第六十七条、第七十五条第二项等规定情形的，人民法院经审查属实，可以判决确认申请注册的药品相关技术方案未落入相关专利权保护范围。"},{"i":8,"n":"第八条","txt":"当事人对其在诉讼中获取的商业秘密或者其他需要保密的商业信息负有保密义务，擅自披露或者在该诉讼活动之外使用、允许他人使用的，应当依法承担民事责任。构成民事诉讼法第一百一十一条规定情形的，人民法院应当依法处理。"},{"i":9,"n":"第九条","txt":"药品上市许可申请人向人民法院提交的申请注册的药品相关技术方案，与其向国家药品审评机构申报的技术资料明显不符，妨碍人民法院审理案件的，人民法院依照民事诉讼法第一百一十一条的规定处理。"},{"i":10,"n":"第十条","txt":"专利权人或者利害关系人在专利法第七十六条所称诉讼中申请行为保全，请求禁止药品上市许可申请人在相关专利权有效期内实施专利法第十一条规定的行为的，人民法院依照专利法、民事诉讼法有关规定处理；请求禁止药品上市申请行为或者审评审批行为的，人民法院不予支持。"},{"i":11,"n":"第十一条","txt":"在针对同一专利权和申请注册药品的侵害专利权或者确认不侵害专利权诉讼中，当事人主张依据专利法第七十六条所称诉讼的生效判决认定涉案药品技术方案是否落入相关专利权保护范围的，人民法院一般予以支持。但是，有证据证明被诉侵权药品技术方案与申请注册的药品相关技术方案不一致或者新主张的事由成立的除外。"},{"i":12,"n":"第十二条","txt":"专利权人或者利害关系人知道或者应当知道其主张的专利权应当被宣告无效或者申请注册药品的相关技术方案未落入专利权保护范围，仍提起专利法第七十六条所称诉讼或者请求行政裁决的，药品上市许可申请人可以向北京知识产权法院提起损害赔偿之诉。"},{"i":13,"n":"第十三条","txt":"人民法院依法向当事人在国务院有关行政部门依据衔接办法所设平台登载的联系人、通讯地址、电子邮件等进行的送达，视为有效送达。当事人向人民法院提交送达地址确认书后，人民法院也可以向该确认书载明的送达地址送达。"},{"i":14,"n":"第十四条","txt":"本规定自2021年7月5日起施行。本院以前发布的相关司法解释与本规定不一致的，以本规定为准。"}],"zuigaorenminfayuanguanyushenlipiaojujiufenanjianruc91c02":[{"i":1,"n":"第一条","txt":"因行使票据权利或者票据法上的非票据权利而引起的纠纷，人民法院应当依法受理。"},{"i":2,"n":"第二条","txt":"依照票据法第十条的规定，票据债务人（即出票人）以在票据未转让时的基础关系违法、双方不具有真实的交易关系和债权债务关系、持票人应付对价而未付对价为由，要求返还票据而提起诉讼的，人民法院应当依法受理。"},{"i":3,"n":"第三条","txt":"依照票据法第三十六条的规定，票据被拒绝承兑、被拒绝付款或者汇票、支票超过提示付款期限后，票据持有人背书转让的，被背书人以背书人为被告行使追索权而提起诉讼的，人民法院应当依法受理。"},{"i":4,"n":"第四条","txt":"持票人不先行使付款请求权而先行使追索权遭拒绝提起诉讼的，人民法院不予受理。除有票据法第六十一条第二款和本规定第三条所列情形外，持票人只能在首先向付款人行使付款请求权而得不到付款时，才可以行使追索权。"},{"i":5,"n":"第五条","txt":"付款请求权是持票人享有的第一顺序权利，追索权是持票人享有的第二顺序权利，即汇票到期被拒绝付款或者具有票据法第六十一条第二款所列情形的，持票人请求背书人、出票人以及汇票的其他债务人支付票据法第七十条第一款所列金额和费用的权利。"},{"i":6,"n":"第六条","txt":"因票据纠纷提起的诉讼，依法由票据支付地或者被告住所地人民法院管辖。"},{"i":7,"n":"第七条","txt":"人民法院在审理、执行票据纠纷案件时，对具有下列情形之一的票据，经当事人申请并提供担保，可以依法采取保全措施或者执行措施："},{"i":8,"n":"第八条","txt":"票据诉讼的举证责任由提出主张的一方当事人承担。"},{"i":9,"n":"第九条","txt":"票据债务人依照票据法第十三条的规定，对与其有直接债权债务关系的持票人提出抗辩，人民法院合并审理票据关系和基础关系的，持票人应当提供相应的证据证明已经履行了约定义务。"},{"i":10,"n":"第十条","txt":"付款人或者承兑人被人民法院依法宣告破产的，持票人因行使追索权而向人民法院提起诉讼时，应当向受理法院提供人民法院依法作出的宣告破产裁定书或者能够证明付款人或者承兑人破产的其他证据。"},{"i":11,"n":"第十一条","txt":"在票据诉讼中，负有举证责任的票据当事人应当在一审人民法院法庭辩论结束以前提供证据。因客观原因不能在上述举证期限以内提供的，应当在举证期限届满以前向人民法院申请延期。延长的期限由人民法院根据案件的具体情况决定。"},{"i":12,"n":"第十二条","txt":"票据法第十七条第一款第（一）、（二）项规定的持票人对票据的出票人和承兑人的权利，包括付款请求权和追索权。"},{"i":13,"n":"第十三条","txt":"票据债务人以票据法第十条、第二十一条的规定为由，对业经背书转让票据的持票人进行抗辩的，人民法院不予支持。"},{"i":14,"n":"第十四条","txt":"票据债务人依照票据法第十二条、第十三条的规定，对持票人提出下列抗辩的，人民法院应予支持："},{"i":15,"n":"第十五条","txt":"票据债务人依照票据法第九条、第十七条、第十八条、第二十二条和第三十一条的规定，对持票人提出下列抗辩的，人民法院应予支持："},{"i":16,"n":"第十六条","txt":"票据出票人或者背书人被宣告破产的，而付款人或者承兑人不知其事实而付款或者承兑，因此所产生的追索权可以登记为破产债权，付款人或者承兑人为债权人。"},{"i":17,"n":"第十七条","txt":"票据法第十七条第一款第（三）、（四）项规定的持票人对前手的追索权，不包括对票据出票人的追索权。"},{"i":18,"n":"第十八条","txt":"票据法第四十条第二款和第六十五条规定的持票人丧失对其前手的追索权，不包括对票据出票人的追索权。"},{"i":19,"n":"第十九条","txt":"票据法第十七条规定的票据权利时效发生中断的，只对发生时效中断事由的当事人有效。"},{"i":20,"n":"第二十条","txt":"票据法第六十六条第一款规定的书面通知是否逾期，以持票人或者其前手发出书面通知之日为准；以信函通知的，以信函投寄邮戳记载之日为准。"},{"i":21,"n":"第二十一条","txt":"票据法第七十条、第七十一条所称中国人民银行规定的利率，是指中国人民银行规定的企业同期流动资金贷款利率。"},{"i":22,"n":"第二十二条","txt":"代理付款人在人民法院公示催告公告发布以前按照规定程序善意付款后，承兑人或者付款人以已经公示催告为由拒付代理付款人已经垫付的款项的，人民法院不予支持。"},{"i":23,"n":"第二十三条","txt":"票据丧失后，失票人直接向人民法院申请公示催告或者提起诉讼的，人民法院应当依法受理。"},{"i":24,"n":"第二十四条","txt":"出票人已经签章的授权补记的支票丧失后，失票人依法向人民法院申请公示催告的，人民法院应当依法受理。"},{"i":25,"n":"第二十五条","txt":"票据法第十五条第三款规定的可以申请公示催告的失票人，是指按照规定可以背书转让的票据在丧失票据占有以前的最后合法持票人。"},{"i":26,"n":"第二十六条","txt":"出票人已经签章但未记载代理付款人的银行汇票丧失后，失票人依法向付款人即出票银行所在地人民法院申请公示催告的，人民法院应当依法受理。"},{"i":27,"n":"第二十七条","txt":"超过付款提示期限的票据丧失以后，失票人申请公示催告的，人民法院应当依法受理。"},{"i":28,"n":"第二十八条","txt":"失票人通知票据付款人挂失止付后三日内向人民法院申请公示催告的，公示催告申请书应当载明下列内容："},{"i":29,"n":"第二十九条","txt":"人民法院决定受理公示催告申请，应当同时通知付款人及代理付款人停止支付，并自立案之日起三日内发出公告。"},{"i":30,"n":"第三十条","txt":"付款人或者代理付款人收到人民法院发出的止付通知，应当立即停止支付，直至公示催告程序终结。非经发出止付通知的人民法院许可擅自解付的，不得免除票据责任。"},{"i":31,"n":"第三十一条","txt":"公告应当在全国性报纸或者其他媒体上刊登，并于同日公布于人民法院公告栏内。人民法院所在地有证券交易所的，还应当同日在该交易所公布。"},{"i":32,"n":"第三十二条","txt":"依照《中华人民共和国民事诉讼法》（以下简称民事诉讼法）第二百一十九条的规定，公告期间不得少于六十日，且公示催告期间届满日不得早于票据付款日后十五日。"},{"i":33,"n":"第三十三条","txt":"依照民事诉讼法第二百二十条第二款的规定，在公示催告期间，以公示催告的票据质押、贴现，因质押、贴现而接受该票据的持票人主张票据权利的，人民法院不予支持，但公示催告期间届满以后人民法院作出除权判决以前取得该票据的除外。"},{"i":34,"n":"第三十四条","txt":"票据丧失后，失票人在票据权利时效届满以前请求出票人补发票据，或者请求债务人付款，在提供相应担保的情况下因债务人拒绝付款或者出票人拒绝补发票据提起诉讼的，由被告住所地或者票据支付地人民法院管辖。"},{"i":35,"n":"第三十五条","txt":"失票人因请求出票人补发票据或者请求债务人付款遭到拒绝而向人民法院提起诉讼的，被告为与失票人具有票据债权债务关系的出票人、拒绝付款的票据付款人或者承兑人。"},{"i":36,"n":"第三十六条","txt":"失票人为行使票据所有权，向非法持有票据人请求返还票据的，人民法院应当依法受理。"},{"i":37,"n":"第三十七条","txt":"失票人向人民法院提起诉讼的，应向人民法院说明曾经持有票据及丧失票据的情形，人民法院应当根据案件的具体情况，决定当事人是否应当提供担保以及担保的数额。"},{"i":38,"n":"第三十八条","txt":"对于伪报票据丧失的当事人，人民法院在查明事实，裁定终结公示催告或者诉讼程序后，可以参照民事诉讼法第一百一十一条的规定，追究伪报人的法律责任。"},{"i":39,"n":"第三十九条","txt":"依照票据法第一百零八条以及经国务院批准的《票据管理实施办法》的规定，票据当事人使用的不是中国人民银行规定的统一格式票据的，按照《票据管理实施办法》的规定认定，但在中国境外签发的票据除外。"},{"i":40,"n":"第四十条","txt":"票据出票人在票据上的签章上不符合票据法以及下述规定的，该签章不具有票据法上的效力："},{"i":41,"n":"第四十一条","txt":"银行汇票、银行本票的出票人以及银行承兑汇票的承兑人在票据上未加盖规定的专用章而加盖该银行的公章，支票的出票人在票据上未加盖与该单位在银行预留签章一致的财务专用章而加盖该出票人公章的，签章人应当承担票据责任。"},{"i":42,"n":"第四十二条","txt":"依照票据法第九条以及《票据管理实施办法》的规定，票据金额的中文大写与数码不一致，或者票据载明的金额、出票日期或者签发日期、收款人名称更改，或者违反规定加盖银行部门印章代替专用章，付款人或者代理付款人对此类票据付款的，应当承担责任。"},{"i":43,"n":"第四十三条","txt":"因更改银行汇票的实际结算金额引起纠纷而提起诉讼，当事人请求认定汇票效力的，人民法院应当认定该银行汇票无效。"},{"i":44,"n":"第四十四条","txt":"空白授权票据的持票人行使票据权利时未对票据必须记载事项补充完全，因付款人或者代理付款人拒绝接收该票据而提起诉讼的，人民法院不予支持。"},{"i":45,"n":"第四十五条","txt":"票据的背书人、承兑人、保证人在票据上的签章不符合票据法以及《票据管理实施办法》规定的，或者无民事行为能力人、限制民事行为能力人在票据上签章的，其签章无效，但不影响人民法院对票据上其他签章效力的认定。"},{"i":46,"n":"第四十六条","txt":"因票据质权人以质押票据再行背书质押或者背书转让引起纠纷而提起诉讼的，人民法院应当认定背书行为无效。"},{"i":47,"n":"第四十七条","txt":"依照票据法第二十七条的规定，票据的出票人在票据上记载“不得转让”字样，票据持有人背书转让的，背书行为无效。背书转让后的受让人不得享有票据权利，票据的出票人、承兑人对受让人不承担票据责任。"},{"i":48,"n":"第四十八条","txt":"依照票据法第二十七条和第三十条的规定，背书人未记载被背书人名称即将票据交付他人的，持票人在票据被背书人栏内记载自己的名称与背书人记载具有同等法律效力。"},{"i":49,"n":"第四十九条","txt":"依照票据法第三十一条的规定，连续背书的第一背书人应当是在票据上记载的收款人，最后的票据持有人应当是最后一次背书的被背书人。"},{"i":50,"n":"第五十条","txt":"依照票据法第三十四条和第三十五条的规定，背书人在票据上记载“不得转让”“委托收款”“质押”字样，其后手再背书转让、委托收款或者质押的，原背书人对后手的被背书人不承担票据责任，但不影响出票人、承兑人以及原背书人之前手的票据责任。"},{"i":51,"n":"第五十一条","txt":"依照票据法第五十七条第二款的规定，贷款人恶意或者有重大过失从事票据质押贷款的，人民法院应当认定质押行为无效。"},{"i":52,"n":"第五十二条","txt":"依照票据法第二十七条的规定，出票人在票据上记载“不得转让”字样，其后手以此票据进行贴现、质押的，通过贴现、质押取得票据的持票人主张票据权利的，人民法院不予支持。"},{"i":53,"n":"第五十三条","txt":"依照票据法第三十四条和第三十五条的规定，背书人在票据上记载“不得转让”字样，其后手以此票据进行贴现、质押的，原背书人对后手的被背书人不承担票据责任。"},{"i":54,"n":"第五十四条","txt":"依照票据法第三十五条第二款的规定，以汇票设定质押时，出质人在汇票上只记载了“质押”字样未在票据上签章的，或者出质人未在汇票、粘单上记载“质押”字样而另行签订质押合同、质押条款的，不构成票据质押。"},{"i":55,"n":"第五十五条","txt":"商业汇票的持票人向其非开户银行申请贴现，与向自己开立存款账户的银行申请贴现具有同等法律效力。但是，持票人有恶意或者与贴现银行恶意串通的除外。"},{"i":56,"n":"第五十六条","txt":"违反规定区域出票，背书转让银行汇票，或者违反票据管理规定跨越票据交换区域出票、背书转让银行本票、支票的，不影响出票人、背书人依法应当承担的票据责任。"},{"i":57,"n":"第五十七条","txt":"依照票据法第三十六条的规定，票据被拒绝承兑、被拒绝付款或者超过提示付款期限，票据持有人背书转让的，背书人应当承担票据责任。"},{"i":58,"n":"第五十八条","txt":"承兑人或者付款人依照票据法第五十三条第二款的规定对逾期提示付款的持票人付款与按照规定的期限付款具有同等法律效力。"},{"i":59,"n":"第五十九条","txt":"国家机关、以公益为目的的事业单位、社会团体作为票据保证人的，票据保证无效，但经国务院批准为使用外国政府或者国际经济组织贷款进行转贷，国家机关提供票据保证的除外。"},{"i":60,"n":"第六十条","txt":"票据保证无效的，票据的保证人应当承担与其过错相应的民事责任。"},{"i":61,"n":"第六十一条","txt":"保证人未在票据或者粘单上记载“保证”字样而另行签订保证合同或者保证条款的，不属于票据保证，人民法院应当适用《中华人民共和国民法典》的有关规定。"},{"i":62,"n":"第六十二条","txt":"人民法院审理票据纠纷案件，适用票据法的规定；票据法没有规定的，适用《中华人民共和国民法典》等法律以及国务院制定的行政法规。"},{"i":63,"n":"第六十三条","txt":"票据当事人因对金融行政管理部门的具体行政行为不服提起诉讼的，适用《中华人民共和国行政处罚法》、票据法以及《票据管理实施办法》等有关票据管理的规定。"},{"i":64,"n":"第六十四条","txt":"人民法院对票据法施行以前已经作出终审裁决的票据纠纷案件进行再审，不适用票据法。"},{"i":65,"n":"第六十五条","txt":"具有下列情形之一的票据，未经背书转让的，票据债务人不承担票据责任；已经背书转让的，票据无效不影响其他真实签章的效力："},{"i":66,"n":"第六十六条","txt":"依照票据法第十四条、第一百零二条、第一百零三条的规定，伪造、变造票据者除应当依法承担刑事、行政责任外，给他人造成损失的，还应当承担民事赔偿责任。被伪造签章者不承担票据责任。"},{"i":67,"n":"第六十七条","txt":"对票据未记载事项或者未完全记载事项作补充记载，补充事项超出授权范围的，出票人对补充后的票据应当承担票据责任。给他人造成损失的，出票人还应当承担相应的民事责任。"},{"i":68,"n":"第六十八条","txt":"付款人或者代理付款人未能识别出伪造、变造的票据或者身份证件而错误付款，属于票据法第五十七条规定的“重大过失”，给持票人造成损失的，应当依法承担民事责任。付款人或者代理付款人承担责任后有权向伪造者、变造者依法追偿。"},{"i":69,"n":"第六十九条","txt":"付款人及其代理付款人有下列情形之一的，应当自行承担责任："},{"i":70,"n":"第七十条","txt":"票据法第六十三条所称“其他有关证明”是指："},{"i":71,"n":"第七十一条","txt":"当事人因申请票据保全错误而给他人造成损失的，应当依法承担民事责任。"},{"i":72,"n":"第七十二条","txt":"因出票人签发空头支票、与其预留本名的签名式样或者印鉴不符的支票给他人造成损失的，支票的出票人和背书人应当依法承担民事责任。"},{"i":73,"n":"第七十三条","txt":"人民法院在审理票据纠纷案件时，发现与本案有牵连但不属同一法律关系的票据欺诈犯罪嫌疑线索的，应当及时将犯罪嫌疑线索提供给有关公安机关，但票据纠纷案件不应因此而中止审理。"},{"i":74,"n":"第七十四条","txt":"依照票据法第一百零四条的规定，由于金融机构工作人员在票据业务中玩忽职守，对违反票据法规定的票据予以承兑、付款、贴现或者保证，给当事人造成损失的，由该金融机构与直接责任人员依法承担连带责任。"},{"i":75,"n":"第七十五条","txt":"依照票据法第一百零六条的规定，由于出票人制作票据，或者其他票据债务人未按照法定条件在票据上签章，给他人造成损失的，除应当按照所记载事项承担票据责任外，还应当承担相应的民事责任。"}],"zuigaorenminfayuanguanyushenliwangluoxiaofeijiufen15b502":[{"i":1,"n":"第一条","txt":"电子商务经营者提供的格式条款有以下内容的，人民法院应当依法认定无效："},{"i":2,"n":"第二条","txt":"电子商务经营者就消费者权益保护法第二十五条第一款规定的四项除外商品做出七日内无理由退货承诺，消费者主张电子商务经营者应当遵守其承诺的，人民法院应予支持。"},{"i":3,"n":"第三条","txt":"消费者因检查商品的必要对商品进行拆封查验且不影响商品完好，电子商务经营者以商品已拆封为由主张不适用消费者权益保护法第二十五条规定的无理由退货制度的，人民法院不予支持，但法律另有规定的除外。"},{"i":4,"n":"第四条","txt":"电子商务平台经营者以标记自营业务方式或者虽未标记自营但实际开展自营业务所销售的商品或者提供的服务损害消费者合法权益，消费者主张电子商务平台经营者承担商品销售者或者服务提供者责任的，人民法院应予支持。"},{"i":5,"n":"第五条","txt":"平台内经营者出售商品或者提供服务过程中，其工作人员引导消费者通过交易平台提供的支付方式以外的方式进行支付，消费者主张平台内经营者承担商品销售者或者服务提供者责任，平台内经营者以未经过交易平台支付为由抗辩的，人民法院不予支持。"},{"i":6,"n":"第六条","txt":"注册网络经营账号开设网络店铺的平台内经营者，通过协议等方式将网络账号及店铺转让给其他经营者，但未依法进行相关经营主体信息变更公示，实际经营者的经营活动给消费者造成损害，消费者主张注册经营者、实际经营者承担赔偿责任的，人民法院应予支持。"},{"i":7,"n":"第七条","txt":"消费者在二手商品网络交易平台购买商品受到损害，人民法院综合销售者出售商品的性质、来源、数量、价格、频率、是否有其他销售渠道、收入等情况，能够认定销售者系从事商业经营活动，消费者主张销售者依据消费者权益保护法承担经营者责任的，人民法院应予支持。"},{"i":8,"n":"第八条","txt":"电子商务经营者在促销活动中提供的奖品、赠品或者消费者换购的商品给消费者造成损害，消费者主张电子商务经营者承担赔偿责任，电子商务经营者以奖品、赠品属于免费提供或者商品属于换购为由主张免责的，人民法院不予支持。"},{"i":9,"n":"第九条","txt":"电子商务经营者与他人签订的以虚构交易、虚构点击量、编造用户评价等方式进行虚假宣传的合同，人民法院应当依法认定无效。"},{"i":10,"n":"第十条","txt":"平台内经营者销售商品或者提供服务损害消费者合法权益，其向消费者承诺的赔偿标准高于相关法定赔偿标准，消费者主张平台内经营者按照承诺赔偿的，人民法院应依法予以支持。"},{"i":11,"n":"第十一条","txt":"平台内经营者开设网络直播间销售商品，其工作人员在网络直播中因虚假宣传等给消费者造成损害，消费者主张平台内经营者承担赔偿责任的，人民法院应予支持。"},{"i":12,"n":"第十二条","txt":"消费者因在网络直播间点击购买商品合法权益受到损害，直播间运营者不能证明已经以足以使消费者辨别的方式标明其并非销售者并标明实际销售者的，消费者主张直播间运营者承担商品销售者责任的，人民法院应予支持。"},{"i":13,"n":"第十三条","txt":"网络直播营销平台经营者通过网络直播方式开展自营业务销售商品，消费者主张其承担商品销售者责任的，人民法院应予支持。"},{"i":14,"n":"第十四条","txt":"网络直播间销售商品损害消费者合法权益，网络直播营销平台经营者不能提供直播间运营者的真实姓名、名称、地址和有效联系方式的，消费者依据消费者权益保护法第四十四条规定向网络直播营销平台经营者请求赔偿的，人民法院应予支持。网络直播营销平台经营者承担责任后，向直播间运营者追偿的，人民法院应予支持。"},{"i":15,"n":"第十五条","txt":"网络直播营销平台经营者对依法需取得食品经营许可的网络直播间的食品经营资质未尽到法定审核义务，使消费者的合法权益受到损害，消费者依据食品安全法第一百三十一条等规定主张网络直播营销平台经营者与直播间运营者承担连带责任的，人民法院应予支持。"},{"i":16,"n":"第十六条","txt":"网络直播营销平台经营者知道或者应当知道网络直播间销售的商品不符合保障人身、财产安全的要求，或者有其他侵害消费者合法权益行为，未采取必要措施，消费者依据电子商务法第三十八条等规定主张网络直播营销平台经营者与直播间运营者承担连带责任的，人民法院应予支持。"},{"i":17,"n":"第十七条","txt":"直播间运营者知道或者应当知道经营者提供的商品不符合保障人身、财产安全的要求，或者有其他侵害消费者合法权益行为，仍为其推广，给消费者造成损害，消费者依据民法典第一千一百六十八条等规定主张直播间运营者与提供该商品的经营者承担连带责任的，人民法院应予支持。"},{"i":18,"n":"第十八条","txt":"网络餐饮服务平台经营者违反食品安全法第六十二条和第一百三十一条规定，未对入网餐饮服务提供者进行实名登记、审查许可证，或者未履行报告、停止提供网络交易平台服务等义务，使消费者的合法权益受到损害，消费者主张网络餐饮服务平台经营者与入网餐饮服务提供者承担连带责任的，人民法院应予支持。"},{"i":19,"n":"第十九条","txt":"入网餐饮服务提供者所经营食品损害消费者合法权益，消费者主张入网餐饮服务提供者承担经营者责任，入网餐饮服务提供者以订单系委托他人加工制作为由抗辩的，人民法院不予支持。"},{"i":20,"n":"第二十条","txt":"本规定自2022年3月15日起施行。"}],"zuigaorenminfayuanguanyushenlichuanboyouwusunhaipef2e0f1":[{"i":1,"n":"第一条","txt":"船舶发生油污事故，对中华人民共和国领域和管辖的其他海域造成油污损害或者形成油污损害威胁，人民法院审理相关船舶油污损害赔偿纠纷案件，适用本规定。"},{"i":2,"n":"第二条","txt":"当事人就油轮装载持久性油类造成的油污损害提起诉讼、申请设立油污损害赔偿责任限制基金，由船舶油污事故发生地海事法院管辖。"},{"i":3,"n":"第三条","txt":"两艘或者两艘以上船舶泄漏油类造成油污损害，受损害人请求各泄漏油船舶所有人承担赔偿责任，按照泄漏油数量及泄漏油类对环境的危害性等因素能够合理分开各自造成的损害，由各泄漏油船舶所有人分别承担责任；不能合理分开各自造成的损害，各泄漏油船舶所有人承担连带责任。但泄漏油船舶所有人依法免予承担责任的除外。"},{"i":4,"n":"第四条","txt":"船舶互有过失碰撞引起油类泄漏造成油污损害的，受损害人可以请求泄漏油船舶所有人承担全部赔偿责任。"},{"i":5,"n":"第五条","txt":"油轮装载的持久性油类造成油污损害的，应依照《防治船舶污染海洋环境管理条例》《1992年国际油污损害民事责任公约》的规定确定赔偿限额。"},{"i":6,"n":"第六条","txt":"经证明油污损害是由于船舶所有人的故意或者明知可能造成此种损害而轻率地作为或者不作为造成的，船舶所有人主张限制赔偿责任，人民法院不予支持。"},{"i":7,"n":"第七条","txt":"油污损害是由于船舶所有人故意造成的，受损害人请求船舶油污损害责任保险人或者财务保证人赔偿，人民法院不予支持。"},{"i":8,"n":"第八条","txt":"受损害人直接向船舶油污损害责任保险人或者财务保证人提起诉讼，船舶油污损害责任保险人或者财务保证人可以对受损害人主张船舶所有人的抗辩。"},{"i":9,"n":"第九条","txt":"船舶油污损害赔偿范围包括："},{"i":10,"n":"第十条","txt":"对预防措施费用以及预防措施造成的进一步灭失或者损害，人民法院应当结合污染范围、污染程度、油类泄漏量、预防措施的合理性、参与清除油污人员及投入使用设备的费用等因素合理认定。"},{"i":11,"n":"第十一条","txt":"对遇险船舶实施防污措施，作业开始时的主要目的仅是为防止、减轻油污损害的，所发生的费用应认定为预防措施费用。"},{"i":12,"n":"第十二条","txt":"船舶泄漏油类污染其他船舶、渔具、养殖设施等财产，受损害人请求油污责任人赔偿因清洗、修复受污染财产支付的合理费用，人民法院应予支持。"},{"i":13,"n":"第十三条","txt":"受损害人因其财产遭受船舶油污，不能正常生产经营的，其收入损失应以财产清洗、修复或者更换所需合理期间为限进行计算。"},{"i":14,"n":"第十四条","txt":"海洋渔业、滨海旅游业及其他用海、临海经营单位或者个人请求因环境污染所遭受的收入损失，具备下列全部条件，由此证明收入损失与环境污染之间具有直接因果关系的，人民法院应予支持："},{"i":15,"n":"第十五条","txt":"未经相关行政主管部门许可，受损害人从事海上养殖、海洋捕捞，主张收入损失的，人民法院不予支持；但请求赔偿清洗、修复、更换养殖或者捕捞设施的合理费用，人民法院应予支持。"},{"i":16,"n":"第十六条","txt":"受损害人主张因其财产受污染或者因环境污染造成的收入损失，应以其前三年同期平均净收入扣减受损期间的实际净收入计算，并适当考虑影响收入的其他相关因素予以合理确定。"},{"i":17,"n":"第十七条","txt":"船舶油污事故造成环境损害的，对环境损害的赔偿应限于已实际采取或者将要采取的合理恢复措施的费用。恢复措施的费用包括合理的监测、评估、研究费用。"},{"i":18,"n":"第十八条","txt":"船舶取得有效的油污损害民事责任保险或者具有相应财务保证的，油污受损害人主张船舶优先权的，人民法院不予支持。"},{"i":19,"n":"第十九条","txt":"对油轮装载的非持久性燃油、非油轮装载的燃油造成油污损害的赔偿请求，适用海商法关于海事赔偿责任限制的规定。"},{"i":20,"n":"第二十条","txt":"为避免油轮装载的非持久性燃油、非油轮装载的燃油造成油污损害，对沉没、搁浅、遇难船舶采取起浮、清除或者使之无害措施，船舶所有人对由此发生的费用主张依照海商法第十一章的规定限制赔偿责任的，人民法院不予支持。"},{"i":21,"n":"第二十一条","txt":"对油轮装载持久性油类造成的油污损害，船舶所有人，或者船舶油污责任保险人、财务保证人主张责任限制的，应当设立油污损害赔偿责任限制基金。"},{"i":22,"n":"第二十二条","txt":"船舶所有人、船舶油污损害责任保险人或者财务保证人申请设立油污损害赔偿责任限制基金，利害关系人对船舶所有人主张限制赔偿责任有异议的，应当在海事诉讼特别程序法第一百零六条第一款规定的异议期内以书面形式提出，但提出该异议不影响基金的设立。"},{"i":23,"n":"第二十三条","txt":"对油轮装载持久性油类造成的油污损害，利害关系人没有在异议期内对船舶所有人主张限制赔偿责任提出异议，油污损害赔偿责任限制基金设立后，海事法院应当解除对船舶所有人的财产采取的保全措施或者发还为解除保全措施而提供的担保。"},{"i":24,"n":"第二十四条","txt":"对油轮装载持久性油类造成的油污损害，利害关系人在异议期内对船舶所有人主张限制赔偿责任提出异议的，人民法院在认定船舶所有人有权限制赔偿责任的裁决生效后，应当解除对船舶所有人的财产采取的保全措施或者发还为解除保全措施而提供的担保。"},{"i":25,"n":"第二十五条","txt":"对油轮装载持久性油类造成的油污损害，受损害人提起诉讼时主张船舶所有人无权限制赔偿责任的，海事法院对船舶所有人是否有权限制赔偿责任的争议，可以先行审理并作出判决。"},{"i":26,"n":"第二十六条","txt":"对油轮装载持久性油类造成的油污损害，受损害人没有在规定的债权登记期间申请债权登记的，视为放弃在油污损害赔偿责任限制基金中受偿的权利。"},{"i":27,"n":"第二十七条","txt":"油污损害赔偿责任限制基金不足以清偿有关油污损害的，应根据确认的赔偿数额依法按比例分配。"},{"i":28,"n":"第二十八条","txt":"对油轮装载持久性油类造成的油污损害，船舶所有人、船舶油污损害责任保险人或者财务保证人申请设立油污损害赔偿责任限制基金、受损害人申请债权登记与受偿，本规定没有规定的，适用海事诉讼特别程序法及相关司法解释的规定。"},{"i":29,"n":"第二十九条","txt":"在油污损害赔偿责任限制基金分配以前，船舶所有人、船舶油污损害责任保险人或者财务保证人，已先行赔付油污损害的，可以书面申请从基金中代位受偿。代位受偿应限于赔付的范围，并不超过接受赔付的人依法可获得的赔偿数额。"},{"i":30,"n":"第三十条","txt":"船舶所有人为主动防止、减轻油污损害而支出的合理费用或者所作的合理牺牲，请求参与油污损害赔偿责任限制基金分配的，人民法院应予支持，比照本规定第二十九条第二款、第三款的规定处理。"},{"i":31,"n":"第三十一条","txt":"本规定中下列用语的含义是："},{"i":32,"n":"第三十二条","txt":"本规定实施前本院发布的司法解释与本规定不一致的，以本规定为准。"}],"zuigaorenminfayuanguanyushenlichuanbopengzhuanghec68eaf7":[],"zuigaorenminfayuanguanyushenlichuanbopengzhuangjiue65d36":[{"i":1,"n":"第一条","txt":"本规定所称船舶碰撞，是指海商法第一百六十五条所指的船舶碰撞，不包括内河船舶之间的碰撞。"},{"i":2,"n":"第二条","txt":"审理船舶碰撞纠纷案件，依照海商法第八章的规定确定碰撞船舶的赔偿责任。"},{"i":3,"n":"第三条","txt":"因船舶碰撞导致船舶触碰引起的侵权纠纷，依照海商法第八章的规定确定碰撞船舶的赔偿责任。"},{"i":4,"n":"第四条","txt":"船舶碰撞产生的赔偿责任由船舶所有人承担，碰撞船舶在光船租赁期间并经依法登记的，由光船承租人承担。"},{"i":5,"n":"第五条","txt":"因船舶碰撞发生的船上人员的人身伤亡属于海商法第一百六十九条第三款规定的第三人的人身伤亡。"},{"i":6,"n":"第六条","txt":"碰撞船舶互有过失造成船载货物损失，船载货物的权利人对承运货物的本船提起违约赔偿之诉，或者对碰撞船舶一方或者双方提起侵权赔偿之诉的，人民法院应当依法予以受理。"},{"i":7,"n":"第七条","txt":"船载货物的权利人因船舶碰撞造成其货物损失向承运货物的本船提起诉讼的，承运船舶可以依照海商法第一百六十九条第二款的规定主张按照过失程度的比例承担赔偿责任。"},{"i":8,"n":"第八条","txt":"碰撞船舶船载货物权利人或者第三人向碰撞船舶一方或者双方就货物或其他财产损失提出赔偿请求的，由碰撞船舶方提供证据证明过失程度的比例。无正当理由拒不提供证据的，由碰撞船舶一方承担全部赔偿责任或者由双方承担连带赔偿责任。"},{"i":9,"n":"第九条","txt":"因起浮、清除、拆毁由船舶碰撞造成的沉没、遇难、搁浅或被弃船舶及船上货物或者使其无害的费用提出的赔偿请求，责任人不能依照海商法第十一章的规定享受海事赔偿责任限制。"},{"i":10,"n":"第十条","txt":"审理船舶碰撞纠纷案件时，人民法院根据当事人的申请进行证据保全取得的或者向有关部门调查收集的证据，应当在当事人完成举证并出具完成举证说明书后出示。"},{"i":11,"n":"第十一条","txt":"船舶碰撞事故发生后，主管机关依法进行调查取得并经过事故当事人和有关人员确认的碰撞事实调查材料，可以作为人民法院认定案件事实的证据，但有相反证据足以推翻的除外。"}],"zuigaorenminfayuanguanyushenlixingzhengxieyianjian115bdf":[{"i":1,"n":"第一条","txt":"行政机关为了实现行政管理或者公共服务目标，与公民、法人或者其他组织协商订立的具有行政法上权利义务内容的协议，属于行政诉讼法第十二条第一款第十一项规定的行政协议。"},{"i":2,"n":"第二条","txt":"公民、法人或者其他组织就下列行政协议提起行政诉讼的，人民法院应当依法受理："},{"i":3,"n":"第三条","txt":"因行政机关订立的下列协议提起诉讼的，不属于人民法院行政诉讼的受案范围："},{"i":4,"n":"第四条","txt":"因行政协议的订立、履行、变更、终止等发生纠纷，公民、法人或者其他组织作为原告，以行政机关为被告提起行政诉讼的，人民法院应当依法受理。"},{"i":5,"n":"第五条","txt":"下列与行政协议有利害关系的公民、法人或者其他组织提起行政诉讼的，人民法院应当依法受理："},{"i":6,"n":"第六条","txt":"人民法院受理行政协议案件后，被告就该协议的订立、履行、变更、终止等提起反诉的，人民法院不予准许。"},{"i":7,"n":"第七条","txt":"当事人书面协议约定选择被告所在地、原告所在地、协议履行地、协议订立地、标的物所在地等与争议有实际联系地点的人民法院管辖的，人民法院从其约定，但违反级别管辖和专属管辖的除外。"},{"i":8,"n":"第八条","txt":"公民、法人或者其他组织向人民法院提起民事诉讼，生效法律文书以涉案协议属于行政协议为由裁定不予立案或者驳回起诉，当事人又提起行政诉讼的，人民法院应当依法受理。"},{"i":9,"n":"第九条","txt":"在行政协议案件中，行政诉讼法第四十九条第三项规定的“有具体的诉讼请求”是指："},{"i":10,"n":"第十条","txt":"被告对于自己具有法定职权、履行法定程序、履行相应法定职责以及订立、履行、变更、解除行政协议等行为的合法性承担举证责任。"},{"i":11,"n":"第十一条","txt":"人民法院审理行政协议案件，应当对被告订立、履行、变更、解除行政协议的行为是否具有法定职权、是否滥用职权、适用法律法规是否正确、是否遵守法定程序、是否明显不当、是否履行相应法定职责进行合法性审查。"},{"i":12,"n":"第十二条","txt":"行政协议存在行政诉讼法第七十五条规定的重大且明显违法情形的，人民法院应当确认行政协议无效。"},{"i":13,"n":"第十三条","txt":"法律、行政法规规定应当经过其他机关批准等程序后生效的行政协议，在一审法庭辩论终结前未获得批准的，人民法院应当确认该协议未生效。"},{"i":14,"n":"第十四条","txt":"原告认为行政协议存在胁迫、欺诈、重大误解、显失公平等情形而请求撤销，人民法院经审理认为符合法律规定可撤销情形的，可以依法判决撤销该协议。"},{"i":15,"n":"第十五条","txt":"行政协议无效、被撤销或者确定不发生效力后，当事人因行政协议取得的财产，人民法院应当判决予以返还；不能返还的，判决折价补偿。"},{"i":16,"n":"第十六条","txt":"在履行行政协议过程中，可能出现严重损害国家利益、社会公共利益的情形，被告作出变更、解除协议的行政行为后，原告请求撤销该行为，人民法院经审理认为该行为合法的，判决驳回原告诉讼请求；给原告造成损失的，判决被告予以补偿。"},{"i":17,"n":"第十七条","txt":"原告请求解除行政协议，人民法院认为符合约定或者法定解除情形且不损害国家利益、社会公共利益和他人合法权益的，可以判决解除该协议。"},{"i":18,"n":"第十八条","txt":"当事人依据民事法律规范的规定行使履行抗辩权的，人民法院应予支持。"},{"i":19,"n":"第十九条","txt":"被告未依法履行、未按照约定履行行政协议，人民法院可以依据行政诉讼法第七十八条的规定，结合原告诉讼请求，判决被告继续履行，并明确继续履行的具体内容；被告无法履行或者继续履行无实际意义的，人民法院可以判决被告采取相应的补救措施；给原告造成损失的，判决被告予以赔偿。"},{"i":20,"n":"第二十条","txt":"被告明确表示或者以自己的行为表明不履行行政协议，原告在履行期限届满之前向人民法院起诉请求其承担违约责任的，人民法院应予支持。"},{"i":21,"n":"第二十一条","txt":"被告或者其他行政机关因国家利益、社会公共利益的需要依法行使行政职权，导致原告履行不能、履行费用明显增加或者遭受损失，原告请求判令被告给予补偿的，人民法院应予支持。"},{"i":22,"n":"第二十二条","txt":"原告以被告违约为由请求人民法院判令其承担违约责任，人民法院经审理认为行政协议无效的，应当向原告释明，并根据原告变更后的诉讼请求判决确认行政协议无效；因被告的行为造成行政协议无效的，人民法院可以依法判决被告承担赔偿责任。原告经释明后拒绝变更诉讼请求的，人民法院可以判决驳回其诉讼请求。"},{"i":23,"n":"第二十三条","txt":"人民法院审理行政协议案件，可以依法进行调解。"},{"i":24,"n":"第二十四条","txt":"公民、法人或者其他组织未按照行政协议约定履行义务，经催告后不履行，行政机关可以作出要求其履行协议的书面决定。公民、法人或者其他组织收到书面决定后在法定期限内未申请行政复议或者提起行政诉讼，且仍不履行，协议内容具有可执行性的，行政机关可以向人民法院申请强制执行。"},{"i":25,"n":"第二十五条","txt":"公民、法人或者其他组织对行政机关不依法履行、未按照约定履行行政协议提起诉讼的，诉讼时效参照民事法律规范确定；对行政机关变更、解除行政协议等行政行为提起诉讼的，起诉期限依照行政诉讼法及其司法解释确定。"},{"i":26,"n":"第二十六条","txt":"行政协议约定仲裁条款的，人民法院应当确认该条款无效，但法律、行政法规或者我国缔结、参加的国际条约另有规定的除外。"},{"i":27,"n":"第二十七条","txt":"人民法院审理行政协议案件，应当适用行政诉讼法的规定；行政诉讼法没有规定的，参照适用民事诉讼法的规定。"},{"i":28,"n":"第二十八条","txt":"2015年5月1日后订立的行政协议发生纠纷的，适用行政诉讼法及本规定。"},{"i":29,"n":"第二十九条","txt":"本规定自2020年1月1日起施行。最高人民法院以前发布的司法解释与本规定不一致的，适用本规定。"}],"zuigaorenminfayuanguanyushenlixingzhengxukeanjianredba48":[{"i":1,"n":"第一条","txt":"公民、法人或者其他组织认为行政机关作出的行政许可决定以及相应的不作为，或者行政机关就行政许可的变更、延续、撤回、注销、撤销等事项作出的有关具体行政行为及其相应的不作为侵犯其合法权益，提起行政诉讼的，人民法院应当依法受理。"},{"i":2,"n":"第二条","txt":"公民、法人或者其他组织认为行政机关未公开行政许可决定或者未提供行政许可监督检查记录侵犯其合法权益，提起行政诉讼的，人民法院应当依法受理。"},{"i":3,"n":"第三条","txt":"公民、法人或者其他组织仅就行政许可过程中的告知补正申请材料、听证等通知行为提起行政诉讼的，人民法院不予受理，但导致许可程序对上述主体事实上终止的除外。"},{"i":4,"n":"第四条","txt":"当事人不服行政许可决定提起诉讼的，以作出行政许可决定的机关为被告；行政许可依法须经上级行政机关批准，当事人对批准或者不批准行为不服一并提起诉讼的，以上级行政机关为共同被告；行政许可依法须经下级行政机关或者管理公共事务的组织初步审查并上报，当事人对不予初步审查或者不予上报不服提起诉讼的，以下级行政机关或者管理公共事务的组织为被告。"},{"i":5,"n":"第五条","txt":"行政机关依据行政许可法第二十六条第二款规定统一办理行政许可的，当事人对行政许可行为不服提起诉讼，以对当事人作出具有实质影响的不利行为的机关为被告。"},{"i":6,"n":"第六条","txt":"行政机关受理行政许可申请后，在法定期限内不予答复，公民、法人或者其他组织向人民法院起诉的，人民法院应当依法受理。"},{"i":7,"n":"第七条","txt":"作为被诉行政许可行为基础的其他行政决定或者文书存在以下情形之一的，人民法院不予认可："},{"i":8,"n":"第八条","txt":"被告不提供或者无正当理由逾期提供证据的，与被诉行政许可行为有利害关系的第三人可以向人民法院提供；第三人对无法提供的证据，可以申请人民法院调取；人民法院在当事人无争议，但涉及国家利益、公共利益或者他人合法权益的情况下，也可以依职权调取证据。"},{"i":9,"n":"第九条","txt":"人民法院审理行政许可案件，应当以申请人提出行政许可申请后实施的新的法律规范为依据；行政机关在旧的法律规范实施期间，无正当理由拖延审查行政许可申请至新的法律规范实施，适用新的法律规范不利于申请人的，以旧的法律规范为依据。"},{"i":10,"n":"第十条","txt":"被诉准予行政许可决定违反当时的法律规范但符合新的法律规范的，判决确认该决定违法；准予行政许可决定不损害公共利益和利害关系人合法权益的，判决驳回原告的诉讼请求。"},{"i":11,"n":"第十一条","txt":"人民法院审理不予行政许可决定案件，认为原告请求准予许可的理由成立，且被告没有裁量余地的，可以在判决理由写明，并判决撤销不予许可决定，责令被告重新作出决定。"},{"i":12,"n":"第十二条","txt":"被告无正当理由拒绝原告查阅行政许可决定及有关档案材料或者监督检查记录的，人民法院可以判决被告在法定或者合理期限内准予原告查阅。"},{"i":13,"n":"第十三条","txt":"被告在实施行政许可过程中，与他人恶意串通共同违法侵犯原告合法权益的，应当承担连带赔偿责任；被告与他人违法侵犯原告合法权益的，应当根据其违法行为在损害发生过程和结果中所起作用等因素，确定被告的行政赔偿责任；被告已经依照法定程序履行审慎合理的审查职责，因他人行为导致行政许可决定违法的，不承担赔偿责任。"},{"i":14,"n":"第十四条","txt":"行政机关依据行政许可法第八条第二款规定变更或者撤回已经生效的行政许可，公民、法人或者其他组织仅主张行政补偿的，应当先向行政机关提出申请；行政机关在法定期限或者合理期限内不予答复或者对行政机关作出的补偿决定不服的，可以依法提起行政诉讼。"},{"i":15,"n":"第十五条","txt":"法律、法规、规章或者规范性文件对变更或者撤回行政许可的补偿标准未作规定的，一般在实际损失范围内确定补偿数额；行政许可属于行政许可法第十二条第（二）项规定情形的，一般按照实际投入的损失确定补偿数额。"},{"i":16,"n":"第十六条","txt":"行政许可补偿案件的调解，参照最高人民法院《关于审理行政赔偿案件若干问题的规定》的有关规定办理。"},{"i":17,"n":"第十七条","txt":"最高人民法院以前所作的司法解释凡与本规定不一致的，按本规定执行。"}],"zuigaorenminfayuanguanyushenlixingzhengpeichanganj3c663e":[{"i":1,"n":"第一条","txt":"国家赔偿法第三条、第四条规定的“其他违法行为”包括以下情形："},{"i":2,"n":"第二条","txt":"依据行政诉讼法第一条、第十二条第一款第十二项和国家赔偿法第二条规定，公民、法人或者其他组织认为行政机关及其工作人员违法行使行政职权对其劳动权、相邻权等合法权益造成人身、财产损害的，可以依法提起行政赔偿诉讼。"},{"i":3,"n":"第三条","txt":"赔偿请求人不服赔偿义务机关下列行为的，可以依法提起行政赔偿诉讼："},{"i":4,"n":"第四条","txt":"法律规定由行政机关最终裁决的行政行为被确认违法后，赔偿请求人可以单独提起行政赔偿诉讼。"},{"i":5,"n":"第五条","txt":"公民、法人或者其他组织认为国防、外交等国家行为或者行政机关制定发布行政法规、规章或者具有普遍约束力的决定、命令侵犯其合法权益造成损害，向人民法院提起行政赔偿诉讼的，不属于人民法院行政赔偿诉讼的受案范围。"},{"i":6,"n":"第六条","txt":"公民、法人或者其他组织一并提起行政赔偿诉讼中的当事人地位，按照其在行政诉讼中的地位确定，行政诉讼与行政赔偿诉讼当事人不一致的除外。"},{"i":7,"n":"第七条","txt":"受害的公民死亡，其继承人和其他有扶养关系的人可以提起行政赔偿诉讼，并提供该公民死亡证明、赔偿请求人与死亡公民之间的关系证明。"},{"i":8,"n":"第八条","txt":"两个以上行政机关共同实施侵权行政行为造成损害的，共同侵权行政机关为共同被告。赔偿请求人坚持对其中一个或者几个侵权机关提起行政赔偿诉讼，以被起诉的机关为被告，未被起诉的机关追加为第三人。"},{"i":9,"n":"第九条","txt":"原行政行为造成赔偿请求人损害，复议决定加重损害的，复议机关与原行政行为机关为共同被告。赔偿请求人坚持对作出原行政行为机关或者复议机关提起行政赔偿诉讼，以被起诉的机关为被告，未被起诉的机关追加为第三人。"},{"i":10,"n":"第十条","txt":"行政机关依据行政诉讼法第九十七条的规定申请人民法院强制执行其行政行为，因据以强制执行的行政行为违法而发生行政赔偿诉讼的，申请强制执行的行政机关为被告。"},{"i":11,"n":"第十一条","txt":"行政赔偿诉讼中，原告应当对行政行为造成的损害提供证据；因被告的原因导致原告无法举证的，由被告承担举证责任。"},{"i":12,"n":"第十二条","txt":"原告主张其被限制人身自由期间受到身体伤害，被告否认相关损害事实或者损害与违法行政行为存在因果关系的，被告应当提供相应的证据证明。"},{"i":13,"n":"第十三条","txt":"行政行为未被确认为违法，公民、法人或者其他组织提起行政赔偿诉讼的，人民法院应当视为提起行政诉讼时一并提起行政赔偿诉讼。"},{"i":14,"n":"第十四条","txt":"原告提起行政诉讼时未一并提起行政赔偿诉讼，人民法院审查认为可能存在行政赔偿的，应当告知原告可以一并提起行政赔偿诉讼。"},{"i":15,"n":"第十五条","txt":"公民、法人或者其他组织应当自知道或者应当知道行政行为侵犯其合法权益之日起两年内，向赔偿义务机关申请行政赔偿。赔偿义务机关在收到赔偿申请之日起两个月内未作出赔偿决定的，公民、法人或者其他组织可以依照行政诉讼法有关规定提起行政赔偿诉讼。"},{"i":16,"n":"第十六条","txt":"公民、法人或者其他组织提起行政诉讼时一并请求行政赔偿的，适用行政诉讼法有关起诉期限的规定。"},{"i":17,"n":"第十七条","txt":"公民、法人或者其他组织仅对行政复议决定中的行政赔偿部分有异议，自复议决定书送达之日起十五日内提起行政赔偿诉讼的，人民法院应当依法受理。"},{"i":18,"n":"第十八条","txt":"行政行为被有权机关依照法定程序撤销、变更、确认违法或无效，或者实施行政行为的行政机关工作人员因该行为被生效法律文书或监察机关政务处分确认为渎职、滥用职权的，属于本规定所称的行政行为被确认为违法的情形。"},{"i":19,"n":"第十九条","txt":"公民、法人或者其他组织一并提起行政赔偿诉讼，人民法院经审查认为行政诉讼不符合起诉条件的，对一并提起的行政赔偿诉讼，裁定不予立案；已经立案的，裁定驳回起诉。"},{"i":20,"n":"第二十条","txt":"在涉及行政许可、登记、征收、征用和行政机关对民事争议所作的裁决的行政案件中，原告提起行政赔偿诉讼的同时，有关当事人申请一并解决相关民事争议的，人民法院可以一并审理。"},{"i":21,"n":"第二十一条","txt":"两个以上行政机关共同实施违法行政行为，或者行政机关及其工作人员与第三人恶意串通作出的违法行政行为，造成公民、法人或者其他组织人身权、财产权等合法权益实际损害的，应当承担连带赔偿责任。"},{"i":22,"n":"第二十二条","txt":"两个以上行政机关分别实施违法行政行为造成同一损害，每个行政机关的违法行为都足以造成全部损害的，各个行政机关承担连带赔偿责任。"},{"i":23,"n":"第二十三条","txt":"由于第三人提供虚假材料，导致行政机关作出的行政行为违法，造成公民、法人或者其他组织损害的，人民法院应当根据违法行政行为在损害发生和结果中的作用大小，确定行政机关承担相应的行政赔偿责任；行政机关已经尽到审慎审查义务的，不承担行政赔偿责任。"},{"i":24,"n":"第二十四条","txt":"由于第三人行为造成公民、法人或者其他组织损害的，应当由第三人依法承担侵权赔偿责任；第三人赔偿不足、无力承担赔偿责任或者下落不明，行政机关又未尽保护、监管、救助等法定义务的，人民法院应当根据行政机关未尽法定义务在损害发生和结果中的作用大小，确定其承担相应的行政赔偿责任。"},{"i":25,"n":"第二十五条","txt":"由于不可抗力等客观原因造成公民、法人或者其他组织损害，行政机关不依法履行、拖延履行法定义务导致未能及时止损或者损害扩大的，人民法院应当根据行政机关不依法履行、拖延履行法定义务行为在损害发生和结果中的作用大小，确定其承担相应的行政赔偿责任。"},{"i":26,"n":"第二十六条","txt":"有下列情形之一的，属于国家赔偿法第三十五条规定的“造成严重后果”："},{"i":27,"n":"第二十七条","txt":"违法行政行为造成公民、法人或者其他组织财产损害，不能返还财产或者恢复原状的，按照损害发生时该财产的市场价格计算损失。市场价格无法确定，或者该价格不足以弥补公民、法人或者其他组织损失的，可以采用其他合理方式计算。"},{"i":28,"n":"第二十八条","txt":"下列损失属于国家赔偿法第三十六条第六项规定的“停产停业期间必要的经常性费用开支”："},{"i":29,"n":"第二十九条","txt":"下列损失属于国家赔偿法第三十六条第八项规定的“直接损失”："},{"i":30,"n":"第三十条","txt":"被告有国家赔偿法第三条规定情形之一，致人精神损害的，人民法院应当判决其在违法行政行为影响的范围内，为受害人消除影响、恢复名誉、赔礼道歉；消除影响、恢复名誉和赔礼道歉的履行方式，可以双方协商，协商不成的，人民法院应当责令被告以适当的方式履行。造成严重后果的，应当判决支付相应的精神损害抚慰金。"},{"i":31,"n":"第三十一条","txt":"人民法院经过审理认为被告对公民、法人或者其他组织造成财产损害的，判决被告限期返还财产、恢复原状；无法返还财产、恢复原状的，判决被告限期支付赔偿金和相应的利息损失。"},{"i":32,"n":"第三十二条","txt":"有下列情形之一的，人民法院判决驳回原告的行政赔偿请求："},{"i":33,"n":"第三十三条","txt":"本规定自2022年5月1日起施行。《最高人民法院关于审理行政赔偿案件若干问题的规定》（法发〔1997〕10号）同时废止。"}],"zuigaorenminfayuanguanyushenlizhengquanshichangxujd3f435":[{"i":1,"n":"第一条","txt":"信息披露义务人在证券交易场所发行、交易证券过程中实施虚假陈述引发的侵权民事赔偿案件，适用本规定。"},{"i":2,"n":"第二条","txt":"原告提起证券虚假陈述侵权民事赔偿诉讼，符合民事诉讼法第一百二十二条规定，并提交以下证据或者证明材料的，人民法院应当受理："},{"i":3,"n":"第三条","txt":"证券虚假陈述侵权民事赔偿案件，由发行人住所地的省、自治区、直辖市人民政府所在的市、计划单列市和经济特区中级人民法院或者专门人民法院管辖。《最高人民法院关于证券纠纷代表人诉讼若干问题的规定》等对管辖另有规定的，从其规定。"},{"i":4,"n":"第四条","txt":"信息披露义务人违反法律、行政法规、监管部门制定的规章和规范性文件关于信息披露的规定，在披露的信息中存在虚假记载、误导性陈述或者重大遗漏的，人民法院应当认定为虚假陈述。"},{"i":5,"n":"第五条","txt":"证券法第八十五条规定的“未按照规定披露信息”，是指信息披露义务人未按照规定的期限、方式等要求及时、公平披露信息。"},{"i":6,"n":"第六条","txt":"原告以信息披露文件中的盈利预测、发展规划等预测性信息与实际经营情况存在重大差异为由主张发行人实施虚假陈述的，人民法院不予支持，但有下列情形之一的除外："},{"i":7,"n":"第七条","txt":"虚假陈述实施日，是指信息披露义务人作出虚假陈述或者发生虚假陈述之日。"},{"i":8,"n":"第八条","txt":"虚假陈述揭露日，是指虚假陈述在具有全国性影响的报刊、电台、电视台或监管部门网站、交易场所网站、主要门户网站、行业知名的自媒体等媒体上，首次被公开揭露并为证券市场知悉之日。"},{"i":9,"n":"第九条","txt":"虚假陈述更正日，是指信息披露义务人在证券交易场所网站或者符合监管部门规定条件的媒体上，自行更正虚假陈述之日。"},{"i":10,"n":"第十条","txt":"有下列情形之一的，人民法院应当认定虚假陈述的内容具有重大性："},{"i":11,"n":"第十一条","txt":"原告能够证明下列情形的，人民法院应当认定原告的投资决定与虚假陈述之间的交易因果关系成立："},{"i":12,"n":"第十二条","txt":"被告能够证明下列情形之一的，人民法院应当认定交易因果关系不成立："},{"i":13,"n":"第十三条","txt":"证券法第八十五条、第一百六十三条所称的过错，包括以下两种情形："},{"i":14,"n":"第十四条","txt":"发行人的董事、监事、高级管理人员和其他直接责任人员主张对虚假陈述没有过错的，人民法院应当根据其工作岗位和职责、在信息披露资料的形成和发布等活动中所起的作用、取得和了解相关信息的渠道、为核验相关信息所采取的措施等实际情况进行审查认定。"},{"i":15,"n":"第十五条","txt":"发行人的董事、监事、高级管理人员依照证券法第八十二条第四款的规定，以书面方式发表附具体理由的意见并依法披露的，人民法院可以认定其主观上没有过错，但在审议、审核信息披露文件时投赞成票的除外。"},{"i":16,"n":"第十六条","txt":"独立董事能够证明下列情形之一的，人民法院应当认定其没有过错："},{"i":17,"n":"第十七条","txt":"保荐机构、承销机构等机构及其直接责任人员提交的尽职调查工作底稿、尽职调查报告、内部审核意见等证据能够证明下列情形的，人民法院应当认定其没有过错："},{"i":18,"n":"第十八条","txt":"会计师事务所、律师事务所、资信评级机构、资产评估机构、财务顾问等证券服务机构制作、出具的文件存在虚假陈述的，人民法院应当按照法律、行政法规、监管部门制定的规章和规范性文件，参考行业执业规范规定的工作范围和程序要求等内容，结合其核查、验证工作底稿等相关证据，认定其是否存在过错。"},{"i":19,"n":"第十九条","txt":"会计师事务所能够证明下列情形之一的，人民法院应当认定其没有过错："},{"i":20,"n":"第二十条","txt":"发行人的控股股东、实际控制人组织、指使发行人实施虚假陈述，致使原告在证券交易中遭受损失的，原告起诉请求直接判令该控股股东、实际控制人依照本规定赔偿损失的，人民法院应当予以支持。"},{"i":21,"n":"第二十一条","txt":"公司重大资产重组的交易对方所提供的信息不符合真实、准确、完整的要求，导致公司披露的相关信息存在虚假陈述，原告起诉请求判令该交易对方与发行人等责任主体赔偿由此导致的损失的，人民法院应当予以支持。"},{"i":22,"n":"第二十二条","txt":"有证据证明发行人的供应商、客户，以及为发行人提供服务的金融机构等明知发行人实施财务造假活动，仍然为其提供相关交易合同、发票、存款证明等予以配合，或者故意隐瞒重要事实致使发行人的信息披露文件存在虚假陈述，原告起诉请求判令其与发行人等责任主体赔偿由此导致的损失的，人民法院应当予以支持。"},{"i":23,"n":"第二十三条","txt":"承担连带责任的当事人之间的责任分担与追偿，按照民法典第一百七十八条的规定处理，但本规定第二十条第二款规定的情形除外。"},{"i":24,"n":"第二十四条","txt":"发行人在证券发行市场虚假陈述，导致原告损失的，原告有权请求按照本规定第二十五条的规定赔偿损失。"},{"i":25,"n":"第二十五条","txt":"信息披露义务人在证券交易市场承担民事赔偿责任的范围，以原告因虚假陈述而实际发生的损失为限。原告实际损失包括投资差额损失、投资差额损失部分的佣金和印花税。"},{"i":26,"n":"第二十六条","txt":"投资差额损失计算的基准日，是指在虚假陈述揭露或更正后，为将原告应获赔偿限定在虚假陈述所造成的损失范围内，确定损失计算的合理期间而规定的截止日期。"},{"i":27,"n":"第二十七条","txt":"在采用集中竞价的交易市场中，原告因虚假陈述买入相关股票所造成的投资差额损失，按照下列方法计算："},{"i":28,"n":"第二十八条","txt":"在采用集中竞价的交易市场中，原告因虚假陈述卖出相关股票所造成的投资差额损失，按照下列方法计算："},{"i":29,"n":"第二十九条","txt":"计算投资差额损失时，已经除权的证券，证券价格和证券数量应当复权计算。"},{"i":30,"n":"第三十条","txt":"证券公司、基金管理公司、保险公司、信托公司、商业银行等市场参与主体依法设立的证券投资产品，在确定因虚假陈述导致的损失时，每个产品应当单独计算。"},{"i":31,"n":"第三十一条","txt":"人民法院应当查明虚假陈述与原告损失之间的因果关系，以及导致原告损失的其他原因等案件基本事实，确定赔偿责任范围。"},{"i":32,"n":"第三十二条","txt":"当事人主张以揭露日或更正日起算诉讼时效的，人民法院应当予以支持。揭露日与更正日不一致的，以在先的为准。"},{"i":33,"n":"第三十三条","txt":"在诉讼时效期间内，部分投资者向人民法院提起人数不确定的普通代表人诉讼的，人民法院应当认定该起诉行为对所有具有同类诉讼请求的权利人发生时效中断的效果。"},{"i":34,"n":"第三十四条","txt":"本规定所称证券交易场所，是指证券交易所、国务院批准的其他全国性证券交易场所。"},{"i":35,"n":"第三十五条","txt":"本规定自2022年1月22日起施行。《最高人民法院关于受理证券市场因虚假陈述引发的民事侵权纠纷案件有关问题的通知》《最高人民法院关于审理证券市场因虚假陈述引发的民事赔偿案件的若干规定》同时废止。《最高人民法院关于审理涉及会计师事务所在审计业务活动中民事侵权赔偿案件的若干规定》与本规定不一致的，以本规定为准。"}],"zuigaorenminfayuanguanyushenliyinhangkaminshijiufe60f51a":[{"i":1,"n":"第一条","txt":"持卡人与发卡行、非银行支付机构、收单行、特约商户等当事人之间因订立银行卡合同、使用银行卡等产生的民事纠纷，适用本规定。"},{"i":2,"n":"第二条","txt":"发卡行在与持卡人订立银行卡合同时，对收取利息、复利、费用、违约金等格式条款未履行提示或者说明义务，致使持卡人没有注意或者理解该条款，持卡人主张该条款不成为合同的内容、对其不具有约束力的，人民法院应予支持。"},{"i":3,"n":"第三条","txt":"具有下列情形之一的，应当认定发卡行对持卡人享有的债权请求权诉讼时效中断："},{"i":4,"n":"第四条","txt":"持卡人主张争议交易为伪卡盗刷交易或者网络盗刷交易的，可以提供生效法律文书、银行卡交易时真卡所在地、交易行为地、账户交易明细、交易通知、报警记录、挂失记录等证据材料进行证明。"},{"i":5,"n":"第五条","txt":"在持卡人告知发卡行其账户发生非因本人交易或者本人授权交易导致的资金或者透支数额变动后，发卡行未及时向持卡人核实银行卡的持有及使用情况，未及时提供或者保存交易单据、监控录像等证据材料，导致有关证据材料无法取得的，应承担举证不能的法律后果。"},{"i":6,"n":"第六条","txt":"人民法院应当全面审查当事人提交的证据，结合银行卡交易行为地与真卡所在地距离、持卡人是否进行了基础交易、交易时间和报警时间、持卡人用卡习惯、银行卡被盗刷的次数及频率、交易系统、技术和设备是否具有安全性等事实，综合判断是否存在伪卡盗刷交易或者网络盗刷交易。"},{"i":7,"n":"第七条","txt":"发生伪卡盗刷交易或者网络盗刷交易，借记卡持卡人基于借记卡合同法律关系请求发卡行支付被盗刷存款本息并赔偿损失的，人民法院依法予以支持。"},{"i":8,"n":"第八条","txt":"发卡行在与持卡人订立银行卡合同或者在开通网络支付业务功能时，未履行告知持卡人银行卡具有相关网络支付功能义务，持卡人以其未与发卡行就争议网络支付条款达成合意为由请求不承担因使用该功能而导致网络盗刷责任的，人民法院应予支持，但有证据证明持卡人同意使用该网络支付功能的，适用本规定第七条规定。"},{"i":9,"n":"第九条","txt":"发卡行在与持卡人订立银行卡合同或者新增网络支付业务时，未完全告知某一网络支付业务持卡人身份识别方式、交易验证方式、交易规则等足以影响持卡人决定是否使用该功能的内容，致使持卡人没有全面准确理解该功能，持卡人以其未与发卡行就相关网络支付条款达成合意为由请求不承担因使用该功能而导致网络盗刷责任的，人民法院应予支持，但持卡人对于网络盗刷具有过错的，应当承担相应过错责任。发卡行虽然未尽前述义务，但是有证据证明持卡人知道并理解该网络支付功能的，适用本规定第七条规定。"},{"i":10,"n":"第十条","txt":"发卡行或者非银行支付机构向持卡人提供的宣传资料载明其承担网络盗刷先行赔付责任，该允诺具体明确，应认定为合同的内容。持卡人据此请求发卡行或者非银行支付机构承担先行赔付责任的，人民法院应予支持。"},{"i":11,"n":"第十一条","txt":"在收单行与发卡行不是同一银行的情形下，因收单行未尽保障持卡人用卡安全义务或者因特约商户未尽审核持卡人签名真伪、银行卡真伪等审核义务导致发生伪卡盗刷交易，持卡人请求收单行或者特约商户承担赔偿责任的，人民法院应予支持，但持卡人对伪卡盗刷交易具有过错，可以减轻或者免除收单行或者特约商户相应责任。"},{"i":12,"n":"第十二条","txt":"发卡行、非银行支付机构、收单行、特约商户承担责任后，请求盗刷者承担侵权责任的，人民法院应予支持。"},{"i":13,"n":"第十三条","txt":"因同一伪卡盗刷交易或者网络盗刷交易，持卡人向发卡行、非银行支付机构、收单行、特约商户、盗刷者等主体主张权利，所获赔偿数额不应超过其因银行卡被盗刷所致损失总额。"},{"i":14,"n":"第十四条","txt":"持卡人依据其对伪卡盗刷交易或者网络盗刷交易不承担或者不完全承担责任的事实，请求发卡行及时撤销相应不良征信记录的，人民法院应予支持。"},{"i":15,"n":"第十五条","txt":"本规定所称伪卡盗刷交易，是指他人使用伪造的银行卡刷卡进行取现、消费、转账等，导致持卡人账户发生非基于本人意思的资金减少或者透支数额增加的行为。"},{"i":16,"n":"第十六条","txt":"本规定施行后尚未终审的案件，适用本规定。本规定施行前已经终审，当事人申请再审或者按照审判监督程序决定再审的案件，不适用本规定。"}],"zuigaorenminfayuanguanyushenlishipinyaopinjiufenan8ee41e":[{"i":1,"n":"第一条","txt":"消费者因食品、药品纠纷提起民事诉讼，符合民事诉讼法规定受理条件的，人民法院应予受理。"},{"i":2,"n":"第二条","txt":"因食品、药品存在质量问题造成消费者损害，消费者可以分别起诉或者同时起诉销售者和生产者。"},{"i":3,"n":"第三条","txt":"因食品、药品质量问题发生纠纷，购买者向生产者、销售者主张权利，生产者、销售者以购买者明知食品、药品存在质量问题而仍然购买为由进行抗辩的，人民法院不予支持。"},{"i":4,"n":"第四条","txt":"食品、药品生产者、销售者提供给消费者的食品或者药品的赠品发生质量安全问题，造成消费者损害，消费者主张权利，生产者、销售者以消费者未对赠品支付对价为由进行免责抗辩的，人民法院不予支持。"},{"i":5,"n":"第五条","txt":"消费者举证证明所购买食品、药品的事实以及所购食品、药品不符合合同的约定，主张食品、药品的生产者、销售者承担违约责任的，人民法院应予支持。"},{"i":6,"n":"第六条","txt":"食品的生产者与销售者应当对于食品符合质量标准承担举证责任。认定食品是否安全，应当以国家标准为依据；对地方特色食品，没有国家标准的，应当以地方标准为依据。没有前述标准的，应当以食品安全法的相关规定为依据。"},{"i":7,"n":"第七条","txt":"食品、药品虽在销售前取得检验合格证明，且食用或者使用时尚在保质期内，但经检验确认产品不合格，生产者或者销售者以该食品、药品具有检验合格证明为由进行抗辩的，人民法院不予支持。"},{"i":8,"n":"第八条","txt":"集中交易市场的开办者、柜台出租者、展销会举办者未履行食品安全法规定的审查、检查、报告等义务，使消费者的合法权益受到损害的，消费者请求集中交易市场的开办者、柜台出租者、展销会举办者承担连带责任的，人民法院应予支持。"},{"i":9,"n":"第九条","txt":"消费者通过网络交易第三方平台购买食品、药品遭受损害，网络交易第三方平台提供者不能提供食品、药品的生产者或者销售者的真实名称、地址与有效联系方式，消费者请求网络交易第三方平台提供者承担责任的，人民法院应予支持。"},{"i":10,"n":"第十条","txt":"未取得食品生产资质与销售资质的民事主体，挂靠具有相应资质的生产者与销售者，生产、销售食品，造成消费者损害，消费者请求挂靠者与被挂靠者承担连带责任的，人民法院应予支持。"},{"i":11,"n":"第十一条","txt":"消费者因虚假广告推荐的食品、药品存在质量问题遭受损害，依据消费者权益保护法等法律相关规定请求广告经营者、广告发布者承担连带责任的，人民法院应予支持。"},{"i":12,"n":"第十二条","txt":"食品检验机构故意出具虚假检验报告，造成消费者损害，消费者请求其承担连带责任的，人民法院应予支持。"},{"i":13,"n":"第十三条","txt":"食品认证机构故意出具虚假认证，造成消费者损害，消费者请求其承担连带责任的，人民法院应予支持。"},{"i":14,"n":"第十四条","txt":"生产、销售的食品、药品存在质量问题，生产者与销售者需同时承担民事责任、行政责任和刑事责任，其财产不足以支付，当事人依照民法典等有关法律规定，请求食品、药品的生产者、销售者首先承担民事责任的，人民法院应予支持。"},{"i":15,"n":"第十五条","txt":"生产不符合安全标准的食品或者销售明知是不符合安全标准的食品，消费者除要求赔偿损失外，依据食品安全法等法律规定向生产者、销售者主张赔偿金的，人民法院应予支持。"},{"i":16,"n":"第十六条","txt":"食品、药品的生产者与销售者以格式合同、通知、声明、告示等方式作出排除或者限制消费者权利，减轻或者免除经营者责任、加重消费者责任等对消费者不公平、不合理的规定，消费者依法请求认定该内容无效的，人民法院应予支持。"},{"i":17,"n":"第十七条","txt":"消费者与化妆品、保健食品等产品的生产者、销售者、广告经营者、广告发布者、推荐者、检验机构等主体之间的纠纷，参照适用本规定。"},{"i":18,"n":"第十八条","txt":"本规定所称的“药品的生产者”包括药品上市许可持有人和药品生产企业，“药品的销售者”包括药品经营企业和医疗机构。"},{"i":19,"n":"第十九条","txt":"本规定施行后人民法院正在审理的一审、二审案件适用本规定。"}],"zuigaorenminfayuanguanyuduiyuzhengquanjiaoyisuojia27b6a9":[],"zuigaorenminfayuanguanyuxunhuifatingshenlianjianru9f9844":[{"i":1,"n":"第一条","txt":"最高人民法院设立巡回法庭，受理巡回区内相关案件。第一巡回法庭设在广东省深圳市，巡回区为广东、广西、海南、湖南四省区。第二巡回法庭设在辽宁省沈阳市，巡回区为辽宁、吉林、黑龙江三省。第三巡回法庭设在江苏省南京市，巡回区为江苏、上海、浙江、福建、江西五省市。第四巡回法庭设在河南省郑州市，巡回区为河南、山西、湖北、安徽四省。第五巡回法庭设在重庆市，巡回区为重庆、四川、贵州、云南、西藏五省区。第六巡回法庭设在陕西省西安市，巡回区为陕西、甘肃、青海、宁夏、新疆五省区。最高人民法院本部直接受理北京、天津、河北、山东、内蒙古五省区市有关案件。"},{"i":2,"n":"第二条","txt":"巡回法庭是最高人民法院派出的常设审判机构。巡回法庭作出的判决、裁定和决定，是最高人民法院的判决、裁定和决定。"},{"i":3,"n":"第三条","txt":"巡回法庭审理或者办理巡回区内应当由最高人民法院受理的以下案件："},{"i":4,"n":"第四条","txt":"知识产权、涉外商事、海事海商、死刑复核、国家赔偿、执行案件和最高人民检察院抗诉的案件暂由最高人民法院本部审理或者办理。"},{"i":5,"n":"第五条","txt":"巡回法庭设立诉讼服务中心，接受并登记属于巡回法庭受案范围的案件材料，为当事人提供诉讼服务。对于依照本规定应当由最高人民法院本部受理案件的材料，当事人要求巡回法庭转交的，巡回法庭应当转交。"},{"i":6,"n":"第六条","txt":"当事人不服巡回区内高级人民法院作出的第一审行政或者民商事判决、裁定提起上诉的，上诉状应当通过原审人民法院向巡回法庭提出。当事人直接向巡回法庭上诉的，巡回法庭应当在五日内将上诉状移交原审人民法院。原审人民法院收到上诉状、答辩状，应当在五日内连同全部案卷和证据，报送巡回法庭。"},{"i":7,"n":"第七条","txt":"当事人对巡回区内高级人民法院作出的已经发生法律效力的判决、裁定申请再审或者申诉的，应当向巡回法庭提交再审申请书、申诉书等材料。"},{"i":8,"n":"第八条","txt":"最高人民法院认为巡回法庭受理的案件对统一法律适用有重大指导意义的，可以决定由本部审理。"},{"i":9,"n":"第九条","txt":"巡回法庭根据审判工作需要，可以在巡回区内巡回审理案件、接待来访。"},{"i":10,"n":"第十条","txt":"巡回法庭按照让审理者裁判、由裁判者负责原则，实行主审法官、合议庭办案责任制。巡回法庭主审法官由最高人民法院从办案能力突出、审判经验丰富的审判人员中选派。巡回法庭的合议庭由主审法官组成。"},{"i":11,"n":"第十一条","txt":"巡回法庭庭长、副庭长应当参加合议庭审理案件。合议庭审理案件时，由承办案件的主审法官担任审判长。庭长或者副庭长参加合议庭审理案件时，自己担任审判长。巡回法庭作出的判决、裁定，经合议庭成员签署后，由审判长签发。"},{"i":12,"n":"第十二条","txt":"巡回法庭受理的案件，统一纳入最高人民法院审判信息综合管理平台进行管理，立案信息、审判流程、裁判文书面向当事人和社会依法公开。"},{"i":13,"n":"第十三条","txt":"巡回法庭设廉政监察员，负责巡回法庭的日常廉政监督工作。"}],"zuigaorenminfayuanguanyuchengyujinrongfayuananjian1f706d":[{"i":1,"n":"第一条","txt":"成渝金融法院管辖重庆市以及四川省属于成渝地区双城经济圈范围内的应由中级人民法院受理的下列第一审金融民商事案件："},{"i":2,"n":"第二条","txt":"下列金融纠纷案件，由成渝金融法院管辖："},{"i":3,"n":"第三条","txt":"以住所地在重庆市以及四川省属于成渝地区双城经济圈范围内依法设立的金融基础设施机构为被告或者第三人，与其履行职责相关的第一审金融民商事案件和涉金融行政案件，由成渝金融法院管辖。"},{"i":4,"n":"第四条","txt":"重庆市以及四川省属于成渝地区双城经济圈范围内应由中级人民法院受理的对金融监管机构以及法律、法规、规章授权的组织，因履行金融监管职责作出的行政行为不服提起诉讼的第一审涉金融行政案件，由成渝金融法院管辖。"},{"i":5,"n":"第五条","txt":"重庆市以及四川省属于成渝地区双城经济圈范围内基层人民法院涉及本规定第一条第一至三项的第一审金融民商事案件和第一审涉金融行政案件的上诉案件，由成渝金融法院审理。"},{"i":6,"n":"第六条","txt":"重庆市以及四川省属于成渝地区双城经济圈范围内应由中级人民法院受理的金融民商事案件、涉金融行政案件的申请再审和再审案件，由成渝金融法院审理。"},{"i":7,"n":"第七条","txt":"成渝金融法院作出的第一审民商事案件和涉金融行政案件生效裁判，重庆市以及四川省属于成渝地区双城经济圈范围内应由中级人民法院执行的涉金融民商事纠纷的仲裁裁决，由成渝金融法院执行。"},{"i":8,"n":"第八条","txt":"当事人对成渝金融法院作出的第一审判决、裁定提起的上诉案件，由重庆市高级人民法院审理。"},{"i":9,"n":"第九条","txt":"成渝金融法院作出发生法律效力的判决、裁定和调解书的申请再审、再审案件，依法应由上一级人民法院管辖的，由重庆市高级人民法院审理。"},{"i":10,"n":"第十条","txt":"重庆市以及四川省属于成渝地区双城经济圈范围内各中级人民法院在本规定施行前已经受理但尚未审结的金融民商事案件和涉金融行政案件，由该中级人民法院继续审理。"},{"i":11,"n":"第十一条","txt":"本规定自2023年1月1日起施行。"}],"zuigaorenminfayuanguanyukouyayupaimaichuanboshiyon686e97":[{"i":1,"n":"第一条","txt":"海事请求人申请对船舶采取限制处分或者抵押等保全措施的，海事法院可以依照民事诉讼法的有关规定，裁定准许并通知船舶登记机关协助执行。"},{"i":2,"n":"第二条","txt":"海事法院应不同海事请求人的申请，可以对本院或其他海事法院已经扣押的船舶采取扣押措施。"},{"i":3,"n":"第三条","txt":"船舶因光船承租人对海事请求负有责任而被扣押的，海事请求人依据海事诉讼特别程序法第二十九条的规定，申请拍卖船舶用于清偿光船承租人经营该船舶产生的相关债务的，海事法院应予准许。"},{"i":4,"n":"第四条","txt":"海事请求人申请扣押船舶的，海事法院应当责令其提供担保。但因船员劳务合同、海上及通海水域人身损害赔偿纠纷申请扣押船舶，且事实清楚、权利义务关系明确的，可以不要求提供担保。"},{"i":5,"n":"第五条","txt":"海事诉讼特别程序法第七十六条第二款规定的海事请求人提供担保的具体数额，应当相当于船舶扣押期间可能产生的各项维持费用与支出、因扣押造成的船期损失和被请求人为使船舶解除扣押而提供担保所支出的费用。"},{"i":6,"n":"第六条","txt":"案件终审后，海事请求人申请返还其所提供担保的，海事法院应将该申请告知被请求人，被请求人在三十日内未提起相关索赔诉讼的，海事法院可以准许海事请求人返还担保的申请。"},{"i":7,"n":"第七条","txt":"船舶扣押期间由船舶所有人或光船承租人负责管理。"},{"i":8,"n":"第八条","txt":"船舶扣押后，海事请求人依据海事诉讼特别程序法第十九条的规定，向其他有管辖权的海事法院提起诉讼的，可以由扣押船舶的海事法院继续实施保全措施。"},{"i":9,"n":"第九条","txt":"扣押船舶裁定执行前，海事请求人撤回扣押船舶申请的，海事法院应当裁定予以准许，并终结扣押船舶裁定的执行。"},{"i":10,"n":"第十条","txt":"船舶拍卖未能成交，需要再次拍卖的，适用拍卖法第四十五条关于拍卖日七日前发布拍卖公告的规定。"},{"i":11,"n":"第十一条","txt":"拍卖船舶由拍卖船舶委员会实施，海事法院不另行委托拍卖机构进行拍卖。"},{"i":12,"n":"第十二条","txt":"海事法院拍卖船舶应当依据评估价确定保留价。保留价不得公开。"},{"i":13,"n":"第十三条","txt":"对经过两次拍卖仍然流拍的船舶，可以进行变卖。变卖价格不得低于评估价的百分之五十。"},{"i":14,"n":"第十四条","txt":"依照本规定第十三条变卖仍未成交的，经已受理登记债权三分之二以上份额的债权人同意，可以低于评估价的百分之五十进行变卖处理。仍未成交的，海事法院可以解除船舶扣押。"},{"i":15,"n":"第十五条","txt":"船舶经海事法院拍卖、变卖后，对该船舶已采取的其他保全措施效力消灭。"},{"i":16,"n":"第十六条","txt":"海事诉讼特别程序法第一百一十一条规定的申请债权登记期间的届满之日，为拍卖船舶公告最后一次发布之日起第六十日。"},{"i":17,"n":"第十七条","txt":"海事法院受理债权登记申请后，应当在船舶被拍卖、变卖成交后，依照海事诉讼特别程序法第一百一十四条的规定作出是否准予的裁定。"},{"i":18,"n":"第十八条","txt":"申请拍卖船舶的海事请求人未经债权登记，直接要求参与拍卖船舶价款分配的，海事法院应予准许。"},{"i":19,"n":"第十九条","txt":"海事法院裁定终止拍卖船舶的，应当同时裁定终结债权登记受偿程序，当事人已经缴纳的债权登记申请费予以退还。"},{"i":20,"n":"第二十条","txt":"当事人在债权登记前已经就有关债权提起诉讼的，不适用海事诉讼特别程序法第一百一十六条第二款的规定，当事人对海事法院作出的判决、裁定可以依法提起上诉。"},{"i":21,"n":"第二十一条","txt":"债权人依照海事诉讼特别程序法第一百一十六条第一款的规定提起确权诉讼后，需要判定碰撞船舶过失程度比例的，当事人对海事法院作出的判决、裁定可以依法提起上诉。"},{"i":22,"n":"第二十二条","txt":"海事法院拍卖、变卖船舶所得价款及其利息，先行拨付海事诉讼特别程序法第一百一十九条第二款规定的费用后，依法按照下列顺序进行分配："},{"i":23,"n":"第二十三条","txt":"当事人依照民事诉讼法第十五章第七节的规定，申请拍卖船舶实现船舶担保物权的，由船舶所在地或船籍港所在地的海事法院管辖，按照海事诉讼特别程序法以及本规定关于船舶拍卖受偿程序的规定处理。"},{"i":24,"n":"第二十四条","txt":"海事法院的上级人民法院扣押与拍卖船舶的，适用本规定。"},{"i":25,"n":"第二十五条","txt":"本规定施行前已经实施的船舶扣押与拍卖，本规定施行后当事人申请复议的，不适用本规定。"}],"zuigaorenminfayuanguanyuzhixingxingfaquedingzuimindf4912":[],"zuigaorenminfayuanguanyuzhixinghejieruoganwentideg21d860":[{"i":1,"n":"第一条","txt":"当事人可以自愿协商达成和解协议，依法变更生效法律文书确定的权利义务主体、履行标的、期限、地点和方式等内容。"},{"i":2,"n":"第二条","txt":"和解协议达成后，有下列情形之一的，人民法院可以裁定中止执行："},{"i":3,"n":"第三条","txt":"中止执行后，申请执行人申请解除查封、扣押、冻结的，人民法院可以准许。"},{"i":4,"n":"第四条","txt":"委托代理人代为执行和解，应当有委托人的特别授权。"},{"i":5,"n":"第五条","txt":"当事人协商一致，可以变更执行和解协议，并向人民法院提交变更后的协议，或者由执行人员将变更后的内容记入笔录，并由各方当事人签名或者盖章。"},{"i":6,"n":"第六条","txt":"当事人达成以物抵债执行和解协议的，人民法院不得依据该协议作出以物抵债裁定。"},{"i":7,"n":"第七条","txt":"执行和解协议履行过程中，符合民法典第五百七十条规定情形的，债务人可以依法向有关机构申请提存；执行和解协议约定给付金钱的，债务人也可以向执行法院申请提存。"},{"i":8,"n":"第八条","txt":"执行和解协议履行完毕的，人民法院作执行结案处理。"},{"i":9,"n":"第九条","txt":"被执行人一方不履行执行和解协议的，申请执行人可以申请恢复执行原生效法律文书，也可以就履行执行和解协议向执行法院提起诉讼。"},{"i":10,"n":"第十条","txt":"申请恢复执行原生效法律文书，适用民事诉讼法第二百三十九条申请执行期间的规定。"},{"i":11,"n":"第十一条","txt":"申请执行人以被执行人一方不履行执行和解协议为由申请恢复执行，人民法院经审查，理由成立的，裁定恢复执行；有下列情形之一的，裁定不予恢复执行："},{"i":12,"n":"第十二条","txt":"当事人、利害关系人认为恢复执行或者不予恢复执行违反法律规定的，可以依照民事诉讼法第二百二十五条规定提出异议。"},{"i":13,"n":"第十三条","txt":"恢复执行后，对申请执行人就履行执行和解协议提起的诉讼，人民法院不予受理。"},{"i":14,"n":"第十四条","txt":"申请执行人就履行执行和解协议提起诉讼，执行法院受理后，可以裁定终结原生效法律文书的执行。执行中的查封、扣押、冻结措施，自动转为诉讼中的保全措施。"},{"i":15,"n":"第十五条","txt":"执行和解协议履行完毕，申请执行人因被执行人迟延履行、瑕疵履行遭受损害的，可以向执行法院另行提起诉讼。"},{"i":16,"n":"第十六条","txt":"当事人、利害关系人认为执行和解协议无效或者应予撤销的，可以向执行法院提起诉讼。执行和解协议被确认无效或者撤销后，申请执行人可以据此申请恢复执行。"},{"i":17,"n":"第十七条","txt":"恢复执行后，执行和解协议已经履行部分应当依法扣除。当事人、利害关系人认为人民法院的扣除行为违反法律规定的，可以依照民事诉讼法第二百二十五条规定提出异议。"},{"i":18,"n":"第十八条","txt":"执行和解协议中约定担保条款，且担保人向人民法院承诺在被执行人不履行执行和解协议时自愿接受直接强制执行的，恢复执行原生效法律文书后，人民法院可以依申请执行人申请及担保条款的约定，直接裁定执行担保财产或者保证人的财产。"},{"i":19,"n":"第十九条","txt":"执行过程中，被执行人根据当事人自行达成但未提交人民法院的和解协议，或者一方当事人提交人民法院但其他当事人不予认可的和解协议，依照民事诉讼法第二百二十五条规定提出异议的，人民法院按照下列情形，分别处理："},{"i":20,"n":"第二十条","txt":"本规定自2018年3月1日起施行。"}],"zuigaorenminfayuanguanyuzhixingdanbaoruoganwentided501a8":[{"i":1,"n":"第一条","txt":"本规定所称执行担保，是指担保人依照民事诉讼法第二百三十一条规定，为担保被执行人履行生效法律文书确定的全部或者部分义务，向人民法院提供的担保。"},{"i":2,"n":"第二条","txt":"执行担保可以由被执行人提供财产担保，也可以由他人提供财产担保或者保证。"},{"i":3,"n":"第三条","txt":"被执行人或者他人提供执行担保的，应当向人民法院提交担保书，并将担保书副本送交申请执行人。"},{"i":4,"n":"第四条","txt":"担保书中应当载明担保人的基本信息、暂缓执行期限、担保期间、被担保的债权种类及数额、担保范围、担保方式、被执行人于暂缓执行期限届满后仍不履行时担保人自愿接受直接强制执行的承诺等内容。"},{"i":5,"n":"第六条","txt":"被执行人或者他人提供执行担保，申请执行人同意的，应当向人民法院出具书面同意意见，也可以由执行人员将其同意的内容记入笔录，并由申请执行人签名或者盖章。"},{"i":6,"n":"第七条","txt":"被执行人或者他人提供财产担保，可以依照民法典规定办理登记等担保物权公示手续；已经办理公示手续的，申请执行人可以依法主张优先受偿权。"},{"i":7,"n":"第八条","txt":"人民法院决定暂缓执行的，可以暂缓全部执行措施的实施，但担保书另有约定的除外。"},{"i":8,"n":"第九条","txt":"担保书内容与事实不符，且对申请执行人合法权益产生实质影响的，人民法院可以依申请执行人的申请恢复执行。"},{"i":9,"n":"第十条","txt":"暂缓执行的期限应当与担保书约定一致，但最长不得超过一年。"},{"i":10,"n":"第十一条","txt":"暂缓执行期限届满后被执行人仍不履行义务，或者暂缓执行期间担保人有转移、隐藏、变卖、毁损担保财产等行为的，人民法院可以依申请执行人的申请恢复执行，并直接裁定执行担保财产或者保证人的财产，不得将担保人变更、追加为被执行人。"},{"i":11,"n":"第十二条","txt":"担保期间自暂缓执行期限届满之日起计算。"},{"i":12,"n":"第十三条","txt":"担保期间届满后，申请执行人申请执行担保财产或者保证人财产的，人民法院不予支持。他人提供财产担保的，人民法院可以依其申请解除对担保财产的查封、扣押、冻结。"},{"i":13,"n":"第十四条","txt":"担保人承担担保责任后，提起诉讼向被执行人追偿的，人民法院应予受理。"},{"i":14,"n":"第十五条","txt":"被执行人申请变更、解除全部或者部分执行措施，并担保履行生效法律文书确定义务的，参照适用本规定。"},{"i":15,"n":"第十六条","txt":"本规定自2018年3月1日起施行。"}],"zuigaorenminfayuanguanyujishudiaochaguancanyuzhish0735b2":[{"i":1,"n":"第一条","txt":"人民法院审理专利、植物新品种、集成电路布图设计、技术秘密、计算机软件、垄断等专业技术性较强的知识产权案件时，可以指派技术调查官参与诉讼活动。"},{"i":2,"n":"第二条","txt":"技术调查官属于审判辅助人员。"},{"i":3,"n":"第三条","txt":"参与知识产权案件诉讼活动的技术调查官确定或者变更后，应当在三日内告知当事人，并依法告知当事人有权申请技术调查官回避。"},{"i":4,"n":"第四条","txt":"技术调查官的回避，参照适用刑事诉讼法、民事诉讼法、行政诉讼法等有关其他人员回避的规定。"},{"i":5,"n":"第五条","txt":"在一个审判程序中参与过案件诉讼活动的技术调查官，不得再参与该案其他程序的诉讼活动。"},{"i":6,"n":"第六条","txt":"参与知识产权案件诉讼活动的技术调查官就案件所涉技术问题履行下列职责："},{"i":7,"n":"第七条","txt":"技术调查官参与调查取证、勘验、保全的，应当事先查阅相关技术资料，就调查取证、勘验、保全的方法、步骤和注意事项等提出建议。"},{"i":8,"n":"第八条","txt":"技术调查官参与询问、听证、庭前会议、开庭审理活动时，经法官同意，可以就案件所涉技术问题向当事人及其他诉讼参与人发问。"},{"i":9,"n":"第九条","txt":"技术调查官应当在案件评议前就案件所涉技术问题提出技术调查意见。"},{"i":10,"n":"第十条","txt":"技术调查官列席案件评议时，其提出的意见应当记入评议笔录，并由其签名。"},{"i":11,"n":"第十一条","txt":"技术调查官提出的技术调查意见可以作为合议庭认定技术事实的参考。"},{"i":12,"n":"第十二条","txt":"技术调查官参与知识产权案件诉讼活动的，应当在裁判文书上署名。技术调查官的署名位于法官助理之下、书记员之上。"},{"i":13,"n":"第十三条","txt":"技术调查官违反与审判工作有关的法律及相关规定，贪污受贿、徇私舞弊，故意出具虚假、误导或者重大遗漏的不实技术调查意见的，应当追究法律责任；构成犯罪的，依法追究刑事责任。"},{"i":14,"n":"第十四条","txt":"根据案件审理需要，上级人民法院可以对本辖区内各级人民法院的技术调查官进行调派。"},{"i":15,"n":"第十五条","txt":"本规定自2019年5月1日起施行。本院以前发布的相关规定与本规定不一致的，以本规定为准。"}],"zuigaorenminfayuanguanyuxinjiangshengchanjianshebif03201":[{"i":1,"n":"第一条","txt":"新疆生产建设兵团基层人民法院和中级人民法院分别行使地方基层人民法院和中级人民法院的案件管辖权，管辖兵团范围内的各类案件。"},{"i":2,"n":"第二条","txt":"兵团人民检察院提起公诉的第一审刑事案件，由兵团人民法院管辖。"},{"i":3,"n":"第三条","txt":"兵团人民法院管辖以下民事案件："},{"i":4,"n":"第四条","txt":"以兵团的行政机关作为被告的行政案件由该行政机关所在地的兵团人民法院管辖，其管辖权限依照行政诉讼法的规定办理。"},{"i":5,"n":"第五条","txt":"兵团人民法院管辖兵团范围内发生的涉外案件。新疆维吾尔自治区高级人民法院生产建设兵团分院根据最高人民法院的有关规定确定管辖涉外案件的兵团法院。"},{"i":6,"n":"第六条","txt":"兵团各级人民法院与新疆维吾尔自治区地方各级人民法院之间因管辖权发生争议的，由争议双方协商解决；协商不成的，报请新疆维吾尔自治区高级人民法院决定管辖。"},{"i":7,"n":"第七条","txt":"新疆维吾尔自治区高级人民法院生产建设兵团分院所管辖第一审案件的上诉法院是最高人民法院。"},{"i":8,"n":"第八条","txt":"对于新疆维吾尔自治区高级人民法院生产建设兵团分院审理再审案件所作出的判决、裁定，新疆维吾尔自治区高级人民法院不再进行再审。"},{"i":9,"n":"第九条","txt":"本规定自2005年6月6日起实施。人民法院关于兵团人民法院案件管辖的其他规定与本规定不一致的，以本规定为准。"}],"zuigaorenminfayuanguanyuzhengquequedingxianjiyishaaa98c0":[{"i":1,"n":"第一条","txt":"法律、法规、规章规定属于县级以上地方人民政府职能部门的行政职权，县级以上地方人民政府通过听取报告、召开会议、组织研究、下发文件等方式进行指导，公民、法人或者其他组织不服县级以上地方人民政府的指导行为提起诉讼的，人民法院应当释明，告知其以具体实施行政行为的职能部门为被告。"},{"i":2,"n":"第二条","txt":"县级以上地方人民政府根据城乡规划法的规定，责成有关职能部门对违法建筑实施强制拆除，公民、法人或者其他组织不服强制拆除行为提起诉讼，人民法院应当根据行政诉讼法第二十六条第一款的规定，以作出强制拆除决定的行政机关为被告；没有强制拆除决定书的，以具体实施强制拆除行为的职能部门为被告。"},{"i":3,"n":"第三条","txt":"公民、法人或者其他组织对集体土地征收中强制拆除房屋等行为不服提起诉讼的，除有证据证明系县级以上地方人民政府具体实施外，人民法院应当根据行政诉讼法第二十六条第一款的规定，以作出强制拆除决定的行政机关为被告；没有强制拆除决定书的，以具体实施强制拆除等行为的行政机关为被告。"},{"i":4,"n":"第四条","txt":"公民、法人或者其他组织向县级以上地方人民政府申请履行法定职责或者给付义务，法律、法规、规章规定该职责或者义务属于下级人民政府或者相应职能部门的行政职权，县级以上地方人民政府已经转送下级人民政府或者相应职能部门处理并告知申请人，申请人起诉要求履行法定职责或者给付义务的，以下级人民政府或者相应职能部门为被告。"},{"i":5,"n":"第五条","txt":"县级以上地方人民政府确定的不动产登记机构或者其他实际履行该职责的职能部门按照《不动产登记暂行条例》的规定办理不动产登记，公民、法人或者其他组织不服提起诉讼的，以不动产登记机构或者实际履行该职责的职能部门为被告。"},{"i":6,"n":"第六条","txt":"县级以上地方人民政府根据《中华人民共和国政府信息公开条例》的规定，指定具体机构负责政府信息公开日常工作，公民、法人或者其他组织对该指定机构以自己名义所作的政府信息公开行为不服提起诉讼的，以该指定机构为被告。"},{"i":7,"n":"第七条","txt":"被诉行政行为不是县级以上地方人民政府作出，公民、法人或者其他组织以县级以上地方人民政府作为被告的，人民法院应当予以指导和释明，告知其向有管辖权的人民法院起诉；公民、法人或者其他组织经人民法院释明仍不变更的，人民法院可以裁定不予立案，也可以将案件移送有管辖权的人民法院。"},{"i":8,"n":"第八条","txt":"本解释自2021年4月1日起施行。本解释施行后，最高人民法院此前作出的相关司法解释与本解释相抵触的，以本解释为准。"}],"zuigaorenminfayuanguanyusixingfuhejizhixingchengxu7bbeb2":[{"i":1,"n":"第一条","txt":"高级人民法院在向被告人送达依法作出的死刑裁判文书时，应当告知其在最高人民法院复核死刑阶段有权委托辩护律师，并将告知情况记入宣判笔录；被告人提出由其近亲属代为委托辩护律师的，除因客观原因无法通知的以外，高级人民法院应当及时通知其近亲属，并将通知情况记录在案。"},{"i":2,"n":"第二条","txt":"最高人民法院复核死刑案件，辩护律师应当自接受委托或者受指派之日起十日内向最高人民法院提交有关手续，并"},{"i":3,"n":"第三条","txt":"辩护律师提交相关手续、辩护意见及证据等材料的，可以经高级人民法院代收并随案移送，也可以寄送至最高人民法院。"},{"i":4,"n":"第四条","txt":"最高人民法院复核裁定作出后，律师提交辩护意见及证据材料的，应当接收并出具接收清单；经审查，相关意见及证据材料可能影响死刑复核结果的，应当暂停交付执行或者停止执行，但不再办理接收委托辩护手续。"},{"i":5,"n":"第五条","txt":"最高人民法院复核裁定下发后，受委托进行宣判的人民法院应当在宣判后五日内将裁判文书送达辩护律师。"},{"i":6,"n":"第六条","txt":"第一审人民法院在执行死刑前，应当告知罪犯可以申请会见其近亲属。"},{"i":7,"n":"第七条","txt":"罪犯近亲属申请会见的，人民法院应当准许，并在执行死刑前及时安排，但罪犯拒绝会见的除外。"},{"i":8,"n":"第八条","txt":"罪犯提出会见近亲属以外的亲友，经人民法院审查，确有正当理由的，可以在确保会见安全的情况下予以准许。"},{"i":9,"n":"第九条","txt":"罪犯申请会见未成年子女的，应当经未成年子女的监护人同意；会见可能影响未成年人身心健康的，人民法院可以采取视频通话等适当方式安排会见，且监护人应当在场。"},{"i":10,"n":"第十条","txt":"会见由人民法院负责安排，一般在罪犯羁押场所进行。"},{"i":11,"n":"第十一条","txt":"会见罪犯的人员应当遵守羁押场所的规定。违反规定的，应当予以警告；不听警告的，人民法院可以终止会见。"},{"i":12,"n":"第十二条","txt":"会见情况应当记录在案，附卷存档。"},{"i":13,"n":"第十三条","txt":"本规定自2019年9月1日起施行。"}],"zuigaorenminfayuanguanyusixinghuanqizhixingxianzhi4eec2e":[{"i":1,"n":"第一条","txt":"根据刑法第五十条第二款的规定，对被判处死刑缓期执行的累犯以及因故意杀人、强奸、抢劫、绑架、放火、爆炸、投放危险物质或者有组织的暴力性犯罪被判处死刑缓期执行的犯罪分子，人民法院根据犯罪情节、人身危险性等情况，可以在作出裁判的同时决定对其限制减刑。"},{"i":2,"n":"第二条","txt":"被告人对第一审人民法院作出的限制减刑判决不服的，可以提出上诉。被告人的辩护人和近亲属，经被告人同意，也可以提出上诉。"},{"i":3,"n":"第三条","txt":"高级人民法院审理或者复核判处死刑缓期执行并限制减刑的案件，认为原判对被告人判处死刑缓期执行适当，但判决限制减刑不当的，应当改判，撤销限制减刑。"},{"i":4,"n":"第四条","txt":"高级人民法院审理判处死刑缓期执行没有限制减刑的上诉案件，认为原判事实清楚、证据充分，但应当限制减刑的，不得直接改判，也不得发回重新审判。确有必要限制减刑的，应当在第二审判决、裁定生效后，按照审判监督程序重新审判。"},{"i":5,"n":"第五条","txt":"高级人民法院审理判处死刑的第二审案件，对被告人改判死刑缓期执行的，如果符合刑法第五十条第二款的规定，可以同时决定对其限制减刑。"},{"i":6,"n":"第六条","txt":"最高人民法院复核死刑案件，认为对被告人可以判处死刑缓期执行并限制减刑的，应当裁定不予核准，并撤销原判，发回重新审判。"},{"i":7,"n":"第七条","txt":"人民法院对被判处死刑缓期执行的被告人所作的限制减刑决定，应当在判决书主文部分单独作为一项予以宣告。"},{"i":8,"n":"第八条","txt":"死刑缓期执行限制减刑案件审理程序的其他事项，依照刑事诉讼法和有关司法解释的规定执行。"}],"zuigaorenminfayuanguanyuminshishenpanjianduchengxuae6022":[{"i":1,"n":"第一条","txt":"上级人民法院应当严格依照民事诉讼法第二百条等规定审查当事人的再审申请，符合法定条件的，裁定再审。不得因指令再审而降低再审启动标准，也不得因当事人反复申诉将依法不应当再审的案件指令下级人民法院再审。"},{"i":2,"n":"第二条","txt":"因当事人申请裁定再审的案件一般应当由裁定再审的人民法院审理。有下列情形之一的，最高人民法院、高级人民法院可以指令原审人民法院再审："},{"i":3,"n":"第三条","txt":"虽然符合本规定第二条可以指令再审的条件，但有下列情形之一的，应当提审："},{"i":4,"n":"第四条","txt":"人民法院按照第二审程序审理再审案件，发现原判决认定基本事实不清的，一般应当通过庭审认定事实后依法作出判决。但原审人民法院未对基本事实进行过审理的，可以裁定撤销原判决，发回重审。原判决认定事实错误的，上级人民法院不得以基本事实不清为由裁定发回重审。"},{"i":5,"n":"第五条","txt":"人民法院按照第二审程序审理再审案件，发现第一审人民法院有下列严重违反法定程序情形之一的，可以依照民事诉讼法第一百七十条第一款第（四）项的规定，裁定撤销原判决，发回第一审人民法院重审："},{"i":6,"n":"第六条","txt":"上级人民法院裁定指令再审、发回重审的，应当在裁定书中阐明指令再审或者发回重审的具体理由。"},{"i":7,"n":"第七条","txt":"再审案件应当围绕申请人的再审请求进行审理和裁判。对方当事人在再审庭审辩论终结前也提出再审请求的，应一并审理和裁判。当事人的再审请求超出原审诉讼请求的不予审理，构成另案诉讼的应告知当事人可以提起新的诉讼。"},{"i":8,"n":"第八条","txt":"再审发回重审的案件，应当围绕当事人原诉讼请求进行审理。当事人申请变更、增加诉讼请求和提出反诉的，按照最高人民法院《关于适用〈中华人民共和国民事诉讼法〉的解释》第二百五十二条的规定审查决定是否准许。当事人变更其在原审中的诉讼主张、质证及辩论意见的，应说明理由并提交相应的证据，理由不成立或证据不充分的，人民法院不予支持。"},{"i":9,"n":"第九条","txt":"各级人民法院对民事案件指令再审和再审发回重审的审判行为，应当严格遵守本规定。违反本规定的，应当依照相关规定追究有关人员的责任。"}],"zuigaorenminfayuanguanyuminshizhixingzhongbiangengb56f0d":[{"i":1,"n":"第一条","txt":"执行过程中，申请执行人或其继承人、权利承受人可以向人民法院申请变更、追加当事人。申请符合法定条件的，人民法院应予支持。"},{"i":2,"n":"第二条","txt":"作为申请执行人的自然人死亡或被宣告死亡，该自然人的遗产管理人、继承人、受遗赠人或其他因该自然人死亡或被宣告死亡依法承受生效法律文书确定权利的主体，申请变更、追加其为申请执行人的，人民法院应予支持。"},{"i":3,"n":"第三条","txt":"作为申请执行人的自然人离婚时，生效法律文书确定的权利全部或部分分割给其配偶，该配偶申请变更、追加其为申请执行人的，人民法院应予支持。"},{"i":4,"n":"第四条","txt":"作为申请执行人的法人或非法人组织终止，因该法人或非法人组织终止依法承受生效法律文书确定权利的主体，申请变更、追加其为申请执行人的，人民法院应予支持。"},{"i":5,"n":"第五条","txt":"作为申请执行人的法人或非法人组织因合并而终止，合并后存续或新设的法人、非法人组织申请变更其为申请执行人的，人民法院应予支持。"},{"i":6,"n":"第六条","txt":"作为申请执行人的法人或非法人组织分立，依分立协议约定承受生效法律文书确定权利的新设法人或非法人组织，申请变更、追加其为申请执行人的，人民法院应予支持。"},{"i":7,"n":"第七条","txt":"作为申请执行人的法人或非法人组织清算或破产时，生效法律文书确定的权利依法分配给第三人，该第三人申请变更、追加其为申请执行人的，人民法院应予支持。"},{"i":8,"n":"第八条","txt":"作为申请执行人的机关法人被撤销，继续履行其职能的主体申请变更、追加其为申请执行人的，人民法院应予支持，但生效法律文书确定的权利依法应由其他主体承受的除外；没有继续履行其职能的主体，且生效法律文书确定权利的承受主体不明确，作出撤销决定的主体申请变更、追加其为申请执行人的，人民法院应予支持。"},{"i":9,"n":"第九条","txt":"申请执行人将生效法律文书确定的债权依法转让给第三人，且书面认可第三人取得该债权，该第三人申请变更、追加其为申请执行人的，人民法院应予支持。"},{"i":10,"n":"第十条","txt":"作为被执行人的自然人死亡或被宣告死亡，申请执行人申请变更、追加该自然人的遗产管理人、继承人、受遗赠人或其他因该自然人死亡或被宣告死亡取得遗产的主体为被执行人，在遗产范围内承担责任的，人民法院应予支持。"},{"i":11,"n":"第十一条","txt":"作为被执行人的法人或非法人组织因合并而终止，申请执行人申请变更合并后存续或新设的法人、非法人组织为被执行人的，人民法院应予支持。"},{"i":12,"n":"第十二条","txt":"作为被执行人的法人或非法人组织分立，申请执行人申请变更、追加分立后新设的法人或非法人组织为被执行人，对生效法律文书确定的债务承担连带责任的，人民法院应予支持。但被执行人在分立前与申请执行人就债务清偿达成的书面协议另有约定的除外。"},{"i":13,"n":"第十三条","txt":"作为被执行人的个人独资企业，不能清偿生效法律文书确定的债务，申请执行人申请变更、追加其出资人为被执行人的，人民法院应予支持。个人独资企业出资人作为被执行人的，人民法院可以直接执行该个人独资企业的财产。"},{"i":14,"n":"第十四条","txt":"作为被执行人的合伙企业，不能清偿生效法律文书确定的债务，申请执行人申请变更、追加普通合伙人为被执行人的，人民法院应予支持。"},{"i":15,"n":"第十五条","txt":"作为被执行人的法人分支机构，不能清偿生效法律文书确定的债务，申请执行人申请变更、追加该法人为被执行人的，人民法院应予支持。法人直接管理的责任财产仍不能清偿债务的，人民法院可以直接执行该法人其他分支机构的财产。"},{"i":16,"n":"第十六条","txt":"个人独资企业、合伙企业、法人分支机构以外的非法人组织作为被执行人，不能清偿生效法律文书确定的债务，申请执行人申请变更、追加依法对该非法人组织的债务承担责任的主体为被执行人的，人民法院应予支持。"},{"i":17,"n":"第十七条","txt":"作为被执行人的营利法人，财产不足以清偿生效法律文书确定的债务，申请执行人申请变更、追加未缴纳或未足额缴纳出资的股东、出资人或依公司法规定对该出资承担连带责任的发起人为被执行人，在尚未缴纳出资的范围内依法承担责任的，人民法院应予支持。"},{"i":18,"n":"第十八条","txt":"作为被执行人的营利法人，财产不足以清偿生效法律文书确定的债务，申请执行人申请变更、追加抽逃出资的股东、出资人为被执行人，在抽逃出资的范围内承担责任的，人民法院应予支持。"},{"i":19,"n":"第十九条","txt":"作为被执行人的公司，财产不足以清偿生效法律文书确定的债务，其股东未依法履行出资义务即转让股权，申请执行人申请变更、追加该原股东或依公司法规定对该出资承担连带责任的发起人为被执行人，在未依法出资的范围内承担责任的，人民法院应予支持。"},{"i":20,"n":"第二十条","txt":"作为被执行人的一人有限责任公司，财产不足以清偿生效法律文书确定的债务，股东不能证明公司财产独立于自己的财产，申请执行人申请变更、追加该股东为被执行人，对公司债务承担连带责任的，人民法院应予支持。"},{"i":21,"n":"第二十一条","txt":"作为被执行人的公司，未经清算即办理注销登记，导致公司无法进行清算，申请执行人申请变更、追加有限责任公司的股东、股份有限公司的董事和控股股东为被执行人，对公司债务承担连带清偿责任的，人民法院应予支持。"},{"i":22,"n":"第二十二条","txt":"作为被执行人的法人或非法人组织，被注销或出现被吊销营业执照、被撤销、被责令关闭、歇业等解散事由后，其股东、出资人或主管部门无偿接受其财产，致使该被执行人无遗留财产或遗留财产不足以清偿债务，申请执行人申请变更、追加该股东、出资人或主管部门为被执行人，在接受的财产范围内承担责任的，人民法院应予支持。"},{"i":23,"n":"第二十三条","txt":"作为被执行人的法人或非法人组织，未经依法清算即办理注销登记，在登记机关办理注销登记时，第三人书面承诺对被执行人的债务承担清偿责任，申请执行人申请变更、追加该第三人为被执行人，在承诺范围内承担清偿责任的，人民法院应予支持。"},{"i":24,"n":"第二十四条","txt":"执行过程中，第三人向执行法院书面承诺自愿代被执行人履行生效法律文书确定的债务，申请执行人申请变更、追加该第三人为被执行人，在承诺范围内承担责任的，人民法院应予支持。"},{"i":25,"n":"第二十五条","txt":"作为被执行人的法人或非法人组织，财产依行政命令被无偿调拨、划转给第三人，致使该被执行人财产不足以清偿生效法律文书确定的债务，申请执行人申请变更、追加该第三人为被执行人，在接受的财产范围内承担责任的，人民法院应予支持。"},{"i":26,"n":"第二十六条","txt":"被申请人在应承担责任范围内已承担相应责任的，人民法院不得责令其重复承担责任。"},{"i":27,"n":"第二十七条","txt":"执行当事人的姓名或名称发生变更的，人民法院可以直接将姓名或名称变更后的主体作为执行当事人，并在法律文书中注明变更前的姓名或名称。"},{"i":28,"n":"第二十八条","txt":"申请人申请变更、追加执行当事人，应当向执行法院提交书面申请及相关证据材料。"},{"i":29,"n":"第二十九条","txt":"执行法院审查变更、追加被执行人申请期间，申请人申请对被申请人的财产采取查封、扣押、冻结措施的，执行法院应当参照民事诉讼法第一百条的规定办理。"},{"i":30,"n":"第三十条","txt":"被申请人、申请人或其他执行当事人对执行法院作出的变更、追加裁定或驳回申请裁定不服的，可以自裁定书送达之日起十日内向上一级人民法院申请复议，但依据本规定第三十二条的规定应当提起诉讼的除外。"},{"i":31,"n":"第三十一条","txt":"上一级人民法院对复议申请应当组成合议庭审查，并自收到申请之日起六十日内作出复议裁定。有特殊情况需要延长的，由本院院长批准。"},{"i":32,"n":"第三十二条","txt":"被申请人或申请人对执行法院依据本规定第十四条第二款、第十七条至第二十一条规定作出的变更、追加裁定或驳回申请裁定不服的，可以自裁定书送达之日起十五日内，向执行法院提起执行异议之诉。"},{"i":33,"n":"第三十三条","txt":"被申请人提起的执行异议之诉，人民法院经审理，按照下列情形分别处理："},{"i":34,"n":"第三十四条","txt":"申请人提起的执行异议之诉，人民法院经审理，按照下列情形分别处理："},{"i":35,"n":"第三十五条","txt":"本规定自2016年12月1日起施行。"}],"zuigaorenminfayuanguanyuminshizhixingzhongcaichand9783f5":[{"i":1,"n":"第一条","txt":"执行过程中，申请执行人应当提供被执行人的财产线索；被执行人应当如实报告财产；人民法院应当通过网络执行查控系统进行调查，根据案件需要应当通过其他方式进行调查的，同时采取其他调查方式。"},{"i":2,"n":"第二条","txt":"申请执行人提供被执行人财产线索，应当填写财产调查表。财产线索明确、具体的，人民法院应当在七日内调查核实；情况紧急的，应当在三日内调查核实。财产线索确实的，人民法院应当及时采取相应的执行措施。"},{"i":3,"n":"第三条","txt":"人民法院依申请执行人的申请或依职权责令被执行人报告财产情况的，应当向其发出报告财产令。金钱债权执行中，报告财产令应当与执行通知同时发出。"},{"i":4,"n":"第四条","txt":"报告财产令应当载明下列事项："},{"i":5,"n":"第五条","txt":"被执行人应当在报告财产令载明的期限内向人民法院书面报告下列财产情况："},{"i":6,"n":"第六条","txt":"被执行人自收到执行通知之日前一年至提交书面财产报告之日，其财产情况发生下列变动的，应当将变动情况一并报告："},{"i":7,"n":"第七条","txt":"被执行人报告财产后，其财产情况发生变动，影响申请执行人债权实现的，应当自财产变动之日起十日内向人民法院补充报告。"},{"i":8,"n":"第八条","txt":"对被执行人报告的财产情况，人民法院应当及时调查核实，必要时可以组织当事人进行听证。"},{"i":9,"n":"第九条","txt":"被执行人拒绝报告、虚假报告或者无正当理由逾期报告财产情况的，人民法院可以根据情节轻重对被执行人或者其法定代理人予以罚款、拘留；构成犯罪的，依法追究刑事责任。"},{"i":10,"n":"第十条","txt":"被执行人拒绝报告、虚假报告或者无正当理由逾期报告财产情况的，人民法院应当依照相关规定将其纳入失信被执行人名单。"},{"i":11,"n":"第十一条","txt":"有下列情形之一的，财产报告程序终结："},{"i":12,"n":"第十二条","txt":"被执行人未按执行通知履行生效法律文书确定的义务，人民法院有权通过网络执行查控系统、现场调查等方式向被执行人、有关单位或个人调查被执行人的身份信息和财产信息，有关单位和个人应当依法协助办理。"},{"i":13,"n":"第十三条","txt":"人民法院通过网络执行查控系统进行调查，与现场调查具有同等法律效力。"},{"i":14,"n":"第十四条","txt":"被执行人隐匿财产、会计账簿等资料拒不交出的，人民法院可以依法采取搜查措施。"},{"i":15,"n":"第十五条","txt":"为查明被执行人的财产情况和履行义务的能力，可以传唤被执行人或被执行人的法定代表人、负责人、实际控制人、直接责任人员到人民法院接受调查询问。"},{"i":16,"n":"第十六条","txt":"人民法院对已经办理查封登记手续的被执行人机动车、船舶、航空器等特定动产未能实际扣押的，可以依照相关规定通知有关单位协助查找。"},{"i":17,"n":"第十七条","txt":"作为被执行人的法人或非法人组织不履行生效法律文书确定的义务，申请执行人认为其有拒绝报告、虚假报告财产情况，隐匿、转移财产等逃避债务情形或者其股东、出资人有出资不实、抽逃出资等情形的，可以书面申请人民法院委托审计机构对该被执行人进行审计。人民法院应当自收到书面申请之日起十日内决定是否准许。"},{"i":18,"n":"第十八条","txt":"人民法院决定审计的，应当随机确定具备资格的审计机构，并责令被执行人提交会计凭证、会计账簿、财务会计报告等与审计事项有关的资料。"},{"i":19,"n":"第十九条","txt":"被执行人拒不提供、转移、隐匿、伪造、篡改、毁弃审计资料，阻挠审计人员查看业务现场或者有其他妨碍审计调查行为的，人民法院可以根据情节轻重对被执行人或其主要负责人、直接责任人员予以罚款、拘留；构成犯罪的，依法追究刑事责任。"},{"i":20,"n":"第二十条","txt":"审计费用由提出审计申请的申请执行人预交。被执行人存在拒绝报告或虚假报告财产情况，隐匿、转移财产或者其他逃避债务情形的，审计费用由被执行人承担；未发现被执行人存在上述情形的，审计费用由申请执行人承担。"},{"i":21,"n":"第二十一条","txt":"被执行人不履行生效法律文书确定的义务，申请执行人可以向人民法院书面申请发布悬赏公告查找可供执行的财产。申请书应当载明下列事项："},{"i":22,"n":"第二十二条","txt":"人民法院决定悬赏查找财产的，应当制作悬赏公告。悬赏公告应当载明悬赏金的数额或计算方法、领取条件等内容。"},{"i":23,"n":"第二十三条","txt":"悬赏公告发布后，有关人员向人民法院提供财产线索的，人民法院应当对有关人员的身份信息和财产线索进行登记；两人以上提供相同财产线索的，应当按照提供线索的先后顺序登记。"},{"i":24,"n":"第二十四条","txt":"有关人员提供人民法院尚未掌握的财产线索，使申请发布悬赏公告的申请执行人的债权得以全部或部分实现的，人民法院应当按照悬赏公告发放悬赏金。"},{"i":25,"n":"第二十五条","txt":"执行人员不得调查与执行案件无关的信息，对调查过程中知悉的国家秘密、商业秘密和个人隐私应当保密。"},{"i":26,"n":"第二十六条","txt":"本规定自2017年5月1日起施行。"}],"zuigaorenminfayuanguanyuminshisusongzhengjuderuogadc3af9":[{"i":1,"n":"第一条","txt":"原告向人民法院起诉或者被告提出反诉，应当提供符合起诉条件的相应的证据。"},{"i":2,"n":"第二条","txt":"人民法院应当向当事人说明举证的要求及法律后果，促使当事人在合理期限内积极、全面、正确、诚实地完成举证。"},{"i":3,"n":"第三条","txt":"在诉讼过程中，一方当事人陈述的于己不利的事实，或者对于己不利的事实明确表示承认的，另一方当事人无需举证证明。"},{"i":4,"n":"第四条","txt":"一方当事人对于另一方当事人主张的于己不利的事实既不承认也不否认，经审判人员说明并询问后，其仍然不明确表示肯定或者否定的，视为对该事实的承认。"},{"i":5,"n":"第五条","txt":"当事人委托诉讼代理人参加诉讼的，除授权委托书明确排除的事项外，诉讼代理人的自认视为当事人的自认。"},{"i":6,"n":"第六条","txt":"普通共同诉讼中，共同诉讼人中一人或者数人作出的自认，对作出自认的当事人发生效力。"},{"i":7,"n":"第七条","txt":"一方当事人对于另一方当事人主张的于己不利的事实有所限制或者附加条件予以承认的，由人民法院综合案件情况决定是否构成自认。"},{"i":8,"n":"第八条","txt":"《最高人民法院关于适用〈中华人民共和国民事诉讼法〉的解释》第九十六条第一款规定的事实，不适用有关自认的规定。"},{"i":9,"n":"第九条","txt":"有下列情形之一，当事人在法庭辩论终结前撤销自认的，人民法院应当准许："},{"i":10,"n":"第十条","txt":"下列事实，当事人无须举证证明："},{"i":11,"n":"第十一条","txt":"当事人向人民法院提供证据，应当提供原件或者原物。如需自己保存证据原件、原物或者提供原件、原物确有困难的，可以提供经人民法院核对无异的复制件或者复制品。"},{"i":12,"n":"第十二条","txt":"以动产作为证据的，应当将原物提交人民法院。原物不宜搬移或者不宜保存的，当事人可以提供复制品、影像资料或者其他替代品。"},{"i":13,"n":"第十三条","txt":"当事人以不动产作为证据的，应当向人民法院提供该不动产的影像资料。"},{"i":14,"n":"第十四条","txt":"电子数据包括下列信息、电子文件："},{"i":15,"n":"第十五条","txt":"当事人以视听资料作为证据的，应当提供存储该视听资料的原始载体。"},{"i":16,"n":"第十六条","txt":"当事人提供的公文书证系在中华人民共和国领域外形成的，该证据应当经所在国公证机关证明，或者履行中华人民共和国与该所在国订立的有关条约中规定的证明手续。"},{"i":17,"n":"第十七条","txt":"当事人向人民法院提供外文书证或者外文说明资料，应当附有中文译本。"},{"i":18,"n":"第十八条","txt":"双方当事人无争议的事实符合《最高人民法院关于适用〈中华人民共和国民事诉讼法〉的解释》第九十六条第一款规定情形的，人民法院可以责令当事人提供有关证据。"},{"i":19,"n":"第十九条","txt":"当事人应当对其提交的证据材料逐一分类编号，对证据材料的来源、证明对象和内容作简要说明，签名盖章，注明提交日期，并依照对方当事人人数提出副本。"},{"i":20,"n":"第二十条","txt":"当事人及其诉讼代理人申请人民法院调查收集证据，应当在举证期限届满前提交书面申请。"},{"i":21,"n":"第二十一条","txt":"人民法院调查收集的书证，可以是原件，也可以是经核对无误的副本或者复制件。是副本或者复制件的，应当在调查笔录中说明来源和取证情况。"},{"i":22,"n":"第二十二条","txt":"人民法院调查收集的物证应当是原物。被调查人提供原物确有困难的，可以提供复制品或者影像资料。提供复制品或者影像资料的，应当在调查笔录中说明取证情况。"},{"i":23,"n":"第二十三条","txt":"人民法院调查收集视听资料、电子数据，应当要求被调查人提供原始载体。"},{"i":24,"n":"第二十四条","txt":"人民法院调查收集可能需要鉴定的证据，应当遵守相关技术规范，确保证据不被污染。"},{"i":25,"n":"第二十五条","txt":"当事人或者利害关系人根据民事诉讼法第八十一条的规定申请证据保全的，申请书应当载明需要保全的证据的基本情况、申请保全的理由以及采取何种保全措施等内容。"},{"i":26,"n":"第二十六条","txt":"当事人或者利害关系人申请采取查封、扣押等限制保全标的物使用、流通等保全措施，或者保全可能对证据持有人造成损失的，人民法院应当责令申请人提供相应的担保。"},{"i":27,"n":"第二十七条","txt":"人民法院进行证据保全，可以要求当事人或者诉讼代理人到场。"},{"i":28,"n":"第二十八条","txt":"申请证据保全错误造成财产损失，当事人请求申请人承担赔偿责任的，人民法院应予支持。"},{"i":29,"n":"第二十九条","txt":"人民法院采取诉前证据保全措施后，当事人向其他有管辖权的人民法院提起诉讼的，采取保全措施的人民法院应当根据当事人的申请，将保全的证据及时移交受理案件的人民法院。"},{"i":30,"n":"第三十条","txt":"人民法院在审理案件过程中认为待证事实需要通过鉴定意见证明的，应当向当事人释明，并指定提出鉴定申请的期间。"},{"i":31,"n":"第三十一条","txt":"当事人申请鉴定，应当在人民法院指定期间内提出，并预交鉴定费用。逾期不提出申请或者不预交鉴定费用的，视为放弃申请。"},{"i":32,"n":"第三十二条","txt":"人民法院准许鉴定申请的，应当组织双方当事人协商确定具备相应资格的鉴定人。当事人协商不成的，由人民法院指定。"},{"i":33,"n":"第三十三条","txt":"鉴定开始之前，人民法院应当要求鉴定人签署承诺书。承诺书中应当载明鉴定人保证客观、公正、诚实地进行鉴定，保证出庭作证，如作虚假鉴定应当承担法律责任等内容。"},{"i":34,"n":"第三十四条","txt":"人民法院应当组织当事人对鉴定材料进行质证。未经质证的材料，不得作为鉴定的根据。"},{"i":35,"n":"第三十五条","txt":"鉴定人应当在人民法院确定的期限内完成鉴定，并提交鉴定书。"},{"i":36,"n":"第三十六条","txt":"人民法院对鉴定人出具的鉴定书，应当审查是否具有下列内容："},{"i":37,"n":"第三十七条","txt":"人民法院收到鉴定书后，应当及时将副本送交当事人。"},{"i":38,"n":"第三十八条","txt":"当事人在收到鉴定人的书面答复后仍有异议的，人民法院应当根据《诉讼费用交纳办法》第十一条的规定，通知有异议的当事人预交鉴定人出庭费用，并通知鉴定人出庭。有异议的当事人不预交鉴定人出庭费用的，视为放弃异议。"},{"i":39,"n":"第三十九条","txt":"鉴定人出庭费用按照证人出庭作证费用的标准计算，由败诉的当事人负担。因鉴定意见不明确或者有瑕疵需要鉴定人出庭的，出庭费用由其自行负担。"},{"i":40,"n":"第四十条","txt":"当事人申请重新鉴定，存在下列情形之一的，人民法院应当准许："},{"i":41,"n":"第四十一条","txt":"对于一方当事人就专门性问题自行委托有关机构或者人员出具的意见，另一方当事人有证据或者理由足以反驳并申请鉴定的，人民法院应予准许。"},{"i":42,"n":"第四十二条","txt":"鉴定意见被采信后，鉴定人无正当理由撤销鉴定意见的，人民法院应当责令其退还鉴定费用，并可以根据情节，依照民事诉讼法第一百一十一条的规定对鉴定人进行处罚。当事人主张鉴定人负担由此增加的合理费用的，人民法院应予支持。"},{"i":43,"n":"第四十三条","txt":"人民法院应当在勘验前将勘验的时间和地点通知当事人。当事人不参加的，不影响勘验进行。"},{"i":44,"n":"第四十四条","txt":"摘录有关单位制作的与案件事实相关的文件、材料，应当注明出处，并加盖制作单位或者保管单位的印章，摘录人和其他调查人员应当在摘录件上签名或者盖章。"},{"i":45,"n":"第四十五条","txt":"当事人根据《最高人民法院关于适用〈中华人民共和国民事诉讼法〉的解释》第一百一十二条的规定申请人民法院责令对方当事人提交书证的，申请书应当载明所申请提交的书证名称或者内容、需要以该书证证明的事实及事实的重要性、对方当事人控制该书证的根据以及应当提交该书证的理由。"},{"i":46,"n":"第四十六条","txt":"人民法院对当事人提交书证的申请进行审查时，应当听取对方当事人的意见，必要时可以要求双方当事人提供证据、进行辩论。"},{"i":47,"n":"第四十七条","txt":"下列情形，控制书证的当事人应当提交书证："},{"i":48,"n":"第四十八条","txt":"控制书证的当事人无正当理由拒不提交书证的，人民法院可以认定对方当事人所主张的书证内容为真实。"},{"i":49,"n":"第四十九条","txt":"被告应当在答辩期届满前提出书面答辩，阐明其对原告诉讼请求及所依据的事实和理由的意见。"},{"i":50,"n":"第五十条","txt":"人民法院应当在审理前的准备阶段向当事人送达举证通知书。"},{"i":51,"n":"第五十一条","txt":"举证期限可以由当事人协商，并经人民法院准许。"},{"i":52,"n":"第五十二条","txt":"当事人在举证期限内提供证据存在客观障碍，属于民事诉讼法第六十五条第二款规定的“当事人在该期限内提供证据确有困难”的情形。"},{"i":53,"n":"第五十三条","txt":"诉讼过程中，当事人主张的法律关系性质或者民事行为效力与人民法院根据案件事实作出的认定不一致的，人民法院应当将法律关系性质或者民事行为效力作为焦点问题进行审理。但法律关系性质对裁判理由及结果没有影响，或者有关问题已经当事人充分辩论的除外。"},{"i":54,"n":"第五十四条","txt":"当事人申请延长举证期限的，应当在举证期限届满前向人民法院提出书面申请。"},{"i":55,"n":"第五十五条","txt":"存在下列情形的，举证期限按照如下方式确定："},{"i":56,"n":"第五十六条","txt":"人民法院依照民事诉讼法第一百三十三条第四项的规定，通过组织证据交换进行审理前准备的，证据交换之日举证期限届满。"},{"i":57,"n":"第五十七条","txt":"证据交换应当在审判人员的主持下进行。"},{"i":58,"n":"第五十八条","txt":"当事人收到对方的证据后有反驳证据需要提交的，人民法院应当再次组织证据交换。"},{"i":59,"n":"第五十九条","txt":"人民法院对逾期提供证据的当事人处以罚款的，可以结合当事人逾期提供证据的主观过错程度、导致诉讼迟延的情况、诉讼标的金额等因素，确定罚款数额。"},{"i":60,"n":"第六十条","txt":"当事人在审理前的准备阶段或者人民法院调查、询问过程中发表过质证意见的证据，视为质证过的证据。"},{"i":61,"n":"第六十一条","txt":"对书证、物证、视听资料进行质证时，当事人应当出示证据的原件或者原物。但有下列情形之一的除外："},{"i":62,"n":"第六十二条","txt":"质证一般按下列顺序进行："},{"i":63,"n":"第六十三条","txt":"当事人应当就案件事实作真实、完整的陈述。"},{"i":64,"n":"第六十四条","txt":"人民法院认为有必要的，可以要求当事人本人到场，就案件的有关事实接受询问。"},{"i":65,"n":"第六十五条","txt":"人民法院应当在询问前责令当事人签署保证书并宣读保证书的内容。"},{"i":66,"n":"第六十六条","txt":"当事人无正当理由拒不到场、拒不签署或宣读保证书或者拒不接受询问的，人民法院应当综合案件情况，判断待证事实的真伪。待证事实无其他证据证明的，人民法院应当作出不利于该当事人的认定。"},{"i":67,"n":"第六十七条","txt":"不能正确表达意思的人，不能作为证人。"},{"i":68,"n":"第六十八条","txt":"人民法院应当要求证人出庭作证，接受审判人员和当事人的询问。证人在审理前的准备阶段或者人民法院调查、询问等双方当事人在场时陈述证言的，视为出庭作证。"},{"i":69,"n":"第六十九条","txt":"当事人申请证人出庭作证的，应当在举证期限届满前向人民法院提交申请书。"},{"i":70,"n":"第七十条","txt":"人民法院准许证人出庭作证申请的，应当向证人送达通知书并告知双方当事人。通知书中应当载明证人作证的时间、地点，作证的事项、要求以及作伪证的法律后果等内容。"},{"i":71,"n":"第七十一条","txt":"人民法院应当要求证人在作证之前签署保证书，并在法庭上宣读保证书的内容。但无民事行为能力人和限制民事行为能力人作为证人的除外。"},{"i":72,"n":"第七十二条","txt":"证人应当客观陈述其亲身感知的事实，作证时不得使用猜测、推断或者评论性语言。"},{"i":73,"n":"第七十三条","txt":"证人应当就其作证的事项进行连续陈述。"},{"i":74,"n":"第七十四条","txt":"审判人员可以对证人进行询问。当事人及其诉讼代理人经审判人员许可后可以询问证人。"},{"i":75,"n":"第七十五条","txt":"证人出庭作证后，可以向人民法院申请支付证人出庭作证费用。证人有困难需要预先支取出庭作证费用的，人民法院可以根据证人的申请在出庭作证前支付。"},{"i":76,"n":"第七十六条","txt":"证人确有困难不能出庭作证，申请以书面证言、视听传输技术或者视听资料等方式作证的，应当向人民法院提交申请书。申请书中应当载明不能出庭的具体原因。"},{"i":77,"n":"第七十七条","txt":"证人经人民法院准许，以书面证言方式作证的，应当签署保证书；以视听传输技术或者视听资料方式作证的，应当签署保证书并宣读保证书的内容。"},{"i":78,"n":"第七十八条","txt":"当事人及其诉讼代理人对证人的询问与待证事实无关，或者存在威胁、侮辱证人或不适当引导等情形的，审判人员应当及时制止。必要时可以依照民事诉讼法第一百一十条、第一百一十一条的规定进行处罚。"},{"i":79,"n":"第七十九条","txt":"鉴定人依照民事诉讼法第七十八条的规定出庭作证的，人民法院应当在开庭审理三日前将出庭的时间、地点及要求通知鉴定人。"},{"i":80,"n":"第八十条","txt":"鉴定人应当就鉴定事项如实答复当事人的异议和审判人员的询问。当庭答复确有困难的，经人民法院准许，可以在庭审结束后书面答复。"},{"i":81,"n":"第八十一条","txt":"鉴定人拒不出庭作证的，鉴定意见不得作为认定案件事实的根据。人民法院应当建议有关主管部门或者组织对拒不出庭作证的鉴定人予以处罚。"},{"i":82,"n":"第八十二条","txt":"经法庭许可，当事人可以询问鉴定人、勘验人。"},{"i":83,"n":"第八十三条","txt":"当事人依照民事诉讼法第七十九条和《最高人民法院关于适用〈中华人民共和国民事诉讼法〉的解释》第一百二十二条的规定，申请有专门知识的人出庭的，申请书中应当载明有专门知识的人的基本情况和申请的目的。"},{"i":84,"n":"第八十四条","txt":"审判人员可以对有专门知识的人进行询问。经法庭准许，当事人可以对有专门知识的人进行询问，当事人各自申请的有专门知识的人可以就案件中的有关问题进行对质。"},{"i":85,"n":"第八十五条","txt":"人民法院应当以证据能够证明的案件事实为根据依法作出裁判。"},{"i":86,"n":"第八十六条","txt":"当事人对于欺诈、胁迫、恶意串通事实的证明，以及对于口头遗嘱或赠与事实的证明，人民法院确信该待证事实存在的可能性能够排除合理怀疑的，应当认定该事实存在。"},{"i":87,"n":"第八十七条","txt":"审判人员对单一证据可以从下列方面进行审核认定："},{"i":88,"n":"第八十八条","txt":"审判人员对案件的全部证据，应当从各证据与案件事实的关联程度、各证据之间的联系等方面进行综合审查判断。"},{"i":89,"n":"第八十九条","txt":"当事人在诉讼过程中认可的证据，人民法院应当予以确认。但法律、司法解释另有规定的除外。"},{"i":90,"n":"第九十条","txt":"下列证据不能单独作为认定案件事实的根据："},{"i":91,"n":"第九十一条","txt":"公文书证的制作者根据文书原件制作的载有部分或者全部内容的副本，与正本具有相同的证明力。"},{"i":92,"n":"第九十二条","txt":"私文书证的真实性，由主张以私文书证证明案件事实的当事人承担举证责任。"},{"i":93,"n":"第九十三条","txt":"人民法院对于电子数据的真实性，应当结合下列因素综合判断："},{"i":94,"n":"第九十四条","txt":"电子数据存在下列情形的，人民法院可以确认其真实性，但有足以反驳的相反证据的除外："},{"i":95,"n":"第九十五条","txt":"一方当事人控制证据无正当理由拒不提交，对待证事实负有举证责任的当事人主张该证据的内容不利于控制人的，人民法院可以认定该主张成立。"},{"i":96,"n":"第九十六条","txt":"人民法院认定证人证言，可以通过对证人的智力状况、品德、知识、经验、法律意识和专业技能等的综合分析作出判断。"},{"i":97,"n":"第九十七条","txt":"人民法院应当在裁判文书中阐明证据是否采纳的理由。"},{"i":98,"n":"第九十八条","txt":"对证人、鉴定人、勘验人的合法权益依法予以保护。"},{"i":99,"n":"第九十九条","txt":"本规定对证据保全没有规定的，参照适用法律、司法解释关于财产保全的规定。"},{"i":100,"n":"第一百条","txt":"本规定自2020年5月1日起施行。"}],"zuigaorenminfayuanguanyuhaishifayuanshoulianjianfa592a64":[],"zuigaorenminfayuanguanyuhaishisusongguanxiawentidebd6190":[],"zuigaorenminfayuanguanyushetaiminshisusongwenshuso3bea68":[{"i":1,"n":"第一条","txt":"人民法院审理涉台民事案件向住所地在台湾地区的当事人送达民事诉讼文书，以及人民法院接受台湾地区有关法院的委托代为向住所地在大陆的当事人送达民事诉讼文书，适用本规定。"},{"i":2,"n":"第二条","txt":"人民法院送达或者代为送达的民事诉讼文书包括：起诉状副本、上诉状副本、反诉状副本、答辩状副本、授权委托书、传票、判决书、调解书、裁定书、支付令、决定书、通知书、证明书、送达回证以及与民事诉讼有关的其他文书。"},{"i":3,"n":"第三条","txt":"人民法院向住所地在台湾地区的当事人送达民事诉讼文书，可以采用下列方式："},{"i":4,"n":"第四条","txt":"采用本规定第三条第一款第（一）、（二）、（三）、（四）项方式送达的，由受送达人、诉讼代理人或者有权接受送达的人在送达回证上签收或者盖章，即为送达；拒绝签收或者盖章的，可以依法留置送达。"},{"i":5,"n":"第五条","txt":"采用本规定第三条第一款第（五）项方式送达的，应当附有送达回证。受送达人未在送达回证上签收但在邮件回执上签收的，视为送达，签收日期为送达日期。"},{"i":6,"n":"第六条","txt":"采用本规定第三条第一款第（六）项方式送达的，应当注明人民法院的传真号码或者电子信箱地址，并要求受送达人在收到传真件或者电子邮件后及时予以回复。以能够确认受送达人收悉的日期为送达日期。"},{"i":7,"n":"第七条","txt":"采用本规定第三条第一款第（七）项方式送达的，应当由有关的高级人民法院出具盖有本院印章的委托函。委托函应当写明案件各方当事人的姓名或者名称、案由、案号；受送达人姓名或者名称、受送达人的详细地址以及需送达的文书种类。"},{"i":8,"n":"第八条","txt":"采用公告方式送达的，公告内容应当在境内外公开发行的报刊或者权威网站上刊登。"},{"i":9,"n":"第九条","txt":"人民法院按照两岸认可的有关途径代为送达台湾地区法院的民事诉讼文书的，应当有台湾地区有关法院的委托函。"},{"i":10,"n":"第十条","txt":"人民法院按照委托函中的受送达人姓名或者名称、地址不能送达的，应当附函写明情况，将委托送达的民事诉讼文书退回。"},{"i":11,"n":"第十一条","txt":"受委托的人民法院对台湾地区有关法院委托送达的民事诉讼文书的内容和后果不负法律责任。"}],"zuigaorenminfayuanguanyushewaiminshihuoshangshianje6f631":[{"i":1,"n":"第一条","txt":"人民法院审理涉外民事或商事案件时，向在中华人民共和国领域内没有住所的受送达人送达司法文书，适用本规定。"},{"i":2,"n":"第二条","txt":"本规定所称司法文书，是指起诉状副本、上诉状副本、反诉状副本、答辩状副本、传票、判决书、调解书、裁定书、支付令、决定书、通知书、证明书、送达回证以及其他司法文书。"},{"i":3,"n":"第三条","txt":"作为受送达人的自然人或者企业、其他组织的法定代表人、主要负责人在中华人民共和国领域内的，人民法院可以向该自然人或者法定代表人、主要负责人送达。"},{"i":4,"n":"第四条","txt":"除受送达人在授权委托书中明确表明其诉讼代理人无权代为接收有关司法文书外，其委托的诉讼代理人为民事诉讼法第二百六十七条第（四）项规定的有权代其接受送达的诉讼代理人，人民法院可以向该诉讼代理人送达。"},{"i":5,"n":"第五条","txt":"人民法院向受送达人送达司法文书，可以送达给其在中华人民共和国领域内设立的代表机构。"},{"i":6,"n":"第六条","txt":"人民法院向在中华人民共和国领域内没有住所的受送达人送达司法文书时，若该受送达人所在国与中华人民共和国签订有司法协助协定，可以依照司法协助协定规定的方式送达；若该受送达人所在国是《关于向国外送达民事或商事司法文书和司法外文书公约》的成员国，可以依照该公约规定的方式送达。"},{"i":7,"n":"第七条","txt":"按照司法协助协定、《关于向国外送达民事或商事司法文书和司法外文书公约》或者外交途径送达司法文书，自我国有关机关将司法文书转递受送达人所在国有关机关之日起满六个月，如果未能收到送达与否的证明文件，且根据各种情况不足以认定已经送达的，视为不能用该种方式送达。"},{"i":8,"n":"第八条","txt":"受送达人所在国允许邮寄送达的，人民法院可以邮寄送达。"},{"i":9,"n":"第九条","txt":"人民法院依照民事诉讼法第二百六十七条第（八）项规定的公告方式送达时，公告内容应在国内外公开发行的报刊上刊登。"},{"i":10,"n":"第十条","txt":"除本规定上述送达方式外，人民法院可以通过传真、电子邮件等能够确认收悉的其他适当方式向受送达人送达。"},{"i":11,"n":"第十一条","txt":"除公告送达方式外，人民法院可以同时采取多种方式向受送达人进行送达，但应根据最先实现送达的方式确定送达日期。"},{"i":12,"n":"第十二条","txt":"人民法院向受送达人在中华人民共和国领域内的法定代表人、主要负责人、诉讼代理人、代表机构以及有权接受送达的分支机构、业务代办人送达司法文书，可以适用留置送达的方式。"},{"i":13,"n":"第十三条","txt":"受送达人未对人民法院送达的司法文书履行签收手续，但存在以下情形之一的，视为送达："},{"i":14,"n":"第十四条","txt":"人民法院送达司法文书，根据有关规定需要通过上级人民法院转递的，应附申请转递函。"},{"i":15,"n":"第十五条","txt":"人民法院送达司法文书，根据有关规定需要提供翻译件的，应由受理案件的人民法院委托中华人民共和国领域内的翻译机构进行翻译。"},{"i":16,"n":"第十六条","txt":"本规定自公布之日起施行。"}],"zuigaorenminfayuanguanyushewaiminshangshianjianguaef67dc":[{"i":1,"n":"第一条","txt":"基层人民法院管辖第一审涉外民商事案件，法律、司法解释另有规定的除外。"},{"i":2,"n":"第二条","txt":"中级人民法院管辖下列第一审涉外民商事案件："},{"i":3,"n":"第三条","txt":"高级人民法院管辖诉讼标的额人民币50亿元以上（包含本数）或者其他在本辖区有重大影响的第一审涉外民商事案件。"},{"i":4,"n":"第四条","txt":"高级人民法院根据本辖区的实际情况，认为确有必要的，经报最高人民法院批准，可以指定一个或数个基层人民法院、中级人民法院分别对本规定第一条、第二条规定的第一审涉外民商事案件实行跨区域集中管辖。"},{"i":5,"n":"第五条","txt":"涉外民商事案件由专门的审判庭或合议庭审理。"},{"i":6,"n":"第六条","txt":"涉外海事海商纠纷案件、涉外知识产权纠纷案件、涉外生态环境损害赔偿纠纷案件以及涉外环境民事公益诉讼案件，不适用本规定。"},{"i":7,"n":"第七条","txt":"涉及香港、澳门特别行政区和台湾地区的民商事案件参照适用本规定。"},{"i":8,"n":"第八条","txt":"本规定自2023年1月1日起施行。本规定施行后受理的案件适用本规定。"},{"i":9,"n":"第九条","txt":"本院以前发布的司法解释与本规定不一致的，以本规定为准。"}],"zuigaorenminfayuanguanyushewaiminshangshianjiansus7e8f30":[{"i":1,"n":"第一条","txt":"第一审涉外民商事案件由下列人民法院管辖："},{"i":2,"n":"第二条","txt":"对国务院批准设立的经济技术开发区人民法院所作的第一审判决、裁定不服的，其第二审由所在地中级人民法院管辖。"},{"i":3,"n":"第三条","txt":"本规定适用于下列案件："},{"i":4,"n":"第四条","txt":"发生在与外国接壤的边境省份的边境贸易纠纷案件，涉外房地产案件和涉外知识产权案件，不适用本规定。"},{"i":5,"n":"第五条","txt":"涉及香港、澳门特别行政区和台湾地区当事人的民商事纠纷案件的管辖，参照本规定处理。"},{"i":6,"n":"第六条","txt":"高级人民法院应当对涉外民商事案件的管辖实施监督，凡越权受理涉外民商事案件的，应当通知或者裁定将案件移送有管辖权的人民法院审理。"},{"i":7,"n":"第七条","txt":"本规定于2002年3月1日起施行。本规定施行前已经受理的案件由原受理人民法院继续审理。"}],"zuigaorenminfayuanguanyushegangaominshangshianjian60f580":[{"i":1,"n":"第一条","txt":"人民法院审理涉及香港特别行政区、澳门特别行政区的民商事案件时，向住所地在香港特别行政区、澳门特别行政区的受送达人送达司法文书，适用本规定。"},{"i":2,"n":"第二条","txt":"本规定所称司法文书，是指起诉状副本、上诉状副本、反诉状副本、答辩状副本、传票、判决书、调解书、裁定书、支付令、决定书、通知书、证明书、送达回证等与诉讼相关的文书。"},{"i":3,"n":"第三条","txt":"作为受送达人的自然人或者企业、其他组织的法定代表人、主要负责人在内地的，人民法院可以直接向该自然人或者法定代表人、主要负责人送达。"},{"i":4,"n":"第四条","txt":"除受送达人在授权委托书中明确表明其诉讼代理人无权代为接收有关司法文书外，其委托的诉讼代理人为有权代其接受送达的诉讼代理人，人民法院可以向该诉讼代理人送达。"},{"i":5,"n":"第五条","txt":"受送达人在内地设立有代表机构的，人民法院可以直接向该代表机构送达。"},{"i":6,"n":"第六条","txt":"人民法院向在内地没有住所的受送达人送达司法文书，可以按照《最高人民法院关于内地与香港特别行政区法院相互委托送达民商事司法文书的安排》或者《最高人民法院关于内地与澳门特别行政区法院就民商事案件相互委托送达司法文书和调取证据的安排》送达。"},{"i":7,"n":"第七条","txt":"人民法院向受送达人送达司法文书，可以邮寄送达。"},{"i":8,"n":"第八条","txt":"人民法院可以通过传真、电子邮件等能够确认收悉的其他适当方式向受送达人送达。"},{"i":9,"n":"第九条","txt":"人民法院不能依照本规定上述方式送达的，可以公告送达。公告内容应当在内地和受送达人住所地公开发行的报刊上刊登，自公告之日起满三个月即视为送达。"},{"i":10,"n":"第十条","txt":"除公告送达方式外，人民法院可以同时采取多种法定方式向受送达人送达。"},{"i":11,"n":"第十一条","txt":"人民法院向在内地的受送达人或者受送达人的法定代表人、主要负责人、诉讼代理人、代表机构以及有权接受送达的分支机构、业务代办人送达司法文书，可以适用留置送达的方式。"},{"i":12,"n":"第十二条","txt":"受送达人未对人民法院送达的司法文书履行签收手续，但存在以下情形之一的，视为送达："},{"i":13,"n":"第十三条","txt":"下级人民法院送达司法文书，根据有关规定需要通过上级人民法院转递的，应当附申请转递函。"}],"zuigaorenminfayuanguanyushengtaihuanjingqinquanmind521ff":[{"i":1,"n":"第一条","txt":"人民法院审理环境污染责任纠纷案件、生态破坏责任纠纷案件和生态环境保护民事公益诉讼案件，适用本规定。"},{"i":2,"n":"第二条","txt":"环境污染责任纠纷案件、生态破坏责任纠纷案件的原告应当就以下事实承担举证责任："},{"i":3,"n":"第三条","txt":"生态环境保护民事公益诉讼案件的原告应当就以下事实承担举证责任："},{"i":4,"n":"第四条","txt":"原告请求被告就其污染环境、破坏生态行为支付人身、财产损害赔偿费用，或者支付民法典第一千二百三十五条规定的损失、费用的，应当就其主张的损失、费用的数额承担举证责任。"},{"i":5,"n":"第五条","txt":"原告起诉请求被告承担环境污染、生态破坏责任的，应当提供被告行为与损害之间具有关联性的证据。"},{"i":6,"n":"第六条","txt":"被告应当就其行为与损害之间不存在因果关系承担举证责任。"},{"i":7,"n":"第七条","txt":"被告证明其排放的污染物、释放的生态因素、产生的生态影响未到达损害发生地，或者其行为在损害发生后才实施且未加重损害后果，或者存在其行为不可能导致损害发生的其他情形的，人民法院应当认定被告行为与损害之间不存在因果关系。"},{"i":8,"n":"第八条","txt":"对于发生法律效力的刑事裁判、行政裁判因未达到证明标准未予认定的事实，在因同一污染环境、破坏生态行为提起的生态环境侵权民事诉讼中，人民法院根据有关事实和证据确信待证事实的存在具有高度可能性的，应当认定该事实存在。"},{"i":9,"n":"第九条","txt":"对于人民法院在生态环境保护民事公益诉讼生效裁判中确认的基本事实，当事人在因同一污染环境、破坏生态行为提起的人身、财产损害赔偿诉讼中无需举证证明，但有相反证据足以推翻的除外。"},{"i":10,"n":"第十条","txt":"对于可能损害国家利益、社会公共利益的事实，双方当事人未主张或者无争议，人民法院认为可能影响裁判结果的，可以责令当事人提供有关证据。"},{"i":11,"n":"第十一条","txt":"实行环境资源案件集中管辖的法院，可以委托侵权行为实施地、侵权结果发生地、被告住所地等人民法院调查收集证据。受委托法院应当在收到委托函次日起三十日内完成委托事项，并将调查收集的证据及有关笔录移送委托法院。"},{"i":12,"n":"第十二条","txt":"当事人或者利害关系人申请保全环境污染、生态破坏相关证据的，人民法院应当结合下列因素进行审查，确定是否采取保全措施："},{"i":13,"n":"第十三条","txt":"在符合证据保全目的的情况下，人民法院应当选择对证据持有人利益影响最小的保全措施，尽量减少对保全标的物价值的损害和对证据持有人生产、生活的影响。"},{"i":14,"n":"第十四条","txt":"人民法院调查收集、保全或者勘验涉及环境污染、生态破坏专门性问题的证据，应当遵守相关技术规范。必要时，可以通知鉴定人到场，或者邀请负有环境资源保护监督管理职责的部门派员协助。"},{"i":15,"n":"第十五条","txt":"当事人向人民法院提交证据后申请撤回该证据，或者声明不以该证据证明案件事实的，不影响其他当事人援引该证据证明案件事实以及人民法院对该证据进行审查认定。"},{"i":16,"n":"第十六条","txt":"对于查明环境污染、生态破坏案件事实的专门性问题，人民法院经审查认为有必要的，应当根据当事人的申请或者依职权委托具有相应资格的机构、人员出具鉴定意见。"},{"i":17,"n":"第十七条","txt":"对于法律适用、当事人责任划分等非专门性问题，或者虽然属于专门性问题，但可以通过法庭调查、勘验等其他方式查明的，人民法院不予委托鉴定。"},{"i":18,"n":"第十八条","txt":"鉴定人需要邀请其他机构、人员完成部分鉴定事项的，应当向人民法院提出申请。"},{"i":19,"n":"第十九条","txt":"未经人民法院准许，鉴定人邀请其他机构、人员完成部分鉴定事项的，鉴定意见不得作为认定案件事实的根据。"},{"i":20,"n":"第二十条","txt":"鉴定人提供虚假鉴定意见的，该鉴定意见不得作为认定案件事实的根据。人民法院可以依照民事诉讼法第一百一十四条的规定进行处理。"},{"i":21,"n":"第二十一条","txt":"因没有鉴定标准、成熟的鉴定方法、相应资格的鉴定人等原因无法进行鉴定，或者鉴定周期过长、费用过高的，人民法院可以结合案件有关事实、当事人申请的有专门知识的人的意见和其他证据，对涉及专门性问题的事实作出认定。"},{"i":22,"n":"第二十二条","txt":"当事人申请有专门知识的人出庭，就鉴定意见或者污染物认定、损害结果、因果关系、生态环境修复方案、生态环境修复费用、生态环境受到损害至修复完成期间服务功能丧失导致的损失、生态环境功能永久性损害造成的损失等专业问题提出意见的，人民法院可以准许。"},{"i":23,"n":"第二十三条","txt":"当事人就环境污染、生态破坏的专门性问题自行委托有关机构、人员出具的意见，人民法院应当结合本案的其他证据，审查确定能否作为认定案件事实的根据。"},{"i":24,"n":"第二十四条","txt":"负有环境资源保护监督管理职责的部门在其职权范围内制作的处罚决定等文书所记载的事项推定为真实，但有相反证据足以推翻的除外。"},{"i":25,"n":"第二十五条","txt":"负有环境资源保护监督管理职责的部门及其所属或者委托的监测机构在行政执法过程中收集的监测数据、形成的事件调查报告、检验检测报告、评估报告等材料，以及公安机关单独或者会同负有环境资源保护监督管理职责的部门提取样品进行检测获取的数据，经当事人质证，可以作为认定案件事实的根据。"},{"i":26,"n":"第二十六条","txt":"对于证明环境污染、生态破坏案件事实有重要意义的书面文件、数据信息或者录音、录像等证据在对方当事人控制之下的，承担举证责任的当事人可以根据《最高人民法院关于适用〈中华人民共和国民事诉讼法〉的解释》第一百一十二条的规定，书面申请人民法院责令对方当事人提交。"},{"i":27,"n":"第二十七条","txt":"承担举证责任的当事人申请人民法院责令对方当事人提交证据的，应当提供有关证据的名称、主要内容、制作人、制作时间或者其他可以将有关证据特定化的信息。根据申请人提供的信息不能使证据特定化的，人民法院不予准许。"},{"i":28,"n":"第二十八条","txt":"承担举证责任的当事人申请人民法院责令对方当事人提交证据的，应当提出证据由对方当事人控制的依据。对方当事人否认控制有关证据的，人民法院应当根据法律规定、当事人约定、交易习惯等因素，结合案件的事实、证据作出判断。"},{"i":29,"n":"第二十九条","txt":"法律、法规、规章规定当事人应当披露或者持有的关于其排放的主要污染物名称、排放方式、排放浓度和总量、超标排放情况、防治污染设施的建设和运行情况、生态环境开发利用情况、生态环境违法信息等环境信息，属于《最高人民法院关于民事诉讼证据的若干规定》第四十七条第一款第三项规定的“对方当事人依照法律规定有权查阅、获取的书证”。"},{"i":30,"n":"第三十条","txt":"在环境污染责任纠纷、生态破坏责任纠纷案件中，损害事实成立，但人身、财产损害赔偿数额难以确定的，人民法院可以结合侵权行为对原告造成损害的程度、被告因侵权行为获得的利益以及过错程度等因素，并可以参考负有环境资源保护监督管理职责的部门的意见等，合理确定。"},{"i":31,"n":"第三十一条","txt":"在生态环境保护民事公益诉讼案件中，损害事实成立，但生态环境修复费用、生态环境受到损害至修复完成期间服务功能丧失导致的损失、生态环境功能永久性损害造成的损失等数额难以确定的，人民法院可以根据污染环境、破坏生态的范围和程度等已查明的案件事实，结合生态环境及其要素的稀缺性、生态环境恢复的难易程度、防治污染设备的运行成本、被告因侵权行为获得的利益以及过错程度等因素，并可以参考负有环境资源保护监督管理职责的部门的意见等，合理确定。"},{"i":32,"n":"第三十二条","txt":"本规定未作规定的，适用《最高人民法院关于民事诉讼证据的若干规定》。"},{"i":33,"n":"第三十三条","txt":"人民法院审理人民检察院提起的环境污染民事公益诉讼案件、生态破坏民事公益诉讼案件，参照适用本规定。"},{"i":34,"n":"第三十四条","txt":"本规定自2023年9月1日起施行。"}],"zuigaorenminfayuanguanyuzhishichanquanminshisusong85e1e4":[{"i":1,"n":"第一条","txt":"知识产权民事诉讼当事人应当遵循诚信原则，依照法律及司法解释的规定，积极、全面、正确、诚实地提供证据。"},{"i":2,"n":"第二条","txt":"当事人对自己提出的主张，应当提供证据加以证明。根据案件审理情况，人民法院可以适用民事诉讼法第六十五条第二款的规定，根据当事人的主张及待证事实、当事人的证据持有情况、举证能力等，要求当事人提供有关证据。"},{"i":3,"n":"第三条","txt":"专利方法制造的产品不属于新产品的，侵害专利权纠纷的原告应当举证证明下列事实："},{"i":4,"n":"第四条","txt":"被告依法主张合法来源抗辩的，应当举证证明合法取得被诉侵权产品、复制品的事实，包括合法的购货渠道、合理的价格和直接的供货方等。"},{"i":5,"n":"第五条","txt":"提起确认不侵害知识产权之诉的原告应当举证证明下列事实："},{"i":6,"n":"第六条","txt":"对于未在法定期限内提起行政诉讼的行政行为所认定的基本事实，或者行政行为认定的基本事实已为生效裁判所确认的部分，当事人在知识产权民事诉讼中无须再证明，但有相反证据足以推翻的除外。"},{"i":7,"n":"第七条","txt":"权利人为发现或者证明知识产权侵权行为，自行或者委托他人以普通购买者的名义向被诉侵权人购买侵权物品所取得的实物、票据等可以作为起诉被诉侵权人侵权的证据。"},{"i":8,"n":"第八条","txt":"中华人民共和国领域外形成的下列证据，当事人仅以该证据未办理公证、认证等证明手续为由提出异议的，人民法院不予支持："},{"i":9,"n":"第九条","txt":"中华人民共和国领域外形成的证据，存在下列情形之一的，当事人仅以该证据未办理认证手续为由提出异议的，人民法院不予支持："},{"i":10,"n":"第十条","txt":"在一审程序中已经根据民事诉讼法第五十九条、第二百六十四条的规定办理授权委托书公证、认证或者其他证明手续的，在后续诉讼程序中，人民法院可以不再要求办理该授权委托书的上述证明手续。"},{"i":11,"n":"第十一条","txt":"人民法院对于当事人或者利害关系人的证据保全申请，应当结合下列因素进行审查："},{"i":12,"n":"第十二条","txt":"人民法院进行证据保全，应当以有效固定证据为限，尽量减少对保全标的物价值的损害和对证据持有人正常生产经营的影响。"},{"i":13,"n":"第十三条","txt":"当事人无正当理由拒不配合或者妨害证据保全，致使无法保全证据的，人民法院可以确定由其承担不利后果。构成民事诉讼法第一百一十一条规定情形的，人民法院依法处理。"},{"i":14,"n":"第十四条","txt":"对于人民法院已经采取保全措施的证据，当事人擅自拆装证据实物、篡改证据材料或者实施其他破坏证据的行为，致使证据不能使用的，人民法院可以确定由其承担不利后果。构成民事诉讼法第一百一十一条规定情形的，人民法院依法处理。"},{"i":15,"n":"第十五条","txt":"人民法院进行证据保全，可以要求当事人或者诉讼代理人到场，必要时可以根据当事人的申请通知有专门知识的人到场，也可以指派技术调查官参与证据保全。"},{"i":16,"n":"第十六条","txt":"人民法院进行证据保全，应当制作笔录、保全证据清单，记录保全时间、地点、实施人、在场人、保全经过、保全标的物状态，由实施人、在场人签名或者盖章。有关人员拒绝签名或者盖章的，不影响保全的效力，人民法院可以在笔录上记明并拍照、录像。"},{"i":17,"n":"第十七条","txt":"被申请人对证据保全的范围、措施、必要性等提出异议并提供相关证据，人民法院经审查认为异议理由成立的，可以变更、终止、解除证据保全。"},{"i":18,"n":"第十八条","txt":"申请人放弃使用被保全证据，但被保全证据涉及案件基本事实查明或者其他当事人主张使用的，人民法院可以对该证据进行审查认定。"},{"i":19,"n":"第十九条","txt":"人民法院可以对下列待证事实的专门性问题委托鉴定："},{"i":20,"n":"第二十条","txt":"经人民法院准许或者双方当事人同意，鉴定人可以将鉴定所涉部分检测事项委托其他检测机构进行检测，鉴定人对根据检测结果出具的鉴定意见承担法律责任。"},{"i":21,"n":"第二十一条","txt":"鉴定业务领域未实行鉴定人和鉴定机构统一登记管理制度的，人民法院可以依照《最高人民法院关于民事诉讼证据的若干规定》第三十二条规定的鉴定人选任程序，确定具有相应技术水平的专业机构、专业人员鉴定。"},{"i":22,"n":"第二十二条","txt":"人民法院应当听取各方当事人意见，并结合当事人提出的证据确定鉴定范围。鉴定过程中，一方当事人申请变更鉴定范围，对方当事人无异议的，人民法院可以准许。"},{"i":23,"n":"第二十三条","txt":"人民法院应当结合下列因素对鉴定意见进行审查："},{"i":24,"n":"第二十四条","txt":"承担举证责任的当事人书面申请人民法院责令控制证据的对方当事人提交证据，申请理由成立的，人民法院应当作出裁定，责令其提交。"},{"i":25,"n":"第二十五条","txt":"人民法院依法要求当事人提交有关证据，其无正当理由拒不提交、提交虚假证据、毁灭证据或者实施其他致使证据不能使用行为的，人民法院可以推定对方当事人就该证据所涉证明事项的主张成立。"},{"i":26,"n":"第二十六条","txt":"证据涉及商业秘密或者其他需要保密的商业信息的，人民法院应当在相关诉讼参与人接触该证据前，要求其签订保密协议、作出保密承诺，或者以裁定等法律文书责令其不得出于本案诉讼之外的任何目的披露、使用、允许他人使用在诉讼程序中接触到的秘密信息。"},{"i":27,"n":"第二十七条","txt":"证人应当出庭作证，接受审判人员及当事人的询问。"},{"i":28,"n":"第二十八条","txt":"当事人可以申请有专门知识的人出庭，就专业问题提出意见。经法庭准许，当事人可以对有专门知识的人进行询问。"},{"i":29,"n":"第二十九条","txt":"人民法院指派技术调查官参与庭前会议、开庭审理的，技术调查官可以就案件所涉技术问题询问当事人、诉讼代理人、有专门知识的人、证人、鉴定人、勘验人等。"},{"i":30,"n":"第三十条","txt":"当事人对公证文书提出异议，并提供相反证据足以推翻的，人民法院对该公证文书不予采纳。"},{"i":31,"n":"第三十一条","txt":"当事人提供的财务账簿、会计凭证、销售合同、进出货单据、上市公司年报、招股说明书、网站或者宣传册等有关记载，设备系统存储的交易数据，第三方平台统计的商品流通数据，评估报告，知识产权许可使用合同以及市场监管、税务、金融部门的记录等，可以作为证据，用以证明当事人主张的侵害知识产权赔偿数额。"},{"i":32,"n":"第三十二条","txt":"当事人主张参照知识产权许可使用费的合理倍数确定赔偿数额的，人民法院可以考量下列因素对许可使用费证据进行审核认定："},{"i":33,"n":"第三十三条","txt":"本规定自2020年11月18日起施行。本院以前发布的相关司法解释与本规定不一致的，以本规定为准。"}],"zuigaorenminfayuanguanyuzhishichanquanfatingruoganaa679e":[{"i":1,"n":"第一条","txt":"最高人民法院设立知识产权法庭，主要审理专利等专业技术性较强的知识产权上诉案件。"},{"i":2,"n":"第二条","txt":"知识产权法庭审理下列上诉案件："},{"i":3,"n":"第三条","txt":"审理本规定第二条所称案件的下级人民法院应当按照规定及时向知识产权法庭移送纸质、电子卷宗。"},{"i":4,"n":"第四条","txt":"知识产权法庭可以要求当事人披露涉案知识产权相关权属、侵权、授权确权等关联案件情况。当事人拒不如实披露的，可以作为认定其是否遵循诚实信用原则和构成滥用权利等的考量因素。"},{"i":5,"n":"第五条","txt":"知识产权法庭可以根据案件情况到实地或者原审人民法院所在地巡回审理案件。"},{"i":6,"n":"第六条","txt":"知识产权法庭采取保全等措施，依照执行程序相关规定办理。"},{"i":7,"n":"第七条","txt":"知识产权法庭审理的案件的立案信息、合议庭组成人员、审判流程、裁判文书等依法公开。"},{"i":8,"n":"第八条","txt":"知识产权法庭法官会议由庭长、副庭长和若干资深法官组成，讨论重大、疑难、复杂案件等。"},{"i":9,"n":"第九条","txt":"知识产权法庭应当加强对有关案件审判工作的调研，及时总结裁判标准和审理规则，指导下级人民法院审判工作。"},{"i":10,"n":"第十条","txt":"对知识产权法院、中级人民法院已经发生法律效力的本规定第二条第一款规定类型的第一审民事和行政案件判决、裁定、调解书，省级人民检察院向高级人民法院提出抗诉的，高级人民法院应当告知其由最高人民检察院依法向最高人民法院提出，并由知识产权法庭审理。"},{"i":11,"n":"第十一条","txt":"本规定自2019年1月1日起施行。最高人民法院此前发布的司法解释与本规定不一致的，以本规定为准。"}],"zuigaorenminfayuanguanyudiyishenzhishichanquanminsa00cba":[{"i":1,"n":"第一条","txt":"发明专利、实用新型专利、植物新品种、集成电路布图设计、技术秘密、计算机软件的权属、侵权纠纷以及垄断纠纷第一审民事、行政案件由知识产权法院，省、自治区、直辖市人民政府所在地的中级人民法院和最高人民法院确定的中级人民法院管辖。"},{"i":2,"n":"第二条","txt":"外观设计专利的权属、侵权纠纷以及涉驰名商标认定第一审民事、行政案件由知识产权法院和中级人民法院管辖；经最高人民法院批准，也可以由基层人民法院管辖，但外观设计专利行政案件除外。"},{"i":3,"n":"第三条","txt":"本规定第一条、第二条规定之外的第一审知识产权民事、行政案件，由最高人民法院确定的基层人民法院管辖。"},{"i":4,"n":"第四条","txt":"对新类型、疑难复杂或者具有法律适用指导意义等知识产权民事、行政案件，上级人民法院可以依照诉讼法有关规定，根据下级人民法院报请或者自行决定提级审理。"},{"i":5,"n":"第五条","txt":"依照本规定需要最高人民法院确定管辖或者调整管辖的诉讼标的额标准、区域范围的，应当层报最高人民法院批准。"},{"i":6,"n":"第六条","txt":"本规定自2022年5月1日起施行。"}],"zuigaorenminfayuanguanyuzonghezhilileisifajianyigoaeb562":[{"i":1,"n":"第一条","txt":"人民法院在履行审判执行职责时发现社会治理领域中存在引起矛盾纠纷多发高发，影响经济社会发展和人民群众权益保护的突出问题，需要向有关主管机关或者其他有关单位提出改进工作、完善治理的司法建议的，适用本规定。"},{"i":2,"n":"第二条","txt":"人民法院提出司法建议，应当遵循确有必要的原则，确保司法建议的针对性、规范性和实效性。"},{"i":3,"n":"第三条","txt":"人民法院提出司法建议时，应当根据综合治理问题涉及的行业、领域等向相应的主管机关或者其他有关单位提出；向主管机关提出的，一般应当向本院辖区范围内的同级主管机关提出。发现的综合治理问题需要异地主管机关采取措施的，可以提出工作建议，层报相应的上级人民法院决定。"},{"i":4,"n":"第四条","txt":"司法建议应当以人民法院名义提出。"},{"i":5,"n":"第五条","txt":"人民法院提出司法建议前，应当结合审判执行工作中发现的问题充分调查研究，并积极与被建议单位沟通，听取其意见。"},{"i":6,"n":"第六条","txt":"人民法院提出司法建议，应当制作司法建议书。"},{"i":7,"n":"第七条","txt":"司法建议书起草完成后，应当依照《中华人民共和国人民法院组织法》第三十七条第一款第四项的规定提请审判委员会审议。"},{"i":8,"n":"第八条","txt":"人民法院提出司法建议时，应当告知被建议单位就建议采纳落实情况等予以书面答复。答复期限根据具体情况确定，一般不超过两个月；法律、司法解释另有规定的，依照其规定。"},{"i":9,"n":"第九条","txt":"司法建议涉及的问题重大，需要引起高度重视的，人民法院可以将司法建议书抄送被建议单位的上级主管机关或者其他有关单位。"},{"i":10,"n":"第十条","txt":"各级人民法院应当确定司法建议工作日常管理机构，完善审核、指导、考核、激励等机制，并将司法建议工作质效纳入绩效考核。"},{"i":11,"n":"第十一条","txt":"各级人民法院应当依照《中华人民共和国人民法院组织法》第九条的规定，将司法建议工作情况列入向同级人民代表大会及其常务委员会报告的事项。"},{"i":12,"n":"第十二条","txt":"人民法院提出综合治理类司法建议以外的其他司法建议的，依照有关法律、司法解释、其他规范性文件的规定办理。有关法律、司法解释、其他规范性文件没有规定的事项，可以根据本辖区的具体情况和实际需要，参照本规定办理。"},{"i":13,"n":"第十三条","txt":"本规定自2023年11月16日起施行。最高人民法院此前发布的司法解释和其他规范性文件与本规定不一致的，以本规定为准。"}],"zuigaorenminfayuanguanyuwangluochaxundongjiebeizhife940f":[{"i":1,"n":"第一条","txt":"人民法院与金融机构已建立网络执行查控机制的，可以通过网络实施查询、冻结被执行人存款等措施。"},{"i":2,"n":"第二条","txt":"人民法院实施网络执行查控措施，应当事前统一向相应金融机构报备有权通过网络采取执行查控措施的特定执行人员的相关公务证件。办理具体业务时，不再另行向相应金融机构提供执行人员的相关公务证件。"},{"i":3,"n":"第三条","txt":"人民法院通过网络查询被执行人存款时，应当向金融机构传输电子协助查询存款通知书。多案集中查询的，可以附汇总的案件查询清单。"},{"i":4,"n":"第四条","txt":"人民法院向金融机构传输的法律文书，应当加盖电子印章。"},{"i":5,"n":"第五条","txt":"人民法院通过网络查询、冻结、续冻、解冻被执行人存款，与执行人员赴金融机构营业场所查询、冻结、续冻、解冻被执行人存款具有同等效力。"},{"i":6,"n":"第六条","txt":"金融机构认为人民法院通过网络执行查控系统采取的查控措施违反相关法律、行政法规规定的，应当向人民法院书面提出异议。人民法院应当在15日内审查完毕并书面回复。"},{"i":7,"n":"第七条","txt":"人民法院应当依据法律、行政法规规定及相应操作规范使用网络执行查控系统和查控信息，确保信息安全。"},{"i":8,"n":"第八条","txt":"人民法院工作人员违反第七条规定的，应当按照《人民法院工作人员处分条例》给予纪律处分；情节严重构成犯罪的，应当依法追究刑事责任。"},{"i":9,"n":"第九条","txt":"人民法院具备相应网络扣划技术条件，并与金融机构协商一致的，可以通过网络执行查控系统采取扣划被执行人存款措施。"},{"i":10,"n":"第十条","txt":"人民法院与工商行政管理、证券监管、土地房产管理等协助执行单位已建立网络执行查控机制，通过网络执行查控系统对被执行人股权、股票、证券账户资金、房地产等其他财产采取查控措施的，参照本规定执行。"}],"zuigaorenminfayuanguanyuxingzhengjiguanfuzerenchut4cca15":[{"i":1,"n":"第一条","txt":"行政诉讼法第三条第三款规定的被诉行政机关负责人应当出庭应诉，是指被诉行政机关负责人依法应当在第一审、第二审、再审等诉讼程序中出庭参加诉讼，行使诉讼权利，履行诉讼义务。"},{"i":2,"n":"第二条","txt":"行政诉讼法第三条第三款规定的被诉行政机关负责人，包括行政机关的正职、副职负责人、参与分管被诉行政行为实施工作的副职级别的负责人以及其他参与分管的负责人。"},{"i":3,"n":"第三条","txt":"有共同被告的行政案件，可以由共同被告协商确定行政机关负责人出庭应诉；也可以由人民法院确定。"},{"i":4,"n":"第四条","txt":"对于涉及食品药品安全、生态环境和资源保护、公共卫生安全等重大公共利益，社会高度关注或者可能引发群体性事件等的案件，人民法院应当通知行政机关负责人出庭应诉。"},{"i":5,"n":"第五条","txt":"人民法院在向行政机关送达的权利义务告知书中，应当一并告知行政机关负责人出庭应诉的法定义务及相关法律后果等事项。"},{"i":6,"n":"第六条","txt":"行政机关负责人出庭应诉的，应当于开庭前向人民法院提交出庭应诉负责人的身份证明。身份证明应当载明该负责人的姓名、职务等基本信息，并加盖行政机关印章。"},{"i":7,"n":"第七条","txt":"对于同一审级需要多次开庭的同一案件，行政机关负责人到庭参加一次庭审的，一般可以认定其已经履行出庭应诉义务，但人民法院通知行政机关负责人再次出庭的除外。"},{"i":8,"n":"第八条","txt":"有下列情形之一的，属于行政诉讼法第三条第三款规定的行政机关负责人不能出庭的情形："},{"i":9,"n":"第九条","txt":"行政机关负责人有正当理由不能出庭的，应当提交相关证明材料，并加盖行政机关印章或者由该机关主要负责人签字认可。"},{"i":10,"n":"第十条","txt":"行政诉讼法第三条第三款规定的相应的工作人员，是指被诉行政机关中具体行使行政职权的工作人员。"},{"i":11,"n":"第十一条","txt":"诉讼参与人参加诉讼活动，应当依法行使诉讼权利，履行诉讼义务，遵守法庭规则，自觉维护诉讼秩序。"},{"i":12,"n":"第十二条","txt":"有下列情形之一的，人民法院应当向监察机关、被诉行政机关的上一级行政机关提出司法建议："},{"i":13,"n":"第十三条","txt":"当事人对行政机关具有本规定第十二条第一款情形提出异议的，人民法院可以在庭审笔录中载明，不影响案件的正常审理。"},{"i":14,"n":"第十四条","txt":"人民法院可以通过适当形式将行政机关负责人出庭应诉情况向社会公开。"},{"i":15,"n":"第十五条","txt":"本规定自2020年7月1日起施行。"}],"zuigaorenminfayuanguanyuxingzhengshenqingzaishenanbb43e1":[{"i":1,"n":"第一条","txt":"再审申请应当符合以下条件："},{"i":2,"n":"第二条","txt":"申请再审，有下列情形之一的，人民法院不予立案："},{"i":3,"n":"第三条","txt":"委托他人代为申请再审的，诉讼代理人应为下列人员："},{"i":4,"n":"第四条","txt":"申请再审，应当提交下列材料："},{"i":5,"n":"第五条","txt":"当事人申请再审，一般还应提交下列材料："},{"i":6,"n":"第六条","txt":"再审申请人提交再审申请书等材料时，应当填写送达地址确认书，并可同时附上相关材料的电子文本。"},{"i":7,"n":"第七条","txt":"再审申请书应当载明下列事项："},{"i":8,"n":"第八条","txt":"再审申请人提交的再审申请书等材料符合上述要求的，人民法院应当出具《诉讼材料收取清单》，注明收到材料日期，并加盖专用收件章。《诉讼材料收取清单》一式两份，一份由人民法院入卷，一份由再审申请人留存。"},{"i":9,"n":"第九条","txt":"再审申请人提出的再审申请不符合本规定的，人民法院应当当场告知再审申请人。"},{"i":10,"n":"第十条","txt":"对符合上述条件的再审申请，人民法院应当及时立案，并应自收到符合条件的再审申请书等材料之日起五日内向再审申请人发送受理通知书，同时向被申请人及原审其他当事人发送应诉通知书、再审申请书副本及送达地址确认书。"},{"i":11,"n":"第十一条","txt":"再审申请人向原审人民法院申请再审或者越级申请再审的，原审人民法院或者有关上级人民法院应当告知其向作出生效裁判的人民法院的上一级法院提出。"},{"i":12,"n":"第十二条","txt":"当事人申请再审，应当在判决、裁定、调解书发生法律效力后六个月内提出。"},{"i":13,"n":"第十三条","txt":"人民法院认为再审申请不符合法定申请再审期间要求的，应当告知再审申请人。"},{"i":14,"n":"第十四条","txt":"再审申请人申请撤回再审申请，尚未立案的，人民法院退回已提交材料并记录在册；已经立案的，人民法院裁定是否准许撤回再审申请。人民法院准许撤回再审申请或者按撤回再审申请处理后，再审申请人再次申请再审的，人民法院不予立案，但有行政诉讼法第九十一条第二项、第三项、第七项、第八项规定等情形，自知道或者应当知道之日起六个月内提出的除外。"},{"i":15,"n":"第十五条","txt":"本规定自2018年1月1日起施行，最高人民法院以前发布的有关规定与本规定不符的，按照本规定执行。"}],"zuigaorenminfayuanguanyuxingzhengsusongchesuruoganab558f":[{"i":1,"n":"第一条","txt":"人民法院经审查认为被诉具体行政行为违法或者不当，可以在宣告判决或者裁定前，建议被告改变其所作的具体行政行为。"},{"i":2,"n":"第二条","txt":"被告改变被诉具体行政行为，原告申请撤诉，符合下列条件的，人民法院应当裁定准许："},{"i":3,"n":"第三条","txt":"有下列情形之一的，属于行政诉讼法第五十一条规定的“被告改变其所作的具体行政行为”："},{"i":4,"n":"第四条","txt":"有下列情形之一的，可以视为“被告改变其所作的具体行政行为”："},{"i":5,"n":"第五条","txt":"被告改变被诉具体行政行为，原告申请撤诉，有履行内容且履行完毕的，人民法院可以裁定准许撤诉；不能即时或者一次性履行的，人民法院可以裁定准许撤诉，也可以裁定中止审理。"},{"i":6,"n":"第六条","txt":"准许撤诉裁定可以载明被告改变被诉具体行政行为的主要内容及履行情况，并可以根据案件具体情况，在裁定理由中明确被诉具体行政行为全部或者部分不再执行。"},{"i":7,"n":"第七条","txt":"申请撤诉不符合法定条件，或者被告改变被诉具体行政行为后当事人不撤诉的，人民法院应当及时作出裁判。"},{"i":8,"n":"第八条","txt":"第二审或者再审期间行政机关改变被诉具体行政行为，当事人申请撤回上诉或者再审申请的，参照本规定。"},{"i":9,"n":"第九条","txt":"本院以前所作的司法解释及规范性文件，凡与本规定不一致的，按本规定执行。"}],"zuigaorenminfayuanguanyuxingzhengsusongzhengjuruog016380":[{"i":1,"n":"第一条","txt":"根据行政诉讼法第三十二条和第四十三条的规定，被告对作出的具体行政行为负有举证责任，应当在收到起诉状副本之日起10日内，提供据以作出被诉具体行政行为的全部证据和所依据的规范性文件。被告不提供或者无正当理由逾期提供证据的，视为被诉具体行政行为没有相应的证据。"},{"i":2,"n":"第二条","txt":"原告或者第三人提出其在行政程序中没有提出的反驳理由或者证据的，经人民法院准许，被告可以在第一审程序中补充相应的证据。"},{"i":3,"n":"第三条","txt":"根据行政诉讼法第三十三条的规定，在诉讼过程中，被告及其诉讼代理人不得自行向原告和证人收集证据。"},{"i":4,"n":"第四条","txt":"公民、法人或者其他组织向人民法院起诉时，应当提供其符合起诉条件的相应的证据材料。"},{"i":5,"n":"第五条","txt":"在行政赔偿诉讼中，原告应当对被诉具体行政行为造成损害的事实提供证据。"},{"i":6,"n":"第六条","txt":"原告可以提供证明被诉具体行政行为违法的证据。原告提供的证据不成立的，不免除被告对被诉具体行政行为合法性的举证责任。"},{"i":7,"n":"第七条","txt":"原告或者第三人应当在开庭审理前或者人民法院指定的交换证据之日提供证据。因正当事由申请延期提供证据的，经人民法院准许，可以在法庭调查中提供。逾期提供证据的，视为放弃举证权利。"},{"i":8,"n":"第八条","txt":"人民法院向当事人送达受理案件通知书或者应诉通知书时，应当告知其举证范围、举证期限和逾期提供证据的法律后果，并告知因正当事由不能按期提供证据时应当提出延期提供证据的申请。"},{"i":9,"n":"第九条","txt":"根据行政诉讼法第三十四条第一款的规定，人民法院有权要求当事人提供或者补充证据。"},{"i":10,"n":"第十条","txt":"根据行政诉讼法第三十一条第一款第（一）项的规定，当事人向人民法院提供书证的，应当符合下列要求："},{"i":11,"n":"第十一条","txt":"根据行政诉讼法第三十一条第一款第（二）项的规定，当事人向人民法院提供物证的，应当符合下列要求："},{"i":12,"n":"第十二条","txt":"根据行政诉讼法第三十一条第一款第（三）项的规定，当事人向人民法院提供计算机数据或者录音、录像等视听资料的，应当符合下列要求："},{"i":13,"n":"第十三条","txt":"根据行政诉讼法第三十一条第一款第（四）项的规定，当事人向人民法院提供证人证言的，应当符合下列要求："},{"i":14,"n":"第十四条","txt":"根据行政诉讼法第三十一条第一款第（六）项的规定，被告向人民法院提供的在行政程序中采用的鉴定结论，应当载明委托人和委托鉴定的事项、向鉴定部门提交的相关材料、鉴定的依据和使用的科学技术手段、鉴定部门和鉴定人鉴定资格的说明，并应有鉴定人的签名和鉴定部门的盖章。通过分析获得的鉴定结论，应当说明分析过程。"},{"i":15,"n":"第十五条","txt":"根据行政诉讼法第三十一条第一款第（七）项的规定，被告向人民法院提供的现场笔录，应当载明时间、地点和事件等内容，并由执法人员和当事人签名。当事人拒绝签名或者不能签名的，应当注明原因。有其他人在现场的，可由其他人签名。"},{"i":16,"n":"第十六条","txt":"当事人向人民法院提供的在中华人民共和国领域外形成的证据，应当说明来源，经所在国公证机关证明，并经中华人民共和国驻该国使领馆认证，或者履行中华人民共和国与证据所在国订立的有关条约中规定的证明手续。"},{"i":17,"n":"第十七条","txt":"当事人向人民法院提供外文书证或者外国语视听资料的，应当附有由具有翻译资质的机构翻译的或者其他翻译准确的中文译本，由翻译机构盖章或者翻译人员签名。"},{"i":18,"n":"第十八条","txt":"证据涉及国家秘密、商业秘密或者个人隐私的，提供人应当作出明确标注，并向法庭说明，法庭予以审查确认。"},{"i":19,"n":"第十九条","txt":"当事人应当对其提交的证据材料分类编号，对证据材料的来源、证明对象和内容作简要说明，签名或者盖章，注明提交日期。"},{"i":20,"n":"第二十条","txt":"人民法院收到当事人提交的证据材料，应当出具收据，注明证据的名称、份数、页数、件数、种类等以及收到的时间，由经办人员签名或者盖章。"},{"i":21,"n":"第二十一条","txt":"对于案情比较复杂或者证据数量较多的案件，人民法院可以组织当事人在开庭前向对方出示或者交换证据，并将交换证据的情况记录在卷。"},{"i":22,"n":"第二十二条","txt":"根据行政诉讼法第三十四条第二款的规定，有下列情形之一的，人民法院有权向有关行政机关以及其他组织、公民调取证据："},{"i":23,"n":"第二十三条","txt":"原告或者第三人不能自行收集，但能够提供确切线索的，可以申请人民法院调取下列证据材料："},{"i":24,"n":"第二十四条","txt":"当事人申请人民法院调取证据的，应当在举证期限内提交调取证据申请书。"},{"i":25,"n":"第二十五条","txt":"人民法院对当事人调取证据的申请，经审查符合调取证据条件的，应当及时决定调取；不符合调取证据条件的，应当向当事人或者其诉讼代理人送达通知书，说明不准许调取的理由。当事人及其诉讼代理人可以在收到通知书之日起3日内向受理申请的人民法院书面申请复议一次。人民法院应当在收到复议申请之日起5日内作出答复。"},{"i":26,"n":"第二十六条","txt":"人民法院需要调取的证据在异地的，可以书面委托证据所在地人民法院调取。受托人民法院应当在收到委托书后，按照委托要求及时完成调取证据工作，送交委托人民法院。受托人民法院不能完成委托内容的，应当告知委托的人民法院并说明原因。"},{"i":27,"n":"第二十七条","txt":"当事人根据行政诉讼法第三十六条的规定向人民法院申请保全证据的，应当在举证期限届满前以书面形式提出，并说明证据的名称和地点、保全的内容和范围、申请保全的理由等事项。"},{"i":28,"n":"第二十八条","txt":"人民法院依照行政诉讼法第三十六条规定保全证据的，可以根据具体情况，采取查封、扣押、拍照、录音、录像、复制、鉴定、勘验、制作询问笔录等保全措施。"},{"i":29,"n":"第二十九条","txt":"原告或者第三人有证据或者有正当理由表明被告据以认定案件事实的鉴定结论可能有错误，在举证期限内书面申请重新鉴定的，人民法院应予准许。"},{"i":30,"n":"第三十条","txt":"当事人对人民法院委托的鉴定部门作出的鉴定结论有异议申请重新鉴定，提出证据证明存在下列情形之一的，人民法院应予准许："},{"i":31,"n":"第三十一条","txt":"对需要鉴定的事项负有举证责任的当事人，在举证期限内无正当理由不提出鉴定申请、不预交鉴定费用或者拒不提供相关材料，致使对案件争议的事实无法通过鉴定结论予以认定的，应当对该事实承担举证不能的法律后果。"},{"i":32,"n":"第三十二条","txt":"人民法院对委托或者指定的鉴定部门出具的鉴定书，应当审查是否具有下列内容："},{"i":33,"n":"第三十三条","txt":"人民法院可以依当事人申请或者依职权勘验现场。"},{"i":34,"n":"第三十四条","txt":"审判人员应当制作勘验笔录，记载勘验的时间、地点、勘验人、在场人、勘验的经过和结果，由勘验人、当事人、在场人签名。"},{"i":35,"n":"第三十五条","txt":"证据应当在法庭上出示，并经庭审质证。未经庭审质证的证据，不能作为定案的依据。"},{"i":36,"n":"第三十六条","txt":"经合法传唤，因被告无正当理由拒不到庭而需要依法缺席判决的，被告提供的证据不能作为定案的依据，但当事人在庭前交换证据中没有争议的证据除外。"},{"i":37,"n":"第三十七条","txt":"涉及国家秘密、商业秘密和个人隐私或者法律规定的其他应当保密的证据，不得在开庭时公开质证。"},{"i":38,"n":"第三十八条","txt":"当事人申请人民法院调取的证据，由申请调取证据的当事人在庭审中出示，并由当事人质证。"},{"i":39,"n":"第三十九条","txt":"当事人应当围绕证据的关联性、合法性和真实性，针对证据有无证明效力以及证明效力大小，进行质证。"},{"i":40,"n":"第四十条","txt":"对书证、物证和视听资料进行质证时，当事人应当出示证据的原件或者原物。但有下列情况之一的除外："},{"i":41,"n":"第四十一条","txt":"凡是知道案件事实的人，都有出庭作证的义务。有下列情形之一的，经人民法院准许，当事人可以提交书面证言："},{"i":42,"n":"第四十二条","txt":"不能正确表达意志的人不能作证。"},{"i":43,"n":"第四十三条","txt":"当事人申请证人出庭作证的，应当在举证期限届满前提出，并经人民法院许可。人民法院准许证人出庭作证的，应当在开庭审理前通知证人出庭作证。"},{"i":44,"n":"第四十四条","txt":"有下列情形之一，原告或者第三人可以要求相关行政执法人员作为证人出庭作证："},{"i":45,"n":"第四十五条","txt":"证人出庭作证时，应当出示证明其身份的证件。法庭应当告知其诚实作证的法律义务和作伪证的法律责任。"},{"i":46,"n":"第四十六条","txt":"证人应当陈述其亲历的具体事实。证人根据其经历所作的判断、推测或者评论，不能作为定案的依据。"},{"i":47,"n":"第四十七条","txt":"当事人要求鉴定人出庭接受询问的，鉴定人应当出庭。鉴定人因正当事由不能出庭的，经法庭准许，可以不出庭，由当事人对其书面鉴定结论进行质证。"},{"i":48,"n":"第四十八条","txt":"对被诉具体行政行为涉及的专门性问题，当事人可以向法庭申请由专业人员出庭进行说明，法庭也可以通知专业人员出庭说明。必要时，法庭可以组织专业人员进行对质。"},{"i":49,"n":"第四十九条","txt":"法庭在质证过程中，对与案件没有关联的证据材料，应予排除并说明理由。"},{"i":50,"n":"第五十条","txt":"在第二审程序中，对当事人依法提供的新的证据，法庭应当进行质证；当事人对第一审认定的证据仍有争议的，法庭也应当进行质证。"},{"i":51,"n":"第五十一条","txt":"按照审判监督程序审理的案件，对当事人依法提供的新的证据，法庭应当进行质证；因原判决、裁定认定事实的证据不足而提起再审所涉及的主要证据，法庭也应当进行质证。"},{"i":52,"n":"第五十二条","txt":"本规定第五十条和第五十一条中的“新的证据”是指以下证据："},{"i":53,"n":"第五十三条","txt":"人民法院裁判行政案件，应当以证据证明的案件事实为依据。"},{"i":54,"n":"第五十四条","txt":"法庭应当对经过庭审质证的证据和无需质证的证据进行逐一审查和对全部证据综合审查，遵循法官职业道德，运用逻辑推理和生活经验，进行全面、客观和公正地分析判断，确定证据材料与案件事实之间的证明关系，排除不具有关联性的证据材料，准确认定案件事实。"},{"i":55,"n":"第五十五条","txt":"法庭应当根据案件的具体情况，从以下方面审查证据的合法性："},{"i":56,"n":"第五十六条","txt":"法庭应当根据案件的具体情况，从以下方面审查证据的真实性："},{"i":57,"n":"第五十七条","txt":"下列证据材料不能作为定案依据："},{"i":58,"n":"第五十八条","txt":"以违反法律禁止性规定或者侵犯他人合法权益的方法取得的证据，不能作为认定案件事实的依据。"},{"i":59,"n":"第五十九条","txt":"被告在行政程序中依照法定程序要求原告提供证据，原告依法应当提供而拒不提供，在诉讼程序中提供的证据，人民法院一般不予采纳。"},{"i":60,"n":"第六十条","txt":"下列证据不能作为认定被诉具体行政行为合法的依据："},{"i":61,"n":"第六十一条","txt":"复议机关在复议程序中收集和补充的证据，或者作出原具体行政行为的行政机关在复议程序中未向复议机关提交的证据，不能作为人民法院认定原具体行政行为合法的依据。"},{"i":62,"n":"第六十二条","txt":"对被告在行政程序中采纳的鉴定结论，原告或者第三人提出证据证明有下列情形之一的，人民法院不予采纳："},{"i":63,"n":"第六十三条","txt":"证明同一事实的数个证据，其证明效力一般可以按照下列情形分别认定："},{"i":64,"n":"第六十四条","txt":"以有形载体固定或者显示的电子数据交换、电子邮件以及其他数据资料，其制作情况和真实性经对方当事人确认，或者以公证等其他有效方式予以证明的，与原件具有同等的证明效力。"},{"i":65,"n":"第六十五条","txt":"在庭审中一方当事人或者其代理人在代理权限范围内对另一方当事人陈述的案件事实明确表示认可的，人民法院可以对该事实予以认定。但有相反证据足以推翻的除外。"},{"i":66,"n":"第六十六条","txt":"在行政赔偿诉讼中，人民法院主持调解时当事人为达成调解协议而对案件事实的认可，不得在其后的诉讼中作为对其不利的证据。"},{"i":67,"n":"第六十七条","txt":"在不受外力影响的情况下，一方当事人提供的证据，对方当事人明确表示认可的，可以认定该证据的证明效力；对方当事人予以否认，但不能提供充分的证据进行反驳的，可以综合全案情况审查认定该证据的证明效力。"},{"i":68,"n":"第六十八条","txt":"下列事实法庭可以直接认定："},{"i":69,"n":"第六十九条","txt":"原告确有证据证明被告持有的证据对原告有利，被告无正当事由拒不提供的，可以推定原告的主张成立。"},{"i":70,"n":"第七十条","txt":"生效的人民法院裁判文书或者仲裁机构裁决文书确认的事实，可以作为定案依据。但是如果发现裁判文书或者裁决文书认定的事实有重大问题的，应当中止诉讼，通过法定程序予以纠正后恢复诉讼。"},{"i":71,"n":"第七十一条","txt":"下列证据不能单独作为定案依据："},{"i":72,"n":"第七十二条","txt":"庭审中经过质证的证据，能够当庭认定的，应当当庭认定；不能当庭认定的，应当在合议庭合议时认定。"},{"i":73,"n":"第七十三条","txt":"法庭发现当庭认定的证据有误，可以按照下列方式纠正："},{"i":74,"n":"第七十四条","txt":"证人、鉴定人及其近亲属的人身和财产安全受法律保护。"},{"i":75,"n":"第七十五条","txt":"证人、鉴定人因出庭作证或者接受询问而支出的合理费用，由提供证人、鉴定人的一方当事人先行支付，由败诉一方当事人承担。"},{"i":76,"n":"第七十六条","txt":"证人、鉴定人作伪证的，依照行政诉讼法第四十九条第一款第（二）项的规定追究其法律责任。"},{"i":77,"n":"第七十七条","txt":"诉讼参与人或者其他人有对审判人员或者证人、鉴定人、勘验人及其近亲属实施威胁、侮辱、殴打、骚扰或者打击报复等妨碍行政诉讼行为的，依照行政诉讼法第四十九条第一款第（三）项、第（五）项或者第（六）项的规定追究其法律责任。"},{"i":78,"n":"第七十八条","txt":"对应当协助调取证据的单位和个人，无正当理由拒不履行协助义务的，依照行政诉讼法第四十九条第一款第（五）项的规定追究其法律责任。"},{"i":79,"n":"第七十九条","txt":"本院以前有关行政诉讼的司法解释与本规定不一致的，以本规定为准。"},{"i":80,"n":"第八十条","txt":"本规定自2002年10月1日起施行。2002年10月1日尚未审结的一审、二审和再审行政案件不适用本规定。"}],"zuigaorenminfayuanguanyucaipanwenshuyinyongfalvfag6e3306":[{"i":1,"n":"第一条","txt":"人民法院的裁判文书应当依法引用相关法律、法规等规范性法律文件作为裁判依据。引用时应当准确完整写明规范性法律文件的名称、条款序号，需要引用具体条文的，应当整条（款、项）引用。"},{"i":2,"n":"第二条","txt":"并列引用多个规范性法律文件的，引用顺序如下：法律及法律解释、行政法规、地方性法规、自治条例或者单行条例、司法解释。同时引用两部以上法律的，应当先引用基本法律，后引用其他法律。引用包括实体法和程序法的，先引用实体法，后引用程序法。"},{"i":3,"n":"第三条","txt":"刑事裁判文书应当引用法律、法律解释或者司法解释。刑事附带民事诉讼裁判文书引用规范性法律文件，同时适用本规定第四条规定。"},{"i":4,"n":"第四条","txt":"民事裁判文书应当引用法律、法律解释或者司法解释。对于应当适用的行政法规、地方性法规或者自治条例和单行条例，可以直接引用。"},{"i":5,"n":"第五条","txt":"行政裁判文书应当引用法律、法律解释、行政法规或者司法解释。对于应当适用的地方性法规、自治条例和单行条例、国务院或者国务院授权的部门公布的行政法规解释或者行政规章，可以直接引用。"},{"i":6,"n":"第六条","txt":"对于本规定第三条、第四条、第五条规定之外的规范性文件，根据审理案件的需要，经审查认定为合法有效的，可以作为裁判说理的依据。"},{"i":7,"n":"第七条","txt":"人民法院制作裁判文书确需引用的规范性法律文件之间存在冲突，根据立法法等有关法律规定无法选择适用的，应当依法提请有决定权的机关做出裁决，不得自行在裁判文书中认定相关规范性法律文件的效力。"},{"i":8,"n":"第八条","txt":"本院以前发布的司法解释与本规定不一致的，以本规定为准。"}],"zuigaorenminfayuanguanyurenkehezhixingtaiwandiquzha1cae1":[{"i":1,"n":"第一条","txt":"台湾地区仲裁裁决的当事人可以根据本规定，作为申请人向人民法院申请认可和执行台湾地区仲裁裁决。"},{"i":2,"n":"第二条","txt":"本规定所称台湾地区仲裁裁决是指，有关常设仲裁机构及临时仲裁庭在台湾地区按照台湾地区仲裁规定就有关民商事争议作出的仲裁裁决，包括仲裁判断、仲裁和解和仲裁调解。"},{"i":3,"n":"第三条","txt":"申请人同时提出认可和执行台湾地区仲裁裁决申请的，人民法院先按照认可程序进行审查，裁定认可后，由人民法院执行机构执行。"},{"i":4,"n":"第四条","txt":"申请认可台湾地区仲裁裁决的案件，由申请人住所地、经常居住地或者被申请人住所地、经常居住地、财产所在地中级人民法院或者专门人民法院受理。"},{"i":5,"n":"第五条","txt":"对申请认可台湾地区仲裁裁决的案件，人民法院应当组成合议庭进行审查。"},{"i":6,"n":"第六条","txt":"申请人委托他人代理申请认可台湾地区仲裁裁决的，应当向人民法院提交由委托人签名或者盖章的授权委托书。"},{"i":7,"n":"第七条","txt":"申请人申请认可台湾地区仲裁裁决，应当提交以下文件或者经证明无误的副本："},{"i":8,"n":"第八条","txt":"对于符合本规定第四条和第七条规定条件的申请，人民法院应当在收到申请后七日内立案，并通知申请人和被申请人，同时将申请书送达被申请人；不符合本规定第四条和第七条规定条件的，应当在七日内裁定不予受理，同时说明不予受理的理由；申请人对裁定不服的，可以提起上诉。"},{"i":9,"n":"第九条","txt":"申请人申请认可台湾地区仲裁裁决，应当提供相关证明文件，以证明该仲裁裁决的真实性。"},{"i":10,"n":"第十条","txt":"人民法院受理认可台湾地区仲裁裁决的申请之前或者之后，可以按照民事诉讼法及相关司法解释的规定，根据申请人的申请，裁定采取保全措施。"},{"i":11,"n":"第十一条","txt":"人民法院受理认可台湾地区仲裁裁决的申请后，当事人就同一争议起诉的，不予受理。"},{"i":12,"n":"第十二条","txt":"人民法院受理认可台湾地区仲裁裁决的申请后，作出裁定前，申请人请求撤回申请的，可以裁定准许。"},{"i":13,"n":"第十三条","txt":"人民法院应当尽快审查认可台湾地区仲裁裁决的申请，决定予以认可的，应当在立案之日起两个月内作出裁定；决定不予认可或者驳回申请的，应当在作出决定前按有关规定自立案之日起两个月内上报最高人民法院。"},{"i":14,"n":"第十四条","txt":"对申请认可和执行的仲裁裁决，被申请人提出证据证明有下列情形之一的，经审查核实，人民法院裁定不予认可："},{"i":15,"n":"第十五条","txt":"人民法院经审查能够确认台湾地区仲裁裁决真实，而且不具有本规定第十四条所列情形的，裁定认可其效力；不能确认该仲裁裁决真实性的，裁定驳回申请。"},{"i":16,"n":"第十六条","txt":"人民法院依据本规定第十四条和第十五条作出的裁定，一经送达即发生法律效力。"},{"i":17,"n":"第十七条","txt":"一方当事人向人民法院申请认可或者执行台湾地区仲裁裁决，另一方当事人向台湾地区法院起诉撤销该仲裁裁决，被申请人申请中止认可或者执行并且提供充分担保的，人民法院应当中止认可或者执行程序。"},{"i":18,"n":"第十八条","txt":"对人民法院裁定不予认可的台湾地区仲裁裁决，申请人再次提出申请的，人民法院不予受理。但当事人可以根据双方重新达成的仲裁协议申请仲裁，也可以就同一争议向人民法院起诉。"},{"i":19,"n":"第十九条","txt":"申请人申请认可和执行台湾地区仲裁裁决的期间，适用民事诉讼法第二百三十九条的规定。"},{"i":20,"n":"第二十条","txt":"人民法院在办理申请认可和执行台湾地区仲裁裁决案件中所作出的法律文书，应当依法送达案件当事人。"},{"i":21,"n":"第二十一条","txt":"申请认可和执行台湾地区仲裁裁决，应当参照《诉讼费用交纳办法》的规定，交纳相关费用。"},{"i":22,"n":"第二十二条","txt":"本规定自2015年7月1日起施行。"}],"zuigaorenminfayuanguanyurenkehezhixingtaiwandiqufa12697c":[{"i":1,"n":"第一条","txt":"台湾地区法院民事判决的当事人以及当事人的继承人、权利承受人可以根据本规定，作为申请人向人民法院申请认可和执行该判决，该判决中的对方当事人为被申请人。双方当事人都提出认可和执行申请的，均列为申请人。"},{"i":2,"n":"第二条","txt":"本规定所称台湾地区法院民事判决，包括台湾地区法院作出的生效民事判决、裁定、和解笔录、调解笔录、支付命令等。"},{"i":3,"n":"第三条","txt":"申请人同时提出认可和执行台湾地区法院民事判决申请的，人民法院先按照认可程序进行审查，裁定认可后，由人民法院执行机构执行。"},{"i":4,"n":"第四条","txt":"申请认可台湾地区法院民事判决的案件，由申请人住所地、经常居住地或者被申请人住所地、经常居住地、财产所在地中级人民法院或者专门人民法院受理。"},{"i":5,"n":"第五条","txt":"申请人委托他人代理申请认可台湾地区法院民事判决的，应当向人民法院提交由委托人签名或者盖章的授权委托书。"},{"i":6,"n":"第六条","txt":"申请认可台湾地区法院民事判决，应当提交下列材料："},{"i":7,"n":"第七条","txt":"申请书应当载明下列事项："},{"i":8,"n":"第八条","txt":"对于符合本规定第四条至第七条规定条件的申请，人民法院应当在收到申请后七日内立案，并通知申请人和被申请人。对于不符合上述规定的申请，人民法院应当在七日内裁定不予受理，同时说明不予受理的理由。已经受理的，裁定驳回申请。申请人对裁定不服的，可以提起上诉。"},{"i":9,"n":"第九条","txt":"人民法院应当在立案之日起五日内将申请书副本送达被申请人。被申请人应当在收到申请书副本之日起十五日内提交意见；被申请人在中国大陆没有住所的，应当在收到申请书副本之日起三十日内提交意见。被申请人在上述期限内不提交意见的，不影响人民法院审查。被申请人申请延期的，是否准许，由人民法院决定。"},{"i":10,"n":"第十条","txt":"对申请认可台湾地区法院民事判决的案件，人民法院应当组成合议庭进行审查。"},{"i":11,"n":"第十一条","txt":"申请人申请认可台湾地区法院民事判决，应当提供相关证明文件，以证明该判决真实并且已经生效。台湾地区法院民事判决为缺席判决的，申请人应当同时提交台湾地区法院已经合法传唤当事人的证明文件，但判决已经对此予以明确说明的除外。"},{"i":12,"n":"第十二条","txt":"申请人提供的台湾地区法院民事判决以及相关证明文件等证据，系通过海峡两岸公证书使用查证渠道转递的，人民法院应当确认其真实性，但有相反证据足以推翻的除外。"},{"i":13,"n":"第十三条","txt":"人民法院受理认可台湾地区法院民事判决的申请之前或者之后，可以依据民事诉讼法及相关司法解释的规定，根据申请人的申请，裁定采取保全措施。"},{"i":14,"n":"第十四条","txt":"人民法院受理认可台湾地区法院民事判决的申请后，作出裁定前，申请人请求撤回申请的，可以裁定准许。"},{"i":15,"n":"第十五条","txt":"人民法院受理认可台湾地区法院民事判决的申请后，应当在立案之日起六个月内审结。有特殊情况需要延长的，报请上一级人民法院批准。"},{"i":16,"n":"第十六条","txt":"台湾地区法院民事判决具有下列情形之一的，裁定不予认可："},{"i":17,"n":"第十七条","txt":"人民法院经审查能够确认台湾地区法院民事判决真实并且已经生效，而且不具有本规定第十六条所列情形的，裁定认可其效力。不能认可判决全部判项的，可以认可其中的部分判项。不能确认该民事判决的真实性或者已经生效的，裁定驳回申请人的申请。"},{"i":18,"n":"第十八条","txt":"经人民法院裁定认可的台湾地区法院民事判决，与人民法院作出的生效判决具有同等效力。"},{"i":19,"n":"第十九条","txt":"人民法院依据本规定第十六条、第十七条作出的裁定，一经送达即发生法律效力。"},{"i":20,"n":"第二十条","txt":"申请人向人民法院申请认可台湾地区法院民事判决，该判决涉及的纠纷与人民法院正在审理的纠纷属于同一纠纷的，人民法院可以裁定中止诉讼。"},{"i":21,"n":"第二十一条","txt":"审查认可台湾地区法院民事判决申请期间，申请人或者被申请人就同一纠纷向人民法院起诉的，裁定不予受理；已经受理的，裁定中止诉讼。"},{"i":22,"n":"第二十二条","txt":"台湾地区法院民事判决已经被人民法院裁定全部或者部分认可，申请人或者被申请人对已经获得认可的部分又向人民法院起诉的，裁定不予受理；已经受理的，裁定驳回起诉。"},{"i":23,"n":"第二十三条","txt":"台湾地区法院民事判决被人民法院裁定全部或者部分认可后，申请人对认可部分申请执行的，依据民事诉讼法关于执行程序的规定予以执行。"},{"i":24,"n":"第二十四条","txt":"申请人申请认可和执行台湾地区法院民事判决的期间，适用民事诉讼法第二百五十条的规定，但申请认可台湾地区法院有关身份关系的判决除外。"},{"i":25,"n":"第二十五条","txt":"人民法院在办理申请认可和执行台湾地区法院民事判决案件中作出的法律文书，应当依法送达申请人和被申请人。"},{"i":26,"n":"第二十六条","txt":"申请认可和执行台湾地区法院民事判决，应当参照《诉讼费用交纳办法》的规定，交纳相关费用。"},{"i":27,"n":"第二十七条","txt":"本规定自2015年7月1日起施行。《最高人民法院关于人民法院认可台湾地区有关法院民事判决的规定》（法释〔1998〕11号）、《最高人民法院关于当事人持台湾地区有关法院民事调解书或者有关机构出具或确认的调解协议书向人民法院申请认可人民法院应否受理的批复》（法释〔1999〕10号）、《最高人民法院关于当事人持台湾地区有关法院支付命令向人民法院申请认可人民法院应否受理的批复》（法释〔2001〕13号）和《最高人民法院关于人民法院认可台湾地区有关法院民事判决的补充规定》（法释〔2009〕4号）同时废止。"}],"zuigaorenminfayuanguanyusheliguojishangshifatingru1674d6":[{"i":1,"n":"第一条","txt":"最高人民法院设立国际商事法庭。国际商事法庭是最高人民法院的常设审判机构。"},{"i":2,"n":"第二条","txt":"国际商事法庭受理下列案件："},{"i":3,"n":"第三条","txt":"具有下列情形之一的商事案件，可以认定为本规定所称的国际商事案件："},{"i":4,"n":"第四条","txt":"国际商事法庭法官由最高人民法院在具有丰富审判工作经验，熟悉国际条约、国际惯例以及国际贸易投资实务，能够同时熟练运用中文和英文作为工作语言的资深法官中选任。"},{"i":5,"n":"第五条","txt":"国际商事法庭审理案件，由三名或者三名以上法官组成合议庭。"},{"i":6,"n":"第六条","txt":"国际商事法庭作出的保全裁定，可以指定下级人民法院执行。"},{"i":7,"n":"第七条","txt":"国际商事法庭审理案件，依照《中华人民共和国涉外民事关系法律适用法》的规定确定争议适用的实体法律。"},{"i":8,"n":"第八条","txt":"国际商事法庭审理案件应当适用域外法律时，可以通过下列途径查明："},{"i":9,"n":"第九条","txt":"当事人向国际商事法庭提交的证据材料系在中华人民共和国领域外形成的，不论是否已办理公证、认证或者其他证明手续，均应当在法庭上质证。"},{"i":10,"n":"第十条","txt":"国际商事法庭调查收集证据以及组织质证，可以采用视听传输技术及其他信息网络方式。"},{"i":11,"n":"第十一条","txt":"最高人民法院组建国际商事专家委员会，并选定符合条件的国际商事调解机构、国际商事仲裁机构与国际商事法庭共同构建调解、仲裁、诉讼有机衔接的纠纷解决平台，形成“一站式”国际商事纠纷解决机制。"},{"i":12,"n":"第十二条","txt":"国际商事法庭在受理案件后七日内，经当事人同意，可以委托国际商事专家委员会成员或者国际商事调解机构调解。"},{"i":13,"n":"第十三条","txt":"经国际商事专家委员会成员或者国际商事调解机构主持调解，当事人达成调解协议的，国际商事法庭可以依照法律规定制发调解书；当事人要求发给判决书的，可以依协议的内容制作判决书送达当事人。"},{"i":14,"n":"第十四条","txt":"当事人协议选择本规定第十一条第一款规定的国际商事仲裁机构仲裁的，可以在申请仲裁前或者仲裁程序开始后，向国际商事法庭申请证据、财产或者行为保全。"},{"i":15,"n":"第十五条","txt":"国际商事法庭作出的判决、裁定，是发生法律效力的判决、裁定。"},{"i":16,"n":"第十六条","txt":"当事人对国际商事法庭作出的已经发生法律效力的判决、裁定和调解书，可以依照民事诉讼法的规定向最高人民法院本部申请再审。"},{"i":17,"n":"第十七条","txt":"国际商事法庭作出的发生法律效力的判决、裁定和调解书，当事人可以向国际商事法庭申请执行。"},{"i":18,"n":"第十八条","txt":"国际商事法庭通过电子诉讼服务平台、审判流程信息公开平台以及其他诉讼服务平台为诉讼参与人提供诉讼便利，并支持通过网络方式立案、缴费、阅卷、证据交换、送达、开庭等。"},{"i":19,"n":"第十九条","txt":"本规定自2018年7月1日起施行。"}],"zuigaorenminfayuanguanyuzhengquanjiufendaibiaorens205f7d":[{"i":1,"n":"第一条","txt":"本规定所指证券纠纷代表人诉讼包括因证券市场虚假陈述、内幕交易、操纵市场等行为引发的普通代表人诉讼和特别代表人诉讼。"},{"i":2,"n":"第二条","txt":"证券纠纷代表人诉讼案件，由省、自治区、直辖市人民政府所在的市、计划单列市和经济特区中级人民法院或者专门人民法院管辖。"},{"i":3,"n":"第三条","txt":"人民法院应当充分发挥多元解纷机制的功能，按照自愿、合法原则，引导和鼓励当事人通过行政调解、行业调解、专业调解等非诉讼方式解决证券纠纷。"},{"i":4,"n":"第四条","txt":"人民法院审理证券纠纷代表人诉讼案件，应当依托信息化技术手段开展立案登记、诉讼文书送达、公告和通知、权利登记、执行款项发放等工作，便利当事人行使诉讼权利、履行诉讼义务，提高审判执行的公正性、高效性和透明度。"},{"i":5,"n":"第五条","txt":"符合以下条件的，人民法院应当适用普通代表人诉讼程序进行审理："},{"i":6,"n":"第六条","txt":"对起诉时当事人人数尚未确定的代表人诉讼，在发出权利登记公告前，人民法院可以通过阅卷、调查、询问和听证等方式对被诉证券侵权行为的性质、侵权事实等进行审查，并在受理后三十日内以裁定的方式确定具有相同诉讼请求的权利人范围。"},{"i":7,"n":"第七条","txt":"人民法院应当在权利人范围确定后五日内发出权利登记公告，通知相关权利人在指定期间登记。权利登记公告应当包括以下内容："},{"i":8,"n":"第八条","txt":"权利人应在公告确定的登记期间向人民法院登记。未按期登记的，可在一审开庭前向人民法院申请补充登记，补充登记前已经完成的诉讼程序对其发生效力。"},{"i":9,"n":"第九条","txt":"人民法院在登记期间届满后十日内对登记的权利人进行审核。不符合权利人范围的投资者，人民法院不确认其原告资格。"},{"i":10,"n":"第十条","txt":"权利登记公告前已就同一证券违法事实提起诉讼且符合权利人范围的投资者，申请撤诉并加入代表人诉讼的，人民法院应当予以准许。"},{"i":11,"n":"第十一条","txt":"人民法院应当将审核通过的权利人列入代表人诉讼原告名单，并通知全体原告。"},{"i":12,"n":"第十二条","txt":"代表人应当符合以下条件："},{"i":13,"n":"第十三条","txt":"在起诉时当事人人数确定的代表人诉讼，应当在起诉前确定获得特别授权的代表人，并在起诉书中就代表人的推选情况作出专项说明。"},{"i":14,"n":"第十四条","txt":"在登记期间向人民法院登记的权利人对拟任代表人的人选提出异议，或者申请担任代表人的，人民法院应当自原告范围审核完毕后十日内在自愿担任代表人的原告中组织推选。"},{"i":15,"n":"第十五条","txt":"依据前条规定推选不出代表人的，由人民法院指定。"},{"i":16,"n":"第十六条","txt":"代表人确定后，人民法院应当进行公告。"},{"i":17,"n":"第十七条","txt":"代表人因丧失诉讼行为能力或者其他事由影响案件审理或者可能损害原告利益的，人民法院依原告申请，可以决定撤销代表人资格。代表人不足二人时，人民法院应当补充指定代表人。"},{"i":18,"n":"第十八条","txt":"代表人与被告达成调解协议草案的，应当向人民法院提交制作调解书的申请书及调解协议草案。申请书应当包括以下内容："},{"i":19,"n":"第十九条","txt":"人民法院经初步审查，认为调解协议草案不存在违反法律、行政法规的强制性规定、违背公序良俗以及损害他人合法权益等情形的，应当自收到申请书后十日内向全体原告发出通知。通知应当包括以下内容："},{"i":20,"n":"第二十条","txt":"对调解协议草案有异议的原告，有权出席听证会或者以书面方式向人民法院提交异议的具体内容及理由。异议人未出席听证会的，人民法院应当在听证会上公开其异议的内容及理由，代表人及其委托诉讼代理人、被告应当进行解释。"},{"i":21,"n":"第二十一条","txt":"人民法院应当综合考虑当事人赞成和反对意见、本案所涉法律和事实情况、调解协议草案的合法性、适当性和可行性等因素，决定是否制作调解书。"},{"i":22,"n":"第二十二条","txt":"代表人变更或者放弃诉讼请求、承认对方当事人诉讼请求、决定撤诉的，应当向人民法院提交书面申请，并通知全体原告。人民法院收到申请后，应当根据原告所提异议情况，依法裁定是否准许。"},{"i":23,"n":"第二十三条","txt":"除代表人诉讼案件外，人民法院还受理其他基于同一证券违法事实发生的非代表人诉讼案件的，原则上代表人诉讼案件先行审理，非代表人诉讼案件中止审理。但非代表人诉讼案件具有典型性且先行审理有利于及时解决纠纷的除外。"},{"i":24,"n":"第二十四条","txt":"人民法院可以依当事人的申请，委托双方认可或者随机抽取的专业机构对投资损失数额、证券侵权行为以外其他风险因素导致的损失扣除比例等进行核定。当事人虽未申请但案件审理确有需要的，人民法院可以通过随机抽取的方式委托专业机构对有关事项进行核定。"},{"i":25,"n":"第二十五条","txt":"代表人请求败诉的被告赔偿合理的公告费、通知费、律师费等费用的，人民法院应当予以支持。"},{"i":26,"n":"第二十六条","txt":"判决被告承担民事赔偿责任的，可以在判决主文中确定赔偿总额和损害赔偿计算方法，并将每个原告的姓名、应获赔偿金额等以列表方式作为民事判决书的附件。"},{"i":27,"n":"第二十七条","txt":"一审判决送达后，代表人决定放弃上诉的，应当在上诉期间届满前通知全体原告。"},{"i":28,"n":"第二十八条","txt":"一审判决送达后，代表人决定上诉的，应当在上诉期间届满前通知全体原告。"},{"i":29,"n":"第二十九条","txt":"符合权利人范围但未参加登记的投资者提起诉讼，且主张的事实和理由与代表人诉讼生效判决、裁定所认定的案件基本事实和法律适用相同的，人民法院审查具体诉讼请求后，裁定适用已经生效的判决、裁定。适用已经生效裁判的裁定中应当明确被告赔偿的金额，裁定一经作出立即生效。"},{"i":30,"n":"第三十条","txt":"履行或者执行生效法律文书所得财产，人民法院在进行分配时，可以通知证券登记结算机构等协助执行义务人依法协助执行。"},{"i":31,"n":"第三十一条","txt":"原告对分配方案有异议的，可以依据民事诉讼法第二百二十五条的规定提出执行异议。"},{"i":32,"n":"第三十二条","txt":"人民法院已经根据民事诉讼法第五十四条第一款、证券法第九十五条第二款的规定发布权利登记公告的，投资者保护机构在公告期间受五十名以上权利人的特别授权，可以作为代表人参加诉讼。先受理的人民法院不具有特别代表人诉讼管辖权的，应当将案件及时移送有管辖权的人民法院。"},{"i":33,"n":"第三十三条","txt":"权利人范围确定后，人民法院应当发出权利登记公告。权利登记公告除本规定第七条的内容外，还应当包括投资者保护机构基本情况、对投资者保护机构的特别授权、投资者声明退出的权利及期间、未声明退出的法律后果等。"},{"i":34,"n":"第三十四条","txt":"投资者明确表示不愿意参加诉讼的，应当在公告期间届满后十五日内向人民法院声明退出。未声明退出的，视为同意参加该代表人诉讼。"},{"i":35,"n":"第三十五条","txt":"投资者保护机构依据公告确定的权利人范围向证券登记结算机构调取的权利人名单，人民法院应当予以登记，列入代表人诉讼原告名单，并通知全体原告。"},{"i":36,"n":"第三十六条","txt":"诉讼过程中由于声明退出等原因导致明示授权投资者的数量不足五十名的，不影响投资者保护机构的代表人资格。"},{"i":37,"n":"第三十七条","txt":"针对同一代表人诉讼，原则上应当由一个投资者保护机构作为代表人参加诉讼。两个以上的投资者保护机构分别受五十名以上投资者委托，且均决定作为代表人参加诉讼的，应当协商处理；协商不成的，由人民法院指定其中一个作为代表人参加诉讼。"},{"i":38,"n":"第三十八条","txt":"投资者保护机构应当采取必要措施，保障被代表的投资者持续了解案件审理的进展情况，回应投资者的诉求。对投资者提出的意见和建议不予采纳的，应当对投资者做好解释工作。"},{"i":39,"n":"第三十九条","txt":"特别代表人诉讼案件不预交案件受理费。败诉或者部分败诉的原告申请减交或者免交诉讼费的，人民法院应当依照《诉讼费用交纳办法》的规定，视原告的经济状况和案件的审理情况决定是否准许。"},{"i":40,"n":"第四十条","txt":"投资者保护机构作为代表人在诉讼中申请财产保全的，人民法院可以不要求提供担保。"},{"i":41,"n":"第四十一条","txt":"人民法院审理特别代表人诉讼案件，本部分没有规定的，适用普通代表人诉讼中关于起诉时当事人人数尚未确定的代表人诉讼的相关规定。"},{"i":42,"n":"第四十二条","txt":"本规定自2020年7月31日起施行。"}],"zuigaorenminfayuanguanyususongdailirenchayueminshib22968":[{"i":1,"n":"第一条","txt":"代理民事诉讼的律师和其他诉讼代理人有权查阅所代理案件的有关材料。但是，诉讼代理人查阅案件材料不得影响案件的审理。"},{"i":2,"n":"第二条","txt":"人民法院应当为诉讼代理人阅卷提供便利条件，安排阅卷场所。必要时，该案件的书记员或者法院其他工作人员应当在场。"},{"i":3,"n":"第三条","txt":"诉讼代理人在诉讼过程中需要查阅案件有关材料的，应当提前与该案件的书记员或者审判人员联系；查阅已经审理终结的案件有关材料的，应当与人民法院有关部门工作人员联系。"},{"i":4,"n":"第四条","txt":"诉讼代理人查阅案件有关材料应当出示律师证或者身份证等有效证件。查阅案件有关材料应当填写查阅案件有关材料阅卷单。"},{"i":5,"n":"第五条","txt":"诉讼代理人在诉讼中查阅案件材料限于案件审判卷和执行卷的正卷，包括起诉书、答辩书、庭审笔录及各种证据材料等。"},{"i":6,"n":"第六条","txt":"诉讼代理人查阅案件有关材料后，应当及时将查阅的全部案件材料交回书记员或者其他负责保管案卷的工作人员。"},{"i":7,"n":"第七条","txt":"诉讼代理人查阅案件材料可以摘抄或者复印。涉及国家秘密的案件材料，依照国家有关规定办理。"},{"i":8,"n":"第八条","txt":"查阅案件材料中涉及国家秘密、商业秘密和个人隐私的，诉讼代理人应当保密。"},{"i":9,"n":"第九条","txt":"诉讼代理人查阅案件材料时不得涂改、损毁、抽取案件材料。"},{"i":10,"n":"第十条","txt":"民事案件的当事人查阅案件有关材料的，参照本规定执行。"},{"i":11,"n":"第十一条","txt":"本规定自公布之日起施行。"}],"zuigaorenminfayuanguanyujinyibujiaqiangheyitingzhi5ffdb6":[{"i":1,"n":"第一条","txt":"合议庭是人民法院的基本审判组织。合议庭全体成员平等参与案件的审理、评议和裁判，依法履行审判职责。"},{"i":2,"n":"第二条","txt":"合议庭由审判员、助理审判员或者人民陪审员随机组成。合议庭成员相对固定的，应当定期交流。人民陪审员参加合议庭的，应当从人民陪审员名单中随机抽取确定。"},{"i":3,"n":"第三条","txt":"承办法官履行下列职责："},{"i":4,"n":"第四条","txt":"依法不开庭审理的案件，合议庭全体成员均应当阅卷，必要时提交书面阅卷意见。"},{"i":5,"n":"第五条","txt":"开庭审理时，合议庭全体成员应当共同参加，不得缺席、中途退庭或者从事与该庭审无关的活动。合议庭成员未参加庭审、中途退庭或者从事与该庭审无关的活动，当事人提出异议的，应当纠正。合议庭仍不纠正的，当事人可以要求休庭，并将有关情况记入庭审笔录。"},{"i":6,"n":"第六条","txt":"合议庭全体成员均应当参加案件评议。评议案件时，合议庭成员应当针对案件的证据采信、事实认定、法律适用、裁判结果以及诉讼程序等问题充分发表意见。必要时，合议庭成员还可提交书面评议意见。"},{"i":7,"n":"第七条","txt":"除提交审判委员会讨论的案件外，合议庭对评议意见一致或者形成多数意见的案件，依法作出判决或者裁定。下列案件可以由审判长提请院长或者庭长决定组织相关审判人员共同讨论，合议庭成员应当参加："},{"i":8,"n":"第八条","txt":"各级人民法院的院长、副院长、庭长、副庭长应当参加合议庭审理案件，并逐步增加审理案件的数量。"},{"i":9,"n":"第九条","txt":"各级人民法院应当建立合议制落实情况的考评机制，并将考评结果纳入岗位绩效考评体系。考评可采取抽查卷宗、案件评查、检查庭审情况、回访当事人等方式。考评包括以下内容："},{"i":10,"n":"第十条","txt":"合议庭组成人员存在违法审判行为的，应当按照《人民法院审判人员违法审判责任追究办法（试行）》等规定追究相应责任。合议庭审理案件有下列情形之一的，合议庭成员不承担责任："},{"i":11,"n":"第十一条","txt":"执行工作中依法需要组成合议庭的，参照本规定执行。"},{"i":12,"n":"第十二条","txt":"本院以前发布的司法解释与本规定不一致的，以本规定为准。"}],"zuigaorenminfayuanguanyushiyongqiyepochanfaruoganw28c3a8":[{"i":1,"n":"第一条","txt":"债务人不能清偿到期债务并且具有下列情形之一的，人民法院应当认定其具备破产原因："},{"i":2,"n":"第二条","txt":"下列情形同时存在的，人民法院应当认定债务人不能清偿到期债务："},{"i":3,"n":"第三条","txt":"债务人的资产负债表，或者审计报告、资产评估报告等显示其全部资产不足以偿付全部负债的，人民法院应当认定债务人资产不足以清偿全部债务，但有相反证据足以证明债务人资产能够偿付全部负债的除外。"},{"i":4,"n":"第四条","txt":"债务人账面资产虽大于负债，但存在下列情形之一的，人民法院应当认定其明显缺乏清偿能力："},{"i":5,"n":"第五条","txt":"企业法人已解散但未清算或者未在合理期限内清算完毕，债权人申请债务人破产清算的，除债务人在法定异议期限内举证证明其未出现破产原因外，人民法院应当受理。"},{"i":6,"n":"第六条","txt":"债权人申请债务人破产的，应当提交债务人不能清偿到期债务的有关证据。债务人对债权人的申请未在法定期限内向人民法院提出异议，或者异议不成立的，人民法院应当依法裁定受理破产申请。"},{"i":7,"n":"第七条","txt":"人民法院收到破产申请时，应当向申请人出具收到申请及所附证据的书面凭证。"},{"i":8,"n":"第八条","txt":"破产案件的诉讼费用，应根据企业破产法第四十三条的规定，从债务人财产中拨付。相关当事人以申请人未预先交纳诉讼费用为由，对破产申请提出异议的，人民法院不予支持。"},{"i":9,"n":"第九条","txt":"申请人向人民法院提出破产申请，人民法院未接收其申请，或者未按本规定第七条执行的，申请人可以向上一级人民法院提出破产申请。"}],"zuigaorenminfayuanguanyushiyongqiyepochanfaruoganw077a3f":[{"i":1,"n":"第一条","txt":"人民法院裁定受理破产申请的，此前债务人尚未支付的公司强制清算费用、未终结的执行程序中产生的评估费、公告费、保管费等执行费用，可以参照企业破产法关于破产费用的规定，由债务人财产随时清偿。"},{"i":2,"n":"第二条","txt":"破产申请受理后，经债权人会议决议通过，或者第一次债权人会议召开前经人民法院许可，管理人或者自行管理的债务人可以为债务人继续营业而借款。提供借款的债权人主张参照企业破产法第四十二条第四项的规定优先于普通破产债权清偿的，人民法院应予支持，但其主张优先于此前已就债务人特定财产享有担保的债权清偿的，人民法院不予支持。"},{"i":3,"n":"第三条","txt":"破产申请受理后，债务人欠缴款项产生的滞纳金，包括债务人未履行生效法律文书应当加倍支付的迟延利息和劳动保险金的滞纳金，债权人作为破产债权申报的，人民法院不予确认。"},{"i":4,"n":"第四条","txt":"保证人被裁定进入破产程序的，债权人有权申报其对保证人的保证债权。"},{"i":5,"n":"第五条","txt":"债务人、保证人均被裁定进入破产程序的，债权人有权向债务人、保证人分别申报债权。"},{"i":6,"n":"第六条","txt":"管理人应当依照企业破产法第五十七条的规定对所申报的债权进行登记造册，详尽记载申报人的姓名、单位、代理人、申报债权额、担保情况、证据、联系方式等事项，形成债权申报登记册。"},{"i":7,"n":"第七条","txt":"已经生效法律文书确定的债权，管理人应当予以确认。"},{"i":8,"n":"第八条","txt":"债务人、债权人对债权表记载的债权有异议的，应当说明理由和法律依据。经管理人解释或调整后，异议人仍然不服的，或者管理人不予解释或调整的，异议人应当在债权人会议核查结束后十五日内向人民法院提起债权确认的诉讼。当事人之间在破产申请受理前订立有仲裁条款或仲裁协议的，应当向选定的仲裁机构申请确认债权债务关系。"},{"i":9,"n":"第九条","txt":"债务人对债权表记载的债权有异议向人民法院提起诉讼的，应将被异议债权人列为被告。债权人对债权表记载的他人债权有异议的，应将被异议债权人列为被告；债权人对债权表记载的本人债权有异议的，应将债务人列为被告。"},{"i":10,"n":"第十条","txt":"单个债权人有权查阅债务人财产状况报告、债权人会议决议、债权人委员会决议、管理人监督报告等参与破产程序所必需的债务人财务和经营信息资料。管理人无正当理由不予提供的，债权人可以请求人民法院作出决定；人民法院应当在五日内作出决定。"},{"i":11,"n":"第十一条","txt":"债权人会议的决议除现场表决外，可以由管理人事先将相关决议事项告知债权人，采取通信、网络投票等非现场方式进行表决。采取非现场方式进行表决的，管理人应当在债权人会议召开后的三日内，以信函、电子邮件、公告等方式将表决结果告知参与表决的债权人。"},{"i":12,"n":"第十二条","txt":"债权人会议的决议具有以下情形之一，损害债权人利益，债权人申请撤销的，人民法院应予支持："},{"i":13,"n":"第十三条","txt":"债权人会议可以依照企业破产法第六十八条第一款第四项的规定，委托债权人委员会行使企业破产法第六十一条第一款第二、三、五项规定的债权人会议职权。债权人会议不得作出概括性授权，委托其行使债权人会议所有职权。"},{"i":14,"n":"第十四条","txt":"债权人委员会决定所议事项应获得全体成员过半数通过，并作成议事记录。债权人委员会成员对所议事项的决议有不同意见的，应当在记录中载明。"},{"i":15,"n":"第十五条","txt":"管理人处分企业破产法第六十九条规定的债务人重大财产的，应当事先制作财产管理或者变价方案并提交债权人会议进行表决，债权人会议表决未通过的，管理人不得处分。"},{"i":16,"n":"第十六条","txt":"本规定自2019年3月28日起实施。"}],"zuigaorenminfayuanguanyushiyongqiyepochanfaruoganwfb13bc":[{"i":1,"n":"第一条","txt":"除债务人所有的货币、实物外，债务人依法享有的可以用货币估价并可以依法转让的债权、股权、知识产权、用益物权等财产和财产权益，人民法院均应认定为债务人财产。"},{"i":2,"n":"第二条","txt":"下列财产不应认定为债务人财产："},{"i":3,"n":"第三条","txt":"债务人已依法设定担保物权的特定财产，人民法院应当认定为债务人财产。"},{"i":4,"n":"第四条","txt":"债务人对按份享有所有权的共有财产的相关份额，或者共同享有所有权的共有财产的相应财产权利，以及依法分割共有财产所得部分，人民法院均应认定为债务人财产。"},{"i":5,"n":"第五条","txt":"破产申请受理后，有关债务人财产的执行程序未依照企业破产法第十九条的规定中止的，采取执行措施的相关单位应当依法予以纠正。依法执行回转的财产，人民法院应当认定为债务人财产。"},{"i":6,"n":"第六条","txt":"破产申请受理后，对于可能因有关利益相关人的行为或者其他原因，影响破产程序依法进行的，受理破产申请的人民法院可以根据管理人的申请或者依职权，对债务人的全部或者部分财产采取保全措施。"},{"i":7,"n":"第七条","txt":"对债务人财产已采取保全措施的相关单位，在知悉人民法院已裁定受理有关债务人的破产申请后，应当依照企业破产法第十九条的规定及时解除对债务人财产的保全措施。"},{"i":8,"n":"第八条","txt":"人民法院受理破产申请后至破产宣告前裁定驳回破产申请，或者依据企业破产法第一百零八条的规定裁定终结破产程序的，应当及时通知原已采取保全措施并已依法解除保全措施的单位按照原保全顺位恢复相关保全措施。"},{"i":9,"n":"第九条","txt":"管理人依据企业破产法第三十一条和第三十二条的规定提起诉讼，请求撤销涉及债务人财产的相关行为并由相对人返还债务人财产的，人民法院应予支持。"},{"i":10,"n":"第十条","txt":"债务人经过行政清理程序转入破产程序的，企业破产法第三十一条和第三十二条规定的可撤销行为的起算点，为行政监管机构作出撤销决定之日。"},{"i":11,"n":"第十一条","txt":"人民法院根据管理人的请求撤销涉及债务人财产的以明显不合理价格进行的交易的，买卖双方应当依法返还从对方获取的财产或者价款。"},{"i":12,"n":"第十二条","txt":"破产申请受理前一年内债务人提前清偿的未到期债务，在破产申请受理前已经到期，管理人请求撤销该清偿行为的，人民法院不予支持。但是，该清偿行为发生在破产申请受理前六个月内且债务人有企业破产法第二条第一款规定情形的除外。"},{"i":13,"n":"第十三条","txt":"破产申请受理后，管理人未依据企业破产法第三十一条的规定请求撤销债务人无偿转让财产、以明显不合理价格交易、放弃债权行为的，债权人依据民法典第五百三十八条、第五百三十九条等规定提起诉讼，请求撤销债务人上述行为并将因此追回的财产归入债务人财产的，人民法院应予受理。"},{"i":14,"n":"第十四条","txt":"债务人对以自有财产设定担保物权的债权进行的个别清偿，管理人依据企业破产法第三十二条的规定请求撤销的，人民法院不予支持。但是，债务清偿时担保财产的价值低于债权额的除外。"},{"i":15,"n":"第十五条","txt":"债务人经诉讼、仲裁、执行程序对债权人进行的个别清偿，管理人依据企业破产法第三十二条的规定请求撤销的，人民法院不予支持。但是，债务人与债权人恶意串通损害其他债权人利益的除外。"},{"i":16,"n":"第十六条","txt":"债务人对债权人进行的以下个别清偿，管理人依据企业破产法第三十二条的规定请求撤销的，人民法院不予支持："},{"i":17,"n":"第十七条","txt":"管理人依据企业破产法第三十三条的规定提起诉讼，主张被隐匿、转移财产的实际占有人返还债务人财产，或者主张债务人虚构债务或者承认不真实债务的行为无效并返还债务人财产的，人民法院应予支持。"},{"i":18,"n":"第十八条","txt":"管理人代表债务人依据企业破产法第一百二十八条的规定，以债务人的法定代表人和其他直接责任人员对所涉债务人财产的相关行为存在故意或者重大过失，造成债务人财产损失为由提起诉讼，主张上述责任人员承担相应赔偿责任的，人民法院应予支持。"},{"i":19,"n":"第十九条","txt":"债务人对外享有债权的诉讼时效，自人民法院受理破产申请之日起中断。"},{"i":20,"n":"第二十条","txt":"管理人代表债务人提起诉讼，主张出资人向债务人依法缴付未履行的出资或者返还抽逃的出资本息，出资人以认缴出资尚未届至公司章程规定的缴纳期限或者违反出资义务已经超过诉讼时效为由抗辩的，人民法院不予支持。"},{"i":21,"n":"第二十一条","txt":"破产申请受理前，债权人就债务人财产提起下列诉讼，破产申请受理时案件尚未审结的，人民法院应当中止审理："},{"i":22,"n":"第二十二条","txt":"破产申请受理前，债权人就债务人财产向人民法院提起本规定第二十一条第一款所列诉讼，人民法院已经作出生效民事判决书或者调解书但尚未执行完毕的，破产申请受理后，相关执行行为应当依据企业破产法第十九条的规定中止，债权人应当依法向管理人申报相关债权。"},{"i":23,"n":"第二十三条","txt":"破产申请受理后，债权人就债务人财产向人民法院提起本规定第二十一条第一款所列诉讼的，人民法院不予受理。"},{"i":24,"n":"第二十四条","txt":"债务人有企业破产法第二条第一款规定的情形时，债务人的董事、监事和高级管理人员利用职权获取的以下收入，人民法院应当认定为企业破产法第三十六条规定的非正常收入："},{"i":25,"n":"第二十五条","txt":"管理人拟通过清偿债务或者提供担保取回质物、留置物，或者与质权人、留置权人协议以质物、留置物折价清偿债务等方式，进行对债权人利益有重大影响的财产处分行为的，应当及时报告债权人委员会。未设立债权人委员会的，管理人应当及时报告人民法院。"},{"i":26,"n":"第二十六条","txt":"权利人依据企业破产法第三十八条的规定行使取回权，应当在破产财产变价方案或者和解协议、重整计划草案提交债权人会议表决前向管理人提出。权利人在上述期限后主张取回相关财产的，应当承担延迟行使取回权增加的相关费用。"},{"i":27,"n":"第二十七条","txt":"权利人依据企业破产法第三十八条的规定向管理人主张取回相关财产，管理人不予认可，权利人以债务人为被告向人民法院提起诉讼请求行使取回权的，人民法院应予受理。"},{"i":28,"n":"第二十八条","txt":"权利人行使取回权时未依法向管理人支付相关的加工费、保管费、托运费、委托费、代销费等费用，管理人拒绝其取回相关财产的，人民法院应予支持。"},{"i":29,"n":"第二十九条","txt":"对债务人占有的权属不清的鲜活易腐等不易保管的财产或者不及时变现价值将严重贬损的财产，管理人及时变价并提存变价款后，有关权利人就该变价款行使取回权的，人民法院应予支持。"},{"i":30,"n":"第三十条","txt":"债务人占有的他人财产被违法转让给第三人，依据民法典第三百一十一条的规定第三人已善意取得财产所有权，原权利人无法取回该财产的，人民法院应当按照以下规定处理："},{"i":31,"n":"第三十一条","txt":"债务人占有的他人财产被违法转让给第三人，第三人已向债务人支付了转让价款，但依据民法典第三百一十一条的规定未取得财产所有权，原权利人依法追回转让财产的，对因第三人已支付对价而产生的债务，人民法院应当按照以下规定处理："},{"i":32,"n":"第三十二条","txt":"债务人占有的他人财产毁损、灭失，因此获得的保险金、赔偿金、代偿物尚未交付给债务人，或者代偿物虽已交付给债务人但能与债务人财产予以区分的，权利人主张取回就此获得的保险金、赔偿金、代偿物的，人民法院应予支持。"},{"i":33,"n":"第三十三条","txt":"管理人或者相关人员在执行职务过程中，因故意或者重大过失不当转让他人财产或者造成他人财产毁损、灭失，导致他人损害产生的债务作为共益债务，由债务人财产随时清偿不足弥补损失，权利人向管理人或者相关人员主张承担补充赔偿责任的，人民法院应予支持。"},{"i":34,"n":"第三十四条","txt":"买卖合同双方当事人在合同中约定标的物所有权保留，在标的物所有权未依法转移给买受人前，一方当事人破产的，该买卖合同属于双方均未履行完毕的合同，管理人有权依据企业破产法第十八条的规定决定解除或者继续履行合同。"},{"i":35,"n":"第三十五条","txt":"出卖人破产，其管理人决定继续履行所有权保留买卖合同的，买受人应当按照原买卖合同的约定支付价款或者履行其他义务。"},{"i":36,"n":"第三十六条","txt":"出卖人破产，其管理人决定解除所有权保留买卖合同，并依据企业破产法第十七条的规定要求买受人向其交付买卖标的物的，人民法院应予支持。"},{"i":37,"n":"第三十七条","txt":"买受人破产，其管理人决定继续履行所有权保留买卖合同的，原买卖合同中约定的买受人支付价款或者履行其他义务的期限在破产申请受理时视为到期，买受人管理人应当及时向出卖人支付价款或者履行其他义务。"},{"i":38,"n":"第三十八条","txt":"买受人破产，其管理人决定解除所有权保留买卖合同，出卖人依据企业破产法第三十八条的规定主张取回买卖标的物的，人民法院应予支持。"},{"i":39,"n":"第三十九条","txt":"出卖人依据企业破产法第三十九条的规定，通过通知承运人或者实际占有人中止运输、返还货物、变更到达地，或者将货物交给其他收货人等方式，对在运途中标的物主张了取回权但未能实现，或者在货物未达管理人前已向管理人主张取回在运途中标的物，在买卖标的物到达管理人后，出卖人向管理人主张取回的，管理人应予准许。"},{"i":40,"n":"第四十条","txt":"债务人重整期间，权利人要求取回债务人合法占有的权利人的财产，不符合双方事先约定条件的，人民法院不予支持。但是，因管理人或者自行管理的债务人违反约定，可能导致取回物被转让、毁损、灭失或者价值明显减少的除外。"},{"i":41,"n":"第四十一条","txt":"债权人依据企业破产法第四十条的规定行使抵销权，应当向管理人提出抵销主张。"},{"i":42,"n":"第四十二条","txt":"管理人收到债权人提出的主张债务抵销的通知后，经审查无异议的，抵销自管理人收到通知之日起生效。"},{"i":43,"n":"第四十三条","txt":"债权人主张抵销，管理人以下列理由提出异议的，人民法院不予支持："},{"i":44,"n":"第四十四条","txt":"破产申请受理前六个月内，债务人有企业破产法第二条第一款规定的情形，债务人与个别债权人以抵销方式对个别债权人清偿，其抵销的债权债务属于企业破产法第四十条第（二）、（三）项规定的情形之一，管理人在破产申请受理之日起三个月内向人民法院提起诉讼，主张该抵销无效的，人民法院应予支持。"},{"i":45,"n":"第四十五条","txt":"企业破产法第四十条所列不得抵销情形的债权人，主张以其对债务人特定财产享有优先受偿权的债权，与债务人对其不享有优先受偿权的债权抵销，债务人管理人以抵销存在企业破产法第四十条规定的情形提出异议的，人民法院不予支持。但是，用以抵销的债权大于债权人享有优先受偿权财产价值的除外。"},{"i":46,"n":"第四十六条","txt":"债务人的股东主张以下列债务与债务人对其负有的债务抵销，债务人管理人提出异议的，人民法院应予支持："},{"i":47,"n":"第四十七条","txt":"人民法院受理破产申请后，当事人提起的有关债务人的民事诉讼案件，应当依据企业破产法第二十一条的规定，由受理破产申请的人民法院管辖。"},{"i":48,"n":"第四十八条","txt":"本规定施行前本院发布的有关企业破产的司法解释，与本规定相抵触的，自本规定施行之日起不再适用。"}],"zuigaorenminfayuanguanyushiyonggongsifashijianxiaoa6b408":[{"i":1,"n":"第一条","txt":"公司法施行后的法律事实引起的民事纠纷案件，适用公司法的规定。"},{"i":2,"n":"第二条","txt":"公司法施行前与公司有关的民事法律行为，依据当时的法律、司法解释认定无效而依据公司法认定有效，因民事法律行为效力发生争议的下列情形，适用公司法的规定："},{"i":3,"n":"第三条","txt":"公司法施行前订立的与公司有关的合同，合同的履行持续至公司法施行后，因公司法施行前的履行行为发生争议的，适用当时的法律、司法解释的规定；因公司法施行后的履行行为发生争议的下列情形，适用公司法的规定："},{"i":4,"n":"第四条","txt":"公司法施行前的法律事实引起的民事纠纷案件，当时的法律、司法解释没有规定而公司法作出规定的下列情形，适用公司法的规定："},{"i":5,"n":"第五条","txt":"公司法施行前的法律事实引起的民事纠纷案件，当时的法律、司法解释已有原则性规定，公司法作出具体规定的下列情形，适用公司法的规定："},{"i":6,"n":"第六条","txt":"应当进行清算的法律事实发生在公司法施行前，因清算责任发生争议的，适用当时的法律、司法解释的规定。"},{"i":7,"n":"第七条","txt":"公司法施行前已经终审的民事纠纷案件，当事人申请再审或者人民法院按照审判监督程序决定再审的，适用当时的法律、司法解释的规定。"},{"i":8,"n":"第八条","txt":"本规定自2024年7月1日起施行。"}],"zuigaorenminfayuanguanyushiyonggongsifaruoganwentic8912f":[{"i":1,"n":"第一条","txt":"公司法实施后，人民法院尚未审结的和新受理的民事案件，其民事行为或事件发生在公司法实施以前的，适用当时的法律法规和司法解释。"},{"i":2,"n":"第二条","txt":"因公司法实施前有关民事行为或者事件发生纠纷起诉到人民法院的，如当时的法律法规和司法解释没有明确规定时，可参照适用公司法的有关规定。"},{"i":3,"n":"第三条","txt":"原告以公司法第二十二条第二款、第七十四条第二款规定事由，向人民法院提起诉讼时，超过公司法规定期限的，人民法院不予受理。"},{"i":4,"n":"第四条","txt":"公司法第一百五十一条规定的180日以上连续持股期间，应为股东向人民法院提起诉讼时，已期满的持股时间；规定的合计持有公司百分之一以上股份，是指两个以上股东持股份额的合计。"},{"i":5,"n":"第五条","txt":"人民法院对公司法实施前已经终审的案件依法进行再审时，不适用公司法的规定。"},{"i":6,"n":"第六条","txt":"本规定自公布之日起实施。"}],"zuigaorenminfayuanguanyushiyonggongsifaruoganwenti9c3b4c":[{"i":1,"n":"第一条","txt":"为设立公司而签署公司章程、向公司认购出资或者股份并履行公司设立职责的人，应当认定为公司的发起人，包括有限责任公司设立时的股东。"},{"i":2,"n":"第二条","txt":"发起人为设立公司以自己名义对外签订合同，合同相对人请求该发起人承担合同责任的，人民法院应予支持；公司成立后合同相对人请求公司承担合同责任的，人民法院应予支持。"},{"i":3,"n":"第三条","txt":"发起人以设立中公司名义对外签订合同，公司成立后合同相对人请求公司承担合同责任的，人民法院应予支持。"},{"i":4,"n":"第四条","txt":"公司因故未成立，债权人请求全体或者部分发起人对设立公司行为所产生的费用和债务承担连带清偿责任的，人民法院应予支持。"},{"i":5,"n":"第五条","txt":"发起人因履行公司设立职责造成他人损害，公司成立后受害人请求公司承担侵权赔偿责任的，人民法院应予支持；公司未成立，受害人请求全体发起人承担连带赔偿责任的，人民法院应予支持。"},{"i":6,"n":"第六条","txt":"股份有限公司的认股人未按期缴纳所认股份的股款，经公司发起人催缴后在合理期间内仍未缴纳，公司发起人对该股份另行募集的，人民法院应当认定该募集行为有效。认股人延期缴纳股款给公司造成损失，公司请求该认股人承担赔偿责任的，人民法院应予支持。"},{"i":7,"n":"第七条","txt":"出资人以不享有处分权的财产出资，当事人之间对于出资行为效力产生争议的，人民法院可以参照民法典第三百一十一条的规定予以认定。"},{"i":8,"n":"第八条","txt":"出资人以划拨土地使用权出资，或者以设定权利负担的土地使用权出资，公司、其他股东或者公司债权人主张认定出资人未履行出资义务的，人民法院应当责令当事人在指定的合理期间内办理土地变更手续或者解除权利负担；逾期未办理或者未解除的，人民法院应当认定出资人未依法全面履行出资义务。"},{"i":9,"n":"第九条","txt":"出资人以非货币财产出资，未依法评估作价，公司、其他股东或者公司债权人请求认定出资人未履行出资义务的，人民法院应当委托具有合法资格的评估机构对该财产评估作价。评估确定的价额显著低于公司章程所定价额的，人民法院应当认定出资人未依法全面履行出资义务。"},{"i":10,"n":"第十条","txt":"出资人以房屋、土地使用权或者需要办理权属登记的知识产权等财产出资，已经交付公司使用但未办理权属变更手续，公司、其他股东或者公司债权人主张认定出资人未履行出资义务的，人民法院应当责令当事人在指定的合理期间内办理权属变更手续；在前述期间内办理了权属变更手续的，人民法院应当认定其已经履行了出资义务；出资人主张自其实际交付财产给公司使用时享有相应股东权利的，人民法院应予支持。"},{"i":11,"n":"第十一条","txt":"出资人以其他公司股权出资，符合下列条件的，人民法院应当认定出资人已履行出资义务："},{"i":12,"n":"第十二条","txt":"公司成立后，公司、股东或者公司债权人以相关股东的行为符合下列情形之一且损害公司权益为由，请求认定该股东抽逃出资的，人民法院应予支持："},{"i":13,"n":"第十三条","txt":"股东未履行或者未全面履行出资义务，公司或者其他股东请求其向公司依法全面履行出资义务的，人民法院应予支持。"},{"i":14,"n":"第十四条","txt":"股东抽逃出资，公司或者其他股东请求其向公司返还出资本息、协助抽逃出资的其他股东、董事、高级管理人员或者实际控制人对此承担连带责任的，人民法院应予支持。"},{"i":15,"n":"第十五条","txt":"出资人以符合法定条件的非货币财产出资后，因市场变化或者其他客观因素导致出资财产贬值，公司、其他股东或者公司债权人请求该出资人承担补足出资责任的，人民法院不予支持。但是，当事人另有约定的除外。"},{"i":16,"n":"第十六条","txt":"股东未履行或者未全面履行出资义务或者抽逃出资，公司根据公司章程或者股东会决议对其利润分配请求权、新股优先认购权、剩余财产分配请求权等股东权利作出相应的合理限制，该股东请求认定该限制无效的，人民法院不予支持。"},{"i":17,"n":"第十七条","txt":"有限责任公司的股东未履行出资义务或者抽逃全部出资，经公司催告缴纳或者返还，其在合理期间内仍未缴纳或者返还出资，公司以股东会决议解除该股东的股东资格，该股东请求确认该解除行为无效的，人民法院不予支持。"},{"i":18,"n":"第十八条","txt":"有限责任公司的股东未履行或者未全面履行出资义务即转让股权，受让人对此知道或者应当知道，公司请求该股东履行出资义务、受让人对此承担连带责任的，人民法院应予支持；公司债权人依照本规定第十三条第二款向该股东提起诉讼，同时请求前述受让人对此承担连带责任的，人民法院应予支持。"},{"i":19,"n":"第十九条","txt":"公司股东未履行或者未全面履行出资义务或者抽逃出资，公司或者其他股东请求其向公司全面履行出资义务或者返还出资，被告股东以诉讼时效为由进行抗辩的，人民法院不予支持。"},{"i":20,"n":"第二十条","txt":"当事人之间对是否已履行出资义务发生争议，原告提供对股东履行出资义务产生合理怀疑证据的，被告股东应当就其已履行出资义务承担举证责任。"},{"i":21,"n":"第二十一条","txt":"当事人向人民法院起诉请求确认其股东资格的，应当以公司为被告，与案件争议股权有利害关系的人作为第三人参加诉讼。"},{"i":22,"n":"第二十二条","txt":"当事人之间对股权归属发生争议，一方请求人民法院确认其享有股权的，应当证明以下事实之一："},{"i":23,"n":"第二十三条","txt":"当事人依法履行出资义务或者依法继受取得股权后，公司未根据公司法第三十一条、第三十二条的规定签发出资证明书、记载于股东名册并办理公司登记机关登记，当事人请求公司履行上述义务的，人民法院应予支持。"},{"i":24,"n":"第二十四条","txt":"有限责任公司的实际出资人与名义出资人订立合同，约定由实际出资人出资并享有投资权益，以名义出资人为名义股东，实际出资人与名义股东对该合同效力发生争议的，如无法律规定的无效情形，人民法院应当认定该合同有效。"},{"i":25,"n":"第二十五条","txt":"名义股东将登记于其名下的股权转让、质押或者以其他方式处分，实际出资人以其对于股权享有实际权利为由，请求认定处分股权行为无效的，人民法院可以参照民法典第三百一十一条的规定处理。"},{"i":26,"n":"第二十六条","txt":"公司债权人以登记于公司登记机关的股东未履行出资义务为由，请求其对公司债务不能清偿的部分在未出资本息范围内承担补充赔偿责任，股东以其仅为名义股东而非实际出资人为由进行抗辩的，人民法院不予支持。"},{"i":27,"n":"第二十七条","txt":"股权转让后尚未向公司登记机关办理变更登记，原股东将仍登记于其名下的股权转让、质押或者以其他方式处分，受让股东以其对于股权享有实际权利为由，请求认定处分股权行为无效的，人民法院可以参照民法典第三百一十一条的规定处理。"},{"i":28,"n":"第二十八条","txt":"冒用他人名义出资并将该他人作为股东在公司登记机关登记的，冒名登记行为人应当承担相应责任；公司、其他股东或者公司债权人以未履行出资义务为由，请求被冒名登记为股东的承担补足出资责任或者对公司债务不能清偿部分的赔偿责任的，人民法院不予支持。"}],"zuigaorenminfayuanguanyushiyonggongsifaruoganwenti2d7e15":[{"i":1,"n":"第一条","txt":"单独或者合计持有公司全部股东表决权百分之十以上的股东，以下列事由之一提起解散公司诉讼，并符合公司法第一百八十二条规定的，人民法院应予受理："},{"i":2,"n":"第二条","txt":"股东提起解散公司诉讼，同时又申请人民法院对公司进行清算的，人民法院对其提出的清算申请不予受理。人民法院可以告知原告，在人民法院判决解散公司后，依据民法典第七十条、公司法第一百八十三条和本规定第七条的规定，自行组织清算或者另行申请人民法院对公司进行清算。"},{"i":3,"n":"第三条","txt":"股东提起解散公司诉讼时，向人民法院申请财产保全或者证据保全的，在股东提供担保且不影响公司正常经营的情形下，人民法院可予以保全。"},{"i":4,"n":"第四条","txt":"股东提起解散公司诉讼应当以公司为被告。"},{"i":5,"n":"第五条","txt":"人民法院审理解散公司诉讼案件，应当注重调解。当事人协商同意由公司或者股东收购股份，或者以减资等方式使公司存续，且不违反法律、行政法规强制性规定的，人民法院应予支持。当事人不能协商一致使公司存续的，人民法院应当及时判决。"},{"i":6,"n":"第六条","txt":"人民法院关于解散公司诉讼作出的判决，对公司全体股东具有法律约束力。"},{"i":7,"n":"第七条","txt":"公司应当依照民法典第七十条、公司法第一百八十三条的规定，在解散事由出现之日起十五日内成立清算组，开始自行清算。"},{"i":8,"n":"第八条","txt":"人民法院受理公司清算案件，应当及时指定有关人员组成清算组。"},{"i":9,"n":"第九条","txt":"人民法院指定的清算组成员有下列情形之一的，人民法院可以根据债权人、公司股东、董事或其他利害关系人的申请，或者依职权更换清算组成员："},{"i":10,"n":"第十条","txt":"公司依法清算结束并办理注销登记前，有关公司的民事诉讼，应当以公司的名义进行。"},{"i":11,"n":"第十一条","txt":"公司清算时，清算组应当按照公司法第一百八十五条的规定，将公司解散清算事宜书面通知全体已知债权人，并根据公司规模和营业地域范围在全国或者公司注册登记地省级有影响的报纸上进行公告。"},{"i":12,"n":"第十二条","txt":"公司清算时，债权人对清算组核定的债权有异议的，可以要求清算组重新核定。清算组不予重新核定，或者债权人对重新核定的债权仍有异议，债权人以公司为被告向人民法院提起诉讼请求确认的，人民法院应予受理。"},{"i":13,"n":"第十三条","txt":"债权人在规定的期限内未申报债权，在公司清算程序终结前补充申报的，清算组应予登记。"},{"i":14,"n":"第十四条","txt":"债权人补充申报的债权，可以在公司尚未分配财产中依法清偿。公司尚未分配财产不能全额清偿，债权人主张股东以其在剩余财产分配中已经取得的财产予以清偿的，人民法院应予支持；但债权人因重大过错未在规定期限内申报债权的除外。"},{"i":15,"n":"第十五条","txt":"公司自行清算的，清算方案应当报股东会或者股东大会决议确认；人民法院组织清算的，清算方案应当报人民法院确认。未经确认的清算方案，清算组不得执行。"},{"i":16,"n":"第十六条","txt":"人民法院组织清算的，清算组应当自成立之日起六个月内清算完毕。"},{"i":17,"n":"第十七条","txt":"人民法院指定的清算组在清理公司财产、编制资产负债表和财产清单时，发现公司财产不足清偿债务的，可以与债权人协商制作有关债务清偿方案。"},{"i":18,"n":"第十八条","txt":"有限责任公司的股东、股份有限公司的董事和控股股东未在法定期限内成立清算组开始清算，导致公司财产贬值、流失、毁损或者灭失，债权人主张其在造成损失范围内对公司债务承担赔偿责任的，人民法院应依法予以支持。"},{"i":19,"n":"第十九条","txt":"有限责任公司的股东、股份有限公司的董事和控股股东，以及公司的实际控制人在公司解散后，恶意处置公司财产给债权人造成损失，或者未经依法清算，以虚假的清算报告骗取公司登记机关办理法人注销登记，债权人主张其对公司债务承担相应赔偿责任的，人民法院应依法予以支持。"},{"i":20,"n":"第二十条","txt":"公司解散应当在依法清算完毕后，申请办理注销登记。公司未经清算即办理注销登记，导致公司无法进行清算，债权人主张有限责任公司的股东、股份有限公司的董事和控股股东，以及公司的实际控制人对公司债务承担清偿责任的，人民法院应依法予以支持。"},{"i":21,"n":"第二十一条","txt":"按照本规定第十八条和第二十条第一款的规定应当承担责任的有限责任公司的股东、股份有限公司的董事和控股股东，以及公司的实际控制人为二人以上的，其中一人或者数人依法承担民事责任后，主张其他人员按照过错大小分担责任的，人民法院应依法予以支持。"},{"i":22,"n":"第二十二条","txt":"公司解散时，股东尚未缴纳的出资均应作为清算财产。股东尚未缴纳的出资，包括到期应缴未缴的出资，以及依照公司法第二十六条和第八十条的规定分期缴纳尚未届满缴纳期限的出资。"},{"i":23,"n":"第二十三条","txt":"清算组成员从事清算事务时，违反法律、行政法规或者公司章程给公司或者债权人造成损失，公司或者债权人主张其承担赔偿责任的，人民法院应依法予以支持。"},{"i":24,"n":"第二十四条","txt":"解散公司诉讼案件和公司清算案件由公司住所地人民法院管辖。公司住所地是指公司主要办事机构所在地。公司办事机构所在地不明确的，由其注册地人民法院管辖。"}],"zuigaorenminfayuanguanyushiyonggongsifaruoganwenti488ee8":[{"i":1,"n":"第一条","txt":"关联交易损害公司利益，原告公司依据民法典第八十四条、公司法第二十一条规定请求控股股东、实际控制人、董事、监事、高级管理人员赔偿所造成的损失，被告仅以该交易已经履行了信息披露、经股东会或者股东大会同意等法律、行政法规或者公司章程规定的程序为由抗辩的，人民法院不予支持。"},{"i":2,"n":"第二条","txt":"关联交易合同存在无效、可撤销或者对公司不发生效力的情形，公司没有起诉合同相对方的，符合公司法第一百五十一条第一款规定条件的股东，可以依据公司法第一百五十一条第二款、第三款规定向人民法院提起诉讼。"},{"i":3,"n":"第三条","txt":"董事任期届满前被股东会或者股东大会有效决议解除职务，其主张解除不发生法律效力的，人民法院不予支持。"},{"i":4,"n":"第四条","txt":"分配利润的股东会或者股东大会决议作出后，公司应当在决议载明的时间内完成利润分配。决议没有载明时间的，以公司章程规定的为准。决议、章程中均未规定时间或者时间超过一年的，公司应当自决议作出之日起一年内完成利润分配。"},{"i":5,"n":"第五条","txt":"人民法院审理涉及有限责任公司股东重大分歧案件时，应当注重调解。当事人协商一致以下列方式解决分歧，且不违反法律、行政法规的强制性规定的，人民法院应予支持："},{"i":6,"n":"第六条","txt":"本规定自2019年4月29日起施行。"}],"zuigaorenminfayuanguanyushiyonggongsifaruoganwenti8402ac":[{"i":1,"n":"第一条","txt":"公司股东、董事、监事等请求确认股东会或者股东大会、董事会决议无效或者不成立的，人民法院应当依法予以受理。"},{"i":2,"n":"第二条","txt":"依据民法典第八十五条、公司法第二十二条第二款请求撤销股东会或者股东大会、董事会决议的原告，应当在起诉时具有公司股东资格。"},{"i":3,"n":"第三条","txt":"原告请求确认股东会或者股东大会、董事会决议不成立、无效或者撤销决议的案件，应当列公司为被告。对决议涉及的其他利害关系人，可以依法列为第三人。"},{"i":4,"n":"第四条","txt":"股东请求撤销股东会或者股东大会、董事会决议，符合民法典第八十五条、公司法第二十二条第二款规定的，人民法院应当予以支持，但会议召集程序或者表决方式仅有轻微瑕疵，且对决议未产生实质影响的，人民法院不予支持。"},{"i":5,"n":"第五条","txt":"股东会或者股东大会、董事会决议存在下列情形之一，当事人主张决议不成立的，人民法院应当予以支持："},{"i":6,"n":"第六条","txt":"股东会或者股东大会、董事会决议被人民法院判决确认无效或者撤销的，公司依据该决议与善意相对人形成的民事法律关系不受影响。"},{"i":7,"n":"第七条","txt":"股东依据公司法第三十三条、第九十七条或者公司章程的规定，起诉请求查阅或者复制公司特定文件材料的，人民法院应当依法予以受理。"},{"i":8,"n":"第八条","txt":"有限责任公司有证据证明股东存在下列情形之一的，人民法院应当认定股东有公司法第三十三条第二款规定的“不正当目的”："},{"i":9,"n":"第九条","txt":"公司章程、股东之间的协议等实质性剥夺股东依据公司法第三十三条、第九十七条规定查阅或者复制公司文件材料的权利，公司以此为由拒绝股东查阅或者复制的，人民法院不予支持。"},{"i":10,"n":"第十条","txt":"人民法院审理股东请求查阅或者复制公司特定文件材料的案件，对原告诉讼请求予以支持的，应当在判决中明确查阅或者复制公司特定文件材料的时间、地点和特定文件材料的名录。"},{"i":11,"n":"第十一条","txt":"股东行使知情权后泄露公司商业秘密导致公司合法利益受到损害，公司请求该股东赔偿相关损失的，人民法院应当予以支持。"},{"i":12,"n":"第十二条","txt":"公司董事、高级管理人员等未依法履行职责，导致公司未依法制作或者保存公司法第三十三条、第九十七条规定的公司文件材料，给股东造成损失，股东依法请求负有相应责任的公司董事、高级管理人员承担民事赔偿责任的，人民法院应当予以支持。"},{"i":13,"n":"第十三条","txt":"股东请求公司分配利润案件，应当列公司为被告。"},{"i":14,"n":"第十四条","txt":"股东提交载明具体分配方案的股东会或者股东大会的有效决议，请求公司分配利润，公司拒绝分配利润且其关于无法执行决议的抗辩理由不成立的，人民法院应当判决公司按照决议载明的具体分配方案向股东分配利润。"},{"i":15,"n":"第十五条","txt":"股东未提交载明具体分配方案的股东会或者股东大会决议，请求公司分配利润的，人民法院应当驳回其诉讼请求，但违反法律规定滥用股东权利导致公司不分配利润，给其他股东造成损失的除外。"},{"i":16,"n":"第十六条","txt":"有限责任公司的自然人股东因继承发生变化时，其他股东主张依据公司法第七十一条第三款规定行使优先购买权的，人民法院不予支持，但公司章程另有规定或者全体股东另有约定的除外。"},{"i":17,"n":"第十七条","txt":"有限责任公司的股东向股东以外的人转让股权，应就其股权转让事项以书面或者其他能够确认收悉的合理方式通知其他股东征求同意。其他股东半数以上不同意转让，不同意的股东不购买的，人民法院应当认定视为同意转让。"},{"i":18,"n":"第十八条","txt":"人民法院在判断是否符合公司法第七十一条第三款及本规定所称的“同等条件”时，应当考虑转让股权的数量、价格、支付方式及期限等因素。"},{"i":19,"n":"第十九条","txt":"有限责任公司的股东主张优先购买转让股权的，应当在收到通知后，在公司章程规定的行使期间内提出购买请求。公司章程没有规定行使期间或者规定不明确的，以通知确定的期间为准，通知确定的期间短于三十日或者未明确行使期间的，行使期间为三十日。"},{"i":20,"n":"第二十条","txt":"有限责任公司的转让股东，在其他股东主张优先购买后又不同意转让股权的，对其他股东优先购买的主张，人民法院不予支持，但公司章程另有规定或者全体股东另有约定的除外。其他股东主张转让股东赔偿其损失合理的，人民法院应当予以支持。"},{"i":21,"n":"第二十一条","txt":"有限责任公司的股东向股东以外的人转让股权，未就其股权转让事项征求其他股东意见，或者以欺诈、恶意串通等手段，损害其他股东优先购买权，其他股东主张按照同等条件购买该转让股权的，人民法院应当予以支持，但其他股东自知道或者应当知道行使优先购买权的同等条件之日起三十日内没有主张，或者自股权变更登记之日起超过一年的除外。"},{"i":22,"n":"第二十二条","txt":"通过拍卖向股东以外的人转让有限责任公司股权的，适用公司法第七十一条第二款、第三款或者第七十二条规定的“书面通知”“通知”“同等条件”时，根据相关法律、司法解释确定。"},{"i":23,"n":"第二十三条","txt":"监事会或者不设监事会的有限责任公司的监事依据公司法第一百五十一条第一款规定对董事、高级管理人员提起诉讼的，应当列公司为原告，依法由监事会主席或者不设监事会的有限责任公司的监事代表公司进行诉讼。"},{"i":24,"n":"第二十四条","txt":"符合公司法第一百五十一条第一款规定条件的股东，依据公司法第一百五十一条第二款、第三款规定，直接对董事、监事、高级管理人员或者他人提起诉讼的，应当列公司为第三人参加诉讼。"},{"i":25,"n":"第二十五条","txt":"股东依据公司法第一百五十一条第二款、第三款规定直接提起诉讼的案件，胜诉利益归属于公司。股东请求被告直接向其承担民事责任的，人民法院不予支持。"},{"i":26,"n":"第二十六条","txt":"股东依据公司法第一百五十一条第二款、第三款规定直接提起诉讼的案件，其诉讼请求部分或者全部得到人民法院支持的，公司应当承担股东因参加诉讼支付的合理费用。"},{"i":27,"n":"第二十七条","txt":"本规定自2017年9月1日起施行。"}],"zuigaorenminfayuanguanyushiyongminfadianshijianxiac504f0":[{"i":1,"n":"第一条","txt":"民法典施行后的法律事实引起的民事纠纷案件，适用民法典的规定。"},{"i":2,"n":"第二条","txt":"民法典施行前的法律事实引起的民事纠纷案件，当时的法律、司法解释有规定，适用当时的法律、司法解释的规定，但是适用民法典的规定更有利于保护民事主体合法权益，更有利于维护社会和经济秩序，更有利于弘扬社会主义核心价值观的除外。"},{"i":3,"n":"第三条","txt":"民法典施行前的法律事实引起的民事纠纷案件，当时的法律、司法解释没有规定而民法典有规定的，可以适用民法典的规定，但是明显减损当事人合法权益、增加当事人法定义务或者背离当事人合理预期的除外。"},{"i":4,"n":"第四条","txt":"民法典施行前的法律事实引起的民事纠纷案件，当时的法律、司法解释仅有原则性规定而民法典有具体规定的，适用当时的法律、司法解释的规定，但是可以依据民法典具体规定进行裁判说理。"},{"i":5,"n":"第五条","txt":"民法典施行前已经终审的案件，当事人申请再审或者按照审判监督程序决定再审的，不适用民法典的规定。"},{"i":6,"n":"第六条","txt":"《中华人民共和国民法总则》施行前，侵害英雄烈士等的姓名、肖像、名誉、荣誉，损害社会公共利益引起的民事纠纷案件，适用民法典第一百八十五条的规定。"},{"i":7,"n":"第七条","txt":"民法典施行前，当事人在债务履行期限届满前约定债务人不履行到期债务时抵押财产或者质押财产归债权人所有的，适用民法典第四百零一条和第四百二十八条的规定。"},{"i":8,"n":"第八条","txt":"民法典施行前成立的合同，适用当时的法律、司法解释的规定合同无效而适用民法典的规定合同有效的，适用民法典的相关规定。"},{"i":9,"n":"第九条","txt":"民法典施行前订立的合同，提供格式条款一方未履行提示或者说明义务，涉及格式条款效力认定的，适用民法典第四百九十六条的规定。"},{"i":10,"n":"第十条","txt":"民法典施行前，当事人一方未通知对方而直接以提起诉讼方式依法主张解除合同的，适用民法典第五百六十五条第二款的规定。"},{"i":11,"n":"第十一条","txt":"民法典施行前成立的合同，当事人一方不履行非金钱债务或者履行非金钱债务不符合约定，对方可以请求履行，但是有民法典第五百八十条第一款第一项、第二项、第三项除外情形之一，致使不能实现合同目的，当事人请求终止合同权利义务关系的，适用民法典第五百八十条第二款的规定。"},{"i":12,"n":"第十二条","txt":"民法典施行前订立的保理合同发生争议的，适用民法典第三编第十六章的规定。"},{"i":13,"n":"第十三条","txt":"民法典施行前，继承人有民法典第一千一百二十五条第一款第四项和第五项规定行为之一，对该继承人是否丧失继承权发生争议的，适用民法典第一千一百二十五条第一款和第二款的规定。"},{"i":14,"n":"第十四条","txt":"被继承人在民法典施行前死亡，遗产无人继承又无人受遗赠，其兄弟姐妹的子女请求代位继承的，适用民法典第一千一百二十八条第二款和第三款的规定，但是遗产已经在民法典施行前处理完毕的除外。"},{"i":15,"n":"第十五条","txt":"民法典施行前，遗嘱人以打印方式立的遗嘱，当事人对该遗嘱效力发生争议的，适用民法典第一千一百三十六条的规定，但是遗产已经在民法典施行前处理完毕的除外。"},{"i":16,"n":"第十六条","txt":"民法典施行前，受害人自愿参加具有一定风险的文体活动受到损害引起的民事纠纷案件，适用民法典第一千一百七十六条的规定。"},{"i":17,"n":"第十七条","txt":"民法典施行前，受害人为保护自己合法权益采取扣留侵权人的财物等措施引起的民事纠纷案件，适用民法典第一千一百七十七条的规定。"},{"i":18,"n":"第十八条","txt":"民法典施行前，因非营运机动车发生交通事故造成无偿搭乘人损害引起的民事纠纷案件，适用民法典第一千二百一十七条的规定。"},{"i":19,"n":"第十九条","txt":"民法典施行前，从建筑物中抛掷物品或者从建筑物上坠落的物品造成他人损害引起的民事纠纷案件，适用民法典第一千二百五十四条的规定。"},{"i":20,"n":"第二十条","txt":"民法典施行前成立的合同，依照法律规定或者当事人约定该合同的履行持续至民法典施行后，因民法典施行前履行合同发生争议的，适用当时的法律、司法解释的规定；因民法典施行后履行合同发生争议的，适用民法典第三编第四章和第五章的相关规定。"},{"i":21,"n":"第二十一条","txt":"民法典施行前租赁期限届满，当事人主张适用民法典第七百三十四条第二款规定的，人民法院不予支持；租赁期限在民法典施行后届满，当事人主张适用民法典第七百三十四条第二款规定的，人民法院依法予以支持。"},{"i":22,"n":"第二十二条","txt":"民法典施行前，经人民法院判决不准离婚后，双方又分居满一年，一方再次提起离婚诉讼的，适用民法典第一千零七十九条第五款的规定。"},{"i":23,"n":"第二十三条","txt":"被继承人在民法典施行前立有公证遗嘱，民法典施行后又立有新遗嘱，其死亡后，因该数份遗嘱内容相抵触发生争议的，适用民法典第一千一百四十二条第三款的规定。"},{"i":24,"n":"第二十四条","txt":"侵权行为发生在民法典施行前，但是损害后果出现在民法典施行后的民事纠纷案件，适用民法典的规定。"},{"i":25,"n":"第二十五条","txt":"民法典施行前成立的合同，当时的法律、司法解释没有规定且当事人没有约定解除权行使期限，对方当事人也未催告的，解除权人在民法典施行前知道或者应当知道解除事由，自民法典施行之日起一年内不行使的，人民法院应当依法认定该解除权消灭；解除权人在民法典施行后知道或者应当知道解除事由的，适用民法典第五百六十四条第二款关于解除权行使期限的规定。"},{"i":26,"n":"第二十六条","txt":"当事人以民法典施行前受胁迫结婚为由请求人民法院撤销婚姻的，撤销权的行使期限适用民法典第一千零五十二条第二款的规定。"},{"i":27,"n":"第二十七条","txt":"民法典施行前成立的保证合同，当事人对保证期间约定不明确，主债务履行期限届满至民法典施行之日不满二年，当事人主张保证期间为主债务履行期限届满之日起二年的，人民法院依法予以支持；当事人对保证期间没有约定，主债务履行期限届满至民法典施行之日不满六个月，当事人主张保证期间为主债务履行期限届满之日起六个月的，人民法院依法予以支持。"},{"i":28,"n":"第二十八条","txt":"本规定自2021年1月1日起施行。"}],"zuigaorenminfayuanguanyushiyonghaishangfashijianxi418d0f":[{"i":1,"n":"第一条","txt":"海商法施行后的法律事实引起的海事纠纷案件，适用海商法的规定。"},{"i":2,"n":"第二条","txt":"海商法施行前的法律事实引起的海事纠纷案件，当时的法律、司法解释没有规定而海商法有规定的，可以适用海商法的规定，但是明显减损当事人合法权益、增加当事人法定义务或者背离当事人合理预期的除外。"},{"i":3,"n":"第三条","txt":"海商法施行前的法律事实引起的海事纠纷案件，当时的法律、司法解释仅有原则性规定而海商法有具体规定的，适用当时的法律、司法解释的规定，但是可以依据海商法的具体规定进行裁判说理。"},{"i":4,"n":"第四条","txt":"海商法施行前成立的合同，依照法律规定或者当事人约定该合同的履行持续至海商法施行后，因海商法施行前履行合同发生争议的，适用当时的法律、司法解释的规定；因海商法施行后履行合同发生争议的，适用海商法有关合同履行的相关规定。"},{"i":5,"n":"第五条","txt":"海商法施行前，当事人约定船舶抵押权不与其担保的债权一并转让的，适用海商法第十八条的规定。"},{"i":6,"n":"第六条","txt":"海商法施行前出具的电子运输记录引起的纠纷，适用海商法第四章第五节有关电子运输记录的规定。"},{"i":7,"n":"第七条","txt":"海商法施行前订立的预约保险合同，在海商法施行后，被保险人履行申报义务或者保险人要求被保险人承担不履行申报义务违约责任的，适用海商法第二百五十九条的规定。"},{"i":8,"n":"第八条","txt":"海商法施行之日诉讼时效期间尚未届满的，有关时效期间的中止适用中止时效的原因消除之日的法律、司法解释的规定；有关时效期间的中断适用中断事由发生时的法律、司法解释的规定。"},{"i":9,"n":"第九条","txt":"海商法施行前已经终审的案件，当事人申请再审或者按照审判监督程序决定再审的，适用当时的法律、司法解释的规定。"},{"i":10,"n":"第十条","txt":"本规定自2026年5月1日起施行。"}],"zuigaorenminfayuanguanyushiyongjianyichengxushenli8bfa38":[{"i":1,"n":"第一条","txt":"基层人民法院根据民事诉讼法第一百五十七条规定审理简单的民事案件，适用本规定，但有下列情形之一的案件除外："},{"i":2,"n":"第二条","txt":"基层人民法院适用第一审普通程序审理的民事案件，当事人各方自愿选择适用简易程序，经人民法院审查同意的，可以适用简易程序进行审理。"},{"i":3,"n":"第三条","txt":"当事人就适用简易程序提出异议，人民法院认为异议成立的，或者人民法院在审理过程中发现不宜适用简易程序的，应当将案件转入普通程序审理。"},{"i":4,"n":"第四条","txt":"原告本人不能书写起诉状，委托他人代写起诉状确有困难的，可以口头起诉。"},{"i":5,"n":"第五条","txt":"当事人应当在起诉或者答辩时向人民法院提供自己准确的送达地址、收件人、电话号码等其他联系方式，并签名或者按指印确认。"},{"i":6,"n":"第六条","txt":"原告起诉后，人民法院可以采取捎口信、电话、传真、电子邮件等简便方式随时传唤双方当事人、证人。"},{"i":7,"n":"第七条","txt":"双方当事人到庭后，被告同意口头答辩的，人民法院可以当即开庭审理；被告要求书面答辩的，人民法院应当将提交答辩状的期限和开庭的具体日期告知各方当事人，并向当事人说明逾期举证以及拒不到庭的法律后果，由各方当事人在笔录和开庭传票的送达回证上签名或者按指印。"},{"i":8,"n":"第八条","txt":"人民法院按照原告提供的被告的送达地址或者其他联系方式无法通知被告应诉的，应当按以下情况分别处理："},{"i":9,"n":"第九条","txt":"被告到庭后拒绝提供自己的送达地址和联系方式的，人民法院应当告知其拒不提供送达地址的后果；经人民法院告知后被告仍然拒不提供的，按下列方式处理："},{"i":10,"n":"第十条","txt":"因当事人自己提供的送达地址不准确、送达地址变更未及时告知人民法院，或者当事人拒不提供自己的送达地址而导致诉讼文书未能被当事人实际接收的，按下列方式处理："},{"i":11,"n":"第十一条","txt":"受送达的自然人以及他的同住成年家属拒绝签收诉讼文书的，或者法人、非法人组织负责收件的人拒绝签收诉讼文书的，送达人应当依据民事诉讼法第八十六条的规定邀请有关基层组织或者所在单位的代表到场见证，被邀请的人不愿到场见证的，送达人应当在送达回证上记明拒收事由、时间和地点以及被邀请人不愿到场见证的情形，将诉讼文书留在受送达人的住所或者从业场所，即视为送达。"},{"i":12,"n":"第十二条","txt":"适用简易程序审理的民事案件，当事人及其诉讼代理人申请证人出庭作证，应当在举证期限届满前提出。"},{"i":13,"n":"第十三条","txt":"当事人一方或者双方就适用简易程序提出异议后，人民法院应当进行审查，并按下列情形分别处理："},{"i":14,"n":"第十四条","txt":"下列民事案件，人民法院在开庭审理时应当先行调解："},{"i":15,"n":"第十五条","txt":"调解达成协议并经审判人员审核后，双方当事人同意该调解协议经双方签名或者按指印生效的，该调解协议自双方签名或者按指印之日起发生法律效力。当事人要求摘录或者复制该调解协议的，应予准许。"},{"i":16,"n":"第十六条","txt":"人民法院可以当庭告知当事人到人民法院领取民事调解书的具体日期，也可以在当事人达成调解协议的次日起十日内将民事调解书发送给当事人。"},{"i":17,"n":"第十七条","txt":"当事人以民事调解书与调解协议的原意不一致为由提出异议，人民法院审查后认为异议成立的，应当根据调解协议裁定补正民事调解书的相关内容。"},{"i":18,"n":"第十八条","txt":"以捎口信、电话、传真、电子邮件等形式发送的开庭通知，未经当事人确认或者没有其他证据足以证明当事人已经收到的，人民法院不得将其作为按撤诉处理和缺席判决的根据。"},{"i":19,"n":"第十九条","txt":"开庭前已经书面或者口头告知当事人诉讼权利义务，或者当事人各方均委托律师代理诉讼的，审判人员除告知当事人申请回避的权利外，可以不再告知当事人其他的诉讼权利义务。"},{"i":20,"n":"第二十条","txt":"对没有委托律师代理诉讼的当事人，审判人员应当对回避、自认、举证责任等相关内容向其作必要的解释或者说明，并在庭审过程中适当提示当事人正确行使诉讼权利、履行诉讼义务，指导当事人进行正常的诉讼活动。"},{"i":21,"n":"第二十一条","txt":"开庭时，审判人员可以根据当事人的诉讼请求和答辩意见归纳出争议焦点，经当事人确认后，由当事人围绕争议焦点举证、质证和辩论。"},{"i":22,"n":"第二十二条","txt":"当事人双方同时到基层人民法院请求解决简单的民事纠纷，但未协商举证期限，或者被告一方经简便方式传唤到庭的，当事人在开庭审理时要求当庭举证的，应予准许；当事人当庭举证有困难的，举证的期限由当事人协商决定，但最长不得超过十五日；协商不成的，由人民法院决定。"},{"i":23,"n":"第二十三条","txt":"适用简易程序审理的民事案件，应当一次开庭审结，但人民法院认为确有必要再次开庭的除外。"},{"i":24,"n":"第二十四条","txt":"书记员应当将适用简易程序审理民事案件的全部活动记入笔录。对于下列事项，应当详细记载："},{"i":25,"n":"第二十五条","txt":"庭审结束时，审判人员可以根据案件的审理情况对争议焦点和当事人各方举证、质证和辩论的情况进行简要总结，并就是否同意调解征询当事人的意见。"},{"i":26,"n":"第二十六条","txt":"审判人员在审理过程中发现案情复杂需要转为普通程序的，应当在审限届满前及时作出决定，并书面通知当事人。"},{"i":27,"n":"第二十七条","txt":"适用简易程序审理的民事案件，除人民法院认为不宜当庭宣判的以外，应当当庭宣判。"},{"i":28,"n":"第二十八条","txt":"当庭宣判的案件，除当事人当庭要求邮寄送达的以外，人民法院应当告知当事人或者诉讼代理人领取裁判文书的期间和地点以及逾期不领取的法律后果。上述情况，应当记入笔录。"},{"i":29,"n":"第二十九条","txt":"当事人因交通不便或者其他原因要求邮寄送达裁判文书的，人民法院可以按照当事人自己提供的送达地址邮寄送达。"},{"i":30,"n":"第三十条","txt":"原告经传票传唤，无正当理由拒不到庭或者未经法庭许可中途退庭的，可以按撤诉处理；被告经传票传唤，无正当理由拒不到庭或者未经法庭许可中途退庭的，人民法院可以根据原告的诉讼请求及双方已经提交给法庭的证据材料缺席判决。"},{"i":31,"n":"第三十一条","txt":"定期宣判的案件，定期宣判之日即为送达之日，当事人的上诉期自定期宣判的次日起开始计算。当事人在定期宣判的日期无正当理由未到庭的，不影响该裁判上诉期间的计算。"},{"i":32,"n":"第三十二条","txt":"适用简易程序审理的民事案件，有下列情形之一的，人民法院在制作裁判文书时对认定事实或者判决理由部分可以适当简化："},{"i":33,"n":"第三十三条","txt":"本院已经公布的司法解释与本规定不一致的，以本规定为准。"},{"i":34,"n":"第三十四条","txt":"本规定自2003年12月1日起施行。2003年12月1日以后受理的民事案件，适用本规定。"}],"zuigaorenminfayuanguanyushiyongcaichanxingruoganwe6dd822":[{"i":1,"n":"第一条","txt":"刑法规定“并处”没收财产或者罚金的犯罪，人民法院在对犯罪分子判处主刑的同时，必须依法判处相应的财产刑；刑法规定“可以并处”没收财产或者罚金的犯罪，人民法院应当根据案件具体情况及犯罪分子的财产状况，决定是否适用财产刑。"},{"i":2,"n":"第二条","txt":"人民法院应当根据犯罪情节，如违法所得数额、造成损失的大小等，并综合考虑犯罪分子缴纳罚金的能力，依法判处罚金。刑法没有明确规定罚金数额标准的，罚金的最低数额不能少于一千元。"},{"i":3,"n":"第三条","txt":"依法对犯罪分子所犯数罪分别判处罚金的，应当实行并罚，将所判处的罚金数额相加，执行总和数额。"},{"i":4,"n":"第四条","txt":"犯罪情节较轻，适用单处罚金不致再危害社会并具有下列情形之一的，可以依法单处罚金："},{"i":5,"n":"第五条","txt":"刑法第五十三条规定的“判决指定的期限”应当在判决书中予以确定；“判决指定的期限”应为从判决发生法律效力第二日起最长不超过三个月。"},{"i":6,"n":"第六条","txt":"刑法第五十三条规定的“由于遭遇不能抗拒的灾祸缴纳确实有困难的”，主要是指因遭受火灾、水灾、地震等灾祸而丧失财产；罪犯因重病、伤残等而丧失劳动能力，或者需要罪犯抚养的近亲属患有重病，需支付巨额医药费等，确实没有财产可供执行的情形。"},{"i":7,"n":"第七条","txt":"刑法第六十条规定的“没收财产以前犯罪分子所负的正当债务”，是指犯罪分子在判决生效前所负他人的合法债务。"},{"i":8,"n":"第八条","txt":"罚金刑的数额应当以人民币为计算单位。"},{"i":9,"n":"第九条","txt":"人民法院认为依法应当判处被告人财产刑的，可以在案件审理过程中，决定扣押或者冻结被告人的财产。"},{"i":10,"n":"第十条","txt":"财产刑由第一审人民法院执行。"},{"i":11,"n":"第十一条","txt":"自判决指定的期限届满第二日起，人民法院对于没有法定减免事由不缴纳罚金的，应当强制其缴纳。"}],"zuigaorenminfayuanguanyutieluyunshufayuananjianguabd5ad9":[{"i":1,"n":"第一条","txt":"铁路运输法院受理同级铁路运输检察院依法提起公诉的刑事案件。"},{"i":2,"n":"第二条","txt":"本规定第一条第二、三款范围内发生的刑事自诉案件，自诉人向铁路运输法院提起自诉的，铁路运输法院应当受理。"},{"i":3,"n":"第三条","txt":"下列涉及铁路运输、铁路安全、铁路财产的民事诉讼，由铁路运输法院管辖："},{"i":4,"n":"第四条","txt":"铁路运输基层法院就本规定第一条至第三条所列案件作出的判决、裁定，当事人提起上诉或铁路运输检察院提起抗诉的二审案件，由相应的铁路运输中级法院受理。"},{"i":5,"n":"第五条","txt":"省、自治区、直辖市高级人民法院可以指定辖区内的铁路运输基层法院受理本规定第三条以外的其他第一审民事案件，并指定该铁路运输基层法院驻在地的中级人民法院或铁路运输中级法院受理对此提起上诉的案件。此类案件发生管辖权争议的，由该高级人民法院指定管辖。"},{"i":6,"n":"第六条","txt":"各高级人民法院指定铁路运输法院受理案件的范围，报最高人民法院批准后实施。"},{"i":7,"n":"第七条","txt":"本院以前作出的有关规定与本规定不一致的，以本规定为准。"}],"zuigaorenminfayuanguanyuxianzhibeizhixingrengaoxia61511b":[{"i":1,"n":"第一条","txt":"被执行人未按执行通知书指定的期间履行生效法律文书确定的给付义务的，人民法院可以采取限制消费措施，限制其高消费及非生活或者经营必需的有关消费。"},{"i":2,"n":"第二条","txt":"人民法院决定采取限制消费措施时，应当考虑被执行人是否有消极履行、规避执行或者抗拒执行的行为以及被执行人的履行能力等因素。"},{"i":3,"n":"第三条","txt":"被执行人为自然人的，被采取限制消费措施后，不得有以下高消费及非生活和工作必需的消费行为："},{"i":4,"n":"第四条","txt":"限制消费措施一般由申请执行人提出书面申请，经人民法院审查决定；必要时人民法院可以依职权决定。"},{"i":5,"n":"第五条","txt":"人民法院决定采取限制消费措施的，应当向被执行人发出限制消费令。限制消费令由人民法院院长签发。限制消费令应当载明限制消费的期间、项目、法律后果等内容。"},{"i":6,"n":"第六条","txt":"人民法院决定采取限制消费措施的，可以根据案件需要和被执行人的情况向有义务协助调查、执行的单位送达协助执行通知书，也可以在相关媒体上进行公告。"},{"i":7,"n":"第七条","txt":"限制消费令的公告费用由被执行人负担；申请执行人申请在媒体公告的，应当垫付公告费用。"},{"i":8,"n":"第八条","txt":"被限制消费的被执行人因生活或者经营必需而进行本规定禁止的消费活动的，应当向人民法院提出申请，获批准后方可进行。"},{"i":9,"n":"第九条","txt":"在限制消费期间，被执行人提供确实有效的担保或者经申请执行人同意的，人民法院可以解除限制消费令；被执行人履行完毕生效法律文书确定的义务的，人民法院应当在本规定第六条通知或者公告的范围内及时以通知或者公告解除限制消费令。"},{"i":10,"n":"第十条","txt":"人民法院应当设置举报电话或者邮箱，接受申请执行人和社会公众对被限制消费的被执行人违反本规定第三条的举报，并进行审查认定。"},{"i":11,"n":"第十一条","txt":"被执行人违反限制消费令进行消费的行为属于拒不履行人民法院已经发生法律效力的判决、裁定的行为，经查证属实的，依照《中华人民共和国民事诉讼法》第一百一十一条的规定，予以拘留、罚款；情节严重，构成犯罪的，追究其刑事责任。"}]};
